})

const formulaDisplayState = shallowRef<FormulaDisplayState>(createEmptyFormulaDisplayState())
const normalizedDocumentFormulaDisplayCache = new WeakMap<SheetDocument, FormulaDisplayState>()
const normalizedDocumentCellMetaCache = new WeakMap<SheetDocument, SheetCellMetaMap>()

const activeColumnFilterEntries = computed(() => getActiveColumnFilterEntries())
const normalizedBaseExternalRowFilterPrograms = computed(() => {
  const programs = [
    props.baseRowFilterProgram,
    ...(Array.isArray(props.baseRowFilterPrograms) ? props.baseRowFilterPrograms : []),
  ]
  return programs
    .filter((program): program is ExternalSheetRowFilterProgram => !!program)
    .map((program) => normalizeExternalRowFilterProgram(program))
})
const normalizedExternalRowFilterProgram = computed(() => normalizeExternalRowFilterProgram(props.rowFilterProgram))
const baseExternalRowFilterProgramActive = computed(() => normalizedBaseExternalRowFilterPrograms.value.some(
  (program) => isExternalRowFilterProgramActive(program),
))
const rowExternalRowFilterProgramActive = computed(() => isExternalRowFilterProgramActive(normalizedExternalRowFilterProgram.value))
const externalRowFilterProgramActive = computed(() => (
  baseExternalRowFilterProgramActive.value
  || rowExternalRowFilterProgramActive.value
))
const filteredVisibleRowCount = computed(() => Math.max(0, rows.value.length - dataFilterHiddenRows.value.length))

const columnHashColorStyleMap = computed(() => {
  const styleMap = new Map<string, HashColorStyle>()
  const headers = normalizeHeaders(columnHeaders.value)
  if (!headers.length || !rows.value.length) {
    return styleMap
  }

  const normalizedRows = rows.value.map((row) => normalizeRow(row, headers))
  const normalizedConfigs = normalizeColumnConfigs(columnConfigs.value, headers)
  const displayState = formulaDisplayState.value
  headers.forEach((header, columnIndex) => {
    const config = normalizedConfigs[header]
    const mode = normalizeColumnHashColorMode(config?.hash_color_mode)
    if (mode === 'none') {
      return
    }

    const tone = normalizeColumnHashColorTone(config?.hash_color_tone)
    const seeds = Array.from(new Set(normalizedRows
      .map((row, rowIndex) => getCellDisplayText(
        rowIndex,
        columnIndex,
        row[columnIndex] ?? '',
        displayState,
        headers,
        normalizedConfigs,
      ).trim())
      .filter(Boolean))).sort(compareHashColorSeeds)
    if (!seeds.length) {
      return
    }

    const tokens = resolveStableVisualTokens(seeds, {
      ...getHashColorTokenOptions(mode, tone),
      minAdjacentHueDistance: HASH_COLOR_MIN_ADJACENT_HUE_DISTANCE,
      minHueDistance: HASH_COLOR_MIN_USED_HUE_DISTANCE,
    })
    seeds.forEach((seed, index) => {
      const key = createColumnHashColorStyleKey(columnIndex, mode, tone, seed)
      if (styleMap.has(key)) {
        return
      }

      const token = tokens[index]
      const style = token ? createHashColorStyleFromToken(mode, tone, token) : null
      if (style) {
        styleMap.set(key, style)
      }
    })
  })

  return styleMap
})

