const columnFilterHiddenRows = computed(() => {
  if (activeColumnFilterEntries.value.length === 0) return []

  const hiddenRows: number[] = []
  rows.value.forEach((row, rowIndex) => {
    if (!doesRowMatchColumnFilters(row, rowIndex)) {
