})
const externalRowFilterHiddenRows = computed(() => {
  if (!externalRowFilterProgramActive.value) return []

  const hiddenRows: number[] = []
  rows.value.forEach((row, rowIndex) => {
    if (
      (
        baseExternalRowFilterProgramActive.value
        && normalizedBaseExternalRowFilterPrograms.value.some((program) => (
          isExternalRowFilterProgramActive(program)
          && !doesRowMatchExternalRowFilterProgram(row, rowIndex, program)
        ))
      )
      || (
        rowExternalRowFilterProgramActive.value
        && !doesRowMatchExternalRowFilterProgram(row, rowIndex, normalizedExternalRowFilterProgram.value)
      )
    ) {
      hiddenRows.push(sheetHeaderRowCount.value + rowIndex)
    }
  })
  return hiddenRows
})
const dataFilterHiddenRows = computed(() => {
  const hiddenRowSet = new Set<number>([
    ...columnFilterHiddenRows.value,
    ...externalRowFilterHiddenRows.value,
  ])
  return [...hiddenRowSet].sort((left, right) => left - right)
})
const sheetFilterHiddenRows = computed(() => {
  const hiddenRowSet = new Set<number>([
    ...columnNoteHiddenRows.value,
    ...dataFilterHiddenRows.value,
  ])
  return [...hiddenRowSet].sort((left, right) => left - right)
})
const rowMarkerColumnCount = computed(() => (sheetViewSettings.value.show_row_numbers ? 1 : 0))

function isRowMarkerHotColumn(hotColumnIndex: number) {
  return rowMarkerColumnCount.value > 0 && hotColumnIndex === 0
}

function toHotColumnIndex(columnIndex: number) {
