}

function toSheetColumnIndex(hotColumnIndex: number) {
  return hotColumnIndex - rowMarkerColumnCount.value
}

function getSheetColumnRangeFromHotRange(startHotColumn: number, endHotColumn: number) {
  const startHot = Math.min(startHotColumn, endHotColumn)
  const endHot = Math.max(startHotColumn, endHotColumn)
  const start = Math.max(toSheetColumnIndex(startHot), 0)
  const end = Math.min(toSheetColumnIndex(endHot), columnHeaders.value.length - 1)
  if (start > end) {
    return null
  }
  return { start, end }
}

function hotRangeIncludesRowMarker(startHotColumn: number, endHotColumn: number) {
  return rowMarkerColumnCount.value > 0
    && Math.min(startHotColumn, endHotColumn) <= 0
    && Math.max(startHotColumn, endHotColumn) >= 0
}

function getHotColumnCount() {
  return rowMarkerColumnCount.value + columnHeaders.value.length
}

const sheetColumnHeaders = computed<false | ((index: number) => string)>(() => {
  if (!sheetViewSettings.value.show_column_markers) {
    return false
  }
  return (hotColumnIndex: number) => {
    if (isRowMarkerHotColumn(hotColumnIndex)) {
      return ''
    }
    const columnIndex = toSheetColumnIndex(hotColumnIndex)
    return columnIndex >= 0 ? getColumnMarkerLabel(columnIndex) : ''
  }
})

const rowHeightLayoutState = computed(() => {
  let singleLineHeight = TABLE_LINE_HEIGHT
  let hasWrappedColumns = false
  const wrappedColumns: Array<{ index: number; fontSize: number; fontFamily: ColumnFontFamily; lineHeight: number }> = []

  columnHeaders.value.forEach((header, index) => {
    const config = columnConfigs.value[header]
    if (config?.hidden === true) {
      return
    }

    const fontSize = getColumnFontSizeFromConfig(config)
    const fontFamily = getColumnFontFamilyFromConfig(config)
    const lineHeight = getColumnLineHeightFromFontSize(fontSize)
    singleLineHeight = Math.max(singleLineHeight, lineHeight)

    if (normalizeColumnDisplayMode(config?.display_mode) !== 'single_line') {
      hasWrappedColumns = true
      wrappedColumns.push({ index, fontSize, fontFamily, lineHeight })
    }
  })

  return {
    hasWrappedColumns,
    singleLineHeight: singleLineHeight + TABLE_CELL_VERTICAL_PADDING * 2 + TABLE_CELL_BORDER_WIDTH,
    wrappedColumns,
  }
})

function expandHeaderGroupLabels(row: SheetHeaderGroupCell[], columnCount: number) {
  const labels: string[] = []
  for (const cell of row) {
    const colspan = Math.max(1, cell.colspan ?? 1)
    labels.push(cell.label)
    for (let index = 1; index < colspan && labels.length < columnCount; index += 1) {
      labels.push('')
    }
    if (labels.length >= columnCount) {
      break
    }
  }
  while (labels.length < columnCount) {
    labels.push('')
  }
  return labels
}

function getColumnNoteFromHeaderPrefixRow(columnIndex: number, headers = columnHeaders.value) {
  const noteRowIndex = columnNoteEntityHeaderLevel.value
  if (noteRowIndex < 0 || noteRowIndex >= sheetHeaderPrefixRows.value.length) {
    return ''
  }
  return normalizeColumnNote(normalizeRow(sheetHeaderPrefixRows.value[noteRowIndex], headers)[columnIndex])
}

function materializeColumnNotePrefixRow(noteOverrides: Record<number, string> = {}) {
  const headers = columnHeaders.value
  const noteRowIndex = columnNoteEntityHeaderLevel.value
  if (!headers.length || noteRowIndex < 0) {
    return false
  }

  const nextPrefixRows = sheetHeaderPrefixRows.value.map((row) => normalizeRow(row, headers))
  while (nextPrefixRows.length <= noteRowIndex) {
    nextPrefixRows.push(createEmptyRow(headers.length))
  }
  const noteRow = normalizeRow(nextPrefixRows[noteRowIndex], headers)
  headers.forEach((_, index) => {
    const hasOverride = Object.prototype.hasOwnProperty.call(noteOverrides, index)
    noteRow[index] = hasOverride
      ? normalizeColumnNote(noteOverrides[index])
      : (getColumnNote(index) || normalizeColumnNote(noteRow[index]))
  })
  nextPrefixRows[noteRowIndex] = noteRow
  sheetHeaderPrefixRows.value = nextPrefixRows
  return true
}

function syncColumnNotesFromHeaderPrefixRows() {
  if (!sheetHeaderPrefixRows.value.length || !columnHeaders.value.length) {
    return false
  }

  const mergedConfigs = mergeGridNoteRowIntoColumnConfigs(
    columnConfigs.value,
    sheetHeaderPrefixRows.value,
    columnHeaders.value,
    normalizedHeaderGroups.value.length,
    sheetHeaderPrefixRows.value.length,
  )
  if (mergedConfigs === columnConfigs.value) {
    return false
  }
  columnConfigs.value = mergedConfigs
  return true
}

const sheetGridRows = computed<SheetRow[]>(() => {
  const headers = columnHeaders.value
  const headerRows = normalizedHeaderGroups.value.map((row) => expandHeaderGroupLabels(row, headers.length))
  headerRows.push([...headers])
  if (hasColumnNoteEntityRow.value) {
    headerRows.push(headers.map((_, index) => (
      hasMaterializedColumnNoteRow.value
        ? getColumnNoteFromHeaderPrefixRow(index, headers)
        : getColumnNote(index)
    )))
  }
  return [
    ...headerRows,
    ...rows.value.map((row) => normalizeRow(row, headers)),
  ]
})

const sheetHotGridRows = computed<SheetRow[]>(() => {
  if (rowMarkerColumnCount.value <= 0) {
    return sheetGridRows.value
  }
  return sheetGridRows.value.map((row) => [
    '',
    ...row,
  ])
})

const hotTableInstanceKey = computed(() => `sheet-${props.workbookId ?? 'standalone'}`)

const rowMarkerColumnWidth = computed(() => {
  if (rowMarkerColumnCount.value <= 0) {
    return 0
  }

  const rowIndexes = new Set<number>()
  const gridRowCount = sheetGridRows.value.length
  for (let rowIndex = 0; rowIndex < Math.min(gridRowCount, sheetHeaderRowCount.value + 80); rowIndex += 1) {
    rowIndexes.add(rowIndex)
  }
  if (gridRowCount > 0) {
    rowIndexes.add(gridRowCount - 1)
  }

  const maxTextWidth = Array.from(rowIndexes).reduce((maxWidth, rowIndex) => (
    Math.max(maxWidth, measureTextWidth(getSheetRowHeaderLabel(rowIndex), TABLE_FONT))
  ), 0)
  return Math.min(
    Math.max(Math.ceil(maxTextWidth) + ROW_MARKER_WIDTH_PADDING, ROW_MARKER_MIN_COLUMN_WIDTH),
    ROW_MARKER_MAX_COLUMN_WIDTH,
  )
})

const sheetHotColumnWidths = computed(() => (
  rowMarkerColumnCount.value > 0
    ? [rowMarkerColumnWidth.value, ...columnWidths.value]
    : [...columnWidths.value]
))

const hotHiddenColumnIndexes = computed(() => (
  hiddenColumnIndexes.value.map((index) => toHotColumnIndex(index))
))

const sheetHotHiddenColumnsSettings = computed(() => ({
  columns: hotHiddenColumnIndexes.value,
  indicators: false,
}))

const sheetHotHiddenRowsSettings = computed(() => ({
  rows: sheetFilterHiddenRows.value,
  indicators: false,
}))

const sheetContentWidth = computed(() => {
  const hiddenHotColumnSet = new Set(hotHiddenColumnIndexes.value)
  const visibleWidth = sheetHotColumnWidths.value.reduce((total, width, index) => (
    hiddenHotColumnSet.has(index) ? total : total + normalizeColumnWidthValue(width)
  ), 0)
  return Math.max(240, Math.ceil(visibleWidth) + 2)
})

const sheetWorkspaceStyle = computed(() => (
  isContentHeightMode.value
    ? { '--sheet-content-width': `${sheetContentWidth.value}px` }
    : {}
))

const fixedHotColumnsStart = computed(() => (
  rowMarkerColumnCount.value > 0 || fixedColumnsStart.value > 0
    ? rowMarkerColumnCount.value + fixedColumnsStart.value
    : 0
))
const SHEET_HOT_MIN_COLUMN_RENDERING_OFFSET = 3
const SHEET_HOT_FROZEN_COLUMN_RENDERING_BUFFER = 2
const sheetHotViewportColumnRenderingOffset = computed(() => Math.max(
  SHEET_HOT_MIN_COLUMN_RENDERING_OFFSET,
  fixedHotColumnsStart.value + SHEET_HOT_FROZEN_COLUMN_RENDERING_BUFFER,
))

function getDocumentColumnNote(header: string, sourceConfigs: Record<string, SheetColumnConfig>) {
  return normalizeColumnNote(sourceConfigs[header]?.note)
}

function shouldIncludeFormulaNoteRow(
  settings: Required<SheetViewSettings>,
) {
  return settings.column_note_display !== 'none'
}

function getFormulaHeaderRowsForDocument(
  headers: string[],
  groups: SheetHeaderGroupCell[][],
  sourceConfigs: Record<string, SheetColumnConfig>,
  settings: Required<SheetViewSettings>,
) {
  const headerRows = groups.map((row) => expandHeaderGroupLabels(row, headers.length))
  headerRows.push([...headers])
  if (shouldIncludeFormulaNoteRow(settings)) {
    headerRows.push(headers.map((header) => getDocumentColumnNote(header, sourceConfigs)))
  }
  return headerRows
}

function getCurrentFormulaHeaderRows(headers = columnHeaders.value) {
  return sheetGridRows.value
    .slice(0, sheetHeaderRowCount.value)
    .map((row) => normalizeRow(row, headers))
}

function getSheetHeaderRowCountForColumnNoteEntity(shouldHaveColumnNoteEntityRow: boolean) {
  return normalizedHeaderGroups.value.length + 1 + (shouldHaveColumnNoteEntityRow ? 1 : 0)
}

function shouldHaveColumnNoteEntityRowForSettings(
  settings: Required<SheetViewSettings>,
) {
  return hasColumnNoteEntityRow.value || settings.column_note_display !== 'none'
}

function getSheetHeaderRowCountForSettings(settings: Required<SheetViewSettings>) {
  return getSheetHeaderRowCountForColumnNoteEntity(
    shouldHaveColumnNoteEntityRowForSettings(settings),
  )
}

const sheetMergeCells = computed(() => {
  return getRenderableMergedCells()
})

const sheetHotMergeCells = computed(() => (
  rowMarkerColumnCount.value > 0
    ? sheetMergeCells.value.map((cell) => ({ ...cell, col: cell.col + rowMarkerColumnCount.value }))
    : sheetMergeCells.value
))

const shouldUseEnhancedSheetRenderSettings = computed(() => sheetRenderPhase.value !== 'core')

const sheetHotRenderMergeCells = computed(() => {
  if (!shouldUseEnhancedSheetRenderSettings.value) {
    return false
  }
  return sheetHotMergeCells.value.length ? sheetHotMergeCells.value : false
})

const sheetHotRenderManualColumnResize = computed(() => (
  shouldUseEnhancedSheetRenderSettings.value && canEditConfig.value
))

const sheetHotRenderManualColumnMove = computed(() => (
  shouldUseEnhancedSheetRenderSettings.value && canEditConfig.value
))

const sheetHotRenderManualRowResize = computed(() => shouldUseEnhancedSheetRenderSettings.value)

const sheetHotRenderManualRowMove = computed(() => (
  shouldUseEnhancedSheetRenderSettings.value && canEditData.value
))

const sheetHotRenderReadOnly = computed(() => !shouldUseEnhancedSheetRenderSettings.value)

const sheetHotRenderCellMetaResolver = computed(() => (
  shouldUseEnhancedSheetRenderSettings.value ? resolveCellMeta : resolveCoreCellMeta
))

const sheetHotRenderRowHeightResolver = computed(() => (
  shouldUseEnhancedSheetRenderSettings.value ? resolveRowHeight : resolveCoreRowHeight
))

const sheetHotRenderAfterRenderer = computed(() => (
  shouldUseEnhancedSheetRenderSettings.value ? handleAfterRenderer : handleCoreAfterRenderer
))

function getDocumentGridRowIndex(gridRowIndex: number) {
  if (gridRowIndex < sheetHeaderRowCount.value) {
    return gridRowIndex
  }
  return sheetHeaderRowCount.value + getDocumentRowIndex(getDataRowIndex(gridRowIndex))
}

function getCurrentGridRowIndexFromDocumentRow(documentGridRow: number) {
  if (documentGridRow < sheetHeaderRowCount.value) {
    return documentGridRow
  }
  const dataRow = documentGridRow - sheetHeaderRowCount.value
  if (pageRowIndexes.value !== null) {
    const pageLocalRow = pageRowIndexes.value.indexOf(dataRow)
    return pageLocalRow >= 0 ? sheetHeaderRowCount.value + pageLocalRow : -1
  }
  const pageLocalRow = dataRow - (effectivePaginationEnabled.value ? pageRowOffset.value : 0)
  return pageLocalRow >= 0 && pageLocalRow < rows.value.length
    ? sheetHeaderRowCount.value + pageLocalRow
    : -1
}

function getLocalDataRowIndexFromDocumentDataIndex(documentDataIndex: number) {
  if (documentDataIndex < 0) {
    return -1
  }
  if (pageRowIndexes.value !== null) {
    return pageRowIndexes.value.indexOf(documentDataIndex)
  }
  const localIndex = documentDataIndex - (effectivePaginationEnabled.value ? pageRowOffset.value : 0)
  return localIndex >= 0 && localIndex < rows.value.length ? localIndex : -1
}

function getDocumentRowEntityId(documentRow: number) {
  if (documentRow < 0) {
    return ''
  }
  if (documentRow < sheetHeaderRowCount.value) {
    return headerRowEntityIds.value[documentRow] ?? ''
  }

  const localDataIndex = getLocalDataRowIndexFromDocumentDataIndex(documentRow - sheetHeaderRowCount.value)
  return localDataIndex >= 0 ? dataRowEntityIds.value[localDataIndex] ?? '' : ''
}

function getColumnEntityId(columnIndex: number) {
  return columnEntityIds.value[columnIndex] ?? ''
}

function getEntityCellAt(documentRow: number, columnIndex: number) {
  const rowId = getDocumentRowEntityId(documentRow)
  const columnId = getColumnEntityId(columnIndex)
  return rowId && columnId ? entityCells.value[rowId]?.[columnId] ?? null : null
}

function updateEntityCellEntry(
  documentRow: number,
  columnIndex: number,
  updater: (entry: SheetEntityCell) => SheetEntityCell | null,
) {
  const rowId = getDocumentRowEntityId(documentRow)
  const columnId = getColumnEntityId(columnIndex)
  if (!rowId || !columnId) {
    return
  }

  const nextCells: SheetEntityCellMap = { ...entityCells.value }
  const nextRowCells: Record<string, SheetEntityCell> = { ...(nextCells[rowId] ?? {}) }
  const nextEntry = normalizeEntityCellEntry(updater({ ...(nextRowCells[columnId] ?? {}) }))
  if (nextEntry) {
    nextRowCells[columnId] = nextEntry
  } else {
    delete nextRowCells[columnId]
  }

  if (Object.keys(nextRowCells).length) {
    nextCells[rowId] = nextRowCells
  } else {
    delete nextCells[rowId]
  }
  entityCells.value = nextCells
}

function setEntityCellRawValue(documentRow: number, columnIndex: number, value: string) {
  updateEntityCellEntry(documentRow, columnIndex, (entry) => {
    const nextEntry = { ...entry }
    const normalizedValue = normalizeCellValue(value)
    if (normalizedValue) {
      nextEntry.value = normalizedValue
    } else {
      delete nextEntry.value
    }
    return nextEntry
  })
}

function getHeaderEntityRowsForSnapshot(headerRows: SheetRow[]) {
  const used = new Set<string>()
  const sourceIds = [...headerRowEntityIds.value]
  const nextIds = headerRows.map((row, rowIndex) => (
    ensureUniqueSheetEntityId(
      normalizeSheetEntityId(sourceIds[rowIndex])
        || createFallbackSheetEntityId(
          getSheetEntityRowKind(rowIndex, columnHeaderLevel.value, headerRows.length),
          rowIndex,
          row.join('\u001f'),
        ),
      used,
      getSheetEntityRowKind(rowIndex, columnHeaderLevel.value, headerRows.length),
    )
  ))
  headerRowEntityIds.value = nextIds
  return nextIds.map((id, rowIndex) => {
    const row: SheetEntityRow = {
      id,
      kind: getSheetEntityRowKind(rowIndex, columnHeaderLevel.value, headerRows.length),
    }
    if (rowIndex === columnNoteHeaderLevel.value && columnNoteDisplayMode.value !== 'row') {
      row.hidden = true
    }
    return row
  })
}

function getColumnEntitiesForSnapshot(headers: string[]) {
  const used = new Set<string>()
  const sourceIds = [...columnEntityIds.value]
  const nextIds = headers.map((header, columnIndex) => (
    ensureUniqueSheetEntityId(
      normalizeSheetEntityId(sourceIds[columnIndex])
        || createFallbackSheetEntityId('col', columnIndex, header),
      used,
      'col',
    )
  ))
  columnEntityIds.value = nextIds
  return headers.map((header, index) => ({
    id: nextIds[index],
    header,
  }))
}

function getDataEntityRowsForSnapshot(normalizedRows: SheetRow[]) {
  const used = new Set(headerRowEntityIds.value)
  const sourceIds = [...dataRowEntityIds.value]
  const nextIds = normalizedRows.map((row, rowIndex) => (
    ensureUniqueSheetEntityId(
      normalizeSheetEntityId(sourceIds[rowIndex])
        || createFallbackSheetEntityId('row', getDocumentRowIndex(rowIndex), row.join('\u001f')),
      used,
      'row',
    )
  ))
  dataRowEntityIds.value = nextIds
  return nextIds.map((id) => ({ id, kind: 'data' as const }))
}

function buildLegacyCellMetaFromEntitySnapshot(
  entityRows: SheetEntityRow[],
  entityColumns: SheetEntityColumn[],
  cells: SheetEntityCellMap,
  sourceMeta: SheetCellMetaMap,
  getDocumentRow: (entityRowIndex: number) => number,
) {
  const nextMeta: SheetCellMetaMap = { ...normalizeCellMetaMap(sourceMeta, entityColumns.length) }
  entityRows.forEach((row, rowIndex) => {
    entityColumns.forEach((column, columnIndex) => {
      const key = createCellMetaKey(getDocumentRow(rowIndex), columnIndex)
      const meta = getEntityCellMeta(cells[row.id]?.[column.id])
      if (meta) {
        nextMeta[key] = meta
      } else {
        delete nextMeta[key]
      }
    })
  })
  return normalizeCellMetaMap(nextMeta, entityColumns.length)
}

function buildRowsWithInlineLinks(
  normalizedRows: SheetRow[],
  entityRows: SheetEntityRow[],
  entityColumns: SheetEntityColumn[],
  cells: SheetEntityCellMap,
  headerRowCount: number,
): SheetStoredRow[] {
  return normalizedRows.map((row, dataRowIndex) => {
    const entityRow = entityRows[headerRowCount + dataRowIndex]
    if (!entityRow) {
      return row
    }

    let changed = false
    const nextRow = row.map((value, columnIndex): SheetStoredCell => {
      const entityColumn = entityColumns[columnIndex]
      const link = entityColumn ? cells[entityRow.id]?.[entityColumn.id]?.link : null
      if (!link) {
        return value
      }
      changed = true
      return { value, link }
    })
    return changed ? nextRow : row
  })
}

function buildGridRowsWithInlineLinks(
  normalizedRows: SheetRow[],
  entityRows: SheetEntityRow[],
  entityColumns: SheetEntityColumn[],
  cells: SheetEntityCellMap,
): SheetStoredRow[] {
  return normalizedRows.map((row, rowIndex) => {
    const entityRow = entityRows[rowIndex]
    if (!entityRow) {
      return row
    }

    let changed = false
    const nextRow = row.map((value, columnIndex): SheetStoredCell => {
      const entityColumn = entityColumns[columnIndex]
      const link = entityColumn ? cells[entityRow.id]?.[entityColumn.id]?.link : null
      if (!link) {
        return value
      }
      changed = true
      return { value, link }
    })
    return changed ? nextRow : row
  })
}

function buildCurrentEntitySnapshot(headers: string[], normalizedRows: SheetRow[]) {
  const headerRows = sheetGridRows.value
    .slice(0, sheetHeaderRowCount.value)
    .map((row) => normalizeRow(row, headers))
  const entityColumns = getColumnEntitiesForSnapshot(headers)
  const headerEntityRows = getHeaderEntityRowsForSnapshot(headerRows)
  const dataEntityRows = getDataEntityRowsForSnapshot(normalizedRows)
  const entityRows = [...headerEntityRows, ...dataEntityRows]
  const documentRows = [...headerRows, ...normalizedRows]
  const getDocumentRow = (entityRowIndex: number) => (
    entityRowIndex < headerRows.length
      ? entityRowIndex
      : headerRows.length + getDocumentRowIndex(entityRowIndex - headerRows.length)
  )
  const nextCells: SheetEntityCellMap = {}

  entityRows.forEach((row, rowIndex) => {
    const sourceRowCells = entityCells.value[row.id] ?? {}
    const nextRowCells: Record<string, SheetEntityCell> = {}
    entityColumns.forEach((column, columnIndex) => {
      const existingCell = sourceRowCells[column.id]
      const existingMeta = getEntityCellMeta(existingCell)
      const legacyMeta = cellMeta.value[createCellMetaKey(getDocumentRow(rowIndex), columnIndex)] ?? null
      const cell = extractEntityCellForSave(
        documentRows[rowIndex]?.[columnIndex] ?? '',
        mergeCellMetaEntries(legacyMeta, existingMeta),
      )
      if (cell) {
        nextRowCells[column.id] = cell
      }
    })
    if (Object.keys(nextRowCells).length) {
      nextCells[row.id] = nextRowCells
    }
  })

  entityCells.value = nextCells
  return {
    entity_columns: entityColumns,
    entity_rows: entityRows,
    entity_cells: nextCells,
    cell_meta: buildLegacyCellMetaFromEntitySnapshot(entityRows, entityColumns, nextCells, cellMeta.value, getDocumentRow),
    rows: buildRowsWithInlineLinks(normalizedRows, entityRows, entityColumns, nextCells, headerRows.length),
  }
}

function getRenderableMergedCells() {
  const currentRows = sheetGridRows.value
  const normalized = normalizeMergedCells(
    [
      ...getHeaderGroupMergeCells(normalizedHeaderGroups.value),
      ...mergedCells.value,
    ],
    Math.max(sheetHeaderRowCount.value + totalRowCount.value, currentRows.length),
    columnHeaders.value.length,
  )

  const rendered: SheetMergedCell[] = []
  const seen = new Set<string>()
  normalized.forEach((cell) => {
    const isHeaderMerge = cell.row < sheetHeaderRowCount.value
    if (isHeaderMerge) {
      if (cell.row + cell.rowspan > sheetHeaderRowCount.value) {
        return
      }
      const key = `${cell.row}:${cell.col}`
      if (!seen.has(key)) {
        seen.add(key)
        rendered.push(cell)
      }
      return
    }

    const row = getCurrentGridRowIndexFromDocumentRow(cell.row)
    if (row < sheetHeaderRowCount.value) {
      return
    }
    if (cell.rowspan > 1) {
      const allRowsVisible = Array.from({ length: cell.rowspan }, (_, offset) => (
        getCurrentGridRowIndexFromDocumentRow(cell.row + offset)
      )).every((gridRow, index) => gridRow === row + index)
      if (!allRowsVisible) {
        return
      }
    }
    const key = `${row}:${cell.col}`
    if (!seen.has(key)) {
      seen.add(key)
      rendered.push({ ...cell, row })
    }
  })
  return rendered
}

function findMergedCellAtDocumentCell(documentRow: number, columnIndex: number) {
  return normalizeMergedCells(
    [
      ...getHeaderGroupMergeCells(normalizedHeaderGroups.value),
      ...mergedCells.value,
    ],
    Math.max(sheetHeaderRowCount.value + totalRowCount.value, sheetGridRows.value.length),
    columnHeaders.value.length,
  ).find((cell) => (
    documentRow >= cell.row
    && documentRow < cell.row + cell.rowspan
    && columnIndex >= cell.col
    && columnIndex < cell.col + cell.colspan
  )) ?? null
}

function findMergedCellAtGridCell(gridRowIndex: number, columnIndex: number) {
  const documentRow = getDocumentGridRowIndex(gridRowIndex)
  return findMergedCellAtDocumentCell(documentRow, columnIndex)
}

function getMergeAnchorForGridCell(gridRowIndex: number, columnIndex: number) {
  const merge = findMergedCellAtGridCell(gridRowIndex, columnIndex)
  if (!merge) {
    return { row: gridRowIndex, column: columnIndex, documentRow: getDocumentGridRowIndex(gridRowIndex) }
  }
  const row = getCurrentGridRowIndexFromDocumentRow(merge.row)
  return {
    row: row >= 0 ? row : gridRowIndex,
    column: merge.col,
    documentRow: merge.row,
  }
}

function getMergeAnchorForDocumentCell(documentRow: number, columnIndex: number) {
  const merge = findMergedCellAtDocumentCell(documentRow, columnIndex)
  if (!merge) {
    return {
      row: getCurrentGridRowIndexFromDocumentRow(documentRow),
      column: columnIndex,
      documentRow,
    }
  }
  return {
    row: getCurrentGridRowIndexFromDocumentRow(merge.row),
    column: merge.col,
    documentRow: merge.row,
  }
}

function normalizeSheetCellToMergeAnchor(cell: SelectedSheetCell): SelectedSheetCell {
  const anchor = getMergeAnchorForDocumentCell(cell.documentRow, cell.column)
  return {
    row: anchor.row >= 0 ? anchor.row : cell.row,
    column: anchor.column,
    documentRow: anchor.documentRow,
  }
}

function normalizeSheetCellsToMergeAnchors(cells: SelectedSheetCell[]) {
  const normalized: SelectedSheetCell[] = []
  const seen = new Set<string>()
  cells.forEach((cell) => {
    const anchor = normalizeSheetCellToMergeAnchor(cell)
    const key = createCellMetaKey(anchor.documentRow, anchor.column)
    if (seen.has(key)) {
      return
    }
    seen.add(key)
    normalized.push(anchor)
  })
  return normalized
}

function getGridCellRawValue(gridRowIndex: number, columnIndex: number) {
  return normalizeCellValue(sheetGridRows.value[gridRowIndex]?.[columnIndex] ?? '')
}

function getLiveGridCellRawValue(gridRowIndex: number, columnIndex: number) {
  const hot = getHotInstance()
  if (!hot || gridRowIndex < 0 || columnIndex < 0) {
    return ''
  }

  return normalizeCellValue(hot.getSourceDataAtCell?.(gridRowIndex, toHotColumnIndex(columnIndex)) ?? '')
}

function getGridCellRenderSourceValue(gridRowIndex: number, columnIndex: number) {
  const rawValue = getGridCellRawValue(gridRowIndex, columnIndex)
  if (rawValue || gridRowIndex >= columnHeaderLevel.value) {
    return rawValue
  }

  const merge = findMergedCellAtGridCell(gridRowIndex, columnIndex)
  if (!merge || merge.row >= columnHeaderLevel.value) {
    return rawValue
  }
  return inferBlankHeaderMergeLabel(sheetGridRows.value, columnHeaders.value, merge, columnHeaderLevel.value)
}

const nestedHeaderStyleRows = computed<(SheetHeaderCellStyle | null)[][]>(() => {
  const rows: (SheetHeaderCellStyle | null)[][] = []
  const themeCells = getTopHeaderThemeCells(normalizedHeaderGroups.value, columnHeaders.value)
  const depth = normalizedHeaderGroups.value.length + 1
  const useAutoTheme = normalizedHeaderGroups.value.length > 0

  normalizedHeaderGroups.value.forEach((row, level) => {
    rows.push(resolveHeaderStyleRow(
      expandHeaderGroupStyles(row, columnHeaders.value.length),
      themeCells,
      level,
      depth,
      useAutoTheme,
    ))
  })

  const fieldHeaderStyleRow = resolveHeaderStyleRow(
    columnHeaders.value.map((header) => getColumnHeaderStyle(columnConfigs.value[header])),
    themeCells,
    normalizedHeaderGroups.value.length,
    depth,
    useAutoTheme,
  )
  rows.push(resolveFieldHeaderStyleRow(fieldHeaderStyleRow, rows))
  return rows
})

const sheetRowHeaders = computed<false | ((index: number) => string)>(() => (
  sheetViewSettings.value.show_row_numbers ? getSheetRowHeaderLabel : false
))
const runtimeSheetHeightMode = computed(() => normalizeSheetHeightMode(
  props.runtimeHeightMode,
  sheetViewSettings.value.height_mode,
))
const isContentHeightMode = computed(() => runtimeSheetHeightMode.value === 'content')

function findColumnIndexByBinding(binding: { header: string, fallbackIndex: number }) {
  const headerIndex = columnHeaders.value.findIndex((header) => normalizeCellValue(header).trim() === binding.header)
  if (headerIndex >= 0) {
    return headerIndex
  }
  return binding.fallbackIndex >= 0 && binding.fallbackIndex < columnHeaders.value.length
    ? binding.fallbackIndex
    : -1
}

function isRegistrationStandardUserIdHeaderColumn(column: number, headerLevel: number) {
  if (headerLevel !== normalizedHeaderGroups.value.length) {
    return false
  }
  const header = normalizeCellValue(columnHeaders.value[column] ?? '').trim()
  if (!REGISTRATION_STANDARD_USER_ID_HEADERS.has(header)) {
    return false
  }
  const headers = new Set(columnHeaders.value.map((item) => normalizeCellValue(item).trim()))
  return headers.has('匹配得分') && headers.has('参考信息')
}

const attendanceCompletedColumnIndex = computed(() => findColumnIndexByBinding(ATTENDANCE_FIELD_BINDINGS.completedDate))

const sheetGridHeight = computed(() => {
  if (isContentHeightMode.value || sheetViewportHeight.value === 'auto') {
    return 'auto'
  }
  const maxGridHeight = Math.floor(Number(props.runtimeMaxGridHeight))
  const constrainedHeight = Number.isFinite(maxGridHeight) && maxGridHeight > 0
    ? Math.min(sheetViewportHeight.value, maxGridHeight)
    : sheetViewportHeight.value
  return Math.max(constrainedHeight, 80)
})

