            },
          },
          {
            key: 'cell_format:paste',
            name: () => (getSelectedSheetCells().length > 1 ? '粘贴到选区' : '粘贴'),
            hidden: () => !hasSheetCellSelection() || !canEditConfig.value || !hasCopiedCellFormat(),
            callback: () => {
              pasteCellFormatToSelectedCells()
