}

type SheetContextMenuConfig = typeof contextMenu
type SheetContextMenuItemConfig = Record<string, any>

function resolveContextMenuItemName(name: unknown, thisArg: unknown, args: unknown[]) {
  if (typeof name === 'function') {
    return String(name.apply(thisArg, args))
  }
  return String(name ?? '')
}

function isContextMenuItemHidden(item: SheetContextMenuItemConfig) {
  return typeof item.hidden === 'function' ? !!item.hidden() : !!item.hidden
}

function isContextMenuItemDisabled(item: SheetContextMenuItemConfig) {
  return typeof item.disabled === 'function' ? !!item.disabled() : !!item.disabled
}

function createTouchTreeContextMenu(baseMenu: SheetContextMenuConfig) {
  const items: SheetContextMenuItemConfig = {}
  Object.entries(baseMenu.items).forEach(([key, item]) => {
    const submenuItems = Array.isArray(item.submenu?.items) ? item.submenu.items : null
    if (!submenuItems?.length) {
      items[key] = item
      return
    }

    const hidden = () => isContextMenuItemHidden(item)
      || submenuItems.every((child: SheetContextMenuItemConfig) => isContextMenuItemHidden(child))
    if (typeof item.callback === 'function') {
      const { submenu: _submenu, ...parentItem } = item
      items[key] = {
        ...parentItem,
        hidden,
        disabled: () => isContextMenuItemDisabled(item),
      }
    } else {
      items[`${key}__group`] = {
        name: item.name,
        disabled: true,
        isCommand: false,
        hidden,
      }
    }

    submenuItems.forEach((child: SheetContextMenuItemConfig, index: number) => {
      // Handsontable treats ":" in command keys as submenu syntax. Touch fallback
      // flattens submenus, so flattened child keys must be plain top-level keys.
      const childKey = `${key}__touch_child_${index}`
      items[childKey] = {
        ...child,
        key: childKey,
        name(this: unknown, ...args: unknown[]) {
          return `\u00A0\u00A0${resolveContextMenuItemName(child.name, this, args)}`
        },
        hidden: () => isContextMenuItemHidden(item) || isContextMenuItemHidden(child),
      }
    })
  })
  return {
    ...baseMenu,
    items,
  }
}

const sheetHotRenderContextMenu = computed(() => (
  shouldUseEnhancedSheetRenderSettings.value
    ? (shouldEnableTouchContextMenuFallback() ? createTouchTreeContextMenu(contextMenu) : contextMenu)
    : false
))

function getCurrentSheetHotRenderSettings() {
  return {
    mergeCells: sheetHotRenderMergeCells.value,
    manualColumnResize: sheetHotRenderManualColumnResize.value,
    manualColumnMove: sheetHotRenderManualColumnMove.value,
    manualRowResize: sheetHotRenderManualRowResize.value,
    manualRowMove: sheetHotRenderManualRowMove.value,
    readOnly: sheetHotRenderReadOnly.value,
    contextMenu: sheetHotRenderContextMenu.value,
    cells: sheetHotRenderCellMetaResolver.value,
    rowHeights: sheetHotRenderRowHeightResolver.value,
    afterRenderer: sheetHotRenderAfterRenderer.value,
  }
}

function clearHotMergeCellsPlugin(hot: Handsontable | null | undefined) {
  if (!hot) {
    return
  }
  try {
    const plugin = (hot as unknown as { getPlugin?: (name: string) => unknown }).getPlugin?.('mergeCells') as SheetHotMergeCellsPlugin | undefined
    plugin?.clearCollections?.()
  } catch (error) {
    console.warn('Failed to clear sheet merged cells plugin state:', error)
  }
}

function shouldClearHotMergeCellsBeforeSettings(settings: Record<string, unknown>) {
  if (!Object.prototype.hasOwnProperty.call(settings, 'mergeCells')) {
    return false
  }
  const mergeCellsSetting = settings.mergeCells
  return mergeCellsSetting === false || (Array.isArray(mergeCellsSetting) && mergeCellsSetting.length === 0)
}

function updateHotSettingsWithMergeReset(hot: Handsontable, settings: Record<string, unknown>) {
  if (shouldClearHotMergeCellsBeforeSettings(settings)) {
    clearHotMergeCellsPlugin(hot)
  }
  hot.updateSettings(settings)
  if (shouldClearHotMergeCellsBeforeSettings(settings)) {
    clearHotMergeCellsPlugin(hot)
  }
}

function loadCurrentHotGridRows(hot: Handsontable | null | undefined) {
  if (!hot) {
    return
  }
  const rows = sheetHotGridRows.value
  markBootPerf('note-sheet-workspace.hot.loadData.start', {
    rows: rows.length,
    columns: rows[0]?.length ?? 0,
  })
  try {
    hot.loadData(rows)
  } finally {
    markBootPerf('note-sheet-workspace.hot.loadData.end')
  }
}

function resetHotInitialGridRowsLoaded() {
  hotInitialDataLoadedContentIdentity = ''
  hotInitialDataLoadedInstance = null
}

function ensureHotInitialGridRowsLoaded(reason: string) {
  const hot = getHotInstance()
  if (!hot || !sheetContentReady.value || !loadedSheetContentIdentity) {
    return false
  }
  if (
    hotInitialDataLoadedInstance === hot
    && hotInitialDataLoadedContentIdentity === loadedSheetContentIdentity
  ) {
    return true
  }
  loadCurrentHotGridRows(hot)
  hotInitialDataLoadedInstance = hot
  hotInitialDataLoadedContentIdentity = loadedSheetContentIdentity
  markBootPerf('note-sheet-workspace.hot.initialLoadData.done', {
    reason,
    identity: loadedSheetContentIdentity,
    rows: sheetHotGridRows.value.length,
    columns: sheetHotGridRows.value[0]?.length ?? 0,
  })
  recordSheetPerfEvent('handsontable.initialLoadData', {
    detail: {
      reason,
      identity: loadedSheetContentIdentity,
      gridRows: sheetHotGridRows.value.length,
      gridColumns: sheetHotGridRows.value[0]?.length ?? 0,
    },
  })
  return true
}

async function waitForHotInitialGridRowsLoaded(reason: string) {
  if (ensureHotInitialGridRowsLoaded(reason)) {
    return 'ready'
  }
  for (let attempt = 1; attempt <= 2; attempt += 1) {
    await nextTick()
    if (ensureHotInitialGridRowsLoaded(reason)) {
      return `next-tick-${attempt}`
    }
  }
  return 'pending'
}

function requestHotInitialGridRowsLoaded(reason: string) {
  if (ensureHotInitialGridRowsLoaded(reason)) {
    return
  }
  void nextTick(() => {
    ensureHotInitialGridRowsLoaded(reason)
  })
}

function isSheetDocumentHidden() {
  return typeof document !== 'undefined' && document.hidden
}

function measureSheetFrameSize(): SheetFrameSize | null {
  const sheetFrame = sheetFrameRef.value
  if (!sheetFrame) {
    return null
  }
  const frameRect = sheetFrame.getBoundingClientRect()
  const width = Math.floor(sheetFrame.clientWidth || frameRect.width)
  const height = Math.floor(sheetFrame.clientHeight || frameRect.height)
  if (!Number.isFinite(width) || !Number.isFinite(height) || width <= 0 || height <= 0) {
    return null
  }
  return { width, height }
}

function isSameSheetFrameSize(left: SheetFrameSize | null, right: SheetFrameSize | null) {
  return (
    !!left
    && !!right
    && Math.abs(left.width - right.width) <= SHEET_VISIBILITY_FRAME_SIZE_TOLERANCE_PX
    && Math.abs(left.height - right.height) <= SHEET_VISIBILITY_FRAME_SIZE_TOLERANCE_PX
  )
}

function clearSheetRenderEnhancementFrame() {
  if (sheetRenderEnhancementFrame == null || typeof window === 'undefined') {
    sheetRenderEnhancementFrame = null
    return
  }
  window.cancelAnimationFrame(sheetRenderEnhancementFrame)
  sheetRenderEnhancementFrame = null
}

function beginSheetCoreRenderPhase() {
  clearSheetRenderEnhancementFrame()
  clearInitialSheetActionStatusRefreshTimer()
  // Mounting once with enhanced settings is cheaper than mounting a core grid
  // and immediately forcing Handsontable through a second full updateSettings.
  sheetRenderPhase.value = 'ready'
}

function finishSheetRenderEnhancement() {
  clearSheetRenderEnhancementFrame()
  sheetRenderPhase.value = 'ready'
}

function scheduleSheetRenderEnhancement(isCurrent?: () => boolean) {
  clearSheetRenderEnhancementFrame()
  if (!sheetContentReady.value) {
    sheetRenderPhase.value = 'ready'
    return
  }
  if (typeof window === 'undefined') {
    sheetRenderPhase.value = 'ready'
    return
  }
  if (isSheetDocumentHidden()) {
    sheetRenderPhase.value = 'ready'
    return
  }

  sheetRenderEnhancementFrame = window.requestAnimationFrame(() => {
    sheetRenderEnhancementFrame = window.requestAnimationFrame(() => {
      sheetRenderEnhancementFrame = null
      void applySheetRenderEnhancement(isCurrent)
    })
  })
}

async function applySheetRenderEnhancement(isCurrent?: () => boolean) {
  if (isCurrent && !isCurrent()) {
    return
  }
  if (!sheetContentReady.value) {
    sheetRenderPhase.value = 'ready'
    return
  }

  const trace = startSheetPerfTrace('sheet.enhance', {
    detail: {
      fromPhase: sheetRenderPhase.value,
    },
  })
  sheetRenderPhase.value = 'enhancing'
  try {
    await nextTick()
    trace?.mark('vue-props-flush')
    if (isCurrent && !isCurrent()) {
      if (sheetRenderPhase.value === 'enhancing') {
        sheetRenderPhase.value = 'ready'
      }
      trace?.finish({ detail: { stale: true } })
      return
    }

    const hot = getHotInstance()
    if (hot) {
      trace?.mark('hot-ready')
      ensureHotInitialGridRowsLoaded('render-enhancement')
      void updateSheetViewportHeight('renderEnhancement')
    }
    if (isCurrent && !isCurrent()) {
      if (sheetRenderPhase.value === 'enhancing') {
        sheetRenderPhase.value = 'ready'
      }
      trace?.finish({ detail: { stale: true } })
      return
    }
    sheetRenderPhase.value = 'ready'
    trace?.finish({
      detail: {
        stale: false,
        rowCount: rows.value.length,
        columnCount: columnHeaders.value.length,
      },
    })
  } catch (error) {
    if (!isCurrent || isCurrent()) {
      sheetRenderPhase.value = 'ready'
    }
    trace?.finish({
      detail: {
        stale: !!isCurrent && !isCurrent(),
        error: error instanceof Error ? error.message : String(error),
      },
    })
    console.warn('Failed to enhance note sheet render:', error)
  }
}

type SheetContextMenuItem = {
  key?: string
}

type SheetContextMenuPlugin = {
  close?: () => void
  open?: (
    position: { left: number; top: number } | Event,
    offset?: { above?: number; below?: number; left?: number; right?: number },
  ) => void
  menu?: {
    hotMenu?: Handsontable
  }
}

function warnReadOnlyAction() {
  if (shouldSuppressReadOnlyActionWarning()) {
    return
  }
  ElMessage.warning('只读权限不能执行此操作')
}

function shouldSuppressReadOnlyActionWarning() {
  return (
    suppressPersistence
    || workspaceLoading.value
    || !sheetContentReady.value
    || readOnlyActionWarningsSuppressedForRender
  )
}

function suppressReadOnlyActionWarningsForSheetRender() {
  readOnlyActionWarningsSuppressedForRender = true
  if (readOnlyActionWarningSuppressTimer != null) {
    window.clearTimeout(readOnlyActionWarningSuppressTimer)
  }
  readOnlyActionWarningSuppressTimer = window.setTimeout(() => {
    readOnlyActionWarningSuppressTimer = null
    readOnlyActionWarningsSuppressedForRender = false
  }, 800)
}

function canEditDataColumn(columnIndex: number) {
  return canEditData.value || editableDataColumnSet.value.has(columnIndex)
}

function canEditFormulaBarCell() {
  const cell = formulaBarCell.value
  if (!cell) {
    return false
  }
  return cell.dataRow >= 0 ? canEditDataColumn(cell.column) : canEditConfig.value
}

function isColumnRangeEditable(startColumn: number, endColumn: number) {
  if (canEditData.value) {
    return true
  }
  for (let columnIndex = startColumn; columnIndex <= endColumn; columnIndex += 1) {
    if (!editableDataColumnSet.value.has(columnIndex)) {
      return false
    }
  }
  return true
}

function warnReadOnlyColumnAction() {
  if (shouldSuppressReadOnlyActionWarning()) {
    return
  }
  ElMessage.warning('当前列只读，不能修改')
}

function ensureCanEditData() {
  if (canEditData.value) {
    return true
  }
  warnReadOnlyAction()
  return false
}

function ensureCanEditConfig() {
  if (canEditConfig.value) {
    return true
  }
  warnReadOnlyAction()
  return false
}

function ensureCanRunSheetActions() {
  if (canRunSheetActions.value) {
    return true
  }
  warnReadOnlyAction()
  return false
}

function getSheetCellActionAtDocumentCell(documentRow: number, columnIndex: number) {
  return getCellActionAt(documentRow, columnIndex)
}

function canOpenExcelImportDialog() {
  return props.sheetId != null && canEditData.value && canRunSheetActions.value
}

function canRunRegistrationMatchAction() {
  return props.sheetId != null && canEditData.value && canRunSheetActions.value
}

function canExportAttendanceSheet() {
  return props.sheetId != null && canEditData.value && canRunSheetActions.value
}

function canDetectClockinLinks() {
  return props.sheetId != null && canEditData.value && canRunSheetActions.value
}

function canRunAttendanceCourseUpdateData() {
  return props.sheetId != null && canEditData.value && canRunSheetActions.value && !!attendanceCourseUpdateTarget.value
}

function isAttendanceCurrentRefundColumn(columnIndex: number) {
  return normalizeCellValue(columnHeaders.value[columnIndex] ?? '').trim() === '当前应返款'
}

function getSelectedAttendanceCourseUpdateDataCell() {
  const cell = getSingleSelectedSheetCell()
  const noteRowIndex = columnNoteHeaderLevel.value
  if (
    !cell
    || noteRowIndex < 0
    || cell.documentRow !== noteRowIndex
    || !isAttendanceCurrentRefundColumn(cell.column)
  ) {
    return null
  }
  return cell
}

function canRunAttendanceCourseUpdateDataFromSelection() {
  return !!getSelectedAttendanceCourseUpdateDataCell() && canRunAttendanceCourseUpdateData()
}

function isAttendanceRefundedColumn(columnIndex: number) {
  return normalizeCellValue(columnHeaders.value[columnIndex] ?? '').trim() === '已返款'
}

function getSelectedAttendanceRefundedColumnIndex() {
  const selection = normalizeHotSelectionRange(getHotInstance()?.getSelectedLast())
  if (!selection) {
    return null
  }
  const range = getSheetColumnRangeFromHotRange(selection[1], selection[3])
  if (!range) {
    return null
  }
  for (let columnIndex = range.start; columnIndex <= range.end; columnIndex += 1) {
    if (isAttendanceRefundedColumn(columnIndex)) {
      return columnIndex
    }
  }
  return null
}

function canCheckAttendanceRefundedAmountsFromSelection() {
  return (
    props.sheetId != null
    && canRunSheetActions.value
    && !attendanceRefundedCheckRunning.value
    && getSelectedAttendanceRefundedColumnIndex() != null
  )
}

function buildAttendanceRefundedCheckMessage(result: AttendanceSheetRefundedCheckResponse) {
  const summary = result.summary
  if (!summary.warning_count) {
    return `已核对 ${summary.checked_count}/${summary.total_count} 行，当前表格已返款与历史返款记录一致。`
  }
  const issueRows = (result.rows || []).filter((row) => row.status !== 'matched')
  const issueLines = issueRows.slice(0, 12).map((row) => {
    const label = [row.student_no, row.student_name].filter(Boolean).join(' ')
    const detail = row.status === 'mismatch'
      ? `表格 ${row.sheet_refunded_amount || 0} / 历史记录 ${row.payment_refunded_amount || 0}`
      : (row.message || row.status)
    return `${row.row_number}行 ${label}: ${detail}`
  })
  const moreText = issueRows.length > issueLines.length ? `\n还有 ${issueRows.length - issueLines.length} 条未显示。` : ''
  return [
    `已核对 ${summary.checked_count}/${summary.total_count} 行，发现 ${summary.warning_count} 条需要处理。`,
    ...issueLines,
  ].join('\n') + moreText
}

async function checkSelectedAttendanceRefundedAmounts() {
  if (props.sheetId == null || attendanceRefundedCheckRunning.value) {
    return
  }
  if (!canRunSheetActions.value) {
    warnReadOnlyAction()
    return
  }
  attendanceRefundedCheckRunning.value = true
  try {
    const result = await checkAttendanceSheetRefundedAmounts(props.sheetId, {
      workbook_id: props.workbookId ?? null,
    })
    const message = buildAttendanceRefundedCheckMessage(result)
    if (result.summary.warning_count > 0) {
      await ElMessageBox.alert(message, '检查已返款', {
        confirmButtonText: '知道了',
        customClass: 'sheet-refunded-check-message',
      })
    } else {
      await ElMessageBox.alert(message, '检查已返款', {
        confirmButtonText: '知道了',
        customClass: 'sheet-refunded-check-message',
        type: 'success',
      })
    }
  } catch (error) {
    ElMessage.error(getSheetActionErrorMessage(error, '检查已返款失败'))
  } finally {
    attendanceRefundedCheckRunning.value = false
  }
}

function isSheetCellActionDisabledByPermission(actionType: SheetCellActionType) {
  if (actionType === SHEET_CELL_ACTION_EXCEL_IMPORT_RESET) {
    return !canOpenExcelImportDialog()
  }
  if (actionType === SHEET_CELL_ACTION_REGISTRATION_ADD_STUDENT) {
    return !(props.sheetId != null && canEditData.value)
  }
  if (
    actionType === SHEET_CELL_ACTION_REGISTRATION_ORDER_MATCH
    || actionType === SHEET_CELL_ACTION_REGISTRATION_USER_MATCH
    || actionType === SHEET_CELL_ACTION_REGISTRATION_COMPOSITE_UPDATE
  ) {
    return !canRunRegistrationMatchAction()
  }
  if (actionType === SHEET_CELL_ACTION_ATTENDANCE_EXPORT) {
    return !canExportAttendanceSheet()
  }
  if (actionType === SHEET_CELL_ACTION_CLOCKIN_LINK_DETECT) {
    return !canDetectClockinLinks()
  }
  if (actionType === SHEET_CELL_ACTION_ATTENDANCE_COURSE_UPDATE_DATA) {
    return !canRunAttendanceCourseUpdateData()
  }
  return false
}

function getSheetActionErrorMessage(error: unknown, fallback: string) {
  const maybeError = error as { response?: { data?: { detail?: unknown } }, message?: string }
  const detail = maybeError?.response?.data?.detail
  return typeof detail === 'string' && detail.trim()
    ? detail
    : maybeError?.message || fallback
}

function getExcelImportErrorMessage(error: unknown) {
  return getSheetActionErrorMessage(error, '导入 Excel 失败')
}

const isAttendanceWjxDataSheet = computed(() => (
  sheetTitle.value.trim() === ATTENDANCE_WJX_DATA_TITLE
  && ATTENDANCE_WJX_SIGNAL_HEADERS.every((header) => findHeaderIndex(columnHeaders.value, header) >= 0)
))

function parsePositiveIntegerCellValue(value: unknown) {
  const text = normalizeCellValue(value).trim()
  if (!/^\d+(?:\.0+)?$/.test(text)) {
    return 0
  }
  const numeric = Number(text)
  return Number.isInteger(numeric) && numeric > 0 ? numeric : 0
}

function getSelectedAttendanceWjxAiPrecheckCell() {
  if (!isOriginalSheetViewActive.value || !isAttendanceWjxDataSheet.value) {
    return null
  }

  const cell = getSingleSelectedDataCell()
  const aiColumn = findHeaderIndex(columnHeaders.value, ATTENDANCE_WJX_AI_HEADER)
  if (!cell || aiColumn < 0 || cell.column !== aiColumn) {
    return null
  }

  const sequenceColumn = findHeaderIndex(columnHeaders.value, ATTENDANCE_WJX_SEQUENCE_HEADER)
  if (sequenceColumn < 0) {
    return null
  }
  const seq = parsePositiveIntegerCellValue(rows.value[cell.row]?.[sequenceColumn])
  return seq > 0 ? { ...cell, seq } : null
}

function canRunAttendanceWjxAiPrecheckFromSelection() {
  return !!getSelectedAttendanceWjxAiPrecheckCell()
}

async function handleRunAttendanceWjxAiPrecheckFromSelection(options: { autoRepair?: boolean } = {}) {
  const selectedCell = getSelectedAttendanceWjxAiPrecheckCell()
  if (!selectedCell) {
    ElMessage.warning('请选择一个 AI初判 单元格')
    return
  }
  if (!ensureCanRunSheetActions() || attendanceWjxAiPrecheckRunning.value) {
    return
  }

  attendanceWjxAiPrecheckRunning.value = true
  try {
    commitPendingSheetGridEdit()
    await flushRemoteSave()
    const result = await runAttendanceWjxDataAiPrecheck(selectedCell.seq, {
      persist: true,
      use_codex_cli: true,
      auto_repair: !!options.autoRepair,
      repair_with_remote_browser: true,
    })
    await restoreInitialDocument({ preserveContent: true })
    const summary = normalizeCellValue(result.precheck?.summary).trim()
    const autoRepair = result.precheck?.auto_repair as Record<string, unknown> | undefined
    const repairSummary = normalizeCellValue(autoRepair?.summary).trim()
    if (options.autoRepair && repairSummary) {
      ElMessage.success(`AI初判完成：${repairSummary}`)
    } else {
      ElMessage.success(summary ? `AI初判完成：${summary}` : 'AI初判已生成')
    }
  } catch (error) {
    console.warn('Failed to run attendance wjx AI precheck', error)
    ElMessage.error(getSheetActionErrorMessage(error, 'AI初判失败'))
  } finally {
    attendanceWjxAiPrecheckRunning.value = false
  }
}

function clearUserMatchRunPollTimer() {
  if (userMatchRunPollTimer) {
    clearTimeout(userMatchRunPollTimer)
    userMatchRunPollTimer = null
  }
}

function clearInitialSheetActionStatusRefreshTimer() {
  if (initialSheetActionStatusRefreshTimer) {
    clearTimeout(initialSheetActionStatusRefreshTimer)
    initialSheetActionStatusRefreshTimer = null
  }
}

function refreshInitialSheetActionStatuses() {
  void refreshAttendanceCourseScriptStatuses()
  if (hasRegistrationAsyncActionCells()) {
    void refreshUserMatchRunStatus(undefined, { silent: true })
  }
  if (hasClockinLinkDetectionActionCells()) {
    void refreshClockinLinkDetectionRunStatus(undefined, { silent: true })
  }
}

function scheduleInitialSheetActionStatusRefresh() {
  clearInitialSheetActionStatusRefreshTimer()
  if (props.sheetId == null) {
    return
  }
  const scheduledSheetId = props.sheetId
  const scheduledWorkbookId = props.workbookId
  const run = () => {
    initialSheetActionStatusRefreshTimer = null
    if (
      props.sheetId !== scheduledSheetId
      || props.workbookId !== scheduledWorkbookId
      || !sheetContentReady.value
    ) {
      return
    }
    refreshInitialSheetActionStatuses()
  }
  if (typeof window === 'undefined') {
    run()
    return
  }
  initialSheetActionStatusRefreshTimer = window.setTimeout(
    run,
    INITIAL_SHEET_ACTION_STATUS_REFRESH_DELAY_MS,
  )
}

function scheduleUserMatchRunPolling() {
  clearUserMatchRunPollTimer()
  const runId = userMatchRunStatus.value?.run_id
  if (!runId || !activeRegistrationActionRun.value || props.sheetId == null) {
    return
  }
  userMatchRunPollTimer = setTimeout(() => {
    void refreshUserMatchRunStatus(runId)
  }, REGISTRATION_MATCH_RUN_POLL_MS)
}

function notifyUserMatchRunTerminalStatus(run: NoteSheetRegistrationMatchRunResponse) {
  if (!run.run_id || isRegistrationMatchRunActive(run) || run.status === 'idle') {
    return
  }
  if (lastNotifiedUserMatchRunId === run.run_id && lastNotifiedUserMatchRunStatus === run.status) {
    return
  }
  lastNotifiedUserMatchRunId = run.run_id
  lastNotifiedUserMatchRunStatus = run.status
  const actionLabel = SHEET_CELL_ACTION_LABELS[run.action as SheetCellActionType] || '任务'

  if (run.status === 'completed') {
    const warningCount = Number(run.warning_count || 0)
    const hasNoEffectiveUpdate = !run.updated_count && (run.total_count > 0 || run.skipped_count > 0)
    const message = run.message || `${actionLabel}已完成`
    if (run.error_count || warningCount || hasNoEffectiveUpdate) {
      ElMessage.warning(message)
    } else {
      ElMessage.success(message)
    }
  } else if (run.status === 'failed') {
    ElMessage.error(run.error_message || run.message || `${actionLabel}失败`)
  } else if (run.status === 'cancelled') {
    ElMessage.warning(run.message || `${actionLabel}已取消`)
  }
}

async function refreshUserMatchRunStatus(runId?: string, options: { silent?: boolean } = {}) {
  if (props.sheetId == null) {
    return null
  }
  try {
    const status = runId
      ? await fetchNoteSheetRegistrationMatchRun(props.sheetId, runId, { workbookId: props.workbookId })
      : await fetchNoteSheetActiveRegistrationMatchRun(
        props.sheetId,
        undefined,
        { workbookId: props.workbookId },
      )

    userMatchRunStatus.value = status.status === 'idle' ? null : status
    if (status.status !== 'idle') {
      userMatchUseBrowserFallback.value = status.use_browser_fallback
      applyRegistrationActionRunSheetDetail(status)
      renderCurrentHotWithReason('registration-run-poll')
    }
    if (isRegistrationMatchRunActive(status)) {
      scheduleUserMatchRunPolling()
    } else {
      clearUserMatchRunPollTimer()
      if (!options.silent) {
        notifyUserMatchRunTerminalStatus(status)
      }
    }
    return status
  } catch (error) {
    clearUserMatchRunPollTimer()
    console.warn('Failed to refresh registration user match run', error)
    if (!options.silent) {
      ElMessage.error(getSheetActionErrorMessage(error, '刷新任务状态失败'))
    }
    return null
  }
}

function clearClockinLinkDetectionRunPollTimer() {
  if (clockinLinkDetectionRunPollTimer) {
    clearTimeout(clockinLinkDetectionRunPollTimer)
    clockinLinkDetectionRunPollTimer = null
  }
}

function scheduleClockinLinkDetectionRunPolling() {
  clearClockinLinkDetectionRunPollTimer()
  const runId = clockinLinkDetectionRunStatus.value?.run_id
  if (!runId || !activeClockinLinkDetectionRun.value || props.sheetId == null) {
    return
  }
  clockinLinkDetectionRunPollTimer = setTimeout(() => {
    void refreshClockinLinkDetectionRunStatus(runId)
  }, REGISTRATION_MATCH_RUN_POLL_MS)
}

function notifyClockinLinkDetectionRunTerminalStatus(run: NoteSheetClockinLinkDetectionRunResponse) {
  if (!run.run_id || isClockinLinkDetectionRunActive(run) || run.status === 'idle') {
    return
  }
  if (lastNotifiedClockinLinkDetectionRunId === run.run_id && lastNotifiedClockinLinkDetectionRunStatus === run.status) {
    return
  }
  lastNotifiedClockinLinkDetectionRunId = run.run_id
  lastNotifiedClockinLinkDetectionRunStatus = run.status
  const actionLabel = SHEET_CELL_ACTION_LABELS[SHEET_CELL_ACTION_CLOCKIN_LINK_DETECT]

  if (run.status === 'completed') {
    const message = run.message || `${actionLabel}完成`
    if (run.error_count || run.warning_count) {
      ElMessage.warning(message)
    } else {
      ElMessage.success(message)
    }
  } else if (run.status === 'failed') {
    ElMessage.error(run.error_message || run.message || `${actionLabel}失败`)
  } else if (run.status === 'cancelled') {
    ElMessage.warning(run.message || `${actionLabel}已取消`)
  }
}

async function refreshClockinLinkDetectionRunStatus(runId?: string, options: { silent?: boolean } = {}) {
  if (props.sheetId == null) {
    return null
  }
  try {
    const status = runId
      ? await fetchNoteSheetClockinLinkDetectionRun(props.sheetId, runId, { workbookId: props.workbookId })
      : await fetchNoteSheetActiveClockinLinkDetectionRun(props.sheetId, { workbookId: props.workbookId })

    clockinLinkDetectionRunStatus.value = status.status === 'idle' ? null : status
    if (status.status !== 'idle') {
      applyClockinLinkDetectionRunSheetDetail(status)
      renderCurrentHotWithReason('clockin-link-detection-poll')
    }
    if (isClockinLinkDetectionRunActive(status)) {
      scheduleClockinLinkDetectionRunPolling()
    } else {
      clearClockinLinkDetectionRunPollTimer()
      if (!options.silent) {
        notifyClockinLinkDetectionRunTerminalStatus(status)
      }
    }
    return status
  } catch (error) {
    clearClockinLinkDetectionRunPollTimer()
    console.warn('Failed to refresh clockin link detection run', error)
    if (!options.silent) {
      ElMessage.error(getSheetActionErrorMessage(error, '刷新打卡链接检测状态失败'))
    }
    return null
  }
}

function openExcelImportDialog(actionCell: { documentRow: number; column: number }) {
  if (!canOpenExcelImportDialog()) {
    warnReadOnlyAction()
    return
  }
  excelImportActionCell.value = actionCell
  excelImportFile.value = null
  excelImportInstruction.value = ''
  if (excelImportFileInputRef.value) {
    excelImportFileInputRef.value.value = ''
  }
  excelImportDialogVisible.value = true
}

function closeExcelImportDialog(force = false) {
  if (excelImportRunning.value && !force) {
    return
  }
  excelImportDialogVisible.value = false
  excelImportActionCell.value = null
  excelImportFile.value = null
  excelImportInstruction.value = ''
  if (excelImportFileInputRef.value) {
    excelImportFileInputRef.value.value = ''
  }
}

function openUserMatchDialog() {
  if (!canRunRegistrationMatchAction()) {
    warnReadOnlyAction()
    return
  }
  if (!activeUserMatchRun.value) {
    userMatchUseBrowserFallback.value = true
  }
  userMatchDialogVisible.value = true
  void refreshUserMatchRunStatus(undefined, { silent: true })
}

function closeUserMatchDialog() {
  userMatchDialogVisible.value = false
  if (!activeUserMatchRun.value) {
    userMatchUseBrowserFallback.value = true
  }
}

function handleExcelImportFileChange(event: Event) {
  const input = event.target as HTMLInputElement | null
  excelImportFile.value = input?.files?.[0] ?? null
}

async function applyExcelImport(mode: NoteSheetExcelImportMode) {
  if (props.sheetId == null || !excelImportFile.value) {
    ElMessage.warning('请选择 Excel 文件')
    return
  }
  if (!canOpenExcelImportDialog()) {
    warnReadOnlyAction()
    return
  }

  excelImportRunningMode.value = mode
  try {
    commitPendingSheetGridEdit()
    await flushRemoteSave()
    clearSaveTimer()
    const result = await importNoteSheetFromExcel(
      props.sheetId,
      {
        file: excelImportFile.value,
        instruction: excelImportInstruction.value,
        mode,
        actionCell: excelImportActionCell.value ?? undefined,
        baseVersion: Number(sheetVersion.value || 1),
      },
      { workbookId: props.workbookId },
    )
    clearSaveTimer()
    clearDraftStorage()
    applyRemoteSheetDetail(result.sheet)
    const extraColumnSuffix = result.extra_columns.length
      ? `，追加 ${result.extra_columns.length} 列`
      : ''
    const skippedDuplicateSuffix = result.skipped_duplicate_count
      ? `，跳过重复订单 ${result.skipped_duplicate_count} 行`
      : ''
    const warningSuffix = result.warnings.length ? `，${result.warnings[0]}` : ''
    const modeText = mode === 'append'
      ? `已添加 ${result.imported_count} 行新表数据`
      : `已清空原表数据并导入 ${result.imported_count} 行新表数据`
    ElMessage.success(`${modeText}${extraColumnSuffix}${skippedDuplicateSuffix}${warningSuffix}`)
    closeExcelImportDialog(true)
  } catch (error) {
    console.warn('Failed to import note sheet from Excel', error)
    if (getNoteSheetApiErrorStatus(error) === 409) {
      sheetRemoteConflictActive = true
      ElMessage.warning('工作表已被其他人更新，已保留本地状态，请刷新后合并')
    } else {
      ElMessage.error(getExcelImportErrorMessage(error))
    }
  } finally {
    excelImportRunningMode.value = null
  }
}

async function downloadAttendanceExport() {
  if (props.sheetId == null) {
    return
  }
  if (!canExportAttendanceSheet()) {
    warnReadOnlyAction()
    return
  }
  if (sheetCellActionRunning.value) {
    return
  }

  sheetCellActionRunning.value = SHEET_CELL_ACTION_ATTENDANCE_EXPORT
  try {
    commitPendingSheetGridEdit()
    await flushRemoteSave()
    const result = await exportAttendanceSheet(props.sheetId, { workbookId: props.workbookId })
    const url = window.URL.createObjectURL(result.blob)
    const anchor = document.createElement('a')
    anchor.href = url
    anchor.download = result.filename || '考勤表.xlsx'
    document.body.appendChild(anchor)
    anchor.click()
    anchor.remove()
    window.URL.revokeObjectURL(url)
    ElMessage.success('已导出考勤表')
  } catch (error) {
    console.warn('Failed to export attendance sheet', error)
    ElMessage.error(getSheetActionErrorMessage(error, '导出考勤表失败'))
  } finally {
    sheetCellActionRunning.value = null
  }
}

async function startClockinLinkDetectionRun(forceRestart = false) {
  if (props.sheetId == null) {
    return
  }
  if (!canDetectClockinLinks()) {
    warnReadOnlyAction()
    return
  }
  if (activeClockinLinkDetectionRun.value && !forceRestart) {
    ElMessage.info(clockinLinkDetectionRunStatus.value?.message || '已有打卡链接检测任务正在运行')
    return
  }
  if (sheetCellActionRunning.value) {
    return
  }

  sheetCellActionRunning.value = SHEET_CELL_ACTION_CLOCKIN_LINK_DETECT
  try {
    commitPendingSheetGridEdit()
    await flushRemoteSave()
    const status = await startNoteSheetClockinLinkDetectionRun(
      props.sheetId,
      { forceRestart },
      { workbookId: props.workbookId },
    )
    clockinLinkDetectionRunStatus.value = status
    applyClockinLinkDetectionRunSheetDetail(status)
    renderCurrentHotWithReason('clockin-link-detection-start')
    ElMessage.success(status.already_running ? '已有打卡链接检测任务正在运行' : '已在后台开始自动检测打卡链接')
    if (isClockinLinkDetectionRunActive(status)) {
      scheduleClockinLinkDetectionRunPolling()
    } else {
      notifyClockinLinkDetectionRunTerminalStatus(status)
    }
  } catch (error) {
    console.warn('Failed to start clockin link detection run', error)
    ElMessage.error(getSheetActionErrorMessage(error, '启动自动检测打卡链接失败'))
  } finally {
    sheetCellActionRunning.value = null
  }
}

async function updateAttendanceCourseData() {
  if (props.sheetId == null) {
    return
  }
  if (!canRunAttendanceCourseUpdateData()) {
    warnReadOnlyAction()
    return
  }
  if (sheetCellActionRunning.value) {
    return
  }

  const target = attendanceCourseUpdateTarget.value
  if (!target) {
    ElMessage.warning('没有识别到梵呗/念住/觉观/禅宗/修道班课程名')
    return
  }

  sheetCellActionRunning.value = SHEET_CELL_ACTION_ATTENDANCE_COURSE_UPDATE_DATA
  try {
    commitPendingSheetGridEdit()
    await flushRemoteSave()
    const result = await runAttendanceCourseUpdateData({
      course_type: target.courseType,
      attendance_sheet_id: props.sheetId,
      course_name: target.courseName,
      include_frozen: false,
      workbook_id: props.workbookId,
    })
    await restoreInitialDocument({ preserveContent: true })
    ElMessage.success(result.step3.message || '考勤数据已更新')
  } catch (error) {
    console.warn('Failed to update attendance course data', error)
    ElMessage.error(getSheetActionErrorMessage(error, '更新考勤数据失败'))
  } finally {
    sheetCellActionRunning.value = null
  }
}

async function applyRegistrationMatchAction(
  type: SheetCellActionType,
  options: { useBrowserFallback?: boolean } = {},
) {
  if (
    type !== SHEET_CELL_ACTION_REGISTRATION_ORDER_MATCH
    && type !== SHEET_CELL_ACTION_REGISTRATION_USER_MATCH
    && type !== SHEET_CELL_ACTION_REGISTRATION_COMPOSITE_UPDATE
  ) {
    return
  }
  if (props.sheetId == null) {
    return
  }
  if (activeRegistrationActionRun.value) {
    ElMessage.info(userMatchRunSummary.value || '已有报名表任务正在运行')
    return
  }
  if (type === SHEET_CELL_ACTION_REGISTRATION_USER_MATCH) {
    await startUserMatchRun(false, options.useBrowserFallback)
    return
  }
  if (!canRunRegistrationMatchAction()) {
    warnReadOnlyAction()
    return
  }
  if (sheetCellActionRunning.value) {
    return
  }

  sheetCellActionRunning.value = type
  try {
    commitPendingSheetGridEdit()
    await flushRemoteSave()
    const status = await startNoteSheetRegistrationMatchRun(
      props.sheetId,
      {
        action: type,
        useBrowserFallback: options.useBrowserFallback ?? true,
      },
      { workbookId: props.workbookId },
    )
    userMatchRunStatus.value = status
    applyRegistrationActionRunSheetDetail(status)
    renderCurrentHotWithReason('registration-action-start')
    ElMessage.success(status.already_running ? '已有报名表任务正在运行' : `已在后台开始${SHEET_CELL_ACTION_LABELS[type]}`)
    if (isRegistrationMatchRunActive(status)) {
      scheduleUserMatchRunPolling()
    } else {
      notifyUserMatchRunTerminalStatus(status)
    }
  } catch (error) {
    console.warn('Failed to run note sheet action', error)
    ElMessage.error(getSheetActionErrorMessage(error, '执行动作失败'))
  } finally {
    sheetCellActionRunning.value = null
  }
}

async function startUserMatchRun(forceRestart = false, useBrowserFallback = userMatchUseBrowserFallback.value) {
  if (props.sheetId == null) {
    return
  }
  if (!canRunRegistrationMatchAction()) {
    warnReadOnlyAction()
    return
  }
  if (userMatchStartPending.value) {
    return
  }
  if (activeRegistrationActionRun.value && !forceRestart) {
    ElMessage.info(userMatchRunSummary.value || '已有报名表任务正在运行')
    return
  }

  userMatchStartPending.value = true
  try {
    commitPendingSheetGridEdit()
    await flushRemoteSave()
    const status = await startNoteSheetRegistrationMatchRun(
      props.sheetId,
      {
        action: SHEET_CELL_ACTION_REGISTRATION_USER_MATCH,
        useBrowserFallback,
        forceRestart,
      },
      { workbookId: props.workbookId },
    )
    userMatchRunStatus.value = status
    userMatchUseBrowserFallback.value = status.use_browser_fallback
    applyRegistrationActionRunSheetDetail(status)
    renderCurrentHotWithReason('registration-user-match-start')
    closeUserMatchDialog()
    ElMessage.success(status.already_running ? '已有用户匹配任务正在运行' : '已在后台开始用户匹配')
    if (isRegistrationMatchRunActive(status)) {
      scheduleUserMatchRunPolling()
    } else {
      notifyUserMatchRunTerminalStatus(status)
    }
  } catch (error) {
    console.warn('Failed to start registration user match run', error)
    ElMessage.error(getSheetActionErrorMessage(error, '启动用户匹配失败'))
  } finally {
    userMatchStartPending.value = false
  }
}

function runSheetCellAction(action: SheetCellAction, actionCell: { documentRow: number; column: number }) {
  if (action.type === SHEET_CELL_ACTION_EXCEL_IMPORT_RESET) {
    openExcelImportDialog(actionCell)
    return
  }
  if (action.type === SHEET_CELL_ACTION_REGISTRATION_ADD_STUDENT) {
    addRegistrationStudentRow()
    return
  }
  if (action.type === SHEET_CELL_ACTION_ATTENDANCE_EXPORT) {
    void downloadAttendanceExport()
    return
  }
  if (action.type === SHEET_CELL_ACTION_CLOCKIN_LINK_DETECT) {
    void startClockinLinkDetectionRun()
    return
  }
  if (action.type === SHEET_CELL_ACTION_ATTENDANCE_COURSE_UPDATE_DATA) {
    void updateAttendanceCourseData()
    return
  }
  if (isRegistrationAsyncAction(action.type) && activeRegistrationActionRun.value) {
    ElMessage.info(userMatchRunSummary.value || '已有报名表任务正在运行')
    return
  }
  if (action.type === SHEET_CELL_ACTION_REGISTRATION_USER_MATCH) {
    openUserMatchDialog()
    return
  }
  void applyRegistrationMatchAction(action.type)
}

let sheetCellActionButtonTriggerGuardUntil = 0

function stopSheetCellActionButtonEvent(event: Event) {
  event.preventDefault()
  event.stopPropagation()
  event.stopImmediatePropagation()
}

function triggerSheetCellActionButtonFromEvent(
  event: Event,
  action: SheetCellAction,
  actionCell: { documentRow: number; column: number },
) {
  if (event instanceof MouseEvent && event.button !== 0) {
    return false
  }

  const now = Date.now()
  stopSheetCellActionButtonEvent(event)
  if (now < sheetCellActionButtonTriggerGuardUntil) {
    return true
  }

  sheetCellActionButtonTriggerGuardUntil = now + SHEET_CELL_ACTION_BUTTON_TRIGGER_GUARD_MS
  runSheetCellAction(action, actionCell)
  return true
}

function createEmptyRow(columnCount = columnHeaders.value.length): SheetRow {
  return Array.from({ length: columnCount }, () => '')
}

function isBlankSheetRow(row: SheetRow | undefined, columnCount = columnHeaders.value.length) {
  if (!row) {
    return true
  }
  for (let index = 0; index < columnCount; index += 1) {
    if (normalizeCellValue(row[index] ?? '').trim()) {
      return false
    }
  }
  return true
}

function isSyntheticEmptyDisplayRow(rowIndex: number) {
  return loadedDocumentDataRowCount.value === 0
    && rows.value.length === 1
    && rowIndex === 0
    && isBlankSheetRow(rows.value[0])
}

function closeColumnNotePopover() {
  columnNotePopover.value.visible = false
  columnNotePopover.value.columnIndex = null
}

function bindColumnNotePopoverPosition(anchorRect: DOMRect) {
  const margin = 12
  columnNotePopover.value.x = anchorRect.left
  columnNotePopover.value.y = anchorRect.bottom + 8

  void nextTick(() => {
    const popoverEl = columnNotePopoverRef.value
    if (!popoverEl) {
      return
    }
    const rect = popoverEl.getBoundingClientRect()
    const maxX = Math.max(margin, window.innerWidth - rect.width - margin)
    const maxY = Math.max(margin, window.innerHeight - rect.height - margin)
    columnNotePopover.value.x = Math.min(Math.max(anchorRect.left, margin), maxX)
    columnNotePopover.value.y = Math.min(Math.max(anchorRect.bottom + 8, margin), maxY)
  })
}

function openColumnNotePopover(columnIndex: number, anchorRect: DOMRect) {
  const header = columnHeaders.value[columnIndex]
  if (!header) {
    closeColumnNotePopover()
    return
  }

  const note = normalizeColumnNote(columnConfigs.value[header]?.note)
  if (!note) {
    closeColumnNotePopover()
    return
  }

  const shouldToggleClose = (
    columnNotePopover.value.visible
    && columnNotePopover.value.columnIndex === columnIndex
  )
  if (shouldToggleClose) {
    closeColumnNotePopover()
    return
  }

  columnNotePopover.value.visible = true
  columnNotePopover.value.columnIndex = columnIndex
  columnNotePopover.value.title = header
  columnNotePopover.value.note = note
  bindColumnNotePopoverPosition(anchorRect)
}

function closeColumnFilterPopover() {
  columnFilterOptionRequestSeq += 1
  columnFilterPopover.value.visible = false
  columnFilterPopover.value.columnIndex = null
  columnFilterPopover.value.header = ''
  columnFilterPopover.value.draftQuery = ''
  columnFilterPopover.value.draftExcludedValues = []
  columnFilterPopover.value.draftDateRange = []
  columnFilterPopover.value.draftNumberOperator = DEFAULT_COLUMN_FILTER_NUMBER_OPERATOR
  columnFilterPopover.value.draftNumberValue = ''
  columnFilterPopover.value.draftNumberValueTo = ''
  columnFilterPopover.value.globalOptions = []
  columnFilterPopover.value.globalOptionTotalRows = 0
  columnFilterPopover.value.globalOptionsLoaded = false
  columnFilterPopover.value.globalOptionsLoading = false
  columnFilterPopover.value.globalOptionsError = ''
}

function bindColumnFilterPopoverPosition(anchorRect: DOMRect) {
  const margin = 12
  columnFilterPopover.value.x = anchorRect.left
  columnFilterPopover.value.y = anchorRect.bottom + 8

  void nextTick(() => {
    const popoverEl = columnFilterPopoverRef.value
    if (!popoverEl) {
      return
    }
    const rect = popoverEl.getBoundingClientRect()
    const maxX = Math.max(margin, window.innerWidth - rect.width - margin)
    const maxY = Math.max(margin, window.innerHeight - rect.height - margin)
    columnFilterPopover.value.x = Math.min(Math.max(anchorRect.left, margin), maxX)
    columnFilterPopover.value.y = Math.min(Math.max(anchorRect.bottom + 8, margin), maxY)
  })
}

function normalizeColumnFilterGlobalOptions(options: NoteSheetColumnOptionItem[]): ColumnFilterOptionStat[] {
  const counts = new Map<string, number>()
  options.forEach((option) => {
    const value = normalizeColumnFilterOptionValue(option.value)
    const count = Math.max(0, Number(option.count) || 0)
    counts.set(value, (counts.get(value) ?? 0) + count)
  })
  return [...counts.entries()]
    .map(([value, count]) => ({
      value,
      label: getColumnFilterOptionLabel(value),
      count,
    }))
    .sort((left, right) => (
      right.count - left.count
      || HASH_COLOR_SEED_COLLATOR.compare(left.label, right.label)
    ))
}

function getColumnFilterGlobalOptionsCacheKey(columnIndex: number) {
  if (props.sheetId == null || sheetVersion.value <= 0) {
    return ''
  }
  return [
    props.workbookId ?? 'sheet',
    props.sheetId,
    sheetVersion.value,
    columnIndex,
  ].join(':')
}

function getCachedColumnFilterGlobalOptions(columnIndex: number) {
  const cacheKey = getColumnFilterGlobalOptionsCacheKey(columnIndex)
  if (!cacheKey) {
    return null
  }
  const entry = columnFilterGlobalOptionsCache.get(cacheKey)
  return entry?.sheetVersion === sheetVersion.value ? entry : null
}

function setCachedColumnFilterGlobalOptions(columnIndex: number, entry: ColumnFilterGlobalOptionsCacheEntry) {
  const cacheKey = getColumnFilterGlobalOptionsCacheKey(columnIndex)
  if (!cacheKey) {
    return
  }
  columnFilterGlobalOptionsCache.set(cacheKey, entry)
}

function applyColumnFilterGlobalOptionsEntry(entry: ColumnFilterGlobalOptionsCacheEntry) {
  columnFilterPopover.value.globalOptions = entry.options
  columnFilterPopover.value.globalOptionTotalRows = entry.totalRows
  columnFilterPopover.value.globalOptionsLoaded = true
  columnFilterPopover.value.globalOptionsLoading = false
  columnFilterPopover.value.globalOptionsError = ''
}

function invalidateColumnFilterGlobalOptionsCache() {
  columnFilterGlobalOptionsCache.clear()
}

function isSheetDataDirtyForColumnFilterStats() {
  return changeSerial !== savedChangeSerial || saveTimer != null || saveInFlight
}

function isSheetLocallyDirty() {
  return changeSerial !== savedChangeSerial || saveTimer != null || saveInFlight
}

function clearSheetResourceReconnectTimer() {
  if (!sheetResourceReconnectTimer) {
    return
  }
  clearTimeout(sheetResourceReconnectTimer)
  sheetResourceReconnectTimer = null
}

function closeSheetResourceSocket() {
  sheetResourceSocketCloseRequested = true
  clearSheetResourceReconnectTimer()
  if (!sheetResourceSocket) {
    return
  }
  sheetResourceSocket.onopen = null
  sheetResourceSocket.onmessage = null
  sheetResourceSocket.onerror = null
  sheetResourceSocket.onclose = null
  sheetResourceSocket.close()
  sheetResourceSocket = null
}

function scheduleSheetResourceReconnect(sheetId: number) {
  if (typeof window === 'undefined' || sheetResourceReconnectTimer || props.sheetId !== sheetId) {
    return
  }
  const delay = Math.min(30_000, 1000 * (2 ** Math.min(sheetResourceReconnectAttempt, 5)))
  sheetResourceReconnectAttempt += 1
  sheetResourceReconnectTimer = window.setTimeout(() => {
    sheetResourceReconnectTimer = null
    if (props.sheetId === sheetId) {
      connectSheetResourceSocket({ reconnect: true })
    }
  }, delay)
}

function getSheetResourceSocketUrl(sheetId: number) {
  const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:'
  return `${protocol}//${window.location.host}/api/note-sheets/ws/resources/sheet/${encodeURIComponent(String(sheetId))}`
}

function connectSheetResourceSocket(options: { reconnect?: boolean } = {}) {
  closeSheetResourceSocket()
  if (typeof window === 'undefined' || props.sheetId == null) {
    return
  }
  const socketSheetId = Number(props.sheetId)
  sheetResourceSocketCloseRequested = false
  clearSheetResourceReconnectTimer()
  const socket = new WebSocket(getSheetResourceSocketUrl(socketSheetId))
  sheetResourceSocket = socket
  socket.onopen = () => {
    if (sheetResourceSocket !== socket || props.sheetId !== socketSheetId) {
      return
    }
    sheetResourceReconnectAttempt = 0
    if (!options.reconnect || saveInFlight || cellPatchInFlight || isSheetLocallyDirty()) {
      return
    }
    void restoreInitialDocument({ preserveContent: false })
  }
  socket.onmessage = (event) => {
    if (sheetResourceSocket !== socket || props.sheetId !== socketSheetId) {
      return
    }
    let message: Record<string, unknown>
    try {
      message = JSON.parse(String(event.data || '{}'))
    } catch {
      return
    }
    if (message.type !== 'resource-updated' || message.resource_type !== 'sheet') {
      return
    }
    const remoteVersion = Number(message.version || 0)
    if (!Number.isFinite(remoteVersion) || remoteVersion <= Number(sheetVersion.value || 1)) {
      return
    }
    invalidateSheetDocumentCache(socketSheetId, props.workbookId ?? null)
    if (saveInFlight || cellPatchInFlight) {
      return
    }
    if (isSheetLocallyDirty()) {
      sheetRemoteConflictActive = true
      persistDraftDocument(buildCurrentDocument())
      invalidateSheetDocumentCache(socketSheetId, props.workbookId ?? null)
      ElMessage.warning('工作表已被其他人更新，已保留本地草稿')
      return
    }
    void restoreInitialDocument({ preserveContent: false })
  }
  socket.onerror = () => {
    socket.close()
  }
  socket.onclose = () => {
    if (sheetResourceSocket === socket) {
      sheetResourceSocket = null
    }
    if (!sheetResourceSocketCloseRequested && props.sheetId === socketSheetId) {
      scheduleSheetResourceReconnect(socketSheetId)
    }
  }
}

function waitForRemoteSaveIdle(timeoutMs = 10_000) {
  if (!saveInFlight) {
    return Promise.resolve(true)
  }

  const startedAt = Date.now()
  return new Promise<boolean>((resolve) => {
    const check = () => {
      if (!saveInFlight) {
        resolve(true)
        return
      }
      if (Date.now() - startedAt >= timeoutMs) {
        resolve(false)
        return
      }
      window.setTimeout(check, 50)
    }
    check()
  })
}

async function ensureColumnFilterStatsSourceClean() {
  if (!isSheetDataDirtyForColumnFilterStats()) {
    return true
  }
  if (!canPersistSheet.value || props.sheetId == null) {
    return false
  }

  if (saveTimer) {
    await flushRemoteSave()
  }
  if (saveInFlight) {
    await waitForRemoteSaveIdle()
  }
  if (saveTimer) {
    await flushRemoteSave()
  }
  if (saveInFlight) {
    await waitForRemoteSaveIdle()
  }
  return !isSheetDataDirtyForColumnFilterStats()
}

async function loadColumnFilterGlobalOptions(columnIndex: number, header: string) {
  if (props.sheetId == null) {
    return
  }

  const requestSeq = ++columnFilterOptionRequestSeq
  const cachedEntry = !isSheetDataDirtyForColumnFilterStats()
    ? getCachedColumnFilterGlobalOptions(columnIndex)
    : null
  if (cachedEntry) {
    applyColumnFilterGlobalOptionsEntry(cachedEntry)
    return
  }

  columnFilterPopover.value.globalOptions = []
  columnFilterPopover.value.globalOptionTotalRows = 0
  columnFilterPopover.value.globalOptionsLoaded = false
  columnFilterPopover.value.globalOptionsLoading = true
  columnFilterPopover.value.globalOptionsError = ''

  try {
    const sourceClean = await ensureColumnFilterStatsSourceClean()
    if (!sourceClean) {
      throw new Error('dirty')
    }
    const freshCachedEntry = getCachedColumnFilterGlobalOptions(columnIndex)
    if (freshCachedEntry) {
      if (
        requestSeq !== columnFilterOptionRequestSeq
        || !columnFilterPopover.value.visible
        || columnFilterPopover.value.columnIndex !== columnIndex
        || columnFilterPopover.value.header !== header
      ) {
        return
      }
      applyColumnFilterGlobalOptionsEntry(freshCachedEntry)
      return
    }

    const result = await fetchNoteSheetColumnOptions(props.sheetId, {
      columnIndex,
      workbookId: props.workbookId,
    })
    if (
      requestSeq !== columnFilterOptionRequestSeq
      || !columnFilterPopover.value.visible
      || columnFilterPopover.value.columnIndex !== columnIndex
      || columnFilterPopover.value.header !== header
    ) {
      return
    }

    const entry = {
      options: normalizeColumnFilterGlobalOptions(result.options),
      totalRows: Math.max(0, Number(result.total_rows) || 0),
      sheetVersion: sheetVersion.value,
    }
    setCachedColumnFilterGlobalOptions(columnIndex, entry)
    applyColumnFilterGlobalOptionsEntry(entry)
  } catch {
    if (
      requestSeq !== columnFilterOptionRequestSeq
      || !columnFilterPopover.value.visible
      || columnFilterPopover.value.columnIndex !== columnIndex
      || columnFilterPopover.value.header !== header
    ) {
      return
    }
    columnFilterPopover.value.globalOptionsError = 'failed'
  } finally {
    if (
      requestSeq === columnFilterOptionRequestSeq
      && columnFilterPopover.value.visible
      && columnFilterPopover.value.columnIndex === columnIndex
      && columnFilterPopover.value.header === header
    ) {
      columnFilterPopover.value.globalOptionsLoading = false
    }
  }
}

function openColumnFilterPopover(columnIndex: number, anchorRect: DOMRect) {
  const header = columnHeaders.value[columnIndex]
  if (!header || !isColumnFilterEnabled(columnIndex)) {
    closeColumnFilterPopover()
    return
  }

  columnFilterOptionRequestSeq += 1
  const optionMode = isColumnFilterOptionMode(columnIndex)
  const dateMode = isColumnFilterDateMode(columnIndex)
  const numberMode = isColumnFilterNumberMode(columnIndex)
  columnFilterPopover.value.visible = true
  columnFilterPopover.value.columnIndex = columnIndex
  columnFilterPopover.value.header = header
  columnFilterPopover.value.globalOptions = []
  columnFilterPopover.value.globalOptionTotalRows = 0
  columnFilterPopover.value.globalOptionsLoaded = false
  columnFilterPopover.value.globalOptionsLoading = false
  columnFilterPopover.value.globalOptionsError = ''
  const state = getColumnFilterState(header)
  columnFilterPopover.value.draftQuery = dateMode || numberMode ? '' : state.query
  columnFilterPopover.value.draftExcludedValues = optionMode
    ? [...state.excludedValues]
    : []
  columnFilterPopover.value.draftDateRange = dateMode
    ? getColumnFilterDateDraftRange(state)
    : []
  columnFilterPopover.value.draftNumberOperator = numberMode
    ? state.numberOperator
    : DEFAULT_COLUMN_FILTER_NUMBER_OPERATOR
  columnFilterPopover.value.draftNumberValue = numberMode ? state.numberValue : ''
  columnFilterPopover.value.draftNumberValueTo = numberMode ? state.numberValueTo : ''
  bindColumnFilterPopoverPosition(anchorRect)
  if (optionMode && effectivePaginationEnabled.value) {
    void loadColumnFilterGlobalOptions(columnIndex, header)
  }
}

function applyColumnFilterPopover() {
  const header = columnFilterPopover.value.header
  if (!header) {
    closeColumnFilterPopover()
    return
  }

  const columnIndex = columnFilterPopover.value.columnIndex
  const dateMode = columnIndex != null && isColumnFilterDateMode(columnIndex)
  const numberMode = columnIndex != null && isColumnFilterNumberMode(columnIndex)
  const query = dateMode || numberMode ? '' : normalizeColumnFilterQuery(columnFilterPopover.value.draftQuery)
  const excludedValues = columnIndex != null && isColumnFilterOptionMode(columnIndex)
    ? columnFilterPopover.value.draftExcludedValues
    : []
  const { dateStart, dateEnd } = dateMode
    ? normalizeColumnFilterDateRange(columnFilterPopover.value.draftDateRange)
    : { dateStart: '', dateEnd: '' }
  const { numberOperator, numberValue, numberValueTo } = numberMode
    ? normalizeColumnFilterNumberState({
      numberOperator: columnFilterPopover.value.draftNumberOperator,
      numberValue: columnFilterPopover.value.draftNumberValue,
      numberValueTo: columnFilterPopover.value.draftNumberValueTo,
    })
    : createEmptyColumnFilterNumberState()
  setColumnFilterState(header, {
    query,
    excludedValues,
    dateStart,
    dateEnd,
    numberOperator,
    numberValue,
    numberValueTo,
  })
  closeColumnFilterPopover()
}

function clearColumnFilterPopover() {
  const header = columnFilterPopover.value.header
  if (header) {
    const nextFilters = { ...columnFilters.value }
    delete nextFilters[header]
    columnFilters.value = nextFilters
  }
  closeColumnFilterPopover()
}

function setColumnFilterPopoverOptionSelected(value: string, selected: boolean) {
  const normalizedValue = normalizeColumnFilterOptionValue(value)
  const excludedSet = new Set(columnFilterPopover.value.draftExcludedValues)
  if (selected) {
    excludedSet.delete(normalizedValue)
  } else {
    excludedSet.add(normalizedValue)
  }
  columnFilterPopover.value.draftExcludedValues = [...excludedSet]
}

function setColumnFilterPopoverOptionGroupSelected(group: ColumnFilterOptionGroupView, selected: boolean) {
  const excludedSet = new Set(columnFilterPopover.value.draftExcludedValues)
  group.children.forEach((option) => {
    const normalizedValue = normalizeColumnFilterOptionValue(option.value)
    if (selected) {
      excludedSet.delete(normalizedValue)
    } else {
      excludedSet.add(normalizedValue)
    }
  })
  columnFilterPopover.value.draftExcludedValues = [...excludedSet]
}

function handleColumnFilterOptionChange(value: string, event: Event) {
  const target = event.target as HTMLInputElement | null
  setColumnFilterPopoverOptionSelected(value, target?.checked === true)
}

function handleColumnFilterOptionGroupChange(group: ColumnFilterOptionGroupView, event: Event) {
  const target = event.target as HTMLInputElement | null
  setColumnFilterPopoverOptionGroupSelected(group, target?.checked === true)
}

function toggleColumnFilterOptionGroup(groupKey: string) {
  const nextExpanded = new Set(expandedColumnFilterOptionGroups.value)
  if (nextExpanded.has(groupKey)) {
    nextExpanded.delete(groupKey)
  } else {
    nextExpanded.add(groupKey)
  }
  expandedColumnFilterOptionGroups.value = nextExpanded
}

function selectAllColumnFilterOptions() {
  columnFilterPopover.value.draftExcludedValues = []
}

function invertColumnFilterOptions() {
  columnFilterPopover.value.draftExcludedValues = columnFilterPopoverOptions.value
    .filter((option) => option.selected)
    .map((option) => option.value)
}

function selectColumnFilterDuplicateOptions() {
  columnFilterPopover.value.draftExcludedValues = columnFilterPopoverOptions.value
    .filter((option) => option.count <= 1)
    .map((option) => option.value)
}

function selectColumnFilterUniqueOptions() {
  columnFilterPopover.value.draftExcludedValues = columnFilterPopoverOptions.value
    .filter((option) => option.count !== 1)
    .map((option) => option.value)
}

function setColumnFilterDateShortcut(shortcut: 'today' | 'this_month' | 'this_year') {
  const now = new Date()
  let start = new Date(now.getFullYear(), now.getMonth(), now.getDate())
  let end = new Date(now.getFullYear(), now.getMonth(), now.getDate())
  if (shortcut === 'this_month') {
    start = new Date(now.getFullYear(), now.getMonth(), 1)
    end = new Date(now.getFullYear(), now.getMonth() + 1, 0)
  } else if (shortcut === 'this_year') {
    start = new Date(now.getFullYear(), 0, 1)
    end = new Date(now.getFullYear(), 11, 31)
  }
  columnFilterPopover.value.draftDateRange = [
    formatDateInputValue(start),
    formatDateInputValue(end),
  ]
}

function handleGlobalMouseDown(event: MouseEvent) {
  const target = event.target as Node | null
  if (target && isFormulaReferenceEditableMouseTarget(target)) {
    clearFormulaReferenceReplacementSpan()
  }

  if (sheetWorkspaceViewLinkMenu.value.visible) {
    closeSheetWorkspaceViewLinkMenu()
  }

  const targetElement = target instanceof HTMLElement
    ? target
    : target?.parentElement instanceof HTMLElement
      ? target.parentElement
      : null
  const insideRichTextInlineToolbar = !!targetElement?.closest('.sheet-rich-text-inline-toolbar, .standard-color-picker-popover')
  const insideRichTextContentEditor = !!targetElement?.closest('.sheet-rich-text-cell-editor')
  if (
    richTextContentEditor.value.visible
    && !insideRichTextContentEditor
    && !insideRichTextInlineToolbar
  ) {
    closeRichTextContentEditor({ save: true })
  }
  if (
    richTextInlineToolbar.value.visible
    && !insideRichTextInlineToolbar
    && !activeRichTextInlineToolbarColorField.value
  ) {
    hideRichTextInlineToolbar({ force: true })
  }

  if (columnFilterPopover.value.visible) {
    if (target && columnFilterPopoverRef.value?.contains(target)) {
      return
    }
    closeColumnFilterPopover()
  }

  if (!columnNotePopover.value.visible) {
    return
  }

  if (target && columnNotePopoverRef.value?.contains(target)) {
    return
  }
  closeColumnNotePopover()
}

