function normalizeCellValue(value: unknown): string {
  const inlineCell = coerceInlineCellRecord(value)
  if (inlineCell) {
    for (const key of ['value', 'text', 'title', 'label', 'name']) {
      if (Object.prototype.hasOwnProperty.call(inlineCell, key)) {
        return normalizeCellValue(inlineCell[key])
      }
    }
    const link = normalizeCellLink(inlineCell.link)
    if (link) {
      return link.title || link.url
    }
    return ''
  }
  return value == null ? '' : String(value)
}

function normalizeMultiTextValue(value: unknown) {
  const raw = normalizeCellValue(value).trim()
  if (!raw || isFormulaExpression(raw)) {
    return raw
  }
  return raw
    .split(MULTI_TEXT_ITEM_SEPARATOR_RE)
    .map((item) => item.trim())
    .filter(Boolean)
    .join(', ')
}

function normalizeTimestampMs(value: unknown): number {
  const numeric = typeof value === 'number' ? value : Number(value)
  if (!Number.isFinite(numeric) || numeric <= 0) {
    return 0
  }
  return numeric < 10000000000 ? numeric * 1000 : numeric
}

function normalizePositivePageNumber(value: unknown, fallback: number) {
  const numeric = Number(value)
  return Number.isInteger(numeric) && numeric > 0 ? numeric : fallback
}

function normalizeNonNegativeInt(value: unknown, fallback = 0) {
  const numeric = Number(value)
  return Number.isInteger(numeric) && numeric >= 0 ? numeric : fallback
}

function normalizeCssColor(value: unknown) {
  if (typeof value !== 'string') {
    return ''
  }
  return value.trim().slice(0, 64)
}

function createFallbackHeader(index: number) {
  return DEFAULT_SHEET_COLUMNS[index] ?? `${CUSTOM_COLUMN_PREFIX}${index + 1}`
}

function ensureUniqueHeaderName(value: string, used: Set<string>) {
  let candidate = value.trim()
  if (!candidate) {
    candidate = `${CUSTOM_COLUMN_PREFIX}${used.size + 1}`
  }

  if (!used.has(candidate)) {
    used.add(candidate)
    return candidate
  }

  let suffix = 2
  while (used.has(`${candidate}${suffix}`)) {
    suffix += 1
  }

  const uniqueValue = `${candidate}${suffix}`
  used.add(uniqueValue)
  return uniqueValue
}

function normalizeHeaders(source: unknown): string[] {
  if (!Array.isArray(source) || !source.length) {
    return [...DEFAULT_SHEET_COLUMNS]
  }

  const used = new Set<string>()
  return source.map((item, index) => ensureUniqueHeaderName(
    normalizeCellValue(item).trim() || createFallbackHeader(index),
    used,
  ))
}

function normalizeHeaderGroupCell(source: unknown, remainingColumnCount: number): SheetHeaderGroupCell | null {
  if (remainingColumnCount <= 0) {
    return null
  }

  if (typeof source === 'string' || typeof source === 'number') {
    return { label: normalizeCellValue(source), colspan: 1 }
  }

  if (!source || typeof source !== 'object') {
    return null
  }

  const record = source as Record<string, unknown>
  const label = normalizeCellValue(record.label)
  const rawColspan = Number(record.colspan)
  const colspan = Number.isInteger(rawColspan) && rawColspan > 0
    ? Math.min(rawColspan, remainingColumnCount)
    : 1
  const backgroundColor = normalizeCssColor(record.background_color)
  const textColor = normalizeCssColor(record.text_color)
  const cell: SheetHeaderGroupCell = { label, colspan }
  if (backgroundColor) {
    cell.background_color = backgroundColor
  }
  if (textColor) {
    cell.text_color = textColor
  }
  return cell
}

function normalizeHeaderGroups(source: unknown, columnCount: number): SheetHeaderGroupCell[][] {
  if (!Array.isArray(source) || columnCount <= 0) {
    return []
  }

  const normalizedRows: SheetHeaderGroupCell[][] = []
  for (const row of source) {
    if (!Array.isArray(row)) {
      continue
    }

    const normalizedRow: SheetHeaderGroupCell[] = []
    let remainingColumnCount = columnCount
    for (const cellSource of row) {
      const cell = normalizeHeaderGroupCell(cellSource, remainingColumnCount)
      if (!cell) {
        continue
      }
      normalizedRow.push(cell)
      remainingColumnCount -= cell.colspan ?? 1
      if (remainingColumnCount <= 0) {
        break
      }
    }

    if (remainingColumnCount > 0 && normalizedRow.length > 0) {
      normalizedRow.push({ label: '', colspan: remainingColumnCount })
    }
    if (normalizedRow.some((cell) => cell.label || cell.background_color || cell.text_color)) {
      normalizedRows.push(normalizedRow)
    }
  }

  return normalizedRows
}

function expandHeaderGroupsToSingleCellRows(groups: SheetHeaderGroupCell[][], columnCount: number) {
  return groups.map((row) => expandHeaderGroupLabels(row, columnCount).map((label) => ({ label, colspan: 1 })))
}

function getHeaderGroupMergeCells(groups: SheetHeaderGroupCell[][]) {
  const cells: SheetMergedCell[] = []
  groups.forEach((row, rowIndex) => {
    let columnIndex = 0
    row.forEach((cell) => {
      const colspan = Math.max(1, cell.colspan ?? 1)
      if (colspan > 1) {
        cells.push({
          row: rowIndex,
          col: columnIndex,
          rowspan: 1,
          colspan,
        })
      }
      columnIndex += colspan
    })
  })
  return cells
}

function createSingleCellHeaderGroupsFromGridRows(
  gridRows: SheetRow[],
  headerGroupRowCount: number,
  headers: string[],
) {
  return gridRows
    .slice(0, Math.max(0, headerGroupRowCount))
    .map((row) => normalizeRow(row, headers).map((label) => ({ label, colspan: 1 })))
}

function getNormalizedHeaderFieldLabels(gridRows: SheetRow[], headers: string[], fieldRowIndex: number) {
  const sourceRow = fieldRowIndex >= 0 ? gridRows[fieldRowIndex] : null
  const labels = normalizeRow(sourceRow ?? headers, headers)
  return labels.map((label, index) => normalizeCellValue(label || headers[index] || createFallbackHeader(index)))
}

function inferAttendanceHeaderGroupLabel(fieldLabels: string[]) {
  const labelSet = new Set(fieldLabels.map((label) => normalizeCellValue(label)).filter(Boolean))
  const hasAny = (...labels: string[]) => labels.some((label) => labelSet.has(label))
  const hasAll = (...labels: string[]) => labels.every((label) => labelSet.has(label))

  if (
    hasAll('分组', '学号')
    && hasAny('禅客', '商户订单号', '昵称', '姓名')
  ) {
    return '用户信息'
  }
  if (
    hasAll('完成视频数', '视频应返款', '打卡应返款', '总应返款')
    && hasAny('已返款', '订单金额', '当前应返款')
  ) {
    return '退款总计（每天晚上上21点更新数据）'
  }
  return ''
}

function inferBlankHeaderMergeLabel(
  gridRows: SheetRow[],
  headers: string[],
  merge: SheetMergedCell,
  fieldRowIndex: number,
) {
  const row = normalizeRow(gridRows[merge.row] ?? [], headers)
  for (let column = merge.col; column < merge.col + merge.colspan; column += 1) {
    const value = normalizeCellValue(row[column] ?? '')
    if (value) {
      return value
    }
  }

  const fieldLabels = getNormalizedHeaderFieldLabels(gridRows, headers, fieldRowIndex)
  return inferAttendanceHeaderGroupLabel(fieldLabels.slice(merge.col, merge.col + merge.colspan))
}

function repairBlankHeaderMergeAnchors(
  gridRows: SheetRow[],
  mergedCells: SheetMergedCell[],
  headers: string[],
  fieldRowIndex: number,
) {
  if (!gridRows.length || fieldRowIndex <= 0) {
    return gridRows
  }

  let changed = false
  const nextRows = gridRows.map((row) => normalizeRow(row, headers))
  mergedCells.forEach((merge) => {
    if (merge.row < 0 || merge.row >= fieldRowIndex || merge.rowspan !== 1 || merge.col < 0 || merge.col >= headers.length) {
      return
    }
    if (normalizeCellValue(nextRows[merge.row]?.[merge.col] ?? '')) {
      return
    }
    const inferredLabel = inferBlankHeaderMergeLabel(nextRows, headers, merge, fieldRowIndex)
    if (!inferredLabel) {
      return
    }
    nextRows[merge.row][merge.col] = inferredLabel
    changed = true
  })

  return changed ? nextRows : gridRows
}

function repairCoveredMergedCellValuesInGridRows(
  gridRows: SheetRow[],
  mergedCells: SheetMergedCell[],
  headers: string[],
) {
  if (!gridRows.length || !mergedCells.length || !headers.length) {
    return gridRows
  }

  let changed = false
  const nextRows = gridRows.map((row) => normalizeRow(row, headers))
  mergedCells.forEach((merge) => {
    if (
      merge.row < 0
      || merge.col < 0
      || merge.row >= nextRows.length
      || merge.col >= headers.length
      || (merge.rowspan <= 1 && merge.colspan <= 1)
    ) {
      return
    }

    const anchorValue = normalizeCellValue(nextRows[merge.row]?.[merge.col] ?? '')
    let coveredValue = ''
    for (let row = merge.row; row < merge.row + merge.rowspan && row < nextRows.length; row += 1) {
      for (let column = merge.col; column < merge.col + merge.colspan && column < headers.length; column += 1) {
        if (row === merge.row && column === merge.col) {
          continue
        }
        const value = normalizeCellValue(nextRows[row]?.[column] ?? '')
        if (value && !coveredValue) {
          coveredValue = value
        }
        if (value) {
          nextRows[row][column] = ''
          changed = true
        }
      }
    }

    if (!anchorValue && coveredValue) {
      nextRows[merge.row][merge.col] = coveredValue
      changed = true
    }
  })

  return changed ? nextRows : gridRows
}

function repairCoveredMergedCellValuesInDataRows(
  sourceRows: SheetRow[],
  mergedCells: SheetMergedCell[],
  headers: string[],
  dataStartRow: number,
) {
  if (!sourceRows.length || !mergedCells.length || !headers.length) {
    return sourceRows
  }

  const headerPlaceholders = Array.from(
    { length: Math.max(0, dataStartRow) },
    () => createEmptyRow(headers.length),
  )
  const gridRows = [
    ...headerPlaceholders,
    ...sourceRows.map((row) => normalizeRow(row, headers)),
  ]
  const repairedGridRows = repairCoveredMergedCellValuesInGridRows(gridRows, mergedCells, headers)
  if (repairedGridRows === gridRows) {
    return sourceRows
  }
  return trimTrailingBlankRows(repairedGridRows.slice(dataStartRow).map((row) => normalizeRow(row, headers)))
}

function mergeGridNoteRowIntoColumnConfigs(
  sourceConfigs: Record<string, SheetColumnConfig>,
  gridRows: SheetRow[],
  headers: string[],
  fieldRowIndex: number,
  dataStartRow: number,
  options: { overwrite?: boolean } = {},
) {
  const noteRowIndex = fieldRowIndex + 1
  if (noteRowIndex < 0 || noteRowIndex >= dataStartRow || noteRowIndex >= gridRows.length) {
    return sourceConfigs
  }

  const noteRow = normalizeRow(gridRows[noteRowIndex], headers)
  let changed = false
  const nextConfigs: Record<string, SheetColumnConfig> = { ...sourceConfigs }
  noteRow.forEach((value, columnIndex) => {
    const note = normalizeColumnNote(value)
    const header = headers[columnIndex]
    if (!note || !header) {
      return
    }

    const currentConfig = nextConfigs[header]
    const currentNote = normalizeColumnNote(currentConfig?.note)
    if ((!options.overwrite && currentNote) || currentNote === note) {
      return
    }

    nextConfigs[header] = { ...(currentConfig ?? {}), note }
    changed = true
  })

  return changed ? nextConfigs : sourceConfigs
}

function mergeRemoteStandardColumnConfigsIntoLocalDraft(
  localConfigs: Record<string, SheetColumnConfig>,
  remoteConfigs: Record<string, SheetColumnConfig>,
  headers: string[],
) {
  let changed = false
  const nextConfigs: Record<string, SheetColumnConfig> = { ...localConfigs }
  for (const header of headers) {
    if (!REGISTRATION_STANDARD_USER_ID_HEADERS.has(header)) {
      continue
    }
    const remoteConfig = remoteConfigs[header]
    if (!remoteConfig) {
      continue
    }
    const currentConfig = nextConfigs[header] ?? {}
    const nextConfig: SheetColumnConfig = { ...currentConfig }
    let headerChanged = false
    for (const key of ['header_background_color', 'header_text_color', 'font_family', 'width_mode', 'duplicate_value_highlight'] as const) {
      const value = remoteConfig[key]
      if (value === undefined || nextConfig[key] === value) {
        continue
      }
      nextConfig[key] = value as never
      headerChanged = true
    }
    if (headerChanged) {
      nextConfigs[header] = nextConfig
      changed = true
    }
  }
  return changed ? nextConfigs : localConfigs
}

function normalizeMergedCells(source: unknown, rowCount: number, columnCount: number) {
  if (!Array.isArray(source) || rowCount <= 0 || columnCount <= 0) {
    return []
  }

  const cells: SheetMergedCell[] = []
  const occupied = new Set<string>()
  for (const item of source) {
    if (!item || typeof item !== 'object') {
      continue
    }
    const record = item as Record<string, unknown>
    const row = normalizeNonNegativeInt(record.row, -1)
    const col = normalizeNonNegativeInt(record.col, -1)
    const rowspan = normalizePositivePageNumber(record.rowspan, 1)
    const colspan = normalizePositivePageNumber(record.colspan, 1)
    if (
      row < 0
      || col < 0
      || row >= rowCount
      || col >= columnCount
      || (rowspan <= 1 && colspan <= 1)
    ) {
      continue
    }

    const boundedRowspan = Math.min(rowspan, rowCount - row)
    const boundedColspan = Math.min(colspan, columnCount - col)
    let overlaps = false
    for (let rowOffset = 0; rowOffset < boundedRowspan && !overlaps; rowOffset += 1) {
      for (let columnOffset = 0; columnOffset < boundedColspan; columnOffset += 1) {
        if (occupied.has(`${row + rowOffset}:${col + columnOffset}`)) {
          overlaps = true
          break
        }
      }
    }
    if (overlaps) {
      continue
    }
    for (let rowOffset = 0; rowOffset < boundedRowspan; rowOffset += 1) {
      for (let columnOffset = 0; columnOffset < boundedColspan; columnOffset += 1) {
        occupied.add(`${row + rowOffset}:${col + columnOffset}`)
      }
    }
    cells.push({ row, col, rowspan: boundedRowspan, colspan: boundedColspan })
  }
  return cells
}

function getMergedCellsSourceRowCount(source: unknown) {
  if (!Array.isArray(source)) {
    return 0
  }
  return source.reduce((maxRow, item) => {
    if (!item || typeof item !== 'object') {
      return maxRow
    }
    const record = item as Record<string, unknown>
    const row = normalizeNonNegativeInt(record.row, -1)
    const rowspan = normalizePositivePageNumber(record.rowspan, 1)
    return row >= 0 ? Math.max(maxRow, row + rowspan) : maxRow
  }, 0)
}

function insertRowsIntoMergedCellSource(
  source: unknown,
  startRow: number,
  amount: number,
  rowCount: number,
  columnCount: number,
) {
  if (amount <= 0) {
    return normalizeMergedCells(source, rowCount, columnCount)
  }
  return normalizeMergedCells(source, rowCount, columnCount).map((cell) => {
    if (cell.row < startRow && startRow < cell.row + cell.rowspan) {
      return { ...cell, rowspan: cell.rowspan + amount }
    }
    return cell.row >= startRow ? { ...cell, row: cell.row + amount } : cell
  })
}

function shiftCellMetaRowKeys(source: unknown, rowDelta: number, columnCount: number) {
  const normalized = normalizeCellMetaMap(source, columnCount)
  if (rowDelta === 0) {
    return normalized
  }
  return shiftNormalizedCellMetaRowKeys(normalized, rowDelta)
}

function shiftNormalizedCellMetaRowKeys(source: SheetCellMetaMap, rowDelta: number) {
  const shifted: SheetCellMetaMap = {}
  for (const [key, meta] of Object.entries(source)) {
    const position = parseCellMetaKey(key)
    if (!position) {
      continue
    }
    shifted[createCellMetaKey(Math.max(0, position.row + rowDelta), position.column)] = meta
  }
  return shifted
}

function insertCellMetaRowKeys(source: unknown, startRow: number, amount: number, columnCount: number) {
  const normalized = normalizeCellMetaMap(source, columnCount)
  if (amount <= 0) {
    return normalized
  }
  return insertNormalizedCellMetaRowKeys(normalized, startRow, amount)
}

function insertNormalizedCellMetaRowKeys(source: SheetCellMetaMap, startRow: number, amount: number) {
  const shifted: SheetCellMetaMap = {}
  for (const [key, meta] of Object.entries(source)) {
    const position = parseCellMetaKey(key)
    if (!position) {
      continue
    }
    const row = position.row >= startRow ? position.row + amount : position.row
    shifted[createCellMetaKey(row, position.column)] = meta
  }
  return shifted
}

function createCellMetaKey(rowIndex: number, columnIndex: number) {
  return `${rowIndex}:${columnIndex}`
}

function parseCellMetaKey(key: string) {
  const match = key.match(/^(\d+):(\d+)$/)
  if (!match) {
    return null
  }

  return {
    row: Number(match[1]),
    column: Number(match[2]),
  }
}

function decodeInlineCellStringToken(value: string) {
  return value
    .replace(/\\'/g, "'")
    .replace(/\\"/g, '"')
    .replace(/\\\\/g, '\\')
}

function extractInlineCellStringField(source: string, field: string) {
  const pattern = new RegExp(`['"]${field}['"]\\s*:\\s*(?:'((?:\\\\'|[^'])*)'|"((?:\\\\"|[^"])*)")`)
  const match = source.match(pattern)
  if (!match) {
    return ''
  }
  return decodeInlineCellStringToken(match[1] ?? match[2] ?? '')
}

function parseInlineCellRecordString(source: string): Record<string, unknown> | null {
  const text = source.trim()
  if (!text.startsWith('{') || (!text.includes('value') && !text.includes('link'))) {
    return null
  }

  try {
    const parsed = JSON.parse(text)
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
      return parsed as Record<string, unknown>
    }
  } catch {
    // Python repr strings from old saves are handled by field extraction below.
  }

  const value = extractInlineCellStringField(text, 'value')
  const url = extractInlineCellStringField(text, 'url')
  const title = extractInlineCellStringField(text, 'title')
  if (!value && !url && !title) {
    return null
  }

  const record: Record<string, unknown> = {}
  if (value) {
    record.value = value
  }
  if (url) {
    record.link = title ? { url, title } : { url }
  }
  return record
}

function coerceInlineCellRecord(source: unknown): Record<string, unknown> | null {
  if (source && typeof source === 'object' && !Array.isArray(source)) {
    return source as Record<string, unknown>
  }
  if (typeof source === 'string') {
    return parseInlineCellRecordString(source)
  }
  return null
}

function normalizeCellLink(source: unknown): SheetCellLink | null {
  const inlineRecord = coerceInlineCellRecord(source)
  if (inlineRecord && inlineRecord !== source && inlineRecord.link) {
    return normalizeCellLink(inlineRecord.link)
  }
  if (!inlineRecord) {
    return null
  }

  const record = inlineRecord
  const url = normalizeHyperlinkUrl(record.url)
  if (!url) {
    if (record.link) {
      return normalizeCellLink(record.link)
    }
    return null
  }

  const title = normalizeCellValue(record.title).trim()
  return title ? { url, title } : { url }
}

function normalizeCellActionType(value: unknown): SheetCellActionType | null {
  const normalized = normalizeCellValue(value).trim()
  return normalized in SHEET_CELL_ACTION_LABELS
    ? (normalized as SheetCellActionType)
    : null
}

function normalizeCellAction(source: unknown): SheetCellAction | null {
  if (typeof source === 'string') {
    const type = normalizeCellActionType(source)
    return type ? { type } : null
  }
  if (!source || typeof source !== 'object') {
    return null
  }

  const record = source as Record<string, unknown>
  const type = normalizeCellActionType(record.type ?? record.name)
  if (!type) {
    return null
  }

  const label = normalizeCellValue(record.label).trim()
  return label ? { type, label } : { type }
}

function normalizeCellFontFamily(value: unknown): CellFontFamily | '' {
  if (value === 'default' || value === 'monospace') {
    return value
  }
  return ''
}

function normalizeCellTextAlign(value: unknown): CellTextAlign | '' {
  if (value === 'left' || value === 'center' || value === 'right') {
    return value
  }
  return ''
}

function normalizeCellVerticalAlign(value: unknown): CellVerticalAlign | '' {
  if (value === 'top' || value === 'middle' || value === 'bottom') {
    return value
  }
  return ''
}

function normalizeCellFontSize(value: unknown): number | null {
  const numeric = Number(value)
  if (!Number.isFinite(numeric) || numeric <= 0) {
    return null
  }
  return Math.min(Math.round(numeric), MAX_COLUMN_FONT_SIZE)
}

function normalizeCellFormatType(value: unknown): CellFormatType | '' {
  if (value === 'normal' || value === 'rich_text') {
    return value
  }
  return ''
}

function normalizeStoredCellFormatType(value: unknown): StoredCellFormatType | null {
  return value === 'rich_text' ? 'rich_text' : null
}

function hasCellStyleValue(style: SheetCellStyle) {
  return Boolean(
    style.background_color
    || style.text_color
    || style.font_family
    || style.font_size
    || style.text_align
    || style.vertical_align,
  )
}

function normalizeCellStyle(source: unknown): SheetCellStyle | null {
  if (!source || typeof source !== 'object') {
    return null
  }

  const record = source as Record<string, unknown>
  const backgroundColor = normalizeCssColor(record.background_color)
  const textColor = normalizeCssColor(record.text_color)
  const fontFamily = normalizeCellFontFamily(record.font_family)
  const fontSize = normalizeCellFontSize(record.font_size)
  const textAlign = normalizeCellTextAlign(record.text_align)
  const verticalAlign = normalizeCellVerticalAlign(record.vertical_align)
  if (!backgroundColor && !textColor && !fontFamily && !fontSize && !textAlign && !verticalAlign) {
    return null
  }

  const style: SheetCellStyle = {}
  if (backgroundColor) {
    style.background_color = backgroundColor
  }
  if (textColor) {
    style.text_color = textColor
  }
  if (fontFamily) {
    style.font_family = fontFamily
  }
  if (fontSize) {
    style.font_size = fontSize
  }
  if (textAlign) {
    style.text_align = textAlign
  }
  if (verticalAlign) {
    style.vertical_align = verticalAlign
  }
  return style
}

function hasRichTextStyleValue(style: SheetRichTextStyle) {
  return Boolean(
    style.text_color
    || style.background_color
    || style.bold
    || style.italic
    || style.underline,
  )
}

function normalizeRichTextStyle(source: unknown): SheetRichTextStyle | null {
  if (!source || typeof source !== 'object') {
    return null
  }

  const record = source as Record<string, unknown>
  const textColor = normalizeCssColor(record.text_color)
  const backgroundColor = normalizeCssColor(record.background_color)
  const style: SheetRichTextStyle = {}
  if (textColor) {
    style.text_color = textColor
  }
  if (backgroundColor) {
    style.background_color = backgroundColor
  }
  if (record.bold === true) {
    style.bold = true
  }
  if (record.italic === true) {
    style.italic = true
  }
  if (record.underline === true) {
    style.underline = true
  }
  return hasRichTextStyleValue(style) ? style : null
}

function normalizeRichTextSpans(source: unknown, textLength?: number): SheetRichTextSpan[] {
  const sourceSpans = Array.isArray(source) ? source : []
  const hasLimit = Number.isFinite(textLength)
  const limit = hasLimit ? Math.max(0, Math.trunc(Number(textLength))) : 0
  const spans: SheetRichTextSpan[] = []

  sourceSpans.forEach((item) => {
    if (!item || typeof item !== 'object') {
      return
    }
    const record = item as Record<string, unknown>
    let start = Math.trunc(Number(record.start))
    let end = Math.trunc(Number(record.end))
    if (!Number.isInteger(start) || !Number.isInteger(end)) {
      return
    }
    start = Math.max(0, start)
    end = Math.max(0, end)
    if (hasLimit) {
      start = Math.min(start, limit)
      end = Math.min(end, limit)
    }
    if (end <= start) {
      return
    }
    const style = normalizeRichTextStyle(record.style)
    if (!style) {
      return
    }
    spans.push({ start, end, style })
  })

  return spans.sort((left, right) => left.start - right.start || left.end - right.end)
}

function normalizeRichText(source: unknown, textLength?: number): SheetRichText | null {
  if (!source || typeof source !== 'object') {
    return null
  }
  const spans = normalizeRichTextSpans((source as Record<string, unknown>).spans, textLength)
  return spans.length ? { spans } : null
}

function normalizeRichTextForText(source: unknown, text: string) {
  return normalizeRichText(source, text.length)
}

function normalizeCellMetaEntry(source: unknown): SheetCellMeta | null {
  const record = coerceInlineCellRecord(source)
  if (!record) {
    return null
  }

  const cellType = normalizeStoredCellFormatType(record.cell_type)
  const link = normalizeCellLink(record.link)
  const action = normalizeCellAction(record.action)
  const style = normalizeCellStyle(record.style)
  const richText = normalizeRichText(record.rich_text)
  if (!cellType && !link && !action && !style && !richText) {
    return null
  }

  const meta: SheetCellMeta = {}
  if (cellType || richText) {
    meta.cell_type = cellType ?? 'rich_text'
  }
  if (link) {
    meta.link = link
  }
  if (action) {
    meta.action = action
  }
  if (style) {
    meta.style = style
  }
  if (richText) {
    meta.rich_text = richText
  }
  return meta
}

function normalizeCellMetaMap(source: unknown, columnCount: number): SheetCellMetaMap {
  if (!source || typeof source !== 'object' || columnCount <= 0) {
    return {}
  }

  const normalized: SheetCellMetaMap = {}
  for (const [key, value] of Object.entries(source as Record<string, unknown>)) {
    const position = parseCellMetaKey(key)
    if (!position || position.column >= columnCount) {
      continue
    }

    const meta = normalizeCellMetaEntry(value)
    if (meta) {
      normalized[createCellMetaKey(position.row, position.column)] = meta
    }
  }
  return normalized
}

function stripCellLinkFromMeta(meta: SheetCellMeta | null | undefined): SheetCellMeta | null {
  if (!meta) {
    return null
  }
  const nextMeta: SheetCellMeta = { ...meta }
  delete nextMeta.link
  return Object.keys(nextMeta).length ? nextMeta : null
}

function stripCellLinksFromMetaMap(source: SheetCellMetaMap): SheetCellMetaMap {
  const nextMeta: SheetCellMetaMap = {}
  for (const [key, meta] of Object.entries(source)) {
    const stripped = stripCellLinkFromMeta(meta)
    if (stripped) {
      nextMeta[key] = stripped
    }
  }
  return nextMeta
}

function stripCellLinksFromEntityCellMap(source: SheetEntityCellMap): SheetEntityCellMap {
  const nextCells: SheetEntityCellMap = {}
  for (const [rowId, rowCells] of Object.entries(source)) {
    const nextRowCells: Record<string, SheetEntityCell> = {}
    for (const [columnId, cell] of Object.entries(rowCells)) {
      const nextCell: SheetEntityCell = { ...cell }
      delete nextCell.link
      if (Object.keys(nextCell).length) {
        nextRowCells[columnId] = nextCell
      }
    }
    if (Object.keys(nextRowCells).length) {
      nextCells[rowId] = nextRowCells
    }
  }
  return nextCells
}

let sheetEntityIdCounter = 0

function normalizeSheetEntityId(value: unknown) {
  return typeof value === 'string' ? value.trim().slice(0, 128) : ''
}

function createSheetEntityId(prefix: string) {
  sheetEntityIdCounter += 1
  return `${prefix}_${Date.now().toString(36)}_${sheetEntityIdCounter.toString(36)}`
}

function createFallbackSheetEntityId(prefix: string, index: number, seed = '') {
  const normalizedSeed = normalizeCellValue(seed).trim()
  const hash = stableHash32(`${prefix}:${index}:${normalizedSeed}`).toString(36)
  return `${prefix}_${index + 1}_${hash}`
}

function ensureUniqueSheetEntityId(candidate: string, used: Set<string>, prefix: string) {
  const base = candidate || createSheetEntityId(prefix)
  if (!used.has(base)) {
    used.add(base)
    return base
  }

  let suffix = 2
  while (used.has(`${base}_${suffix}`)) {
    suffix += 1
  }
  const uniqueId = `${base}_${suffix}`
  used.add(uniqueId)
  return uniqueId
}

function normalizeSheetEntityRowKind(value: unknown): SheetEntityRowKind | null {
  return value === 'header_group' || value === 'field' || value === 'field_note' || value === 'data'
    ? value
    : null
}

function getSheetEntityRowKind(rowIndex: number, fieldRowIndex: number, dataStartRow: number): SheetEntityRowKind {
  if (rowIndex >= dataStartRow) {
    return 'data'
  }
  if (rowIndex === fieldRowIndex) {
    return 'field'
  }
  if (rowIndex > fieldRowIndex) {
    return 'field_note'
  }
  return 'header_group'
}

function normalizeEntityCellEntry(source: unknown): SheetEntityCell | null {
  if (!source || typeof source !== 'object') {
    return null
  }

  const record = source as Record<string, unknown>
  const value = normalizeCellValue(record.value)
  const meta = normalizeCellMetaEntry(record)
  const cell: SheetEntityCell = { ...(meta ?? {}) }
  if (isFormulaExpression(value)) {
    delete cell.cell_type
    delete cell.rich_text
  }
  if (value) {
    cell.value = value
  }
  return Object.keys(cell).length ? cell : null
}

function normalizeEntityCellMap(source: unknown): SheetEntityCellMap {
  if (!source || typeof source !== 'object') {
    return {}
  }

  const normalized: SheetEntityCellMap = {}
  for (const [rawRowId, rawCells] of Object.entries(source as Record<string, unknown>)) {
    const rowId = normalizeSheetEntityId(rawRowId)
    if (!rowId || !rawCells || typeof rawCells !== 'object') {
      continue
    }

    const rowCells: Record<string, SheetEntityCell> = {}
    for (const [rawColumnId, rawCell] of Object.entries(rawCells as Record<string, unknown>)) {
      const columnId = normalizeSheetEntityId(rawColumnId)
      if (!columnId) {
        continue
      }
      const cell = normalizeEntityCellEntry(rawCell)
      if (cell) {
        rowCells[columnId] = cell
      }
    }
    if (Object.keys(rowCells).length) {
      normalized[rowId] = rowCells
    }
  }
  return normalized
}

function getEntityCellMeta(cell: SheetEntityCell | null | undefined): SheetCellMeta | null {
  return normalizeCellMetaEntry(cell ?? null)
}

function mergeCellMetaEntries(
  baseMeta: SheetCellMeta | null | undefined,
  overlayMeta: SheetCellMeta | null | undefined,
): SheetCellMeta | null {
  if (!baseMeta && !overlayMeta) {
    return null
  }
  return normalizeCellMetaEntry({
    ...(baseMeta ?? {}),
    ...(overlayMeta ?? {}),
  })
}

function reconcileHeaderEntityCellMeta(
  normalizedMeta: SheetCellMeta | null | undefined,
  existingMeta: SheetCellMeta | null | undefined,
) {
  const mergedMeta = mergeCellMetaEntries(normalizedMeta, existingMeta)
  if (!mergedMeta) {
    return null
  }
  const nextMeta: SheetCellMeta = { ...mergedMeta }
  if (normalizedMeta?.action) {
    nextMeta.action = normalizedMeta.action
  } else {
    delete nextMeta.action
  }
  return normalizeCellMetaEntry(nextMeta)
}

function replaceEntityCellMeta(entry: SheetEntityCell, meta: SheetCellMeta | null): SheetEntityCell {
  const nextEntry = { ...entry }
  delete nextEntry.link
  delete nextEntry.action
  delete nextEntry.style
  delete nextEntry.cell_type
  delete nextEntry.rich_text
  if (meta?.cell_type) {
    nextEntry.cell_type = meta.cell_type
  }
  if (meta?.link) {
    nextEntry.link = meta.link
  }
  if (meta?.action) {
    nextEntry.action = meta.action
  }
  if (meta?.style) {
    nextEntry.style = meta.style
  }
  if (meta?.rich_text) {
    nextEntry.rich_text = meta.rich_text
  }
  return nextEntry
}

function normalizeEntityColumns(source: unknown, headers: string[]): SheetEntityColumn[] {
  const sourceColumns = Array.isArray(source) ? source : []
  const used = new Set<string>()
  return headers.map((header, index) => {
    const record = sourceColumns[index] && typeof sourceColumns[index] === 'object'
      ? sourceColumns[index] as Record<string, unknown>
      : null
    const sourceId = normalizeSheetEntityId(record?.id)
    const fallbackId = createFallbackSheetEntityId('col', index, header)
    return {
      id: ensureUniqueSheetEntityId(sourceId || fallbackId, used, 'col'),
      header,
    }
  })
}

function normalizeEntityRows(
  source: unknown,
  dataStartRow: number,
  fieldRowIndex: number,
  dataRowCount: number,
): SheetEntityRow[] {
  const sourceRows = Array.isArray(source) ? source : []
  const used = new Set<string>()
  const rowCount = Math.max(0, dataStartRow) + Math.max(0, dataRowCount)
  return Array.from({ length: rowCount }, (_, index) => {
    const record = sourceRows[index] && typeof sourceRows[index] === 'object'
      ? sourceRows[index] as Record<string, unknown>
      : null
    const kind = getSheetEntityRowKind(index, fieldRowIndex, dataStartRow)
    const sourceId = normalizeSheetEntityId(record?.id)
    const fallbackId = createFallbackSheetEntityId(kind === 'data' ? 'row' : kind, index)
    const row: SheetEntityRow = {
      id: ensureUniqueSheetEntityId(sourceId || fallbackId, used, kind === 'data' ? 'row' : kind),
      kind: normalizeSheetEntityRowKind(record?.kind) ?? kind,
    }
    if (record?.hidden === true) {
      row.hidden = true
    }
    return row
  })
}

function extractEntityCellForSave(value: unknown, meta: SheetCellMeta | null | undefined): SheetEntityCell | null {
  const normalizedValue = normalizeCellValue(value)
  const normalizedMeta = normalizeCellMetaEntry(meta ?? null)
  const cell: SheetEntityCell = { ...(normalizedMeta ?? {}) }
  if (isFormulaExpression(normalizedValue)) {
    delete cell.cell_type
    delete cell.rich_text
  } else if (cell.rich_text) {
    const normalizedRichText = normalizeRichTextForText(cell.rich_text, normalizedValue)
    if (normalizedRichText) {
      cell.rich_text = normalizedRichText
    } else {
      delete cell.rich_text
    }
  }
  if (normalizedValue) {
    cell.value = normalizedValue
  }
  return Object.keys(cell).length ? cell : null
}

function normalizeLegacySheetCellActionType(value: unknown): SheetCellActionType | null {
  const compactValue = normalizeLegacySheetCellActionLabel(normalizeCellValue(value))
  return LEGACY_SHEET_CELL_ACTION_LABEL_TYPES.get(compactValue) ?? null
}

function addLegacySheetCellActions(
  sourceMeta: SheetCellMetaMap,
  normalizedGridRows: SheetRow[],
  columnCount: number,
) {
  if (columnCount <= 0) {
    return sourceMeta
  }

  const pendingActions: Array<{ key: string, actionType: SheetCellActionType }> = []
  normalizedGridRows.forEach((row, rowIndex) => {
    row.forEach((value, columnIndex) => {
      const actionType = normalizeLegacySheetCellActionType(value)
      if (!actionType) {
        return
      }
      const key = createCellMetaKey(rowIndex, columnIndex)
      const currentMeta = sourceMeta[key]
      if (currentMeta?.action?.type === actionType) {
        return
      }
      pendingActions.push({ key, actionType })
    })
  })
  if (!pendingActions.length) {
    return sourceMeta
  }

  const nextMeta: SheetCellMetaMap = { ...sourceMeta }
  pendingActions.forEach(({ key, actionType }) => {
    nextMeta[key] = {
      ...(nextMeta[key] ?? {}),
      action: {
        type: actionType,
        label: SHEET_CELL_ACTION_LABELS[actionType],
      },
    }
  })
  return normalizeCellMetaMap(nextMeta, columnCount)
}

function pruneInvalidRegistrationHeaderActions(
  sourceMeta: SheetCellMetaMap,
  normalizedGridRows: SheetRow[],
  headers: string[],
  dataStartRow: number,
) {
  if (dataStartRow <= 0 || !Object.keys(sourceMeta).length) {
    return sourceMeta
  }

  let changed = false
  const nextMeta: SheetCellMetaMap = { ...sourceMeta }
  for (const [key, meta] of Object.entries(sourceMeta)) {
    const position = parseCellMetaKey(key)
    const action = meta?.action
    if (!position || !action || position.row >= dataStartRow) {
      continue
    }
    if (
      action.type !== SHEET_CELL_ACTION_REGISTRATION_ADD_STUDENT
      && action.type !== SHEET_CELL_ACTION_REGISTRATION_ORDER_MATCH
      && action.type !== SHEET_CELL_ACTION_REGISTRATION_USER_MATCH
      && action.type !== SHEET_CELL_ACTION_REGISTRATION_COMPOSITE_UPDATE
    ) {
      continue
    }
    if (
      isSheetCellActionAllowedInRows(
        action,
        position.row,
        position.column,
        headers,
        normalizedGridRows,
        dataStartRow,
      )
    ) {
      continue
    }

    const nextEntry = { ...meta }
    delete nextEntry.action
    if (Object.keys(nextEntry).length) {
      nextMeta[key] = nextEntry
    } else {
      delete nextMeta[key]
    }
    changed = true
  }

  return changed ? normalizeCellMetaMap(nextMeta, headers.length) : sourceMeta
}

function finalizeNormalizedSheetCellMeta(
  sourceMeta: SheetCellMetaMap,
  normalizedGridRows: SheetRow[],
  headers: string[],
  dataStartRow: number,
  normalizeTrace?: SheetPerfTrace | null,
) {
  const cellMetaWithLegacyActions = addLegacySheetCellActions(
    sourceMeta,
    normalizedGridRows,
    headers.length,
  )
  normalizeTrace?.mark('cell-meta-legacy-actions')
  const cellMetaWithPrunedRegistrationActions = pruneInvalidRegistrationHeaderActions(
    cellMetaWithLegacyActions,
    normalizedGridRows,
    headers,
    dataStartRow,
  )
  normalizeTrace?.mark('cell-meta-registration-pruned-actions')
  const cellMetaWithRegistrationAddAction = addDefaultRegistrationAddStudentAction(
    cellMetaWithPrunedRegistrationActions,
    normalizedGridRows,
    headers,
    dataStartRow,
  )
  normalizeTrace?.mark('cell-meta-registration-add-action')
  const cellMetaWithRegistrationUserMatchAction = addDefaultRegistrationUserMatchAction(
    cellMetaWithRegistrationAddAction,
    normalizedGridRows,
    headers,
    dataStartRow,
  )
  normalizeTrace?.mark('cell-meta-registration-user-match-action')
  const normalizedCellMeta = addDefaultRegistrationCompositeUpdateAction(
    cellMetaWithRegistrationUserMatchAction,
    normalizedGridRows,
    headers,
    dataStartRow,
  )
  normalizeTrace?.mark('cell-meta-registration-composite-action')
  return normalizedCellMeta
}

function cellMetaHasActionType(meta: SheetCellMeta | null | undefined, actionType: SheetCellActionType) {
  return meta?.action?.type === actionType
}

function hasNormalizedHeader(headers: string[], target: string) {
  return headers.some((header) => normalizeCellValue(header).trim() === target)
}

function getNormalizedHeaderValue(headers: string[], columnIndex: number) {
  return normalizeCellValue(headers[columnIndex] ?? '').trim()
}

function getHeaderGridCellTextFromRows(gridRows: SheetRow[], documentRow: number, columnIndex: number) {
  if (documentRow < 0 || documentRow >= gridRows.length) {
    return ''
  }
  return normalizeCellValue(gridRows[documentRow]?.[columnIndex] ?? '').trim()
}

function isActionCellTextCompatibleInRows(
  action: SheetCellAction,
  documentRow: number,
  columnIndex: number,
  gridRows: SheetRow[],
) {
  const text = getHeaderGridCellTextFromRows(gridRows, documentRow, columnIndex)
  return !text || normalizeLegacySheetCellActionType(text) === action.type
}

function canRestoreDefaultSheetCellActionInRows(
  targetActionType: SheetCellActionType,
  currentMeta: SheetCellMeta | null | undefined,
  documentRow: number,
  columnIndex: number,
  gridRows: SheetRow[],
) {
  if (currentMeta?.action?.type && currentMeta.action.type !== targetActionType) {
    return false
  }
  const cellText = getHeaderGridCellTextFromRows(gridRows, documentRow, columnIndex)
  return !cellText || normalizeLegacySheetCellActionType(cellText) === targetActionType
}

function resolveRegistrationOrderMatchHostHeader(headers: string[]) {
  if (hasNormalizedHeader(headers, '微信支付订单号')) {
    return '微信支付订单号'
  }
  return hasNormalizedHeader(headers, '错误手机号') ? '错误手机号' : ''
}

function isRegistrationActionHostColumnInHeaders(actionType: SheetCellActionType, columnIndex: number, headers: string[]) {
  const header = getNormalizedHeaderValue(headers, columnIndex)
  if (actionType === SHEET_CELL_ACTION_REGISTRATION_ADD_STUDENT) {
    return header === STUDENT_LOOKUP_SUBMITTED_AT_HEADER
  }
  if (actionType === SHEET_CELL_ACTION_REGISTRATION_ORDER_MATCH) {
    return header === resolveRegistrationOrderMatchHostHeader(headers)
  }
  if (actionType === SHEET_CELL_ACTION_REGISTRATION_USER_MATCH) {
    return header === '用户ID'
  }
  if (actionType === SHEET_CELL_ACTION_REGISTRATION_COMPOSITE_UPDATE) {
    return header === '匹配得分'
  }
  return true
}

function isSheetCellActionAllowedInRows(
  action: SheetCellAction,
  documentRow: number,
  columnIndex: number,
  headers: string[],
  gridRows: SheetRow[],
  headerRowCount: number,
) {
  if (documentRow < 0 || columnIndex < 0) {
    return false
  }
  if (
    action.type === SHEET_CELL_ACTION_REGISTRATION_ADD_STUDENT
    || action.type === SHEET_CELL_ACTION_REGISTRATION_ORDER_MATCH
    || action.type === SHEET_CELL_ACTION_REGISTRATION_USER_MATCH
    || action.type === SHEET_CELL_ACTION_REGISTRATION_COMPOSITE_UPDATE
  ) {
    return (
      documentRow < headerRowCount
      && isRegistrationActionHostColumnInHeaders(action.type, columnIndex, headers)
      && isActionCellTextCompatibleInRows(action, documentRow, columnIndex, gridRows)
    )
  }
  return true
}

function isSheetCellActionAllowedAt(action: SheetCellAction, documentRow: number, columnIndex: number) {
  return isSheetCellActionAllowedInRows(
    action,
    documentRow,
    columnIndex,
    columnHeaders.value,
    sheetGridRows.value,
    sheetHeaderRowCount.value,
  )
}

function addDefaultRegistrationAddStudentAction(
  sourceMeta: SheetCellMetaMap,
  normalizedGridRows: SheetRow[],
  headers: string[],
  dataStartRow: number,
) {
  const submittedAtColumn = headers.findIndex((header) => normalizeCellValue(header).trim() === STUDENT_LOOKUP_SUBMITTED_AT_HEADER)
  if (
    submittedAtColumn < 0
    || !headers.some((header) => normalizeCellValue(header).trim() === '姓名')
  ) {
    return sourceMeta
  }

  const prefixRowCount = Math.min(Math.max(dataStartRow, 0), normalizedGridRows.length)
  const nextMeta: SheetCellMetaMap = { ...sourceMeta }
  for (let rowIndex = 0; rowIndex < prefixRowCount; rowIndex += 1) {
    const row = normalizedGridRows[rowIndex]
    const hasExcelImportAction = row.some((value, columnIndex) => {
      const key = createCellMetaKey(rowIndex, columnIndex)
      return (
        cellMetaHasActionType(nextMeta[key], SHEET_CELL_ACTION_EXCEL_IMPORT_RESET)
        || normalizeLegacySheetCellActionType(value) === SHEET_CELL_ACTION_EXCEL_IMPORT_RESET
      )
    })
    if (!hasExcelImportAction) {
      continue
    }

    const key = createCellMetaKey(rowIndex, submittedAtColumn)
    const currentMeta = nextMeta[key]
    if (!canRestoreDefaultSheetCellActionInRows(
      SHEET_CELL_ACTION_REGISTRATION_ADD_STUDENT,
      currentMeta,
      rowIndex,
      submittedAtColumn,
      normalizedGridRows,
    )) {
      return sourceMeta
    }
    if (currentMeta?.action?.type === SHEET_CELL_ACTION_REGISTRATION_ADD_STUDENT) {
      return sourceMeta
    }
    nextMeta[key] = {
      ...(currentMeta ?? {}),
      action: {
        type: SHEET_CELL_ACTION_REGISTRATION_ADD_STUDENT,
        label: SHEET_CELL_ACTION_LABELS[SHEET_CELL_ACTION_REGISTRATION_ADD_STUDENT],
      },
    }
    return normalizeCellMetaMap(nextMeta, headers.length)
  }

  return sourceMeta
}

function addDefaultRegistrationCompositeUpdateAction(
  sourceMeta: SheetCellMetaMap,
  normalizedGridRows: SheetRow[],
  headers: string[],
  dataStartRow: number,
) {
  const scoreColumn = headers.findIndex((header) => normalizeCellValue(header).trim() === '匹配得分')
  if (
    scoreColumn < 0
    || !headers.some((header) => normalizeCellValue(header).trim() === '用户ID')
    || !headers.some((header) => normalizeCellValue(header).trim() === '微信支付订单号')
  ) {
    return sourceMeta
  }

  const prefixRowCount = Math.min(Math.max(dataStartRow, 0), normalizedGridRows.length)
  const nextMeta: SheetCellMetaMap = { ...sourceMeta }
  for (let rowIndex = 0; rowIndex < prefixRowCount; rowIndex += 1) {
    const row = normalizedGridRows[rowIndex]
    const hasRegistrationAction = row.some((value, columnIndex) => {
      const key = createCellMetaKey(rowIndex, columnIndex)
      const actionType = nextMeta[key]?.action?.type || normalizeLegacySheetCellActionType(value)
      return (
        actionType === SHEET_CELL_ACTION_REGISTRATION_ORDER_MATCH
        || actionType === SHEET_CELL_ACTION_REGISTRATION_USER_MATCH
        || actionType === SHEET_CELL_ACTION_EXCEL_IMPORT_RESET
      )
    })
    if (!hasRegistrationAction) {
      continue
    }

    const key = createCellMetaKey(rowIndex, scoreColumn)
    const currentMeta = nextMeta[key]
    if (!canRestoreDefaultSheetCellActionInRows(
      SHEET_CELL_ACTION_REGISTRATION_COMPOSITE_UPDATE,
      currentMeta,
      rowIndex,
      scoreColumn,
      normalizedGridRows,
    )) {
      return sourceMeta
    }
    if (currentMeta?.action?.type === SHEET_CELL_ACTION_REGISTRATION_COMPOSITE_UPDATE) {
      return sourceMeta
    }
    nextMeta[key] = {
      ...(currentMeta ?? {}),
      action: {
        type: SHEET_CELL_ACTION_REGISTRATION_COMPOSITE_UPDATE,
        label: SHEET_CELL_ACTION_LABELS[SHEET_CELL_ACTION_REGISTRATION_COMPOSITE_UPDATE],
      },
    }
    return normalizeCellMetaMap(nextMeta, headers.length)
  }

  return sourceMeta
}

function addDefaultRegistrationUserMatchAction(
  sourceMeta: SheetCellMetaMap,
  normalizedGridRows: SheetRow[],
  headers: string[],
  dataStartRow: number,
) {
  const userIdColumn = headers.findIndex((header) => normalizeCellValue(header).trim() === '用户ID')
  if (userIdColumn < 0 || !headers.some((header) => normalizeCellValue(header).trim() === '姓名')) {
    return sourceMeta
  }

  const prefixRowCount = Math.min(Math.max(dataStartRow, 0), normalizedGridRows.length)
  const nextMeta: SheetCellMetaMap = { ...sourceMeta }
  for (let rowIndex = 0; rowIndex < prefixRowCount; rowIndex += 1) {
    const row = normalizedGridRows[rowIndex]
    const hasRegistrationAction = row.some((value, columnIndex) => {
      const key = createCellMetaKey(rowIndex, columnIndex)
      const actionType = nextMeta[key]?.action?.type || normalizeLegacySheetCellActionType(value)
      return (
        actionType === SHEET_CELL_ACTION_REGISTRATION_ORDER_MATCH
        || actionType === SHEET_CELL_ACTION_REGISTRATION_COMPOSITE_UPDATE
        || actionType === SHEET_CELL_ACTION_EXCEL_IMPORT_RESET
      )
    })
    if (!hasRegistrationAction) {
      continue
    }

    const key = createCellMetaKey(rowIndex, userIdColumn)
    const currentMeta = nextMeta[key]
    if (!canRestoreDefaultSheetCellActionInRows(
      SHEET_CELL_ACTION_REGISTRATION_USER_MATCH,
      currentMeta,
      rowIndex,
      userIdColumn,
      normalizedGridRows,
    )) {
      return sourceMeta
    }
    if (currentMeta?.action?.type === SHEET_CELL_ACTION_REGISTRATION_USER_MATCH) {
      return sourceMeta
    }
    nextMeta[key] = {
      ...(currentMeta ?? {}),
      action: {
        type: SHEET_CELL_ACTION_REGISTRATION_USER_MATCH,
        label: SHEET_CELL_ACTION_LABELS[SHEET_CELL_ACTION_REGISTRATION_USER_MATCH],
      },
    }
    return normalizeCellMetaMap(nextMeta, headers.length)
  }

  return sourceMeta
}

function splitColumnNoteLeadingLink(source: unknown) {
  const note = normalizeColumnNote(source)
  const match = note.match(/^链接[:：]\s*(https?:\/\/[^\s]+)\s*(?:\r?\n)?/i)
  if (!match) {
    return { note, link: null as SheetCellLink | null }
  }

  return {
    note: note.slice(match[0].length).trim(),
    link: normalizeCellLink({ url: match[1] }),
  }
}

function getColumnHeaderStyle(config: SheetColumnConfig | undefined): SheetHeaderCellStyle | null {
  if (!config?.header_background_color && !config?.header_text_color) {
    return null
  }
  return {
    background_color: config.header_background_color,
    text_color: config.header_text_color,
  }
}

function expandHeaderGroupStyles(row: SheetHeaderGroupCell[], columnCount: number): (SheetHeaderCellStyle | null)[] {
  const styles: (SheetHeaderCellStyle | null)[] = []
  for (const cell of row) {
    const colspan = Math.max(1, cell.colspan ?? 1)
    const style = cell.background_color || cell.text_color
      ? { background_color: cell.background_color, text_color: cell.text_color }
      : null
    for (let index = 0; index < colspan && styles.length < columnCount; index += 1) {
      styles.push(style)
    }
  }
  while (styles.length < columnCount) {
    styles.push(null)
  }
  return styles
}

function getTopHeaderThemeCells(groups: SheetHeaderGroupCell[][], headers: string[]): SheetHeaderThemeCell[] {
  const fallbackThemeCells = () => {
    const tokens = resolveStableVisualTokens(headers.map((header) => header.trim() || '列'))
    return headers.map((header, index) => ({
      seed: header.trim() || '列',
      hue: tokens[index]?.hue ?? null,
    }))
  }

  const topRow = groups[0]
  if (!topRow?.length) {
    return fallbackThemeCells()
  }

  const entries: Array<{ seed: string; colspan: number }> = []
  let columnIndex = 0
  for (const cell of topRow) {
    const colspan = Math.max(1, cell.colspan ?? 1)
    const seed = cell.label.trim() || headers[columnIndex]?.trim() || '列'
    entries.push({ seed, colspan })
    columnIndex += colspan
  }

  while (columnIndex < headers.length) {
    const seed = headers[columnIndex]?.trim() || '列'
    entries.push({ seed, colspan: 1 })
    columnIndex += 1
  }

  const tokens = resolveStableVisualTokens(entries.map((entry) => entry.seed), {
    minAdjacentHueDistance: HEADER_THEME_MIN_ADJACENT_HUE_DISTANCE,
    minHueDistance: HEADER_THEME_MIN_USED_HUE_DISTANCE,
  })
  const themeCells: SheetHeaderThemeCell[] = []
  entries.forEach((entry, index) => {
    const hue = tokens[index]?.hue ?? null
    for (let offset = 0; offset < entry.colspan && themeCells.length < headers.length; offset += 1) {
      themeCells.push({ seed: entry.seed, hue })
    }
  })

  return themeCells.length ? themeCells : fallbackThemeCells()
}

function getAutoHeaderStyle(themeCell: SheetHeaderThemeCell, level: number, depth: number): SheetHeaderCellStyle | null {
  const normalizedSeed = themeCell.seed.trim()
  if (!normalizedSeed || themeCell.hue == null) {
    return null
  }

  const hue = themeCell.hue
  const denominator = Math.max(depth - 1, 1)
  const lightness = Math.min(96, Math.round(84 + (level / denominator) * 10))
  const saturation = Math.max(44, 62 - level * 4)
  return {
    background_color: `hsl(${hue} ${saturation}% ${lightness}%)`,
    text_color: '#111827',
  }
}

function resolveHeaderStyleRow(
  explicitStyles: (SheetHeaderCellStyle | null)[],
  themeCells: SheetHeaderThemeCell[],
  level: number,
  depth: number,
  useAutoTheme: boolean,
) {
  return themeCells.map((themeCell, index) => {
    const explicitStyle = explicitStyles[index]
    if (!useAutoTheme) {
      return explicitStyle
    }

    const autoStyle = getAutoHeaderStyle(themeCell, level, depth)
    if (!autoStyle) {
      return explicitStyle
    }
    if (!explicitStyle) {
      return autoStyle
    }
    return {
      background_color: explicitStyle.background_color || autoStyle.background_color,
      text_color: explicitStyle.text_color || autoStyle.text_color,
    }
  })
}

function getLightHeaderBackgroundColor(value: unknown) {
  const color = normalizeCssColor(value)
  return color ? `color-mix(in srgb, ${color} 38%, white)` : ''
}

function getNearestGroupHeaderStyle(
  groupStyleRows: (SheetHeaderCellStyle | null)[][],
  column: number,
) {
  for (let rowIndex = groupStyleRows.length - 1; rowIndex >= 0; rowIndex -= 1) {
    const style = groupStyleRows[rowIndex]?.[column]
    if (style?.background_color || style?.text_color) {
      return style
    }
  }
  return null
}

function resolveFieldHeaderStyleRow(
  fieldStyles: (SheetHeaderCellStyle | null)[],
  groupStyleRows: (SheetHeaderCellStyle | null)[][],
) {
  if (!groupStyleRows.length) {
    return fieldStyles
  }
  return fieldStyles.map((fieldStyle, column) => {
    const groupStyle = getNearestGroupHeaderStyle(groupStyleRows, column)
    const backgroundColor = getLightHeaderBackgroundColor(groupStyle?.background_color)
    if (!backgroundColor) {
      return fieldStyle
    }
    return {
      background_color: backgroundColor,
      text_color: fieldStyle?.text_color || groupStyle?.text_color,
    }
  })
}

function getNearestGridGroupHeaderStyle(column: number) {
  for (let row = columnHeaderLevel.value - 1; row >= 0; row -= 1) {
    const documentRow = getDocumentGridRowIndex(row)
    const merge = findStoredMergedCellAtDocumentCell(documentRow, column)
    const anchorDocumentRow = merge?.row ?? documentRow
    const anchorColumn = merge?.col ?? column
    const cellStyle = getCellStyleAt(anchorDocumentRow, anchorColumn)
    if (cellStyle?.background_color || cellStyle?.text_color) {
      return {
        background_color: cellStyle.background_color,
        text_color: cellStyle.text_color,
      }
    }
    const computedStyle = nestedHeaderStyleRows.value[row]?.[column]
    if (computedStyle?.background_color || computedStyle?.text_color) {
      return computedStyle
    }
  }
  return null
}

function findStoredMergedCellAtDocumentCell(documentRow: number, columnIndex: number) {
  return normalizeMergedCells(
    mergedCells.value,
    Math.max(sheetHeaderRowCount.value + totalRowCount.value, sheetGridRows.value.length),
    columnHeaders.value.length,
  ).find((cell) => (
    documentRow >= cell.row
    && documentRow < cell.row + cell.rowspan
    && columnIndex >= cell.col
    && columnIndex < cell.col + cell.colspan
  )) ?? null
}

function resolveGridFieldHeaderStyle(column: number, fieldStyle: SheetHeaderCellStyle | null) {
  const groupStyle = getNearestGridGroupHeaderStyle(column)
  const backgroundColor = getLightHeaderBackgroundColor(groupStyle?.background_color)
  if (!backgroundColor) {
    return fieldStyle
  }
  return {
    background_color: backgroundColor,
    text_color: fieldStyle?.text_color || groupStyle?.text_color,
  }
}

function normalizeColumnDisplayMode(value: unknown): ColumnDisplayMode {
  return value === 'wrap' ? 'wrap' : DEFAULT_COLUMN_DISPLAY_MODE
}

function normalizeColumnTextAlign(value: unknown): ColumnTextAlign {
  if (value === 'left' || value === 'center' || value === 'right') {
    return value
  }
  return DEFAULT_COLUMN_TEXT_ALIGN
}

function normalizeColumnValueType(value: unknown): ColumnValueType {
  if (value === 'multi_text' || value === 'number' || value === 'percent' || value === 'date') {
    return value
  }
  return 'text'
}

function normalizeColumnBaseType(value: unknown): ColumnBaseType {
  if (value === 'number' || value === 'time') {
    return value
  }
  return 'text'
}

function normalizeColumnTextRule(value: unknown, valueType: ColumnValueType = 'text'): ColumnTextRule {
  if (valueType !== 'text') {
    return 'none'
  }
  if (value === 'phone' || value === 'id_card') {
    return value
  }
  return 'none'
}

function normalizeColumnTextRuleFromRecord(record: Record<string, unknown>, valueType: ColumnValueType) {
  if (record.value_type === 'phone') {
    return normalizeColumnTextRule('phone', valueType)
  }
  return normalizeColumnTextRule(record.text_rule, valueType)
}

function normalizeColumnValueMode(value: unknown): ColumnValueMode {
  if (value === 'fixed_options' || value === 'fixed') {
    return 'fixed_options'
  }
  return 'free'
}

function getColumnBaseType(config: Pick<ColumnSettingsDraft, 'value_type'>): ColumnBaseType {
  const valueType = normalizeColumnValueType(config.value_type)
  if (valueType === 'number' || valueType === 'percent') {
    return 'number'
  }
  if (valueType === 'date') {
    return 'time'
  }
  return 'text'
}

function getColumnSubType(config: Pick<ColumnSettingsDraft, 'value_type' | 'text_rule'>): ColumnSubType {
  const valueType = normalizeColumnValueType(config.value_type)
  const textRule = normalizeColumnTextRule(config.text_rule, valueType)
  if (valueType === 'multi_text') {
    return 'multi_text'
  }
  if (valueType === 'number') {
    return 'number'
  }
  if (valueType === 'percent') {
    return 'percent'
  }
  if (valueType === 'date') {
    return 'date'
  }
  if (textRule === 'phone') {
    return 'phone'
  }
  if (textRule === 'id_card') {
    return 'id_card'
  }
  return 'plain_text'
}

function getColumnSubTypeBaseType(value: ColumnSubType): ColumnBaseType {
  if (value === 'number' || value === 'percent') {
    return 'number'
  }
  if (value === 'date') {
    return 'time'
  }
  return 'text'
}

function normalizeColumnSubType(value: unknown, baseType: ColumnBaseType): ColumnSubType {
  const options = COLUMN_SUB_TYPE_OPTIONS[baseType]
  return options.some((option) => option.value === value)
    ? value as ColumnSubType
    : options[0].value
}

function getDefaultColumnSubType(baseType: ColumnBaseType): ColumnSubType {
  return COLUMN_SUB_TYPE_OPTIONS[baseType][0].value
}

function normalizeColumnDisplayFormat(value: unknown, valueType: ColumnValueType) {
  const raw = normalizeCellValue(value).trim()
  if (valueType === 'date') {
    return raw || DEFAULT_DATE_DISPLAY_FORMAT
  }
  if (valueType === 'number') {
    return raw
  }
  if (valueType === 'percent') {
    return raw || DEFAULT_PERCENT_DISPLAY_FORMAT
  }
  return ''
}

function isDefaultColumnDisplayFormat(valueType: ColumnValueType, displayFormat: string) {
  if (valueType === 'date') {
    return normalizeColumnDisplayFormat(displayFormat, valueType) === DEFAULT_DATE_DISPLAY_FORMAT
  }
  if (valueType === 'percent') {
    return normalizeColumnDisplayFormat(displayFormat, valueType) === DEFAULT_PERCENT_DISPLAY_FORMAT
  }
  return normalizeColumnDisplayFormat(displayFormat, valueType) === ''
}

function normalizeColumnHashColorMode(value: unknown): ColumnHashColorMode {
  if (value === 'text' || value === 'background') {
    return value
  }
  return 'none'
}

function normalizeColumnHashColorTone(value: unknown): ColumnHashColorTone {
  return value === 'dark' ? 'dark' : 'light'
}

function normalizeColumnWidthMode(value: unknown): ColumnWidthMode {
  return value === 'fixed' ? 'fixed' : 'adaptive'
}

function normalizeColumnFontFamily(value: unknown): ColumnFontFamily {
  return value === 'monospace' ? 'monospace' : 'default'
}

function normalizeColumnFontSize(value: unknown) {
  const numeric = Number(value)
  if (!Number.isFinite(numeric) || numeric <= 0) {
    return DEFAULT_COLUMN_FONT_SIZE
  }
  return Math.min(Math.round(numeric), MAX_COLUMN_FONT_SIZE)
}

function normalizeColumnNote(value: unknown) {
  return normalizeCellValue(value).trim()
}

function normalizeHyperlinkUrl(value: unknown) {
  const raw = normalizeCellValue(value).trim()
  if (!raw) {
    return ''
  }

  const compact = raw.slice(0, 2048)
  const lower = compact.toLowerCase()
  if (
    lower.startsWith('javascript:')
    || lower.startsWith('data:')
    || lower.startsWith('vbscript:')
  ) {
    return ''
  }

  if (
    /^[a-z][a-z\d+.-]*:/i.test(compact)
    || compact.startsWith('/')
    || compact.startsWith('#')
  ) {
    return compact
  }

  if (/^[^\s]+\.[^\s]+/.test(compact)) {
    return `https://${compact}`
  }

  return compact
}

function isColumnHiddenConfigValue(value: unknown) {
  return value === true
}

function createDefaultSheetViewSettings(heightMode: SheetHeightMode = DEFAULT_SHEET_HEIGHT_MODE): Required<SheetViewSettings> {
  return {
    show_row_numbers: true,
    row_marker_numbering: 'global',
    row_marker_origin: 'sheet',
    show_column_markers: true,
    column_marker_style: 'letters',
    column_note_display: 'none',
    height_mode: heightMode,
    mobile_default_view: 'sheet',
    frozen_column_count: 0,
    pagination: {
      enabled: false,
      page_size: DEFAULT_PAGE_SIZE,
    },
  }
}

function normalizeColumnMarkerStyle(value: unknown): ColumnMarkerStyle {
  return value === 'numbers' ? 'numbers' : 'letters'
}

function normalizeRowMarkerNumbering(value: unknown): RowMarkerNumbering {
  return value === 'page' ? 'page' : 'global'
}

function normalizeRowMarkerOrigin(value: unknown): RowMarkerOrigin {
  if (value === 'sheet' || value === 'sheet_zero') {
    return value
  }
  return 'data'
}

function normalizeColumnNoteDisplayMode(
  value: unknown,
  fallback: ColumnNoteDisplayMode = 'none',
): ColumnNoteDisplayMode {
  if (value === 'none' || value === 'hover' || value === 'row') {
    return value
  }
  return fallback
}

function normalizeSheetHeightMode(value: unknown, fallback: SheetHeightMode = DEFAULT_SHEET_HEIGHT_MODE): SheetHeightMode {
  if (value === 'fill' || value === 'content') {
    return value
  }
  return fallback
}

function normalizeSheetMobileDefaultView(value: unknown): SheetMobileDefaultView {
  return value === 'lookup' ? 'lookup' : 'sheet'
}

function getDefaultSheetHeightMode() {
  return normalizeSheetHeightMode(props.defaultHeightMode)
}

function normalizeFormulaReferenceOrigin(value: unknown): FormulaReferenceOrigin {
  if (value === 'sheet' || value === 'sheet_v2') {
    return value
  }
  return 'data'
}

function normalizeSheetPageSize(value: unknown) {
  const numeric = Number(value)
  if (!Number.isFinite(numeric)) {
    return DEFAULT_PAGE_SIZE
  }
  return Math.min(Math.max(Math.round(numeric), 1), 1000)
}

function normalizeFrozenColumnCount(value: unknown, columnCount = Number.MAX_SAFE_INTEGER) {
  const numeric = Number(value)
  if (!Number.isFinite(numeric)) {
    return 0
  }
  const maxColumnCount = Number.isFinite(columnCount)
    ? Math.max(0, Math.floor(columnCount))
    : Number.MAX_SAFE_INTEGER
  return Math.min(Math.max(Math.floor(numeric), 0), maxColumnCount)
}

function normalizeSheetViewSettings(
  source: unknown,
  columnCount = Number.MAX_SAFE_INTEGER,
  defaultHeightMode: SheetHeightMode = DEFAULT_SHEET_HEIGHT_MODE,
  defaultColumnNoteDisplay: ColumnNoteDisplayMode = 'none',
): Required<SheetViewSettings> {
  const defaults = createDefaultSheetViewSettings(defaultHeightMode)
  defaults.column_note_display = defaultColumnNoteDisplay
  if (!source || typeof source !== 'object') {
    return defaults
  }

  const record = source as Record<string, unknown>
  return {
    show_row_numbers: record.show_row_numbers !== false,
    row_marker_numbering: normalizeRowMarkerNumbering(record.row_marker_numbering),
    row_marker_origin: normalizeRowMarkerOrigin(record.row_marker_origin),
    show_column_markers: record.show_column_markers !== false,
    column_marker_style: normalizeColumnMarkerStyle(record.column_marker_style),
    column_note_display: normalizeColumnNoteDisplayMode(record.column_note_display, defaults.column_note_display),
    height_mode: normalizeSheetHeightMode(record.height_mode, defaultHeightMode),
    mobile_default_view: normalizeSheetMobileDefaultView(record.mobile_default_view),
    frozen_column_count: normalizeFrozenColumnCount(record.frozen_column_count, columnCount),
    pagination: (() => {
      const pagination = record.pagination
      if (!pagination || typeof pagination !== 'object') {
        return { ...defaults.pagination }
      }
      const paginationRecord = pagination as Record<string, unknown>
      return {
        enabled: paginationRecord.enabled === true,
        page_size: normalizeSheetPageSize(paginationRecord.page_size),
      }
    })(),
  }
}

function isDefinedNameValid(name: string) {
  return DEFINED_NAME_RE.test(name)
    && !DEFINED_NAME_A1_RE.test(name)
    && !DEFINED_NAME_R1C1_RE.test(name)
}

function normalizeDefinedNameFormula(value: unknown) {
  const text = normalizeCellValue(value).trim()
  if (!text) {
    return ''
  }
  return normalizeFormulaInputExpression(text.startsWith('=') ? text : `=${text}`)
}

function normalizeDefinedNameItems(
  source: unknown,
  scope?: NoteSheetDefinedNameItem['scope'],
): NoteSheetDefinedNameItem[] {
  if (!Array.isArray(source)) {
    return []
  }
  const result: NoteSheetDefinedNameItem[] = []
  const seen = new Set<string>()
  source.forEach((item) => {
    if (!item || typeof item !== 'object') {
      return
    }
    const record = item as Record<string, unknown>
    const name = normalizeCellValue(record.name).trim()
    if (!name || !isDefinedNameValid(name)) {
      return
    }
    const key = name.toLowerCase()
    if (seen.has(key)) {
      return
    }
    seen.add(key)
    result.push({
      name,
      formula: normalizeDefinedNameFormula(record.formula),
      comment: normalizeCellValue(record.comment).trim(),
      scope: scope ?? (record.scope === 'workbook' || record.scope === 'worksheet' ? record.scope : undefined),
    })
  })
  return result
}

function serializeDefinedNameItems(source: NoteSheetDefinedNameItem[]) {
  return normalizeDefinedNameItems(source).map((item) => ({
    name: item.name,
    formula: item.formula,
    comment: item.comment ?? '',
  }))
}

function areDefinedNameItemsEqual(left: NoteSheetDefinedNameItem[], right: NoteSheetDefinedNameItem[]) {
  const normalizedLeft = normalizeDefinedNameItems(left)
  const normalizedRight = normalizeDefinedNameItems(right)
  if (normalizedLeft.length !== normalizedRight.length) {
    return false
  }
  return normalizedLeft.every((item, index) => {
    const other = normalizedRight[index]
    return !!other
      && item.name === other.name
      && item.formula === other.formula
      && (item.comment ?? '') === (other.comment ?? '')
      && item.scope === other.scope
  })
}

function areDefinedNameWorksheetScopesEqual(
  left: NoteSheetDefinedNameWorksheetScope[],
  right: NoteSheetDefinedNameWorksheetScope[],
) {
  if (left.length !== right.length) {
    return false
  }
  return left.every((item, index) => {
    const other = right[index]
    return !!other
      && item.sheet_id === other.sheet_id
      && item.sheet_title === other.sheet_title
      && item.sheet_version === other.sheet_version
      && areDefinedNameItemsEqual(item.names, other.names)
  })
}

function getDefinedNameWorksheetScopeKey(sheetId: number): DefinedNameScopeKey {
  return `worksheet:${sheetId}`
}

function parseDefinedNameWorksheetScopeKey(scopeKey: DefinedNameScopeKey) {
  if (!scopeKey.startsWith('worksheet:')) {
    return null
  }
  const sheetId = Number(scopeKey.slice('worksheet:'.length))
  return Number.isInteger(sheetId) && sheetId > 0 ? sheetId : null
}

function normalizeDefinedNameWorksheetScopes(source: unknown): NoteSheetDefinedNameWorksheetScope[] {
  if (!Array.isArray(source)) {
    return []
  }
  const result: NoteSheetDefinedNameWorksheetScope[] = []
  const seen = new Set<number>()
  source.forEach((item) => {
    if (!item || typeof item !== 'object') {
      return
    }
    const record = item as Record<string, unknown>
    const sheetId = Number(record.sheet_id)
    if (!Number.isInteger(sheetId) || sheetId <= 0 || seen.has(sheetId)) {
      return
    }
    seen.add(sheetId)
    const sheetVersion = Number(record.sheet_version)
    result.push({
      sheet_id: sheetId,
      sheet_title: normalizeCellValue(record.sheet_title).trim() || `工作表${sheetId}`,
      sheet_version: Number.isFinite(sheetVersion) ? sheetVersion : null,
      names: normalizeDefinedNameItems(record.names, 'worksheet'),
    })
  })
  return result
}

const definedNameScopeOptions = computed(() => [
  ...(props.workbookId != null
    ? [{ value: 'workbook' as DefinedNameScopeKey, label: '工作簿（全部工作表）' }]
    : []),
  ...definedNameWorksheetScopes.value.map((item) => ({
    value: getDefinedNameWorksheetScopeKey(item.sheet_id),
    label: item.sheet_title || `工作表${item.sheet_id}`,
  })),
])

function getCurrentDefinedNameWorksheetScopeKey(): DefinedNameScopeKey {
  const currentSheetId = Number(props.sheetId)
  if (Number.isInteger(currentSheetId) && currentSheetId > 0) {
    const currentScope = definedNameWorksheetScopes.value.find((item) => item.sheet_id === currentSheetId)
    if (currentScope) {
      return getDefinedNameWorksheetScopeKey(currentSheetId)
    }
  }
  const firstScope = definedNameWorksheetScopes.value[0]
  if (firstScope) {
    return getDefinedNameWorksheetScopeKey(firstScope.sheet_id)
  }
  return props.workbookId != null ? 'workbook' : getDefinedNameWorksheetScopeKey(currentSheetId)
}

function serializeDefinedNameWorksheetScopes(
  worksheetNamesBySheetId: Map<number, NoteSheetDefinedNameItem[]>,
): NoteSheetDefinedNameWorksheetScope[] {
  return definedNameWorksheetScopes.value.map((scope) => ({
    sheet_id: scope.sheet_id,
    sheet_title: scope.sheet_title,
    sheet_version: scope.sheet_version,
    names: serializeDefinedNameItems(worksheetNamesBySheetId.get(scope.sheet_id) ?? []),
  }))
}

function syncDefinedNamesFromResponse(response: NoteSheetDefinedNamesResponse) {
  const nextWorkbookDefinedNames = normalizeDefinedNameItems(response.workbook, 'workbook')
  const responseWorksheets = normalizeDefinedNameWorksheetScopes(response.worksheets)
  const fallbackWorksheetNames = normalizeDefinedNameItems(response.worksheet, 'worksheet')
  const currentSheetId = Number(props.sheetId)
  let nextWorksheetScopes: NoteSheetDefinedNameWorksheetScope[] = []
  if (responseWorksheets.length) {
    nextWorksheetScopes = responseWorksheets
  } else if (Number.isInteger(currentSheetId) && currentSheetId > 0) {
    nextWorksheetScopes = [{
      sheet_id: currentSheetId,
      sheet_title: sheetTitle.value || `工作表${currentSheetId}`,
      sheet_version: Number.isFinite(response.sheet_version) ? Number(response.sheet_version) : null,
      names: fallbackWorksheetNames,
    }]
  }

  const activeWorksheet = nextWorksheetScopes.find((item) => item.sheet_id === currentSheetId)
  const nextSheetDefinedNames = activeWorksheet
    ? normalizeDefinedNameItems(activeWorksheet.names, 'worksheet')
    : fallbackWorksheetNames
  const formulaContextChanged = !areDefinedNameItemsEqual(workbookDefinedNames.value, nextWorkbookDefinedNames)
    || !areDefinedNameItemsEqual(sheetDefinedNames.value, nextSheetDefinedNames)

  if (!areDefinedNameItemsEqual(workbookDefinedNames.value, nextWorkbookDefinedNames)) {
    workbookDefinedNames.value = nextWorkbookDefinedNames
  }
  if (!areDefinedNameWorksheetScopesEqual(definedNameWorksheetScopes.value, nextWorksheetScopes)) {
    definedNameWorksheetScopes.value = nextWorksheetScopes
  }
  if (!areDefinedNameItemsEqual(sheetDefinedNames.value, nextSheetDefinedNames)) {
    sheetDefinedNames.value = nextSheetDefinedNames
  }
  const activeSheetVersion = activeWorksheet?.sheet_version ?? response.sheet_version
  if (Number.isFinite(activeSheetVersion)) {
    sheetVersion.value = Number(activeSheetVersion)
  }
  return formulaContextChanged
}

function normalizeColumnConfigs(source: unknown, headers: string[]): Record<string, SheetColumnConfig> {
  if (!source || typeof source !== 'object') {
    return {}
  }

  const record = source as Record<string, unknown>
  const normalized: Record<string, SheetColumnConfig> = {}

  for (const header of headers) {
    const config = record[header]
    if (!config || typeof config !== 'object') {
      continue
    }

    const configRecord = config as Record<string, unknown>
    const valueType = normalizeColumnValueType(configRecord.value_type)
    const textRule = normalizeColumnTextRuleFromRecord(configRecord, valueType)
    const valueMode = normalizeColumnValueMode(configRecord.value_mode)
    const filterEnabled = configRecord.filter_enabled === true
    const displayFormat = normalizeColumnDisplayFormat(configRecord.display_format, valueType)
    const allowEmpty = configRecord.allow_empty !== false
    const displayMode = normalizeColumnDisplayMode(configRecord.display_mode)
    const align = normalizeColumnTextAlign(configRecord.align)
    const trimWhitespace = configRecord.trim_whitespace !== false
    const duplicateValueHighlight = configRecord.duplicate_value_highlight === true
    const hashColorMode = normalizeColumnHashColorMode(configRecord.hash_color_mode)
    const hashColorTone = normalizeColumnHashColorTone(configRecord.hash_color_tone)
    const widthMode = normalizeColumnWidthMode(configRecord.width_mode)
    const fontFamily = normalizeColumnFontFamily(configRecord.font_family)
    const fontSize = normalizeColumnFontSize(configRecord.font_size)
    const hidden = isColumnHiddenConfigValue(configRecord.hidden)
    const restoreIndex = normalizeNonNegativeInt(configRecord.restore_index, -1)
    const headerBackgroundColor = normalizeCssColor(configRecord.header_background_color)
    const headerTextColor = normalizeCssColor(configRecord.header_text_color)
    const noteWithLink = splitColumnNoteLeadingLink(configRecord.note)
    const note = noteWithLink.note
    const headerLink = normalizeCellLink(configRecord.header_link) ?? noteWithLink.link

    if (
      valueType !== 'text'
      || textRule !== 'none'
      || valueMode !== 'free'
      || filterEnabled
      || !isDefaultColumnDisplayFormat(valueType, displayFormat)
      || allowEmpty === false
      || displayMode !== DEFAULT_COLUMN_DISPLAY_MODE
      || align !== DEFAULT_COLUMN_TEXT_ALIGN
      || trimWhitespace === false
      || duplicateValueHighlight
      || hashColorMode !== 'none'
      || widthMode !== 'adaptive'
      || fontFamily !== 'default'
      || fontSize !== DEFAULT_COLUMN_FONT_SIZE
      || hidden
      || restoreIndex >= 0
      || headerBackgroundColor
      || headerTextColor
      || note
      || headerLink
    ) {
      normalized[header] = {}
      if (valueType !== 'text') {
        normalized[header].value_type = valueType
      }
      if (valueType === 'text' && textRule !== 'none') {
        normalized[header].text_rule = textRule
      }
      if (valueMode !== 'free') {
        normalized[header].value_mode = valueMode
      }
      if (filterEnabled) {
        normalized[header].filter_enabled = true
      }
      if (!isDefaultColumnDisplayFormat(valueType, displayFormat)) {
        normalized[header].display_format = displayFormat
      }
      if (!allowEmpty) {
        normalized[header].allow_empty = false
      }
      if (displayMode !== DEFAULT_COLUMN_DISPLAY_MODE) {
        normalized[header].display_mode = displayMode
      }
      if (align !== DEFAULT_COLUMN_TEXT_ALIGN) {
        normalized[header].align = align
      }
      if (!trimWhitespace) {
        normalized[header].trim_whitespace = false
      }
      if (duplicateValueHighlight) {
        normalized[header].duplicate_value_highlight = true
      }
      if (hashColorMode !== 'none') {
        normalized[header].hash_color_mode = hashColorMode
        if (hashColorTone !== 'light') {
          normalized[header].hash_color_tone = hashColorTone
        }
      }
      if (widthMode !== 'adaptive') {
        normalized[header].width_mode = widthMode
      }
      if (fontFamily !== 'default') {
        normalized[header].font_family = fontFamily
      }
      if (fontSize !== DEFAULT_COLUMN_FONT_SIZE) {
        normalized[header].font_size = fontSize
      }
      if (hidden) {
        normalized[header].hidden = true
      }
      if (restoreIndex >= 0) {
        normalized[header].restore_index = restoreIndex
      }
      if (headerBackgroundColor) {
        normalized[header].header_background_color = headerBackgroundColor
      }
      if (headerTextColor) {
        normalized[header].header_text_color = headerTextColor
      }
      if (note) {
        normalized[header].note = note
      }
      if (headerLink) {
        normalized[header].header_link = headerLink
      }
    }
  }

  return normalized
}

function normalizeColumnConfig(source: unknown): ColumnSettingsDraft {
  if (!source || typeof source !== 'object') {
    return createDefaultColumnSettingsDraft()
  }

  const record = source as Record<string, unknown>
  const valueType = normalizeColumnValueType(record.value_type)
  const textRule = normalizeColumnTextRuleFromRecord(record, valueType)
  const hashColorMode = normalizeColumnHashColorMode(record.hash_color_mode)
  return {
    value_type: valueType,
    text_rule: textRule,
    value_mode: normalizeColumnValueMode(record.value_mode),
    filter_enabled: record.filter_enabled === true,
    display_format: normalizeColumnDisplayFormat(record.display_format, valueType),
    allow_empty: record.allow_empty !== false,
    display_mode: normalizeColumnDisplayMode(record.display_mode),
    align: normalizeColumnTextAlign(record.align),
    trim_whitespace: record.trim_whitespace !== false,
    duplicate_value_highlight: record.duplicate_value_highlight === true,
    hash_color_mode: hashColorMode,
    hash_color_tone: hashColorMode === 'none' ? 'light' : normalizeColumnHashColorTone(record.hash_color_tone),
    width_mode: normalizeColumnWidthMode(record.width_mode),
    width_value: 120,
    font_family: normalizeColumnFontFamily(record.font_family),
    font_size: normalizeColumnFontSize(record.font_size),
  }
}

function createDefaultColumnSettingsDraft(): ColumnSettingsDraft {
  return {
    value_type: 'text',
    text_rule: 'none',
    value_mode: 'free',
    filter_enabled: false,
    display_format: '',
    allow_empty: true,
    display_mode: DEFAULT_COLUMN_DISPLAY_MODE,
    align: DEFAULT_COLUMN_TEXT_ALIGN,
    trim_whitespace: true,
    duplicate_value_highlight: false,
    hash_color_mode: 'none',
    hash_color_tone: 'light',
    width_mode: 'adaptive',
    width_value: 120,
    font_family: 'default',
    font_size: DEFAULT_COLUMN_FONT_SIZE,
  }
}

function createColumnSettingsTouchedState(touched = false): ColumnSettingsTouchedState {
  return Object.fromEntries(
    COLUMN_SETTINGS_KEYS.map((key) => [key, touched]),
  ) as ColumnSettingsTouchedState
}

function createColumnSettingsMixedState(): ColumnSettingsMixedState {
  return Object.fromEntries(
    COLUMN_SETTINGS_KEYS.map((key) => [key, false]),
  ) as ColumnSettingsMixedState
}

function getVisibleColumnCount() {
  return columnHeaders.value.length - hiddenColumnIndexes.value.length
}

function shouldShowHideColumnAction() {
  const bounds = getSelectionColumnBounds()
  if (!shouldShowColumnActions() || !bounds || !isSelectedByColumnHeader() || isSelectedByCorner()) {
    return false
  }
  const selectedCount = bounds.end - bounds.start + 1
  return getVisibleColumnCount() - selectedCount >= 1
}

function getHiddenColumnIndexesToShowFromSelection() {
  const bounds = getSelectionColumnBounds()
  const columnCount = columnHeaders.value.length
  if (!hasColumnHeaderSelection() || !bounds || columnCount <= 0) {
    return []
  }

  const start = Math.max(0, Math.min(bounds.start, columnCount - 1))
  const end = Math.max(start, Math.min(bounds.end, columnCount - 1))
  const isColumnHidden = (index: number) => {
    const header = columnHeaders.value[index]
    return !!header && columnConfigs.value[header]?.hidden === true
  }

  const indexes = new Set<number>()
  for (let index = start; index <= end; index += 1) {
    if (isColumnHidden(index)) {
      indexes.add(index)
    }
  }

  const visibleIndexes = columnHeaders.value
    .map((header, index) => (columnConfigs.value[header]?.hidden === true ? -1 : index))
    .filter((index) => index >= 0)
  const firstVisibleIndex = visibleIndexes[0]
  const lastVisibleIndex = visibleIndexes[visibleIndexes.length - 1]

  if (firstVisibleIndex != null && start <= firstVisibleIndex && firstVisibleIndex <= end) {
    for (let index = 0; index < firstVisibleIndex; index += 1) {
      if (isColumnHidden(index)) {
        indexes.add(index)
      }
    }
  }

  if (lastVisibleIndex != null && start <= lastVisibleIndex && lastVisibleIndex <= end) {
    for (let index = lastVisibleIndex + 1; index < columnCount; index += 1) {
      if (isColumnHidden(index)) {
        indexes.add(index)
      }
    }
  }

  return [...indexes].sort((left, right) => left - right)
}

function shouldShowShowColumnAction() {
  return getHiddenColumnIndexesToShowFromSelection().length > 0
}

function getDuplicateHighlightColorSeed(value: string) {
  return value.trim()
}

function getDuplicateHighlightBaseColor(seed: string) {
  const normalizedSeed = getDuplicateHighlightColorSeed(seed)
  if (!normalizedSeed) {
    return null
  }

  const colorIndex = stableHash32(normalizedSeed) % DUPLICATE_HIGHLIGHT_PALETTE.length
  return DUPLICATE_HIGHLIGHT_PALETTE[colorIndex] ?? DUPLICATE_HIGHLIGHT_PALETTE[0]
}

function parseHexColorToRgb(color: string): { r: number; g: number; b: number } | null {
  const match = color.trim().match(/^#?([0-9a-fA-F]{6})$/)
  if (!match) {
    return null
  }
  const value = match[1]
  return {
    r: Number.parseInt(value.slice(0, 2), 16),
    g: Number.parseInt(value.slice(2, 4), 16),
    b: Number.parseInt(value.slice(4, 6), 16),
  }
}

function rgbChannelToHex(value: number) {
  return Math.max(0, Math.min(255, Math.round(value))).toString(16).padStart(2, '0').toUpperCase()
}

function mixDuplicateHighlightColors(sourceColors: string[]) {
  const fillColor = parseHexColorToRgb('#FFFFFF')
  if (!fillColor) {
    return null
  }

  const entries = sourceColors
    .map((color) => parseHexColorToRgb(color))
    .filter((color): color is { r: number; g: number; b: number } => !!color)
  if (!entries.length) {
    return null
  }

  const sourceWeight = 100
  const fillWeight = entries.length * sourceWeight + 220
  const totalWeight = entries.length * sourceWeight + fillWeight
  const mixed = entries.reduce(
    (acc, color) => ({
      r: acc.r + color.r * sourceWeight,
      g: acc.g + color.g * sourceWeight,
      b: acc.b + color.b * sourceWeight,
    }),
    {
      r: fillColor.r * fillWeight,
      g: fillColor.g * fillWeight,
      b: fillColor.b * fillWeight,
    },
  )
  return `#${rgbChannelToHex(mixed.r / totalWeight)}${rgbChannelToHex(mixed.g / totalWeight)}${rgbChannelToHex(mixed.b / totalWeight)}`
}

function mixCellAccentStyle(sourceColors: string[]) {
  const normalizedSourceColors = sourceColors.filter(Boolean)
  if (!normalizedSourceColors.length) {
    return null
  }

  const cacheKey = normalizedSourceColors.join('|')
  const cached = duplicateHighlightStyleCache.get(cacheKey)
  if (cached) {
    return cached
  }

  const backgroundColor = mixDuplicateHighlightColors(normalizedSourceColors)
  if (!backgroundColor) {
    return null
  }

  const style = {
    backgroundColor,
  }
  duplicateHighlightStyleCache.set(cacheKey, style)
  return style
}

function normalizeRow(row: unknown, headers: string[]): SheetRow {
  if (Array.isArray(row)) {
    const normalized = row.slice(0, headers.length).map(normalizeCellValue)
    while (normalized.length < headers.length) {
      normalized.push('')
    }
    return normalized
  }

  if (row && typeof row === 'object') {
    const source = row as Record<string, unknown>
    return headers.map((header) => normalizeCellValue(source[header]))
  }

  return createEmptyRow(headers.length)
}

function getInlineCellMeta(source: unknown): SheetCellMeta | null {
  return normalizeCellMetaEntry(source)
}

function mergeInlineCellMetaIntoCellMeta(
  sourceMeta: SheetCellMetaMap,
  sourceRows: unknown[],
  dataStartRow: number,
  headers: string[],
  options: { normalizeResult?: boolean } = {},
) {
  const nextMeta: SheetCellMetaMap = { ...sourceMeta }
  sourceRows.forEach((row, rowIndex) => {
    if (!Array.isArray(row)) {
      return
    }
    row.slice(0, headers.length).forEach((cell, columnIndex) => {
      const inlineMeta = getInlineCellMeta(cell)
      if (!inlineMeta) {
        return
      }
      const key = createCellMetaKey(dataStartRow + rowIndex, columnIndex)
      nextMeta[key] = normalizeCellMetaEntry({ ...(nextMeta[key] ?? {}), ...inlineMeta }) ?? inlineMeta
    })
  })
  return options.normalizeResult === false ? nextMeta : normalizeCellMetaMap(nextMeta, headers.length)
}

function mergeSourceDocumentInlineLinksIntoCellMeta(
  sourceMeta: SheetCellMetaMap,
  source: unknown,
  dataStartRow: number,
  headers: string[],
) {
  if (!source || typeof source !== 'object') {
    return sourceMeta
  }

  const record = source as Record<string, unknown>
  let nextMeta = normalizeCellMetaMap(sourceMeta, headers.length)
  if (record.cell_meta && typeof record.cell_meta === 'object' && !Array.isArray(record.cell_meta)) {
    const rawMeta = normalizeCellMetaMap(record.cell_meta, headers.length)
    nextMeta = normalizeCellMetaMap({ ...nextMeta, ...rawMeta }, headers.length)
  }
  if (Array.isArray(record.rows)) {
    nextMeta = mergeInlineCellMetaIntoCellMeta(nextMeta, record.rows, dataStartRow, headers)
  }
  if (Array.isArray(record.grid_rows)) {
    const sourceDataStartRow = normalizeNonNegativeInt(record.data_start_row, dataStartRow)
    nextMeta = mergeInlineCellMetaIntoCellMeta(
      nextMeta,
      record.grid_rows.slice(0, sourceDataStartRow),
      0,
      headers,
    )
    nextMeta = mergeInlineCellMetaIntoCellMeta(
      nextMeta,
      record.grid_rows.slice(sourceDataStartRow),
      dataStartRow,
      headers,
    )
  }
  return normalizeCellMetaMap(nextMeta, headers.length)
}

function isMeaningfulRow(row: SheetRow): boolean {
  return row.some((cell) => cell.trim() !== '')
}

function trimTrailingBlankRows(sourceRows: SheetRow[]): SheetRow[] {
  let end = sourceRows.length
  while (end > 0 && !isMeaningfulRow(sourceRows[end - 1] ?? [])) {
    end -= 1
  }
  return sourceRows.slice(0, end)
}

function createDefaultDocument(defaultHeightMode: SheetHeightMode = getDefaultSheetHeightMode()): SheetDocument {
  const gridRows = [[...DEFAULT_SHEET_COLUMNS]]
  return {
    schema_version: 1,
    columns: [...DEFAULT_SHEET_COLUMNS],
    rows: [],
    grid_rows: gridRows,
    data_start_row: 1,
    field_row_index: 0,
    merged_cells: [],
    formula_reference_origin: 'sheet_v2',
    header_groups: [],
    cell_meta: {},
    column_configs: {},
    column_widths: DEFAULT_SHEET_COLUMNS.map((header) => getAdaptiveColumnWidth(header)),
    view_settings: createDefaultSheetViewSettings(defaultHeightMode),
    defined_names: [],
  }
}

function normalizeRowsFormulaReferencesForOrigin(
  sourceRows: SheetRow[],
  origin: FormulaReferenceOrigin,
  headerRowCount: number,
) {
  if (headerRowCount <= 0) {
    return sourceRows
  }
  if (origin === 'data') {
    return remapRowsFormulaReferencesByRowDelta(sourceRows, headerRowCount)
  }
  // The old "sheet" marker was produced by a short-lived migration that over-shifted A1 row refs.
  if (origin === 'sheet') {
    return remapRowsFormulaReferencesByRowDelta(sourceRows, -headerRowCount)
  }
  return sourceRows
}

function normalizeSheetDocument(
  source: unknown,
  formulaOptions: FormulaDisplayBuildOptions = {},
  defaultHeightMode: SheetHeightMode = DEFAULT_SHEET_HEIGHT_MODE,
): SheetDocument {
  if (!source || typeof source !== 'object') {
    return createDefaultDocument(defaultHeightMode)
  }

  const record = source as Record<string, unknown>
  const normalizeTraceDetail = {
    sourceRows: Array.isArray(record.rows) ? record.rows.length : 0,
    sourceGridRows: Array.isArray(record.grid_rows) ? record.grid_rows.length : 0,
    sourceColumns: Array.isArray(record.columns) ? record.columns.length : 0,
    sourceMergedCells: Array.isArray(record.merged_cells) ? record.merged_cells.length : 0,
    sourceCellMeta: record.cell_meta && typeof record.cell_meta === 'object' && !Array.isArray(record.cell_meta)
      ? Object.keys(record.cell_meta).length
      : 0,
  }
  const normalizeTrace = startSheetPerfTrace('sheet.normalizeDocument', {
    detail: normalizeTraceDetail,
  })
  const headers = normalizeHeaders(record.columns)
  const sourceRows = Array.isArray(record.rows) ? record.rows : []
  const sourceUnifiedGridRows = Array.isArray(record.grid_rows) ? record.grid_rows : []
  const sourceWidths = Array.isArray(record.column_widths) ? record.column_widths : []
  let normalizedColumnConfigs = normalizeColumnConfigs(record.column_configs, headers)
  const sourceHeaderGroups = normalizeHeaderGroups(record.header_groups, headers.length)
  const hasConfigColumnNotes = headers.some((header) => getDocumentColumnNote(header, normalizedColumnConfigs) !== '')
  const hasUnifiedGridRows = Array.isArray(record.grid_rows)
  normalizeTrace?.mark('headers-config')
  const unifiedSourceGridRows = hasUnifiedGridRows
    ? sourceUnifiedGridRows.map((row) => normalizeRow(row, headers))
    : []
  const inferredFieldRowIndex = normalizeNonNegativeInt(record.field_row_index, sourceHeaderGroups.length)
  const inferredDataStartRow = normalizeNonNegativeInt(record.data_start_row, sourceHeaderGroups.length + 1)
  const sourceHasMaterializedColumnNoteRow = (
    hasUnifiedGridRows
    && inferredDataStartRow > inferredFieldRowIndex + 1
    && unifiedSourceGridRows.length > inferredFieldRowIndex + 1
  )
  const fallbackColumnNoteDisplay = sourceHasMaterializedColumnNoteRow
    ? 'row'
    : hasConfigColumnNotes
      ? 'hover'
      : 'none'
  let normalizedSettings = normalizeSheetViewSettings(
    record.view_settings,
    headers.length,
    defaultHeightMode,
    fallbackColumnNoteDisplay,
  )
  if (
    normalizedSettings.column_note_display === 'hover'
    && !sourceHasMaterializedColumnNoteRow
    && !hasConfigColumnNotes
  ) {
    normalizedSettings = { ...normalizedSettings, column_note_display: 'none' }
  }
  normalizeTrace?.mark('grid-settings')
  const formulaHeaderRows = getFormulaHeaderRowsForDocument(
    headers,
    sourceHeaderGroups,
    normalizedColumnConfigs,
    normalizedSettings,
  )
  let dataStartRow = normalizeNonNegativeInt(record.data_start_row, formulaHeaderRows.length)
  const fieldRowIndex = normalizeNonNegativeInt(record.field_row_index, Math.max(0, formulaHeaderRows.length - 1))
  let sourceGridRows = hasUnifiedGridRows
    ? unifiedSourceGridRows
    : [
      ...formulaHeaderRows.map((row) => normalizeRow(row, headers)),
      ...sourceRows.map((row) => normalizeRow(row, headers)),
    ]
  const columnNoteRowIndex = fieldRowIndex + 1
  const shouldInsertMissingColumnNoteRow = (
    hasUnifiedGridRows
    && normalizedSettings.column_note_display !== 'none'
    && !sourceHasMaterializedColumnNoteRow
    && dataStartRow <= columnNoteRowIndex
  )
  const previousDataStartRow = dataStartRow
  if (shouldInsertMissingColumnNoteRow) {
    const nextGridRows = sourceGridRows.map((row) => normalizeRow(row, headers))
    while (nextGridRows.length < columnNoteRowIndex) {
      nextGridRows.push(createEmptyRow(headers.length))
    }
    nextGridRows.splice(
      columnNoteRowIndex,
      0,
      headers.map((header) => getDocumentColumnNote(header, normalizedColumnConfigs)),
    )
    sourceGridRows = nextGridRows
    dataStartRow += 1
  }
  const sourceFormulaOrigin = normalizeFormulaReferenceOrigin(record.formula_reference_origin)
  const sourceNormalizedRows = trimTrailingBlankRows(
    (hasUnifiedGridRows ? sourceGridRows.slice(dataStartRow) : sourceRows.map((row) => normalizeRow(row, headers))),
  )
  let normalizedRows = normalizeRowsFormulaReferencesForOrigin(
    sourceNormalizedRows,
    sourceFormulaOrigin,
    dataStartRow,
  )
  if (shouldInsertMissingColumnNoteRow && sourceFormulaOrigin === 'sheet_v2') {
    normalizedRows = remapRowsFormulaReferencesForHeaderRowCountChange(
      normalizedRows,
      previousDataStartRow,
      dataStartRow,
    )
  }
  normalizeTrace?.mark('source-rows')
  const initialNormalizedGridRows = [
    ...sourceGridRows.slice(0, dataStartRow).map((row) => normalizeRow(row, headers)),
    ...normalizedRows,
  ]
  const sourceMergedCells = [
    ...(!hasUnifiedGridRows ? getHeaderGroupMergeCells(sourceHeaderGroups) : []),
    ...(Array.isArray(record.merged_cells) ? record.merged_cells : []),
  ]
  const migratedMergedCells = shouldInsertMissingColumnNoteRow
    ? insertRowsIntoMergedCellSource(
      sourceMergedCells,
      columnNoteRowIndex,
      1,
      Math.max(initialNormalizedGridRows.length, getMergedCellsSourceRowCount(sourceMergedCells) + 1),
      headers.length,
    )
    : sourceMergedCells
  const normalizedMergedCells = normalizeMergedCells(
    migratedMergedCells,
    Math.max(initialNormalizedGridRows.length, getMergedCellsSourceRowCount(migratedMergedCells)),
    headers.length,
  )
  let normalizedGridRows = repairBlankHeaderMergeAnchors(
    initialNormalizedGridRows,
    normalizedMergedCells,
    headers,
    fieldRowIndex,
  )
  normalizedGridRows = repairCoveredMergedCellValuesInGridRows(
    normalizedGridRows,
    normalizedMergedCells,
    headers,
  )
  normalizeTrace?.mark('merge-grid')
  normalizedColumnConfigs = mergeGridNoteRowIntoColumnConfigs(
    normalizedColumnConfigs,
    normalizedGridRows,
    headers,
    fieldRowIndex,
    dataStartRow,
    { overwrite: true },
  )
  normalizedRows = trimTrailingBlankRows(
    normalizedGridRows.slice(dataStartRow).map((row) => normalizeRow(row, headers)),
  )
  const normalizedHeaderGroups = hasUnifiedGridRows
    ? createSingleCellHeaderGroupsFromGridRows(normalizedGridRows, fieldRowIndex, headers)
    : expandHeaderGroupsToSingleCellRows(sourceHeaderGroups, headers.length)
  const sourceCellMeta = hasUnifiedGridRows
    ? (
        shouldInsertMissingColumnNoteRow
          ? insertCellMetaRowKeys(record.cell_meta, columnNoteRowIndex, 1, headers.length)
          : normalizeCellMetaMap(record.cell_meta, headers.length)
      )
    : shiftCellMetaRowKeys(record.cell_meta, dataStartRow, headers.length)
  normalizeTrace?.mark('cell-meta-source')
  const sourceCellMetaWithStoredLinks = sourceCellMeta
  const sourceCellMetaWithInlineHeaderLinks = hasUnifiedGridRows
    ? mergeInlineCellMetaIntoCellMeta(
      sourceCellMetaWithStoredLinks,
      sourceUnifiedGridRows.slice(0, previousDataStartRow),
      0,
      headers,
      { normalizeResult: false },
    )
    : sourceCellMetaWithStoredLinks
  normalizeTrace?.mark('cell-meta-inline-header-links')
  const sourceCellMetaWithInlineRowLinks = mergeInlineCellMetaIntoCellMeta(
    sourceCellMetaWithInlineHeaderLinks,
    sourceRows,
    dataStartRow,
    headers,
    { normalizeResult: false },
  )
  normalizeTrace?.mark('cell-meta-inline-row-links')
  const sourceCellMetaWithInlineGridLinks = hasUnifiedGridRows
    ? mergeInlineCellMetaIntoCellMeta(
      sourceCellMetaWithInlineRowLinks,
      sourceUnifiedGridRows.slice(previousDataStartRow),
      dataStartRow,
      headers,
      { normalizeResult: false },
    )
    : sourceCellMetaWithInlineRowLinks
  const sourceCellMetaWithInlineLinks = normalizeCellMetaMap(sourceCellMetaWithInlineGridLinks, headers.length)
  normalizeTrace?.mark('cell-meta-inline-grid-links')
  const normalizedCellMeta = finalizeNormalizedSheetCellMeta(
    sourceCellMetaWithInlineLinks,
    normalizedGridRows,
    headers,
    dataStartRow,
    normalizeTrace,
  )
  normalizeTrace?.mark('cell-meta')
  const normalizedEntityColumns = normalizeEntityColumns(record.entity_columns, headers)
  const normalizedEntityRows = normalizeEntityRows(
    record.entity_rows,
    dataStartRow,
    fieldRowIndex,
    Math.max(
      normalizedRows.length,
      Array.isArray(record.entity_rows) ? Math.max(0, record.entity_rows.length - dataStartRow) : 0,
    ),
  )
  const normalizedEntityCells = stripCellLinksFromEntityCellMap(normalizeEntityCellMap(record.entity_cells))
  normalizeTrace?.mark('entities')
  const normalizedFormulaHeaderRows = normalizedGridRows
    .slice(0, dataStartRow)
    .map((row) => normalizeRow(row, headers))
  const formulaDisplayForWidths = formulaEngineClass.value
    ? buildFormulaDisplayStateForRows(
        headers,
        normalizedRows,
        normalizedColumnConfigs,
        {
          ...formulaOptions,
          headerRows: normalizedFormulaHeaderRows,
          headerRowCount: dataStartRow,
        },
      )
    : createEmptyFormulaDisplayState(dataStartRow)
  normalizeTrace?.mark('formula-display')
  const normalizedWidths = headers.map((_, index) => {
    const width = Number(sourceWidths[index])
    if (Number.isFinite(width) && width > 0) {
      return normalizeColumnWidthValue(width)
    }
    return getAutoColumnWidth(index, headers, normalizedRows, normalizedColumnConfigs, formulaDisplayForWidths)
  })
  normalizeTrace?.mark('formula-widths')
  const normalizedDocument: SheetDocument = {
    schema_version: 1,
    columns: headers,
    rows: normalizedRows,
    grid_rows: normalizedGridRows,
    data_start_row: dataStartRow,
    field_row_index: fieldRowIndex,
    merged_cells: normalizedMergedCells,
    formula_reference_origin: 'sheet_v2',
    header_groups: normalizedHeaderGroups,
    cell_meta: normalizedCellMeta,
    entity_columns: normalizedEntityColumns,
    entity_rows: normalizedEntityRows,
    entity_cells: normalizedEntityCells,
    column_configs: normalizedColumnConfigs,
    column_widths: normalizedWidths,
    view_settings: normalizedSettings,
    defined_names: normalizeDefinedNameItems(record.defined_names, 'worksheet'),
  }
  normalizeTrace?.finish({
    detail: {
      ...normalizeTraceDetail,
      rows: normalizedRows.length,
      gridRows: normalizedGridRows.length,
      columns: headers.length,
      mergedCells: normalizedMergedCells.length,
      cellMeta: Object.keys(normalizedCellMeta).length,
      entityRows: normalizedEntityRows.length,
      entityColumns: normalizedEntityColumns.length,
    },
  })
  normalizedDocumentFormulaDisplayCache.set(normalizedDocument, formulaDisplayForWidths)
  normalizedDocumentCellMetaCache.set(normalizedDocument, normalizedCellMeta)
  return normalizedDocument
}

function mergeRemoteHeaderPrefixIntoLocalDraft(localDocument: SheetDocument, remoteDocument: SheetDocument): SheetDocument {
  const headers = normalizeHeaders(remoteDocument.columns)
  const localHeaders = normalizeHeaders(localDocument.columns)
  if (
    headers.length !== localHeaders.length
    || headers.some((header, index) => header !== localHeaders[index])
  ) {
    return localDocument
  }

  const dataStartRow = normalizeNonNegativeInt(remoteDocument.data_start_row, 0)
  if (dataStartRow <= 0 || !Array.isArray(remoteDocument.grid_rows)) {
    return localDocument
  }

  const remoteFieldRowIndex = normalizeNonNegativeInt(remoteDocument.field_row_index, Math.max(0, dataStartRow - 1))
  const localDataStartRow = normalizeNonNegativeInt(localDocument.data_start_row, dataStartRow)
  const localFieldRowIndex = normalizeNonNegativeInt(localDocument.field_row_index, Math.max(0, localDataStartRow - 1))
  const remoteHeaderGroups = normalizeHeaderGroups(remoteDocument.header_groups, headers.length)
  const localHeaderGroups = normalizeHeaderGroups(localDocument.header_groups, headers.length)
  const remoteMergedCells = normalizeMergedCells(remoteDocument.merged_cells, remoteDocument.grid_rows.length, headers.length)
  const localMergedCells = normalizeMergedCells(localDocument.merged_cells, Math.max(localDocument.grid_rows?.length ?? 0, dataStartRow), headers.length)
  let changed = (
    localDataStartRow !== dataStartRow
    || localFieldRowIndex !== remoteFieldRowIndex
    || JSON.stringify(localHeaderGroups) !== JSON.stringify(remoteHeaderGroups)
    || JSON.stringify(localMergedCells) !== JSON.stringify(remoteMergedCells)
  )
  const nextDocument: SheetDocument = {
    ...localDocument,
    data_start_row: dataStartRow,
    field_row_index: remoteFieldRowIndex,
    header_groups: remoteHeaderGroups,
    merged_cells: remoteMergedCells,
  }
  if (localDataStartRow !== dataStartRow) {
    const prefixDelta = dataStartRow - localDataStartRow
    if (prefixDelta > 0) {
      nextDocument.rows = localDocument.rows.slice(prefixDelta)
    }
  }

  const remoteSettings = normalizeSheetViewSettings(remoteDocument.view_settings, headers.length)
  const localSettings = normalizeSheetViewSettings(localDocument.view_settings, headers.length)
  if (remoteSettings.column_note_display === 'row' && localSettings.column_note_display !== 'row') {
    nextDocument.view_settings = {
      ...(localDocument.view_settings ?? {}),
      column_note_display: 'row',
    }
    changed = true
  }

  const localGridRows = Array.isArray(localDocument.grid_rows)
    ? localDocument.grid_rows.map((row) => normalizeRow(row, headers))
    : []
  const remoteGridRows = remoteDocument.grid_rows.map((row) => normalizeRow(row, headers))
  const remotePrefixRows = remoteGridRows
    .slice(0, dataStartRow)
    .map((row) => normalizeRow(row, headers))
  while (remotePrefixRows.length < dataStartRow) {
    remotePrefixRows.push(createEmptyRow(headers.length))
  }
  const localPrefixRows = localGridRows
    .slice(0, dataStartRow)
    .map((row) => normalizeRow(row, headers))
  const prefixChanged = (
    localPrefixRows.length !== remotePrefixRows.length
    || remotePrefixRows.some((row, rowIndex) => row.some((value, columnIndex) => (
      normalizeCellValue(value) !== normalizeCellValue(localPrefixRows[rowIndex]?.[columnIndex] ?? '')
    )))
  )
  if (prefixChanged) {
    changed = true
  }

  nextDocument.grid_rows = [
    ...remotePrefixRows,
    ...nextDocument.rows.map((row) => normalizeRow(row, headers)),
  ]

  const normalizedLocalConfigs = normalizeColumnConfigs(localDocument.column_configs, headers)
  const normalizedRemoteConfigs = normalizeColumnConfigs(remoteDocument.column_configs, headers)
  const mergedStandardConfigs = mergeRemoteStandardColumnConfigsIntoLocalDraft(
    normalizedLocalConfigs,
    normalizedRemoteConfigs,
    headers,
  )
  const mergedConfigs = mergeGridNoteRowIntoColumnConfigs(
    mergedStandardConfigs,
    remoteGridRows,
    headers,
    normalizeNonNegativeInt(remoteDocument.field_row_index, Math.max(0, dataStartRow - 1)),
    dataStartRow,
    { overwrite: true },
  )
  const configsChanged = mergedConfigs !== normalizedLocalConfigs
  if (configsChanged) {
    nextDocument.column_configs = mergedConfigs
  }

  return changed || configsChanged ? nextDocument : localDocument
}

function isRemoteHeaderPrefixCompatibleWithLocalDraft(localDocument: SheetDocument, remoteDocument: SheetDocument) {
  const headers = normalizeHeaders(remoteDocument.columns)
  const localHeaders = normalizeHeaders(localDocument.columns)
  if (
    headers.length !== localHeaders.length
    || headers.some((header, index) => header !== localHeaders[index])
  ) {
    return false
  }

  const dataStartRow = normalizeNonNegativeInt(remoteDocument.data_start_row, 0)
  if (dataStartRow <= 0 || !Array.isArray(remoteDocument.grid_rows)) {
    return true
  }

  const localGridRows = Array.isArray(localDocument.grid_rows)
    ? localDocument.grid_rows.map((row) => normalizeRow(row, headers))
    : []
  const remoteGridRows = remoteDocument.grid_rows.map((row) => normalizeRow(row, headers))
  for (let rowIndex = 0; rowIndex < dataStartRow && rowIndex < remoteGridRows.length; rowIndex += 1) {
    for (let columnIndex = 0; columnIndex < headers.length; columnIndex += 1) {
      const remoteValue = normalizeCellValue(remoteGridRows[rowIndex]?.[columnIndex] ?? '')
      if (!remoteValue) {
        continue
      }
      const localValue = normalizeCellValue(localGridRows[rowIndex]?.[columnIndex] ?? '')
      if (localValue !== remoteValue) {
        return false
      }
    }
  }
  return true
}

function getDocumentStoredCell(document: SheetDocument, dataRowIndex: number, columnIndex: number): unknown {
  const row = Array.isArray(document.rows) ? document.rows[dataRowIndex] : null
  if (Array.isArray(row) && columnIndex < row.length) {
    return row[columnIndex]
  }

  const dataStartRow = normalizeNonNegativeInt(document.data_start_row, 0)
  const gridRow = Array.isArray(document.grid_rows) ? document.grid_rows[dataStartRow + dataRowIndex] : null
  if (Array.isArray(gridRow) && columnIndex < gridRow.length) {
    return gridRow[columnIndex]
  }
  return ''
}

function getDocumentStoredCellLink(document: SheetDocument, dataRowIndex: number, columnIndex: number) {
  const inlineLink = normalizeCellLink(getDocumentStoredCell(document, dataRowIndex, columnIndex))
  if (inlineLink) {
    return inlineLink
  }

  const headers = normalizeHeaders(document.columns)
  if (columnIndex < 0 || columnIndex >= headers.length) {
    return null
  }

  const dataStartRow = normalizeNonNegativeInt(document.data_start_row, 0)
  const documentRow = dataStartRow + dataRowIndex
  const cellMeta = normalizeCellMetaEntry((document.cell_meta ?? {})[createCellMetaKey(documentRow, columnIndex)])
  if (cellMeta?.link) {
    return cellMeta.link
  }

  const entityRows = normalizeEntityRows(
    document.entity_rows,
    dataStartRow,
    normalizeNonNegativeInt(document.field_row_index, Math.max(0, dataStartRow - 1)),
    Math.max(0, document.rows.length),
  )
  const entityColumns = normalizeEntityColumns(document.entity_columns, headers)
  const rowId = entityRows[documentRow]?.id
  const columnId = entityColumns[columnIndex]?.id
  if (!rowId || !columnId) {
    return null
  }

  return getEntityCellMeta(normalizeEntityCellMap(document.entity_cells)[rowId]?.[columnId])?.link ?? null
}

function isDraftPreservingRemoteCellLinks(localDocument: SheetDocument, remoteDocument: SheetDocument) {
  const headers = normalizeHeaders(remoteDocument.columns)
  const localHeaders = normalizeHeaders(localDocument.columns)
  if (
    headers.length !== localHeaders.length
    || headers.some((header, index) => header !== localHeaders[index])
  ) {
    return true
  }

  const rowCount = Math.min(localDocument.rows.length, remoteDocument.rows.length)
  for (let rowIndex = 0; rowIndex < rowCount; rowIndex += 1) {
    for (let columnIndex = 0; columnIndex < headers.length; columnIndex += 1) {
      const remoteCell = getDocumentStoredCell(remoteDocument, rowIndex, columnIndex)
      const remoteLink = getDocumentStoredCellLink(remoteDocument, rowIndex, columnIndex)
      if (!remoteLink) {
        continue
      }

      const localCell = getDocumentStoredCell(localDocument, rowIndex, columnIndex)
      if (normalizeCellValue(localCell) !== normalizeCellValue(remoteCell)) {
        continue
      }
      if (!getDocumentStoredCellLink(localDocument, rowIndex, columnIndex)) {
        return false
      }
    }
  }
  return true
}

function buildCurrentDocument(): SheetDocument {
  const headers = normalizeHeaders(columnHeaders.value)
  const normalizedRows = trimTrailingBlankRows(rows.value.map((row) => normalizeRow(row, headers)))
  const entitySnapshot = buildCurrentEntitySnapshot(headers, normalizedRows)
  const normalizedGridRows = sheetGridRows.value.map((row) => normalizeRow(row, headers))
  return {
    schema_version: 1,
    columns: headers,
    column_ids: [...columnEntityIds.value],
    rows: entitySnapshot.rows,
    row_ids: [...dataRowEntityIds.value],
    grid_rows: buildGridRowsWithInlineLinks(
      normalizedGridRows,
      entitySnapshot.entity_rows,
      entitySnapshot.entity_columns,
      entitySnapshot.entity_cells,
    ),
    data_start_row: sheetHeaderRowCount.value,
    field_row_index: columnHeaderLevel.value,
    merged_cells: normalizeMergedCells(mergedCells.value, sheetHeaderRowCount.value + totalRowCount.value, headers.length),
    formula_reference_origin: 'sheet_v2',
    header_groups: normalizeHeaderGroups(headerGroups.value, headers.length),
    cell_meta: stripCellLinksFromMetaMap(entitySnapshot.cell_meta),
    entity_columns: entitySnapshot.entity_columns,
    entity_rows: entitySnapshot.entity_rows,
    entity_cells: stripCellLinksFromEntityCellMap(entitySnapshot.entity_cells),
    column_configs: normalizeColumnConfigs(columnConfigs.value, headers),
    column_widths: headers.map((_, index) => columnWidths.value[index] ?? getAutoColumnWidth(
      index,
      headers,
      normalizedRows,
      normalizeColumnConfigs(columnConfigs.value, headers),
    )),
    view_settings: normalizeSheetViewSettings(sheetViewSettings.value, headers.length),
    defined_names: serializeDefinedNameItems(sheetDefinedNames.value),
  }
}

function getEntitySourceDataRowIndex(sourceRowCount: number, dataStartRow: number, loadedRowCount: number, localDataIndex: number) {
  const sequentialIndex = dataStartRow + localDataIndex
  if (sourceRowCount <= dataStartRow + loadedRowCount) {
    return sequentialIndex
  }

  const documentDataIndex = getDocumentRowIndex(localDataIndex)
  const documentIndex = dataStartRow + documentDataIndex
  return documentIndex >= dataStartRow && documentIndex < sourceRowCount ? documentIndex : sequentialIndex
}

function initializeSheetEntitiesFromDocument(
  document: SheetDocument,
  headers: string[],
  dataStartRow: number,
  fieldRowIndex: number,
  normalizedRows: SheetRow[],
  normalizedCellMeta: SheetCellMetaMap,
) {
  const entityColumns = normalizeEntityColumns(document.entity_columns, headers)
  const sourceColumnIds = Array.isArray(document.column_ids) ? document.column_ids : []
  columnEntityIds.value = entityColumns.map((column, index) => (
    normalizeSheetEntityId(sourceColumnIds[index]) || column.id
  ))

  const sourceEntityRows = normalizeEntityRows(
    document.entity_rows,
    dataStartRow,
    fieldRowIndex,
    Math.max(
      normalizedRows.length,
      Array.isArray(document.entity_rows) ? Math.max(0, document.entity_rows.length - dataStartRow) : 0,
    ),
  )
  const headerRows = sourceEntityRows.slice(0, dataStartRow)
  const fallbackHeaderRows = normalizeEntityRows([], dataStartRow, fieldRowIndex, 0)
  headerRowEntityIds.value = Array.from({ length: dataStartRow }, (_, index) => (
    headerRows[index]?.id ?? fallbackHeaderRows[index]?.id ?? createSheetEntityId('header')
  ))
  const sourceRowIds = Array.isArray(document.row_ids) ? document.row_ids : []
  const rowIdsArePaged = sourceRowIds.length === normalizedRows.length
  dataRowEntityIds.value = normalizedRows.map((row, localIndex) => {
    const sourceIndex = getEntitySourceDataRowIndex(sourceEntityRows.length, dataStartRow, normalizedRows.length, localIndex)
    const sourceRowIdIndex = rowIdsArePaged ? localIndex : getDocumentRowIndex(localIndex)
    return normalizeSheetEntityId(sourceRowIds[sourceRowIdIndex])
      || sourceEntityRows[sourceIndex]?.id
      || createFallbackSheetEntityId('row', getDocumentRowIndex(localIndex), row.join('\u001f'))
  })

  const normalizedEntityCells = normalizeEntityCellMap(document.entity_cells)
  const sourceGridRows = Array.isArray(document.grid_rows)
    ? document.grid_rows.map((row) => normalizeRow(row, headers))
    : [
      ...sheetGridRows.value.slice(0, dataStartRow).map((row) => normalizeRow(row, headers)),
      ...normalizedRows,
    ]
  const nextCells: SheetEntityCellMap = {}
  const writeCell = (
    targetRowId: string,
    sourceRowId: string,
    documentRow: number,
    row: SheetRow,
  ) => {
    if (!targetRowId) {
      return
    }
    const rowCells: Record<string, SheetEntityCell> = {}
    entityColumns.forEach((column, columnIndex) => {
      const existingCell = normalizedEntityCells[sourceRowId]?.[column.id]
        ?? normalizedEntityCells[targetRowId]?.[column.id]
        ?? null
      const existingMeta = getEntityCellMeta(existingCell)
      const legacyMeta = normalizedCellMeta[createCellMetaKey(documentRow, columnIndex)] ?? null
      const effectiveMeta = documentRow < dataStartRow
        ? reconcileHeaderEntityCellMeta(legacyMeta, existingMeta)
        : mergeCellMetaEntries(legacyMeta, existingMeta)
      const cell = extractEntityCellForSave(row[columnIndex] ?? '', effectiveMeta)
      if (cell) {
        rowCells[column.id] = cell
      }
    })
    if (Object.keys(rowCells).length) {
      nextCells[targetRowId] = rowCells
    }
  }

  headerRowEntityIds.value.forEach((rowId, rowIndex) => {
    const sourceRowId = sourceEntityRows[rowIndex]?.id ?? rowId
    writeCell(rowId, sourceRowId, rowIndex, normalizeRow(sourceGridRows[rowIndex], headers))
  })
  normalizedRows.forEach((row, localIndex) => {
    const sourceIndex = getEntitySourceDataRowIndex(sourceEntityRows.length, dataStartRow, normalizedRows.length, localIndex)
    const sourceRowId = sourceEntityRows[sourceIndex]?.id ?? dataRowEntityIds.value[localIndex]
    writeCell(
      dataRowEntityIds.value[localIndex],
      sourceRowId,
      dataStartRow + getDocumentRowIndex(localIndex),
      normalizeRow(row, headers),
    )
  })
  entityCells.value = nextCells
}

function isFormulaExpression(value: unknown) {
  return typeof value === 'string' && value.startsWith('=')
}

function getFormulaStringEndQuote(startQuote: string) {
  if (startQuote === '“') {
    return '”'
  }
  if (startQuote === '‘') {
    return '’'
  }
  return startQuote
}

function isFormulaStringQuote(char: string) {
  return char === '"' || char === '\'' || char === '“' || char === '”' || char === '‘' || char === '’'
}

function findNextNonWhitespaceIndex(value: string, startIndex: number) {
  for (let index = startIndex; index < value.length; index += 1) {
    if (!/\s/.test(value[index])) {
      return index
    }
  }
  return -1
}

function normalizeFormulaStringContentForDoubleQuote(content: string) {
  return content.replace(/"/g, '""')
}

function normalizeFormulaStringContentForSingleQuote(content: string) {
  return content.replace(/'/g, "''")
}

function readNormalizedFormulaStringToken(value: string, startIndex: number) {
  const startQuote = value[startIndex]
  const endQuote = getFormulaStringEndQuote(startQuote)
  let content = ''

  for (let index = startIndex + 1; index < value.length; index += 1) {
    const char = value[index]
    if (char === endQuote) {
      if ((startQuote === '"' || startQuote === '\'') && value[index + 1] === endQuote) {
        content += endQuote
        index += 1
        continue
      }

      const nextNonWhitespaceIndex = findNextNonWhitespaceIndex(value, index + 1)
      if (nextNonWhitespaceIndex >= 0 && value[nextNonWhitespaceIndex] === '!') {
        return {
          endIndex: index,
          value: `'${normalizeFormulaStringContentForSingleQuote(content)}'`,
        }
      }

      return {
        endIndex: index,
        value: `"${normalizeFormulaStringContentForDoubleQuote(content)}"`,
      }
    }

    content += char
  }

  return {
    endIndex: value.length - 1,
    value: value.slice(startIndex),
  }
}

function readFormulaFunctionAlias(value: string, startIndex: number) {
  const aliases = [
    { source: '日期解析', target: 'DATE_PARSE' },
    { source: 'DATEDIF', target: 'DATEDIF_COMPAT' },
    { source: 'TEXTJOIN', target: 'TEXTJOIN_COMPAT' },
  ]
  for (const alias of aliases) {
    if (value.slice(startIndex, startIndex + alias.source.length).toUpperCase() !== alias.source) {
      continue
    }
    const nextIndex = findNextNonWhitespaceIndex(value, startIndex + alias.source.length)
    if (nextIndex >= 0 && (value[nextIndex] === '(' || value[nextIndex] === '（')) {
      return {
        endIndex: startIndex + alias.source.length - 1,
        value: alias.target,
      }
    }
  }
  return null
}

function isFormulaIdentifierChar(char: string | undefined) {
  return !!char && /[\p{L}\p{N}_.]/u.test(char)
}

function readFormulaBooleanLiteral(value: string, startIndex: number) {
  for (const source of ['TRUE', 'FALSE']) {
    if (value.slice(startIndex, startIndex + source.length).toUpperCase() !== source) {
      continue
    }
    if (isFormulaIdentifierChar(value[startIndex - 1]) || isFormulaIdentifierChar(value[startIndex + source.length])) {
      continue
    }

    const nextIndex = findNextNonWhitespaceIndex(value, startIndex + source.length)
    if (nextIndex >= 0 && (value[nextIndex] === '(' || value[nextIndex] === '（')) {
      continue
    }

    return {
      endIndex: startIndex + source.length - 1,
      value: `${source}()`,
    }
  }
  return null
}

function normalizeFormulaInputExpression(value: string) {
  if (!isFormulaExpression(value)) {
    return value
  }

  let normalized = ''
  for (let index = 0; index < value.length; index += 1) {
    const char = value[index]
    if (isFormulaStringQuote(char)) {
      const token = readNormalizedFormulaStringToken(value, index)
      normalized += token.value
      index = token.endIndex
      continue
    }

    const functionAlias = readFormulaFunctionAlias(value, index)
    if (functionAlias) {
      normalized += functionAlias.value
      index = functionAlias.endIndex
      continue
    }

    const booleanLiteral = readFormulaBooleanLiteral(value, index)
    if (booleanLiteral) {
      normalized += booleanLiteral.value
      index = booleanLiteral.endIndex
      continue
    }

    if (char === '，') {
      normalized += ','
      continue
    }
    if (char === '（') {
      normalized += '('
      continue
    }
    if (char === '）') {
      normalized += ')'
      continue
    }
    normalized += char
  }
  return normalized
}

function normalizeFormulaExpressionForEngine(value: string) {
  return normalizeFormulaInputExpression(value)
}

function getCurrentFormulaDisplayRowOffset() {
  return effectivePaginationEnabled.value ? pageRowOffset.value : 0
}

function normalizeFormulaExpressionForPagedEngine(
  value: string,
  rowOffset: number,
  dataRowCount: number,
  headerRowCount: number,
) {
  const normalizedFormula = normalizeFormulaExpressionForEngine(value)
  if (rowOffset <= 0) {
    return normalizedFormula
  }

  return remapFormulaCellReferences(normalizedFormula, (sourceRowIndex) => {
    if (sourceRowIndex < headerRowCount) {
      return sourceRowIndex
    }
    const localDataRowIndex = sourceRowIndex - headerRowCount - rowOffset
    return localDataRowIndex >= 0 && localDataRowIndex < dataRowCount
      ? headerRowCount + localDataRowIndex
      : null
  })
}

function normalizeFormulaEngineCellValue(cellValue: string): FormulaEngineCellValue {
  if (isFormulaExpression(cellValue)) {
    return cellValue
  }
  return cellValue === '' ? null : cellValue
}

function isFormulaErrorValue(value: unknown): value is { value: string } {
  return (
    !!value
    && typeof value === 'object'
    && typeof (value as { value?: unknown }).value === 'string'
    && (value as { value: string }).value.startsWith('#')
  )
}

function createFormulaCellModel(
  formula: string,
  calculatedValue: unknown,
  config: SheetColumnConfig | ColumnSettingsDraft | undefined,
): FormulaCellModel {
  // Excel separates Formula, Value/Value2, and Text. JavaScript has no VBA
  // Date/Currency coercion layer, so Value and Value2 are equivalent for now.
  return {
    formula,
    value: calculatedValue,
    value2: calculatedValue,
    text: formatCellDisplayValueCached(calculatedValue, config),
  }
}

function getDisplayFormatCacheKey(config: SheetColumnConfig | ColumnSettingsDraft | undefined) {
  return [
    config?.value_type ?? 'text',
    config?.display_format ?? '',
  ].join(':')
}

function formatCellDisplayValueCached(
  value: unknown,
  config: SheetColumnConfig | ColumnSettingsDraft | undefined,
) {
  const normalizedValue = normalizeCellValue(value)
  const cacheKey = `${getDisplayFormatCacheKey(config)}:${normalizedValue}`
  const cached = cellDisplayTextCache.get(cacheKey)
  if (cached != null) {
    return cached
  }

  const formattedValue = formatCellDisplayValue(normalizedValue, config)
  if (cellDisplayTextCache.size > 5000) {
    cellDisplayTextCache.clear()
  }
  cellDisplayTextCache.set(cacheKey, formattedValue)
  return formattedValue
}

function normalizeRegexFlags(value: unknown) {
  const rawFlags = normalizeCellValue(value).trim()
  const allowedFlags = new Set(['d', 'g', 'i', 'm', 's', 'u', 'v', 'y'])
  let flags = ''
  for (const flag of rawFlags) {
    if (!allowedFlags.has(flag) || flags.includes(flag)) {
      continue
    }
    flags += flag
  }
  return flags
}

function buildGlobalRegexFlags(value: unknown) {
  const flags = normalizeRegexFlags(value)
  return flags.includes('g') ? flags : `${flags}g`
}

function normalizePythonRegexReplacement(value: unknown) {
  return normalizeCellValue(value)
    .replace(/\\g<(\d+)>/g, '$$$1')
    .replace(/\\([1-9]\d*)/g, '$$$1')
}

function replaceRegexWithCount(text: string, regex: RegExp, replacement: string, count: number) {
  if (count <= 0) {
    return text.replace(regex, replacement)
  }

  let replacedCount = 0
  return text.replace(regex, (...args: unknown[]) => {
    if (replacedCount >= count) {
      return normalizeCellValue(args[0])
    }
    replacedCount += 1
    return replacement.replace(/\$(\d+)/g, (_match, groupIndex: string) => (
      normalizeCellValue(args[Number(groupIndex)] ?? '')
    ))
  })
}

type FormulaDateParts = {
  year: number
  month: number
  day: number
  hour?: number
  minute?: number
  second?: number
  timePrecision?: 'minute' | 'second'
}

function normalizeDateParsePattern(value: unknown) {
  const pattern = normalizeCellValue(value).trim().toLowerCase().replace(/[^ymd]/g, '')
  return pattern || 'yyyymmdd'
}

function normalizeTwoDigitYear(value: number) {
  return value >= 70 ? 1900 + value : 2000 + value
}

function isValidDateParts(parts: FormulaDateParts) {
  if (
    !Number.isInteger(parts.year)
    || !Number.isInteger(parts.month)
    || !Number.isInteger(parts.day)
    || parts.year < 1
    || parts.month < 1
    || parts.month > 12
    || parts.day < 1
    || parts.day > 31
  ) {
    return false
  }
  const date = new Date(Date.UTC(parts.year, parts.month - 1, parts.day))
  return (
    date.getUTCFullYear() === parts.year
    && date.getUTCMonth() === parts.month - 1
    && date.getUTCDate() === parts.day
  )
}

function hasFormulaTimeParts(parts: FormulaDateParts) {
  return Number.isInteger(parts.hour) && Number.isInteger(parts.minute)
}

function isValidFormulaTimeParts(parts: FormulaDateParts) {
  if (!hasFormulaTimeParts(parts)) {
    return true
  }
  const hour = parts.hour ?? 0
  const minute = parts.minute ?? 0
  const second = parts.second ?? 0
  return (
    hour >= 0
    && hour <= 23
    && minute >= 0
    && minute <= 59
    && Number.isInteger(second)
    && second >= 0
    && second <= 59
  )
}

function parseOptionalFormulaTimeParts(hourValue: string | undefined, minuteValue: string | undefined, secondValue: string | undefined) {
  if (hourValue == null) {
    return {}
  }

  const hour = Number(hourValue)
  const minute = minuteValue == null ? 0 : Number(minuteValue)
  const second = secondValue == null ? 0 : Number(secondValue)
  const parts: Partial<FormulaDateParts> = {
    hour,
    minute,
    second,
    timePrecision: secondValue == null ? 'minute' : 'second',
  }
  return isValidFormulaTimeParts(parts as FormulaDateParts) ? parts : null
}

function formulaDatePartsToSerial(parts: FormulaDateParts) {
  const dateSerial = Math.floor(Date.UTC(parts.year, parts.month - 1, parts.day) / MS_PER_DAY) + EXCEL_DATE_UNIX_EPOCH_SERIAL
  if (!hasFormulaTimeParts(parts)) {
    return dateSerial
  }

  const seconds = (parts.hour ?? 0) * 60 * 60 + (parts.minute ?? 0) * 60 + (parts.second ?? 0)
  return dateSerial + seconds / (24 * 60 * 60)
}

function formulaDateSerialToParts(value: number): FormulaDateParts | null {
  if (!Number.isFinite(value)) {
    return null
  }

  const date = new Date(Math.round((value - EXCEL_DATE_UNIX_EPOCH_SERIAL) * MS_PER_DAY))
  const parts = {
    year: date.getUTCFullYear(),
    month: date.getUTCMonth() + 1,
    day: date.getUTCDate(),
    hour: date.getUTCHours(),
    minute: date.getUTCMinutes(),
    second: date.getUTCSeconds(),
  }
  if (!parts.hour && !parts.minute && !parts.second) {
    delete (parts as Partial<FormulaDateParts>).hour
    delete (parts as Partial<FormulaDateParts>).minute
    delete (parts as Partial<FormulaDateParts>).second
  } else {
    ;(parts as FormulaDateParts).timePrecision = 'second'
  }
  return isValidDateParts(parts) && isValidFormulaTimeParts(parts) ? parts : null
}

function formulaDatePartsToUtcDate(parts: FormulaDateParts) {
  return new Date(Date.UTC(parts.year, parts.month - 1, parts.day))
}

function formulaDateSerialToUtcDate(value: number) {
  const parts = formulaDateSerialToParts(Math.floor(value))
  return parts ? formulaDatePartsToUtcDate(parts) : null
}

function formulaUtcDateToSerial(value: Date) {
  return Math.floor(value.getTime() / MS_PER_DAY) + EXCEL_DATE_UNIX_EPOCH_SERIAL
}

function parseSeparatedFormulaDate(value: unknown) {
  const text = normalizeCellValue(value).trim()
  const match = text.match(/^(\d{4})[-/年](\d{1,2})[-/月](\d{1,2})日?$/)
  if (!match) {
    return null
  }
  const parts = {
    year: Number(match[1]),
    month: Number(match[2]),
    day: Number(match[3]),
  }
  return isValidDateParts(parts) ? parts : null
}

function parseCompactFormulaDate(value: unknown, patternValue: unknown) {
  const text = normalizeCellValue(value)
  const pattern = normalizeDateParsePattern(patternValue)
  let parts: FormulaDateParts | null = null

  if (pattern === 'yyyymmdd' || pattern === 'yymmdd') {
    const eightDigitMatch = text.match(/\d{8}/)
    if (eightDigitMatch) {
      const digits = eightDigitMatch[0]
      parts = {
        year: Number(digits.slice(0, 4)),
        month: Number(digits.slice(4, 6)),
        day: Number(digits.slice(6, 8)),
      }
    } else {
      const sixDigitMatch = text.match(/\d{6}/)
      if (sixDigitMatch) {
        const digits = sixDigitMatch[0]
        parts = {
          year: normalizeTwoDigitYear(Number(digits.slice(0, 2))),
          month: Number(digits.slice(2, 4)),
          day: Number(digits.slice(4, 6)),
        }
      }
    }
  }

  if (!parts || !isValidDateParts(parts)) {
    return null
  }
  return parts
}

function normalizeFormulaDateSerial(value: unknown) {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return Math.floor(value)
  }

  const text = normalizeCellValue(value).trim()
  if (!text) {
    return null
  }
  const numericValue = Number(text)
  if (Number.isFinite(numericValue)) {
    return Math.floor(numericValue)
  }

  const parts = parseSeparatedFormulaDate(text)
    ?? parseCompactFormulaDate(text, 'yyyymmdd')
  return parts ? formulaDatePartsToSerial(parts) : null
}

function getFormulaFullYearsBetween(start: Date, end: Date) {
  let years = end.getUTCFullYear() - start.getUTCFullYear()
  const endMonth = end.getUTCMonth()
  const startMonth = start.getUTCMonth()
  if (endMonth < startMonth || (endMonth === startMonth && end.getUTCDate() < start.getUTCDate())) {
    years -= 1
  }
  return years
}

function getFormulaFullMonthsBetween(start: Date, end: Date) {
  let months = (end.getUTCFullYear() - start.getUTCFullYear()) * 12 + end.getUTCMonth() - start.getUTCMonth()
  if (end.getUTCDate() < start.getUTCDate()) {
    months -= 1
  }
  return months
}

function daysInFormulaUtcMonth(year: number, monthIndex: number) {
  return new Date(Date.UTC(year, monthIndex + 1, 0)).getUTCDate()
}

function calculateFormulaDateDif(startSerial: number, endSerial: number, unitValue: unknown) {
  const unit = normalizeCellValue(unitValue).trim().toUpperCase()
  const start = formulaDateSerialToUtcDate(startSerial)
  const end = formulaDateSerialToUtcDate(endSerial)
  if (!start || !end || endSerial < startSerial) {
    return null
  }

  const days = Math.floor(endSerial) - Math.floor(startSerial)
  if (unit === 'D') {
    return days
  }
  if (unit === 'Y') {
    return getFormulaFullYearsBetween(start, end)
  }
  if (unit === 'M') {
    return getFormulaFullMonthsBetween(start, end)
  }
  if (unit === 'YM') {
    return ((getFormulaFullMonthsBetween(start, end) % 12) + 12) % 12
  }
  if (unit === 'MD') {
    if (end.getUTCDate() >= start.getUTCDate()) {
      return end.getUTCDate() - start.getUTCDate()
    }
    const previousEndMonthDayCount = daysInFormulaUtcMonth(end.getUTCFullYear(), end.getUTCMonth() - 1)
    return previousEndMonthDayCount - start.getUTCDate() + end.getUTCDate()
  }
  if (unit === 'YD') {
    const adjustedStart = new Date(Date.UTC(end.getUTCFullYear(), start.getUTCMonth(), start.getUTCDate()))
    if (adjustedStart > end) {
      adjustedStart.setUTCFullYear(adjustedStart.getUTCFullYear() - 1)
    }
    return Math.floor((end.getTime() - adjustedStart.getTime()) / MS_PER_DAY)
  }

  return null
}

function padDatePart(value: number) {
  return String(value).padStart(2, '0')
}

function formatFormulaTime(parts: FormulaDateParts) {
  if (!hasFormulaTimeParts(parts)) {
    return ''
  }
  const hour = padDatePart(parts.hour ?? 0)
  const minute = padDatePart(parts.minute ?? 0)
  const second = padDatePart(parts.second ?? 0)
  return parts.timePrecision === 'minute' && second === '00'
    ? `${hour}:${minute}`
    : `${hour}:${minute}:${second}`
}

function isMinuteFormatToken(format: string, index: number, tokenLength: number) {
  return format[index - 1] === ':' || format[index + tokenLength] === ':'
}

function readFormulaDateFormatToken(format: string, index: number, parts: FormulaDateParts) {
  const rest = format.slice(index).toLowerCase()
  if (rest.startsWith('yyyy')) {
    return { length: 4, value: String(parts.year), isTime: false }
  }
  if (rest.startsWith('yy')) {
    return { length: 2, value: padDatePart(parts.year % 100), isTime: false }
  }
  if (rest.startsWith('hh')) {
    return { length: 2, value: padDatePart(parts.hour ?? 0), isTime: true }
  }
  if (rest.startsWith('h')) {
    return { length: 1, value: String(parts.hour ?? 0), isTime: true }
  }
  if (rest.startsWith('ss')) {
    return { length: 2, value: padDatePart(parts.second ?? 0), isTime: true }
  }
  if (rest.startsWith('s')) {
    return { length: 1, value: String(parts.second ?? 0), isTime: true }
  }
  if (rest.startsWith('mm')) {
    const isTime = isMinuteFormatToken(format, index, 2)
    return {
      length: 2,
      value: padDatePart(isTime ? (parts.minute ?? 0) : parts.month),
      isTime,
    }
  }
  if (rest.startsWith('m')) {
    const isTime = isMinuteFormatToken(format, index, 1)
    return {
      length: 1,
      value: String(isTime ? (parts.minute ?? 0) : parts.month),
      isTime,
    }
  }
  if (rest.startsWith('dd')) {
    return { length: 2, value: padDatePart(parts.day), isTime: false }
  }
  if (rest.startsWith('d')) {
    return { length: 1, value: String(parts.day), isTime: false }
  }
  return null
}

function formatFormulaDate(parts: FormulaDateParts, formatValue: unknown, options: { appendSourceTime?: boolean } = {}) {
  const format = normalizeCellValue(formatValue).trim() || DEFAULT_DATE_DISPLAY_FORMAT
  let result = ''
  let hasTimeToken = false

  for (let index = 0; index < format.length;) {
    const token = readFormulaDateFormatToken(format, index, parts)
    if (token) {
      result += token.value
      hasTimeToken ||= token.isTime
      index += token.length
    } else {
      result += format[index]
      index += 1
    }
  }

  const sourceTime = formatFormulaTime(parts)
  return options.appendSourceTime && sourceTime && !hasTimeToken
    ? `${result} ${sourceTime}`
    : result
}

function splitDisplayFormatArguments(value: string) {
  const args: string[] = []
  let current = ''
  let depth = 0
  let quoteEnd = ''
  let quoteStart = ''

  for (let index = 0; index < value.length; index += 1) {
    const char = value[index]
    if (quoteEnd) {
      current += char
      if (char === quoteEnd) {
        if ((quoteStart === '"' || quoteStart === '\'') && value[index + 1] === quoteEnd) {
          current += value[index + 1]
          index += 1
          continue
        }
        quoteEnd = ''
        quoteStart = ''
      }
      continue
    }

    if (isFormulaStringQuote(char)) {
      quoteStart = char
      quoteEnd = getFormulaStringEndQuote(char)
      current += char
      continue
    }

    if (char === '(' || char === '（') {
      depth += 1
      current += char
      continue
    }
    if (char === ')' || char === '）') {
      depth = Math.max(0, depth - 1)
      current += char
      continue
    }
    if ((char === ',' || char === '，') && depth === 0) {
      args.push(current.trim())
      current = ''
      continue
    }
    current += char
  }

  args.push(current.trim())
  return args
}

function readDisplayFormatCaseArguments(value: string) {
  const trimmed = value.trim()
  const match = trimmed.match(/^case\s*\(/i)
  if (!match) {
    return null
  }

  const openIndex = match[0].lastIndexOf('(')
  let depth = 0
  let quoteEnd = ''
  let quoteStart = ''
  for (let index = openIndex; index < trimmed.length; index += 1) {
    const char = trimmed[index]
    if (quoteEnd) {
      if (char === quoteEnd) {
        if ((quoteStart === '"' || quoteStart === '\'') && trimmed[index + 1] === quoteEnd) {
          index += 1
          continue
        }
        quoteEnd = ''
        quoteStart = ''
      }
      continue
    }
    if (isFormulaStringQuote(char)) {
      quoteStart = char
      quoteEnd = getFormulaStringEndQuote(char)
      continue
    }
    if (char === '(' || char === '（') {
      depth += 1
      continue
    }
    if (char === ')' || char === '）') {
      depth -= 1
      if (depth === 0) {
        return trimmed.slice(index + 1).trim()
          ? null
          : splitDisplayFormatArguments(trimmed.slice(openIndex + 1, index))
      }
    }
  }
  return null
}

function unquoteDisplayFormatArgument(value: string) {
  const trimmed = value.trim()
  if (trimmed.length < 2) {
    return trimmed
  }

  const start = trimmed[0]
  const end = trimmed[trimmed.length - 1]
  if ((start === '"' && end === '"') || (start === '\'' && end === '\'')) {
    return trimmed.slice(1, -1).replace(new RegExp(`${start}${start}`, 'g'), start)
  }
  if ((start === '“' && end === '”') || (start === '‘' && end === '’')) {
    return trimmed.slice(1, -1)
  }
  return trimmed
}

function getNumericDisplayFormatValue(value: unknown) {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return value
  }
  const text = normalizeCellValue(value).trim()
  return /^[-+]?(?:\d+(?:\.\d+)?|\.\d+)$/.test(text) ? Number(text) : null
}

function evaluateDisplayFormatCaseCondition(
  condition: string,
  value: unknown,
  context: { valueType: ColumnValueType; dateParts: FormulaDateParts | null },
) {
  const normalized = condition.trim().toLowerCase().replace(/\s+/g, '')
  if (!normalized) {
    return false
  }

  if (normalized === 'is_current_year') {
    return !!context.dateParts && context.dateParts.year === new Date().getFullYear()
  }

  const comparisonMatch = normalized.match(/^(>=|<=|==|=|>|<|!=|<>)([-+]?(?:\d+(?:\.\d+)?|\.\d+))$/)
  if (comparisonMatch) {
    const numericValue = getNumericDisplayFormatValue(value)
    if (numericValue == null) {
      return false
    }
    const target = Number(comparisonMatch[2])
    switch (comparisonMatch[1]) {
      case '>':
        return numericValue > target
      case '<':
        return numericValue < target
      case '>=':
        return numericValue >= target
      case '<=':
        return numericValue <= target
      case '!=':
      case '<>':
        return numericValue !== target
      default:
        return numericValue === target
    }
  }

  return false
}

function resolveDisplayFormatPattern(
  displayFormat: string,
  value: unknown,
  context: { valueType: ColumnValueType; dateParts: FormulaDateParts | null },
) {
  const normalizedFormat = normalizeCellValue(displayFormat).trim()
  const caseArgs = readDisplayFormatCaseArguments(normalizedFormat)
  if (!caseArgs || caseArgs.length < 3) {
    return normalizedFormat
  }

  const hasDefault = caseArgs.length % 2 === 1
  const conditionArgCount = hasDefault ? caseArgs.length - 1 : caseArgs.length
  for (let index = 0; index + 1 < conditionArgCount; index += 2) {
    if (evaluateDisplayFormatCaseCondition(caseArgs[index], value, context)) {
      return unquoteDisplayFormatArgument(caseArgs[index + 1])
    }
  }

  return hasDefault ? unquoteDisplayFormatArgument(caseArgs[caseArgs.length - 1]) : ''
}

function parseDateDisplayValue(value: unknown): FormulaDateParts | null {
  if (typeof value === 'number') {
    return formulaDateSerialToParts(value)
  }

  const text = normalizeCellValue(value).trim()
  if (!text) {
    return null
  }

  if (/^-?\d+(?:\.\d+)?$/.test(text)) {
    const serialParts = formulaDateSerialToParts(Number(text))
    if (serialParts) {
      return serialParts
    }
  }

  const separatedMatch = text.match(/^(\d{4})[-/年](\d{1,2})[-/月](\d{1,2})日?(?:[ T]+(\d{1,2})(?::(\d{1,2})(?::(\d{1,2}))?)?)?$/)
  if (separatedMatch) {
    const timeParts = parseOptionalFormulaTimeParts(separatedMatch[4], separatedMatch[5], separatedMatch[6])
    if (!timeParts) {
      return null
    }
    const parts = {
      year: Number(separatedMatch[1]),
      month: Number(separatedMatch[2]),
      day: Number(separatedMatch[3]),
      ...timeParts,
    }
    return isValidDateParts(parts) && isValidFormulaTimeParts(parts) ? parts : null
  }

  const compactMatch = text.match(/^(\d{4})(\d{2})(\d{2})(?:(\d{2})(\d{2})(\d{2})?)?$/)
  if (compactMatch) {
    const timeParts = parseOptionalFormulaTimeParts(compactMatch[4], compactMatch[5], compactMatch[6])
    if (!timeParts) {
      return null
    }
    const parts = {
      year: Number(compactMatch[1]),
      month: Number(compactMatch[2]),
      day: Number(compactMatch[3]),
      ...timeParts,
    }
    return isValidDateParts(parts) && isValidFormulaTimeParts(parts) ? parts : null
  }

  return null
}

function formatBasicDisplayValue(value: unknown) {
  if (value == null) {
    return ''
  }
  if (isFormulaErrorValue(value)) {
    return value.value
  }
  if (typeof value === 'number') {
    return Number.isFinite(value) ? String(value) : '#NUM!'
  }
  if (typeof value === 'boolean') {
    return value ? 'TRUE' : 'FALSE'
  }
  return normalizeCellValue(value)
}

function parsePercentDisplayNumber(value: unknown) {
  if (typeof value === 'number') {
    return Number.isFinite(value) ? value : null
  }
  if (isFormulaErrorValue(value)) {
    return null
  }

  const text = normalizeCellValue(value).trim()
  if (!text) {
    return null
  }

  const percentMatch = text.match(/^([-+]?(?:\d+(?:\.\d+)?|\.\d+))%$/)
  if (percentMatch) {
    return Number(percentMatch[1]) / 100
  }

  if (/^[-+]?(?:\d+(?:\.\d+)?|\.\d+)$/.test(text)) {
    return Number(text)
  }
  return null
}

function getPercentDisplayDecimalPlaces(displayFormat: string) {
  const normalized = normalizeCellValue(displayFormat).trim() || DEFAULT_PERCENT_DISPLAY_FORMAT
  const match = normalized.match(/\.(0+)%$/)
  return match ? match[1].length : 0
}

function formatPercentDisplayValue(value: unknown, displayFormat: string) {
  if (value == null || normalizeCellValue(value).trim() === '') {
    return ''
  }
  if (isFormulaErrorValue(value)) {
    return value.value
  }

  const numberValue = parsePercentDisplayNumber(value)
  if (numberValue == null) {
    return formatBasicDisplayValue(value)
  }

  const decimalPlaces = getPercentDisplayDecimalPlaces(displayFormat)
  const percentValue = numberValue * 100
  const rounded = Math.abs(percentValue) < 0.5 / (10 ** decimalPlaces)
    ? 0
    : percentValue
  return `${rounded.toFixed(decimalPlaces)}%`
}

function formatDateEditText(value: unknown) {
  const parts = parseDateDisplayValue(value)
  return parts
    ? formatFormulaDate(parts, hasFormulaTimeParts(parts)
      ? (parts.timePrecision === 'minute' ? 'yyyy/mm/dd hh:mm' : 'yyyy/mm/dd hh:mm:ss')
      : 'yyyy/mm/dd')
    : normalizeCellValue(value)
}

function normalizeDateInputValue(value: string) {
  const parts = parseDateDisplayValue(value)
  return parts ? String(formulaDatePartsToSerial(parts)) : value
}

function normalizePercentInputValue(value: string) {
  const numberValue = parsePercentDisplayNumber(value)
  return numberValue == null ? value : String(numberValue)
}

function formatCellDisplayValue(value: unknown, config: SheetColumnConfig | ColumnSettingsDraft | undefined) {
  const columnConfig = normalizeColumnConfig(config)
  if (columnConfig.value_type === 'date') {
    if (value == null || normalizeCellValue(value).trim() === '') {
      return ''
    }
    if (isFormulaErrorValue(value)) {
      return value.value
    }

    const parts = parseDateDisplayValue(value)
    if (parts) {
      const displayPattern = resolveDisplayFormatPattern(columnConfig.display_format, value, {
        valueType: columnConfig.value_type,
        dateParts: parts,
      })
      return formatFormulaDate(parts, displayPattern, { appendSourceTime: true })
    }
  }
  if (columnConfig.value_type === 'percent') {
    return formatPercentDisplayValue(value, columnConfig.display_format)
  }

  return formatBasicDisplayValue(value)
}

function registerSheetFormulaPlugins(module: unknown) {
  if (sheetFormulaPluginRegistered || !module || typeof module !== 'object') {
    return
  }

  const formulaModule = module as Record<string, unknown>
  const HyperFormula = formulaModule.HyperFormula as FormulaEngineClass | undefined
  const hasRegisteredSheetFormulas = (
    !!HyperFormula?.getFunctionPlugin?.('RE_SUB')
    && !!HyperFormula.getFunctionPlugin?.('DATE_PARSE')
    && !!HyperFormula.getFunctionPlugin?.('DATEDIF_COMPAT')
    && !!HyperFormula.getFunctionPlugin?.('TEXTJOIN_COMPAT')
  )
  if (!HyperFormula?.registerFunctionPlugin || hasRegisteredSheetFormulas) {
    sheetFormulaPluginRegistered = true
    return
  }

  const FunctionPlugin = formulaModule.FunctionPlugin as new (...args: unknown[]) => {
    runFunction: (
      args: unknown[],
      state: unknown,
      metadata: unknown,
      implementation: (...args: unknown[]) => unknown,
    ) => unknown
    metadata: (name: string) => unknown
  }
  const FunctionArgumentType = formulaModule.FunctionArgumentType as Record<string, unknown> | undefined
  const CellError = formulaModule.CellError as (new (type: unknown, message?: string) => unknown) | undefined
  const ErrorType = formulaModule.ErrorType as Record<string, unknown> | undefined
  if (
    !FunctionPlugin
    || !FunctionArgumentType?.STRING
    || !FunctionArgumentType?.NUMBER
    || !FunctionArgumentType?.ANY
    || !CellError
    || !ErrorType?.VALUE
  ) {
    return
  }

  class SheetFormulaPlugin extends FunctionPlugin {
    static implementedFunctions = {
      RE_SUB: {
        method: 'reSub',
        parameters: [
          { argumentType: FunctionArgumentType.STRING },
          { argumentType: FunctionArgumentType.STRING },
          { argumentType: FunctionArgumentType.STRING },
          { argumentType: FunctionArgumentType.NUMBER, defaultValue: 0 },
          { argumentType: FunctionArgumentType.STRING, defaultValue: '' },
        ],
      },
      DATE_PARSE: {
        method: 'dateParse',
        parameters: [
          { argumentType: FunctionArgumentType.STRING },
          { argumentType: FunctionArgumentType.STRING, defaultValue: 'yyyymmdd' },
          { argumentType: FunctionArgumentType.STRING, defaultValue: '' },
        ],
      },
      DATEDIF_COMPAT: {
        method: 'dateDifCompat',
        parameters: [
          { argumentType: FunctionArgumentType.ANY },
          { argumentType: FunctionArgumentType.ANY },
          { argumentType: FunctionArgumentType.STRING },
        ],
      },
      TEXTJOIN_COMPAT: {
        method: 'textJoinCompat',
        parameters: [
          { argumentType: FunctionArgumentType.STRING },
          { argumentType: FunctionArgumentType.ANY },
          { argumentType: FunctionArgumentType.ANY },
        ],
        repeatLastArgs: 1,
        expandRanges: true,
      },
    }

    reSub(ast: { args: unknown[] }, state: unknown) {
      return this.runFunction(
        ast.args,
        state,
        this.metadata('RE_SUB'),
        (pattern: string, replacement: string, text: string, count = 0, flags = '') => {
          try {
            const regex = new RegExp(pattern, buildGlobalRegexFlags(flags))
            return replaceRegexWithCount(
              text,
              regex,
              normalizePythonRegexReplacement(replacement),
              Math.max(0, Math.floor(Number(count) || 0)),
            )
          } catch (error) {
            return new CellError(ErrorType.VALUE, error instanceof Error ? error.message : 'Invalid regular expression')
          }
        },
      )
    }

    dateParse(ast: { args: unknown[] }, state: unknown) {
      return this.runFunction(
        ast.args,
        state,
        this.metadata('DATE_PARSE'),
        (text: string, pattern = 'yyyymmdd') => {
          const parts = parseCompactFormulaDate(text, pattern)
          if (!parts) {
            return new CellError(ErrorType.VALUE, 'Invalid date text')
          }
          return formulaDatePartsToSerial(parts)
        },
      )
    }

    dateDifCompat(ast: { args: unknown[] }, state: unknown) {
      return this.runFunction(
        ast.args,
        state,
        this.metadata('DATEDIF_COMPAT'),
        (startValue: unknown, endValue: unknown, unit: string) => {
          const startSerial = normalizeFormulaDateSerial(startValue)
          const endSerial = normalizeFormulaDateSerial(endValue)
          if (startSerial == null || endSerial == null) {
            return new CellError(ErrorType.VALUE, 'Invalid date value')
          }

          const result = calculateFormulaDateDif(startSerial, endSerial, unit)
          return result == null
            ? new CellError(ErrorType.VALUE, 'Invalid DATEDIF arguments')
            : result
        },
      )
    }

    textJoinCompat(ast: { args: unknown[] }, state: unknown) {
      return this.runFunction(
        ast.args,
        state,
        this.metadata('TEXTJOIN_COMPAT'),
        (delimiter: string, ignoreEmptyValue: unknown, ...items: unknown[]) => {
          const ignoreEmpty = Boolean(ignoreEmptyValue)
          const values = items
            .flat(Number.POSITIVE_INFINITY)
            .map((item) => normalizeCellValue(item))
            .filter((item) => !ignoreEmpty || item !== '')
          return values.join(delimiter)
        },
      )
    }
  }

  HyperFormula.registerFunctionPlugin(SheetFormulaPlugin, {
    enGB: {
      RE_SUB: 'RE_SUB',
      DATE_PARSE: 'DATE_PARSE',
      DATEDIF_COMPAT: 'DATEDIF_COMPAT',
      TEXTJOIN_COMPAT: 'TEXTJOIN_COMPAT',
    },
  })
  sheetFormulaPluginRegistered = true
}

function loadFormulaEngineClass() {
  if (formulaEngineClass.value) {
    return Promise.resolve(formulaEngineClass.value)
  }

  if (!formulaEngineImportPromise) {
    formulaEngineImportPromise = import('hyperformula')
      .then((module) => {
        registerSheetFormulaPlugins(module)
        formulaEngineClass.value = module.HyperFormula as FormulaEngineClass
        return formulaEngineClass.value
      })
      .catch((error) => {
        formulaEngineImportPromise = null
        console.warn('Failed to load sheet formula engine', error)
        return null
      })
  }

  return formulaEngineImportPromise
}

async function ensureFormulaEngineLoaded() {
  if (formulaEngineClass.value) {
    return formulaEngineClass.value
  }

  const FormulaEngine = await loadFormulaEngineClass()
  if (!FormulaEngine) {
    return null
  }
  const formulaDisplayChanged = refreshFormulaDisplayState()
  if (formulaDisplayChanged) {
    renderCurrentHotWithReason('formula-engine-loaded')
  }
  refreshAdaptiveFormulaColumnWidths()
  return FormulaEngine
}

async function waitForInitialFormulaEnginePreload(
  promise: Promise<FormulaEngineClass | null>,
  budgetMs = FORMULA_ENGINE_INITIAL_PRELOAD_BUDGET_MS,
) {
  if (formulaEngineClass.value) {
    return 'ready'
  }
  let timer: ReturnType<typeof setTimeout> | null = null
  const timeoutPromise = new Promise<'timeout'>((resolve) => {
    timer = setTimeout(() => resolve('timeout'), budgetMs)
  })
  const result = await Promise.race([
    promise.then((FormulaEngine) => (FormulaEngine ? 'ready' : 'unavailable')),
    timeoutPromise,
  ])
  if (timer != null) {
    clearTimeout(timer)
  }
  return result
}

function createEmptyFormulaDisplayState(dataStartRow = 0): FormulaDisplayState {
  return {
    cells: [],
    errorKeys: new Set(),
    dataStartRow,
  }
}

function hasFormulaDisplayCells(displayState: FormulaDisplayState | null | undefined) {
  return !!displayState?.cells.some((row) => row.some(Boolean))
}

function rowsHaveFormulaExpressions(sourceRows: SheetRow[]) {
  return sourceRows.some((row) => row.some(isFormulaExpression))
}

function shouldReuseCachedFormulaDisplayState(
  cachedState: FormulaDisplayState | null | undefined,
  headers: string[],
  sourceRows: SheetRow[],
) {
  if (!cachedState) {
    return false
  }
  if (!formulaEngineClass.value || hasFormulaDisplayCells(cachedState)) {
    return true
  }
  const formulaHeaderRows = getCurrentFormulaHeaderRows(headers)
    .map((row) => normalizeRow(row, headers))
  return !rowsHaveFormulaExpressions(formulaHeaderRows) && !rowsHaveFormulaExpressions(sourceRows)
}

function buildFormulaDisplayStateForRows(
  headers: string[],
  sourceRows: SheetRow[],
  sourceConfigs: Record<string, SheetColumnConfig> = columnConfigs.value,
  options: FormulaDisplayBuildOptions = {},
): FormulaDisplayState {
  const normalizedDataRows = sourceRows.map((row) => normalizeRow(row, headers))
  const normalizedHeaderRows = (options.headerRows ?? getCurrentFormulaHeaderRows(headers))
    .map((row) => normalizeRow(row, headers))
  const headerRowCount = normalizeNonNegativeInt(options.headerRowCount, normalizedHeaderRows.length)
  const normalizedRows = [
    ...normalizedHeaderRows.slice(0, headerRowCount),
    ...normalizedDataRows,
  ]
  const rowOffset = normalizeNonNegativeInt(options.rowOffset, getCurrentFormulaDisplayRowOffset())
  const formulaCells: Array<{ row: number; column: number }> = []

  normalizedRows.forEach((row, rowIndex) => {
    row.forEach((cellValue, columnIndex) => {
      if (isFormulaExpression(cellValue)) {
        formulaCells.push({ row: rowIndex, column: columnIndex })
      }
    })
  })

  if (!formulaCells.length) {
    return {
      cells: [],
      errorKeys: new Set(),
      dataStartRow: headerRowCount,
    }
  }

  const FormulaEngine = formulaEngineClass.value
  if (!FormulaEngine) {
    void ensureFormulaEngineLoaded()
    return {
      cells: [],
      errorKeys: new Set(),
      dataStartRow: headerRowCount,
    }
  }

  const namedExpressionContext = buildFormulaNamedExpressionContext()
  const engineRows = normalizedRows.map((row) => row.map((cellValue) => {
    if (!isFormulaExpression(cellValue)) {
      return normalizeFormulaEngineCellValue(cellValue)
    }
    return replaceFormulaDefinedNameAliases(
      normalizeFormulaExpressionForPagedEngine(cellValue, rowOffset, normalizedDataRows.length, headerRowCount),
      namedExpressionContext.aliases,
    )
  }))
  const cells = normalizedRows.map((row) => row.map(() => null as FormulaCellModel | null))
  const errorKeys = new Set<string>()
  let engine: FormulaEngineInstance | null = null
  try {
    engine = FormulaEngine.buildFromArray(engineRows, { licenseKey: 'gpl-v3' }, namedExpressionContext.namedExpressions)
    formulaCells.forEach(({ row, column }) => {
      const calculatedValue = engine?.getCellValue({ sheet: 0, row, col: column })
      cells[row][column] = createFormulaCellModel(
        normalizedRows[row]?.[column] ?? '',
        calculatedValue,
        sourceConfigs[headers[column] ?? ''],
      )
      if (isFormulaErrorValue(calculatedValue)) {
        errorKeys.add(createCellMetaKey(row, column))
      }
    })
  } catch (error) {
    console.warn('Failed to evaluate sheet formulas', error)
    formulaCells.forEach(({ row, column }) => {
      cells[row][column] = {
        formula: normalizedRows[row]?.[column] ?? '',
        value: '#ERROR!',
        value2: '#ERROR!',
        text: '#ERROR!',
      }
      errorKeys.add(createCellMetaKey(row, column))
    })
  } finally {
    engine?.destroy()
  }

  return { cells, errorKeys, dataStartRow: headerRowCount }
}

function buildFormulaDefinedNameAliases(items: NoteSheetDefinedNameItem[]): SheetFormulaNameAlias[] {
  const aliases: SheetFormulaNameAlias[] = []
  const seen = new Set<string>()
  items.forEach((item) => {
    const name = normalizeCellValue(item.name).trim()
    const key = name.toLowerCase()
    if (!name || seen.has(key)) {
      return
    }
    seen.add(key)
    aliases.push({
      source: name,
      sourceLower: key,
      alias: `__cy_defined_name_${aliases.length}`,
    })
  })
  return aliases.sort((left, right) => right.source.length - left.source.length)
}

function replaceFormulaDefinedNameAliases(value: string, aliases: SheetFormulaNameAlias[]) {
  if (!aliases.length || !isFormulaExpression(value)) {
    return value
  }

  let result = ''
  let index = 0
  let inString = false
  while (index < value.length) {
    const char = value[index] ?? ''
    if (char === '"') {
      result += char
      if (inString && value[index + 1] === '"') {
        result += value[index + 1]
        index += 2
        continue
      }
      inString = !inString
      index += 1
      continue
    }

    if (!inString) {
      const matchedAlias = aliases.find((alias) => {
        const sourceText = value.slice(index, index + alias.source.length)
        return (
          sourceText.toLowerCase() === alias.sourceLower
          && !isFormulaIdentifierChar(value[index - 1])
          && !isFormulaIdentifierChar(value[index + alias.source.length])
        )
      })
      if (matchedAlias) {
        result += matchedAlias.alias
        index += matchedAlias.source.length
        continue
      }
    }

    result += char
    index += 1
  }
  return result
}

function buildFormulaNamedExpressionContextSignature(
  workbookItems: NoteSheetDefinedNameItem[],
  worksheetItems: NoteSheetDefinedNameItem[],
) {
  return JSON.stringify({
    workbook: workbookItems.map((item) => [item.name, item.formula]),
    worksheet: worksheetItems.map((item) => [item.name, item.formula]),
  })
}

function buildFormulaNamedExpressionContext(): SheetFormulaNamedExpressionContext {
  const workbookItems = normalizeDefinedNameItems(workbookDefinedNames.value, 'workbook')
  const worksheetItems = normalizeDefinedNameItems(sheetDefinedNames.value, 'worksheet')
  const signature = buildFormulaNamedExpressionContextSignature(workbookItems, worksheetItems)
  if (formulaNamedExpressionContextCache?.signature === signature) {
    return formulaNamedExpressionContextCache.context
  }
  const aliases = buildFormulaDefinedNameAliases([...workbookItems, ...worksheetItems])
  const aliasByName = new Map(aliases.map((item) => [item.sourceLower, item.alias]))
  const namedExpressions: SheetFormulaNamedExpression[] = []

  workbookItems.forEach((item) => {
    const alias = aliasByName.get(item.name.toLowerCase())
    if (alias && item.formula) {
      namedExpressions.push({
        name: alias,
        expression: replaceFormulaDefinedNameAliases(item.formula, aliases),
      })
    }
  })
  worksheetItems.forEach((item) => {
    const alias = aliasByName.get(item.name.toLowerCase())
    if (alias && item.formula) {
      namedExpressions.push({
        name: alias,
        expression: replaceFormulaDefinedNameAliases(item.formula, aliases),
        scope: 0,
      })
    }
  })

  const context = { namedExpressions, aliases }
  formulaNamedExpressionContextCache = { signature, context }
  return context
}

function buildFormulaDisplayState(): FormulaDisplayState {
  const headers = normalizeHeaders(columnHeaders.value)
  const headerRows = getCurrentFormulaHeaderRows(headers)
  return buildFormulaDisplayStateForRows(
    headers,
    rows.value,
    columnConfigs.value,
    {
      headerRows,
      headerRowCount: headerRows.length,
    },
  )
}

function areFormulaDisplayCellsVisuallyEqual(left: FormulaCellModel | null | undefined, right: FormulaCellModel | null | undefined) {
  if (!left && !right) {
    return true
  }
  if (!left || !right) {
    return false
  }
  return left.formula === right.formula
    && left.text === right.text
}

function areFormulaDisplayStatesVisuallyEqual(left: FormulaDisplayState, right: FormulaDisplayState) {
  if (left.dataStartRow !== right.dataStartRow || left.errorKeys.size !== right.errorKeys.size) {
    return false
  }
  for (const key of left.errorKeys) {
    if (!right.errorKeys.has(key)) {
      return false
    }
  }
  if (left.cells.length !== right.cells.length) {
    return false
  }
  return left.cells.every((leftRow, rowIndex) => {
    const rightRow = right.cells[rowIndex] ?? []
    if (leftRow.length !== rightRow.length) {
      return false
    }
    return leftRow.every((leftCell, columnIndex) => (
      areFormulaDisplayCellsVisuallyEqual(leftCell, rightRow[columnIndex])
    ))
  })
}

function refreshFormulaDisplayState() {
  const nextState = buildFormulaDisplayState()
  const changed = !areFormulaDisplayStatesVisuallyEqual(formulaDisplayState.value, nextState)
  formulaDisplayState.value = nextState
  return changed
}

function getFormulaDisplayTextFromState(
  displayState: FormulaDisplayState | null,
  rowIndex: number,
  columnIndex: number,
) {
  const gridRowIndex = (displayState?.dataStartRow ?? sheetHeaderRowCount.value) + rowIndex
  return displayState?.cells[gridRowIndex]?.[columnIndex]?.text ?? ''
}

function getFormulaCellModel(rowIndex: number, columnIndex: number) {
  if (rowIndex < 0 || columnIndex < 0) {
    return null
  }
  const row = rows.value[rowIndex]
  if (!row || !isFormulaExpression(row[columnIndex])) {
    return null
  }
  return getFormulaCellModelAtGridRow(formulaDisplayState.value.dataStartRow + rowIndex, columnIndex)
}

function getFormulaCellModelAtGridRow(gridRowIndex: number, columnIndex: number) {
  if (gridRowIndex < 0 || columnIndex < 0) {
    return null
  }
  return formulaDisplayState.value.cells[gridRowIndex]?.[columnIndex] ?? null
}

function getColumnConfigByIndex(
  columnIndex: number,
  headers = columnHeaders.value,
  sourceConfigs: Record<string, SheetColumnConfig> = columnConfigs.value,
) {
  return sourceConfigs[headers[columnIndex] ?? '']
}

function getCellDisplayText(
  rowIndex: number,
  columnIndex: number,
  rawValue: unknown,
  displayState?: FormulaDisplayState | null,
  headers = columnHeaders.value,
  sourceConfigs: Record<string, SheetColumnConfig> = columnConfigs.value,
) {
  const normalizedValue = normalizeCellValue(rawValue)
  if (isFormulaExpression(normalizedValue)) {
    const state = displayState === undefined ? formulaDisplayState.value : displayState
    return getFormulaDisplayTextFromState(state, rowIndex, columnIndex)
  }
  return formatCellDisplayValueCached(normalizedValue, getColumnConfigByIndex(columnIndex, headers, sourceConfigs))
}

function getCellSemanticValue(rowIndex: number, columnIndex: number, rawValue: unknown) {
  const normalizedValue = normalizeCellValue(rawValue)
  if (!isFormulaExpression(normalizedValue)) {
    return normalizedValue
  }
  return getFormulaCellModel(rowIndex, columnIndex)?.value2 ?? ''
}

function normalizeColumnFilterQuery(value: unknown) {
  return normalizeCellValue(value).trim()
}

function normalizeColumnFilterSearchText(value: unknown) {
  return normalizeCellValue(value).trim().toLowerCase()
}

function normalizeColumnFilterOptionValue(value: unknown) {
  return normalizeCellValue(value).trim()
}

function formatColumnFilterCount(value: unknown) {
  const numeric = Number(value)
  if (!Number.isFinite(numeric)) {
    return '0'
  }
  return Math.max(0, Math.round(numeric)).toLocaleString('zh-CN')
}

function getColumnFilterOptionLabel(value: string) {
  return value || '(空白)'
}

function getColumnFilterOptionGroupKey(option: ColumnFilterOptionView) {
  const label = option.label.trim()
  if (!label || label === '(空白)') {
    return ''
  }

  const match = label.match(/^([^\s/\\:：,，、|;；()（）\[\]【】\-]+)(?:[\s/\\:：,，、|;；()（）\[\]【】\-]|$)/)
  const key = match?.[1]?.trim() ?? ''
  return key.length >= 2 ? key : ''
}

function getGroupedColumnFilterChildLabel(option: ColumnFilterOptionView, groupLabel: string) {
  const label = option.label.trim()
  if (!label || label === groupLabel) {
    return option.label
  }

  const suffix = label
    .slice(groupLabel.length)
    .replace(/^[\s/\\:：,，、|;；()（）\[\]【】\-]+/, '')
    .trim()
  return suffix || option.label
}

function buildColumnFilterOptionEntries(options: ColumnFilterOptionView[]): ColumnFilterOptionListEntry[] {
  if (options.length < COLUMN_FILTER_OPTION_GROUP_MIN_CHILDREN) {
    return options.map((option) => ({ kind: 'option', option }))
  }

  const buckets = new Map<string, ColumnFilterOptionView[]>()
  options.forEach((option) => {
    const key = getColumnFilterOptionGroupKey(option)
    if (!key) {
      return
    }
    buckets.set(key, [...(buckets.get(key) ?? []), option])
  })

  const groupKeys = new Set(
    [...buckets.entries()]
      .filter(([, children]) => children.length >= COLUMN_FILTER_OPTION_GROUP_MIN_CHILDREN)
      .map(([key]) => key),
  )
  if (!groupKeys.size) {
    return options.map((option) => ({ kind: 'option', option }))
  }

  const emittedGroups = new Set<string>()
  return options.flatMap((option) => {
    const key = getColumnFilterOptionGroupKey(option)
    if (!key || !groupKeys.has(key)) {
      return [{ kind: 'option', option } satisfies ColumnFilterOptionListEntry]
    }
    if (emittedGroups.has(key)) {
      return []
    }

    emittedGroups.add(key)
    const children = (buckets.get(key) ?? []).map((child) => ({
      ...child,
      displayLabel: getGroupedColumnFilterChildLabel(child, key),
    }))
    const selectedCount = children.filter((child) => child.selected).length
    const expanded = expandedColumnFilterOptionGroups.value.has(key)
      || (selectedCount > 0 && selectedCount < children.length)
    return [{
      kind: 'group',
      group: {
        key,
        label: key,
        count: children.reduce((sum, child) => sum + child.count, 0),
        selected: selectedCount === children.length,
        indeterminate: selectedCount > 0 && selectedCount < children.length,
        expanded,
        children,
      },
    } satisfies ColumnFilterOptionListEntry]
  })
}

function normalizeColumnFilterExcludedValues(value: unknown) {
  if (!Array.isArray(value)) {
    return []
  }

  const seen = new Set<string>()
  const values: string[] = []
  value.forEach((item) => {
    const normalized = normalizeColumnFilterOptionValue(item)
    if (seen.has(normalized)) {
      return
    }
    seen.add(normalized)
    values.push(normalized)
  })
  return values
}

function formatColumnFilterDateParts(parts: FormulaDateParts) {
  return `${parts.year}-${String(parts.month).padStart(2, '0')}-${String(parts.day).padStart(2, '0')}`
}

function formatDateInputValue(value: Date) {
  return `${value.getFullYear()}-${String(value.getMonth() + 1).padStart(2, '0')}-${String(value.getDate()).padStart(2, '0')}`
}

function normalizeColumnFilterDateValue(value: unknown) {
  const parts = parseDateDisplayValue(value)
  return parts ? formatColumnFilterDateParts(parts) : ''
}

function normalizeColumnFilterDateRange(value: unknown): Pick<ColumnFilterState, 'dateStart' | 'dateEnd'> {
  const source = Array.isArray(value) ? value : []
  const dateStart = normalizeColumnFilterDateValue(source[0])
  const dateEnd = normalizeColumnFilterDateValue(source[1])
  if (dateStart && dateEnd && dateStart > dateEnd) {
    return { dateStart: dateEnd, dateEnd: dateStart }
  }
  return { dateStart, dateEnd }
}

function getColumnFilterDateDraftRange(state: ColumnFilterState) {
  return state.dateStart && state.dateEnd ? [state.dateStart, state.dateEnd] : []
}

function normalizeColumnFilterNumberOperator(value: unknown): ColumnFilterNumberOperator {
  return COLUMN_FILTER_NUMBER_OPERATOR_OPTIONS.some((option) => option.value === value)
    ? value as ColumnFilterNumberOperator
    : DEFAULT_COLUMN_FILTER_NUMBER_OPERATOR
}

function parseColumnFilterNumberValue(value: unknown) {
  if (typeof value === 'number') {
    return Number.isFinite(value) ? value : Number.NaN
  }

  let text = normalizeCellValue(value).trim()
  if (!text) {
    return Number.NaN
  }

  let sign = 1
  const parenthesizedNegative = text.match(/^\((.+)\)$/)
  if (parenthesizedNegative) {
    sign = -1
    text = parenthesizedNegative[1].trim()
  }

  let multiplier = 1
  if (/%$/.test(text)) {
    multiplier = 0.01
    text = text.replace(/%$/, '')
  }
  if (/万$/.test(text)) {
    multiplier *= 10_000
    text = text.replace(/万$/, '')
  } else if (/亿$/.test(text)) {
    multiplier *= 100_000_000
    text = text.replace(/亿$/, '')
  }

  const normalized = text.replace(/[￥¥,，\s]/g, '')
  if (!/^[-+]?(?:\d+(?:\.\d+)?|\.\d+)$/.test(normalized)) {
    return Number.NaN
  }
  return Number(normalized) * multiplier * sign
}

function normalizeColumnFilterNumberInput(value: unknown) {
  const text = normalizeCellValue(value).trim()
  return Number.isFinite(parseColumnFilterNumberValue(text)) ? text : ''
}

function createEmptyColumnFilterNumberState(): Pick<ColumnFilterState, 'numberOperator' | 'numberValue' | 'numberValueTo'> {
  return {
    numberOperator: DEFAULT_COLUMN_FILTER_NUMBER_OPERATOR,
    numberValue: '',
    numberValueTo: '',
  }
}

function normalizeColumnFilterNumberState(value: unknown): Pick<ColumnFilterState, 'numberOperator' | 'numberValue' | 'numberValueTo'> {
  if (!value || typeof value !== 'object') {
    return createEmptyColumnFilterNumberState()
  }

  const record = value as Record<string, unknown>
  const numberOperator = normalizeColumnFilterNumberOperator(record.numberOperator ?? record.number_operator)
  let numberValue = normalizeColumnFilterNumberInput(record.numberValue ?? record.number_value)
  let numberValueTo = numberOperator === 'between'
    ? normalizeColumnFilterNumberInput(record.numberValueTo ?? record.number_value_to)
    : ''

  if (numberOperator === 'between' && numberValue && numberValueTo) {
    const leftNumber = parseColumnFilterNumberValue(numberValue)
    const rightNumber = parseColumnFilterNumberValue(numberValueTo)
    if (Number.isFinite(leftNumber) && Number.isFinite(rightNumber) && leftNumber > rightNumber) {
      [numberValue, numberValueTo] = [numberValueTo, numberValue]
    }
  }

  return { numberOperator, numberValue, numberValueTo }
}

function isColumnFilterNumberStateActive(state: ColumnFilterState) {
  if (!Number.isFinite(parseColumnFilterNumberValue(state.numberValue))) {
    return false
  }
  if (state.numberOperator !== 'between') {
    return true
  }
  return Number.isFinite(parseColumnFilterNumberValue(state.numberValueTo))
}

function normalizeColumnFilterState(value: unknown): ColumnFilterState {
  if (typeof value === 'string') {
    return {
      query: normalizeColumnFilterQuery(value),
      excludedValues: [],
      dateStart: '',
      dateEnd: '',
      ...createEmptyColumnFilterNumberState(),
    }
  }
  if (!value || typeof value !== 'object') {
    return {
      query: '',
      excludedValues: [],
      dateStart: '',
      dateEnd: '',
      ...createEmptyColumnFilterNumberState(),
    }
  }

  const record = value as Record<string, unknown>
  const legacyRange = normalizeColumnFilterDateRange(record.dateRange ?? record.date_range)
  const explicitDateStart = normalizeColumnFilterDateValue(record.dateStart ?? record.date_start)
  const explicitDateEnd = normalizeColumnFilterDateValue(record.dateEnd ?? record.date_end)
  const dateStart = explicitDateStart || legacyRange.dateStart
  const dateEnd = explicitDateEnd || legacyRange.dateEnd
  const numberState = normalizeColumnFilterNumberState(record)
  return {
    query: normalizeColumnFilterQuery(record.query),
    excludedValues: normalizeColumnFilterExcludedValues(record.excludedValues ?? record.excluded_values),
    ...(dateStart && dateEnd && dateStart > dateEnd
      ? { dateStart: dateEnd, dateEnd: dateStart }
      : { dateStart, dateEnd }),
    ...numberState,
  }
}

function isColumnFilterStateEmpty(state: ColumnFilterState) {
  return (
    !state.query
    && state.excludedValues.length === 0
    && !state.dateStart
    && !state.dateEnd
    && !isColumnFilterNumberStateActive(state)
  )
}

function getColumnFilterState(header: string) {
  return normalizeColumnFilterState(columnFilters.value[header])
}

function setColumnFilterState(header: string, state: ColumnFilterState) {
  const normalized = normalizeColumnFilterState(state)
  const nextFilters = { ...columnFilters.value }
  if (isColumnFilterStateEmpty(normalized)) {
    delete nextFilters[header]
  } else {
    nextFilters[header] = normalized
  }
  columnFilters.value = nextFilters
}

function isColumnFilterEnabled(columnIndex: number) {
  const header = columnHeaders.value[columnIndex]
  return !!header && normalizeColumnConfig(columnConfigs.value[header]).filter_enabled
}

function isColumnFilterOptionMode(columnIndex: number) {
  const header = columnHeaders.value[columnIndex]
  return !!header && normalizeColumnConfig(columnConfigs.value[header]).value_mode === 'fixed_options'
}

function isColumnFilterDateMode(columnIndex: number) {
  const header = columnHeaders.value[columnIndex]
  return !!header && normalizeColumnConfig(columnConfigs.value[header]).value_type === 'date'
}

function isColumnFilterNumberMode(columnIndex: number) {
  const header = columnHeaders.value[columnIndex]
  const valueType = header ? normalizeColumnConfig(columnConfigs.value[header]).value_type : null
  return valueType === 'number' || valueType === 'percent'
}

function getColumnFilterOptions(columnIndex: number): ColumnFilterOptionStat[] {
  const counts = new Map<string, number>()
  rows.value.forEach((row, rowIndex) => {
    const rawValue = row?.[columnIndex] ?? ''
    const displayText = getCellDisplayText(rowIndex, columnIndex, rawValue)
    const value = normalizeColumnFilterOptionValue(displayText)
    counts.set(value, (counts.get(value) ?? 0) + 1)
  })

  return [...counts.entries()]
    .map(([value, count]) => ({
      value,
      label: getColumnFilterOptionLabel(value),
      count,
    }))
    .sort((left, right) => (
      right.count - left.count
      || HASH_COLOR_SEED_COLLATOR.compare(left.label, right.label)
    ))
}

function normalizeExternalRowFilterProgram(value?: ExternalSheetRowFilterProgram | null): NormalizedExternalSheetRowFilterProgram {
  return {
    default: typeof value?.default === 'boolean' ? value.default : false,
    rules: Array.isArray(value?.rules) ? value.rules.map((rule) => ({
      action: rule.action === 'exclude' || rule.action === 'filter' ? rule.action : 'include',
      matcher: normalizeExternalRowFilterMatcher(rule.matcher),
    })) : [],
  }
}

function normalizeExternalRowFilterMatcher(value?: ExternalSheetRowFilterMatcher | null): NormalizedExternalSheetRowFilterMatcher {
  const kind = value?.kind === 'none' || value?.kind === 'field' || value?.kind === 'full_text_contains'
    ? value.kind
    : 'all'
  return {
    kind,
    field: typeof value?.field === 'string' ? value.field : null,
    op: value?.op ?? (kind === 'field' ? 'contains' : null),
    value: value?.value ?? '',
    values: Array.isArray(value?.values) ? value.values : [],
  }
}

function isExternalRowFilterProgramActive(program: NormalizedExternalSheetRowFilterProgram) {
  return program.rules.some((rule) => isExternalRowFilterRuleMeaningful(rule))
}

function isExternalRowFilterRuleMeaningful(rule: NormalizedExternalSheetRowFilterRule) {
  const matcher = normalizeExternalRowFilterMatcher(rule.matcher)
  if (matcher.kind === 'none') return true
  if (matcher.kind === 'all') return rule.action !== 'include'
  if (matcher.kind === 'full_text_contains') return String(matcher.value ?? '').trim() !== ''
  if (matcher.kind !== 'field' || !matcher.field) return false
  if (matcher.op === 'between' || matcher.op === 'in' || matcher.op === 'not_in') {
    return matcher.values.some((item) => String(item ?? '').trim() !== '')
  }
  return String(matcher.value ?? '').trim() !== ''
}

function doesRowMatchExternalRowFilterProgram(
  row: SheetRow,
  rowIndex: number,
  program: NormalizedExternalSheetRowFilterProgram,
) {
  let decision = program.default
  for (const rule of program.rules) {
    const matcher = normalizeExternalRowFilterMatcher(rule.matcher)
    if (!isExternalRowFilterRuleMeaningful({ ...rule, matcher })) {
      continue
    }
    const matched = doesRowMatchExternalRowFilterMatcher(row, rowIndex, matcher)
    if (rule.action === 'filter') {
      decision = decision && matched
    } else if (rule.action === 'exclude') {
      decision = decision && !matched
    } else {
      decision = decision || matched
    }
  }
  return decision
}

function doesRowMatchExternalRowFilterMatcher(
  row: SheetRow,
  rowIndex: number,
  matcher: NormalizedExternalSheetRowFilterMatcher,
) {
  if (matcher.kind === 'all') return true
  if (matcher.kind === 'none') return false
  if (matcher.kind === 'full_text_contains') {
    const keyword = normalizeColumnFilterSearchText(String(matcher.value ?? ''))
    if (!keyword) return true
    return row.some((rawValue, columnIndex) => {
      const displayText = getCellDisplayText(rowIndex, columnIndex, rawValue)
      return normalizeColumnFilterSearchText(displayText).includes(keyword)
    })
  }
  if (matcher.kind !== 'field' || !matcher.field) return true

  const columnIndex = getExternalRowFilterFieldIndex(matcher.field)
  if (columnIndex < 0) return true
  const displayText = getCellDisplayText(rowIndex, columnIndex, row[columnIndex] ?? '')
  return compareExternalRowFilterValue(displayText, matcher)
}

function getExternalRowFilterFieldIndex(field: string) {
  const normalizedField = normalizeCellValue(field).trim()
  return columnHeaders.value.findIndex((header) => normalizeCellValue(header).trim() === normalizedField)
}

function compareExternalRowFilterValue(
  rawText: string,
  matcher: NormalizedExternalSheetRowFilterMatcher,
) {
  const op = matcher.op || 'contains'
  const text = normalizeCellValue(rawText).trim()
  const value = normalizeCellValue(matcher.value).trim()
  const values = matcher.values.map((item) => normalizeCellValue(item).trim())

  if (op === 'contains') return normalizeColumnFilterSearchText(text).includes(normalizeColumnFilterSearchText(value))
  if (op === 'not_contains') return !normalizeColumnFilterSearchText(text).includes(normalizeColumnFilterSearchText(value))
  if (op === 'eq') return text === value
  if (op === 'neq') return text !== value
  if (op === 'in') return values.includes(text)
  if (op === 'not_in') return !values.includes(text)
  if (op === 'between') {
    if (values.length < 2 || !values[0] || !values[1]) return true
    return compareExternalComparableValue(text, values[0]) >= 0
      && compareExternalComparableValue(text, values[1]) <= 0
  }
  if (op === 'gte') return compareExternalComparableValue(text, value) >= 0
  if (op === 'lte') return compareExternalComparableValue(text, value) <= 0
  return true
}

function compareExternalComparableValue(left: string, right: string) {
  const leftNumber = parseExternalNumber(left)
  const rightNumber = parseExternalNumber(right)
  if (Number.isFinite(leftNumber) && Number.isFinite(rightNumber)) {
    return leftNumber - rightNumber
  }

  const leftDate = parseExternalDate(left)
  const rightDate = parseExternalDate(right)
  if (Number.isFinite(leftDate) && Number.isFinite(rightDate)) {
    return leftDate - rightDate
  }

  return left.localeCompare(right, 'zh-Hans-CN', { numeric: true, sensitivity: 'base' })
}

function parseExternalNumber(value: string) {
  const normalized = value.replace(/[,，￥¥\s]/g, '')
  if (!normalized || !/^[+-]?\d+(\.\d+)?$/.test(normalized)) return Number.NaN
  return Number(normalized)
}

function parseExternalDate(value: string) {
  const match = value.trim().match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})/)
  if (!match) return Number.NaN
  const date = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]))
  return date.getTime()
}

function getColumnFilterDateDayValue(value: unknown) {
  const parts = parseDateDisplayValue(value)
  if (!parts) {
    return Number.NaN
  }
  return Date.UTC(parts.year, parts.month - 1, parts.day) / 86_400_000
}

function getRowColumnFilterDateDayValue(rowIndex: number, columnIndex: number, rawValue: unknown) {
  const semanticValue = getCellSemanticValue(rowIndex, columnIndex, rawValue)
  const semanticDay = getColumnFilterDateDayValue(semanticValue)
  if (Number.isFinite(semanticDay)) {
    return semanticDay
  }

  const rawDay = getColumnFilterDateDayValue(rawValue)
  if (Number.isFinite(rawDay)) {
    return rawDay
  }

  return getColumnFilterDateDayValue(getCellDisplayText(rowIndex, columnIndex, rawValue))
}

function getRowColumnFilterNumberValue(rowIndex: number, columnIndex: number, rawValue: unknown) {
  const semanticValue = getCellSemanticValue(rowIndex, columnIndex, rawValue)
  const semanticNumber = parseColumnFilterNumberValue(semanticValue)
  if (Number.isFinite(semanticNumber)) {
    return semanticNumber
  }

  const rawNumber = parseColumnFilterNumberValue(rawValue)
  if (Number.isFinite(rawNumber)) {
    return rawNumber
  }

  return parseColumnFilterNumberValue(getCellDisplayText(rowIndex, columnIndex, rawValue))
}

function doesNumberValueMatchColumnFilter(
  value: number,
  operator: ColumnFilterNumberOperator,
  left: number,
  right: number,
) {
  if (operator === 'eq') return value === left
  if (operator === 'neq') return value !== left
  if (operator === 'gt') return value > left
  if (operator === 'gte') return value >= left
  if (operator === 'lt') return value < left
  if (operator === 'lte') return value <= left
  if (operator === 'between') return value >= left && value <= right
  return true
}

function isColumnFilterActive(columnIndex: number) {
  const header = columnHeaders.value[columnIndex]
  if (!header || !isColumnFilterEnabled(columnIndex)) {
    return false
  }
  const state = getColumnFilterState(header)
  return (
    state.query !== ''
    || (isColumnFilterOptionMode(columnIndex) && state.excludedValues.length > 0)
    || (isColumnFilterDateMode(columnIndex) && (!!state.dateStart || !!state.dateEnd))
    || (isColumnFilterNumberMode(columnIndex) && isColumnFilterNumberStateActive(state))
  )
}

function getActiveColumnFilterEntries() {
  return columnHeaders.value
    .map((header, columnIndex) => {
      const state = getColumnFilterState(header)
      const excludedValues = isColumnFilterOptionMode(columnIndex)
        ? state.excludedValues
        : []
      const dateMode = isColumnFilterDateMode(columnIndex)
      const numberMode = isColumnFilterNumberMode(columnIndex)
      return {
        header,
        columnIndex,
        query: state.query,
        excludedValues: new Set(excludedValues),
        dateStartDay: dateMode ? getColumnFilterDateDayValue(state.dateStart) : Number.NaN,
        dateEndDay: dateMode ? getColumnFilterDateDayValue(state.dateEnd) : Number.NaN,
        numberOperator: state.numberOperator,
        numberValue: numberMode ? parseColumnFilterNumberValue(state.numberValue) : Number.NaN,
        numberValueTo: numberMode ? parseColumnFilterNumberValue(state.numberValueTo) : Number.NaN,
      }
    })
    .filter((item) => (
      isColumnFilterEnabled(item.columnIndex)
      && (
        item.query !== ''
        || item.excludedValues.size > 0
        || Number.isFinite(item.dateStartDay)
        || Number.isFinite(item.dateEndDay)
        || (
          Number.isFinite(item.numberValue)
          && (item.numberOperator !== 'between' || Number.isFinite(item.numberValueTo))
        )
      )
    ))
}

function doesRowMatchColumnFilters(row: SheetRow, rowIndex: number) {
  for (const filter of activeColumnFilterEntries.value) {
    const rawValue = row[filter.columnIndex] ?? ''
    const displayText = getCellDisplayText(rowIndex, filter.columnIndex, rawValue)
    if (
      filter.query
      && !normalizeColumnFilterSearchText(displayText).includes(normalizeColumnFilterSearchText(filter.query))
    ) {
      return false
    }
    if (filter.excludedValues.has(normalizeColumnFilterOptionValue(displayText))) {
      return false
    }
    if (Number.isFinite(filter.dateStartDay) || Number.isFinite(filter.dateEndDay)) {
      const dayValue = getRowColumnFilterDateDayValue(rowIndex, filter.columnIndex, rawValue)
      if (!Number.isFinite(dayValue)) {
        return false
      }
      if (Number.isFinite(filter.dateStartDay) && dayValue < filter.dateStartDay) {
        return false
      }
      if (Number.isFinite(filter.dateEndDay) && dayValue > filter.dateEndDay) {
        return false
      }
    }
    if (
      Number.isFinite(filter.numberValue)
      && (filter.numberOperator !== 'between' || Number.isFinite(filter.numberValueTo))
    ) {
      const numberValue = getRowColumnFilterNumberValue(rowIndex, filter.columnIndex, rawValue)
      if (!Number.isFinite(numberValue)) {
        return false
      }
      if (!doesNumberValueMatchColumnFilter(
        numberValue,
        filter.numberOperator,
        filter.numberValue,
        filter.numberValueTo,
      )) {
        return false
      }
    }
  }
  return true
}

function pruneColumnFilters() {
  const nextFilters: Record<string, ColumnFilterState> = {}
  columnHeaders.value.forEach((header, columnIndex) => {
    if (!isColumnFilterEnabled(columnIndex)) {
      return
    }
    const state = getColumnFilterState(header)
    const normalized: ColumnFilterState = {
      query: state.query,
      excludedValues: isColumnFilterOptionMode(columnIndex) ? state.excludedValues : [],
      dateStart: isColumnFilterDateMode(columnIndex) ? state.dateStart : '',
      dateEnd: isColumnFilterDateMode(columnIndex) ? state.dateEnd : '',
      ...(isColumnFilterNumberMode(columnIndex)
        ? normalizeColumnFilterNumberState(state)
        : createEmptyColumnFilterNumberState()),
    }
    if (!isColumnFilterStateEmpty(normalized)) {
      nextFilters[header] = normalized
    }
  })
  if (JSON.stringify(nextFilters) !== JSON.stringify(columnFilters.value)) {
    columnFilters.value = nextFilters
  }
  const popoverColumn = columnFilterPopover.value.columnIndex
  if (popoverColumn != null && !isColumnFilterEnabled(popoverColumn)) {
    closeColumnFilterPopover()
  }
}

function getCellTextForLayout(rowIndex: number, columnIndex: number, rawValue: unknown) {
  return getCellDisplayText(rowIndex, columnIndex, rawValue)
}

function getExcelColumnIndex(label: string) {
  let index = 0
  const normalizedLabel = label.toUpperCase()
  for (const char of normalizedLabel) {
    const charCode = char.charCodeAt(0)
    if (charCode < 65 || charCode > 90) {
      return null
    }
    index = index * 26 + charCode - 64
  }
  return index - 1
}

function applyFormulaReferenceColumnCase(label: string, sourceLabel: string) {
  return sourceLabel === sourceLabel.toLowerCase() ? label.toLowerCase() : label
}

function shiftFormulaCellReferences(formula: string, rowDelta: number, columnDelta: number) {
  if (!isFormulaExpression(formula) || (!rowDelta && !columnDelta)) {
    return formula
  }

  return formula.replace(
    FORMULA_CELL_REFERENCE_RE,
    (
      _match,
      prefix: string,
      columnAbsoluteMarker: string,
      columnLabel: string,
      rowAbsoluteMarker: string,
      rowLabel: string,
    ) => {
      const sourceColumnIndex = getExcelColumnIndex(columnLabel)
      const sourceRowNumber = Number(rowLabel)
      if (sourceColumnIndex == null || !Number.isInteger(sourceRowNumber) || sourceRowNumber < 1) {
        return `${prefix}#REF!`
      }

      const nextColumnIndex = columnAbsoluteMarker ? sourceColumnIndex : sourceColumnIndex + columnDelta
      const nextRowNumber = rowAbsoluteMarker ? sourceRowNumber : sourceRowNumber + rowDelta
      if (nextColumnIndex < 0 || nextRowNumber < 1) {
        return `${prefix}#REF!`
      }

      const nextColumnLabel = applyFormulaReferenceColumnCase(getExcelColumnLabel(nextColumnIndex), columnLabel)
      return `${prefix}${columnAbsoluteMarker}${nextColumnLabel}${rowAbsoluteMarker}${nextRowNumber}`
    },
  )
}

function remapFormulaCellReferences(
  value: unknown,
  rowIndexMapper?: (rowIndex: number) => number | null,
  columnIndexMapper?: (columnIndex: number) => number | null,
) {
  const formula = normalizeCellValue(value)
  if (!isFormulaExpression(formula)) {
    return formula
  }

  return formula.replace(
    FORMULA_CELL_REFERENCE_RE,
    (
      _match,
      prefix: string,
      columnAbsoluteMarker: string,
      columnLabel: string,
      rowAbsoluteMarker: string,
      rowLabel: string,
    ) => {
      const sourceColumnIndex = getExcelColumnIndex(columnLabel)
      const sourceRowNumber = Number(rowLabel)
      if (sourceColumnIndex == null || !Number.isInteger(sourceRowNumber) || sourceRowNumber < 1) {
        return `${prefix}#REF!`
      }

      const sourceRowIndex = sourceRowNumber - 1
      const nextColumnIndex = columnIndexMapper ? columnIndexMapper(sourceColumnIndex) : sourceColumnIndex
      const nextRowIndex = rowIndexMapper ? rowIndexMapper(sourceRowIndex) : sourceRowIndex
      if (nextColumnIndex == null || nextRowIndex == null || nextColumnIndex < 0 || nextRowIndex < 0) {
        return `${prefix}#REF!`
      }

      const nextColumnLabel = applyFormulaReferenceColumnCase(getExcelColumnLabel(nextColumnIndex), columnLabel)
      return `${prefix}${columnAbsoluteMarker}${nextColumnLabel}${rowAbsoluteMarker}${nextRowIndex + 1}`
    },
  )
}

function remapRowsFormulaReferencesByRowDelta(sourceRows: SheetRow[], rowDelta: number) {
  if (rowDelta === 0) {
    return sourceRows
  }

  let changed = false
  const nextRows = sourceRows.map((row) => row.map((cellValue) => {
    if (!isFormulaExpression(cellValue)) {
      return cellValue
    }
    const nextValue = remapFormulaCellReferences(cellValue, (rowIndex) => {
      const nextRowIndex = rowIndex + rowDelta
      return nextRowIndex >= 0 ? nextRowIndex : null
    })
    if (nextValue !== cellValue) {
      changed = true
    }
    return nextValue
  }))
  return changed ? nextRows : sourceRows
}

function remapRowsFormulaReferencesForHeaderRowCountChange(
  sourceRows: SheetRow[],
  previousHeaderRowCount: number,
  nextHeaderRowCount: number,
) {
  const delta = nextHeaderRowCount - previousHeaderRowCount
  if (delta === 0) {
    return sourceRows
  }

  let changed = false
  const nextRows = sourceRows.map((row) => row.map((cellValue) => {
    if (!isFormulaExpression(cellValue)) {
      return cellValue
    }

    const nextValue = remapFormulaCellReferences(cellValue, (rowIndex) => {
      if (delta > 0) {
        return rowIndex >= previousHeaderRowCount ? rowIndex + delta : rowIndex
      }
      if (rowIndex >= nextHeaderRowCount && rowIndex < previousHeaderRowCount) {
        return null
      }
      return rowIndex >= previousHeaderRowCount ? rowIndex + delta : rowIndex
    })
    if (nextValue !== cellValue) {
      changed = true
    }
    return nextValue
  }))
  return changed ? nextRows : sourceRows
}

function normalizeAutofillRange(range: SheetAutofillRange) {
  const topStart = range.getTopStartCorner()
  const bottomEnd = range.getBottomEndCorner()
  const startRow = Math.min(topStart.row, bottomEnd.row)
  const endRow = Math.max(topStart.row, bottomEnd.row)
  const startColumn = Math.min(topStart.col, bottomEnd.col)
  const endColumn = Math.max(topStart.col, bottomEnd.col)
  return {
    startRow,
    endRow,
    startColumn,
    endColumn,
    rowCount: endRow - startRow + 1,
    columnCount: endColumn - startColumn + 1,
  }
}

function shiftAutofillRange(range: SheetAutofillRange, rowOffset: number, columnOffset = 0): SheetAutofillRange {
  return {
    getTopStartCorner: () => {
      const corner = range.getTopStartCorner()
      return { row: corner.row + rowOffset, col: corner.col + columnOffset }
    },
    getBottomEndCorner: () => {
      const corner = range.getBottomEndCorner()
      return { row: corner.row + rowOffset, col: corner.col + columnOffset }
    },
  }
}

function getAutofillSourceOffset(
  targetOffset: number,
  targetLength: number,
  sourceLength: number,
  reverse: boolean,
) {
  if (sourceLength <= 0) {
    return 0
  }
  if (!reverse) {
    return targetOffset % sourceLength
  }

  const fillOffset = targetLength % sourceLength
  return (targetOffset + sourceLength - fillOffset) % sourceLength
}

function buildFormulaAutofillData(
  sourceRange: SheetAutofillRange,
  targetRange: SheetAutofillRange,
  direction: SheetAutofillDirection,
) {
  const sourceBounds = normalizeAutofillRange(sourceRange)
  const targetBounds = normalizeAutofillRange(targetRange)
  if (
    sourceBounds.rowCount <= 0
    || sourceBounds.columnCount <= 0
    || targetBounds.rowCount <= 0
    || targetBounds.columnCount <= 0
  ) {
    return null
  }

  const sourceHasFormula = Array.from({ length: sourceBounds.rowCount }).some((_, rowOffset) => (
    Array.from({ length: sourceBounds.columnCount }).some((__, columnOffset) => (
      isFormulaExpression(getRawCellValue(
        sourceBounds.startRow + rowOffset,
        sourceBounds.startColumn + columnOffset,
      ))
    ))
  ))
  if (!sourceHasFormula) {
    return null
  }

  return Array.from({ length: targetBounds.rowCount }, (_, targetRowOffset) => (
    Array.from({ length: targetBounds.columnCount }, (__, targetColumnOffset) => {
      const sourceRowOffset = getAutofillSourceOffset(
        targetRowOffset,
        targetBounds.rowCount,
        sourceBounds.rowCount,
        direction === 'up',
      )
      const sourceColumnOffset = getAutofillSourceOffset(
        targetColumnOffset,
        targetBounds.columnCount,
        sourceBounds.columnCount,
        direction === 'left',
      )
      const sourceRow = sourceBounds.startRow + sourceRowOffset
      const sourceColumn = sourceBounds.startColumn + sourceColumnOffset
      const targetRow = targetBounds.startRow + targetRowOffset
      const targetColumn = targetBounds.startColumn + targetColumnOffset
      const sourceValue = getRawCellValue(sourceRow, sourceColumn)
      if (!isFormulaExpression(sourceValue)) {
        return sourceValue
      }
      return shiftFormulaCellReferences(sourceValue, targetRow - sourceRow, targetColumn - sourceColumn)
    })
  ))
}

function setRenderedCellText(TD: HTMLTableCellElement, text: string) {
  const ellipsisElement = TD.querySelector('.htTextEllipsis') as HTMLElement | null
  if (ellipsisElement) {
    if (ellipsisElement.textContent !== text) {
      ellipsisElement.textContent = text
    }
    return
  }
  if (TD.textContent !== text) {
    TD.textContent = text
  }
}

function areRichTextStylesEqual(left: SheetRichTextStyle | null | undefined, right: SheetRichTextStyle | null | undefined) {
  return (left?.text_color ?? '') === (right?.text_color ?? '')
    && (left?.background_color ?? '') === (right?.background_color ?? '')
    && !!left?.bold === !!right?.bold
    && !!left?.italic === !!right?.italic
    && !!left?.underline === !!right?.underline
}

function mergeRichTextStyles(
  base: SheetRichTextStyle | null | undefined,
  patch: SheetRichTextStyle | null | undefined,
) {
  const next: SheetRichTextStyle = { ...(base ?? {}) }
  if (!patch) {
    return hasRichTextStyleValue(next) ? next : null
  }
  if (patch.text_color !== undefined) {
    if (patch.text_color) {
      next.text_color = patch.text_color
    } else {
      delete next.text_color
    }
  }
  if (patch.background_color !== undefined) {
    if (patch.background_color) {
      next.background_color = patch.background_color
    } else {
      delete next.background_color
    }
  }
  if (patch.bold !== undefined) {
    if (patch.bold) {
      next.bold = true
    } else {
      delete next.bold
    }
  }
  if (patch.italic !== undefined) {
    if (patch.italic) {
      next.italic = true
    } else {
      delete next.italic
    }
  }
  if (patch.underline !== undefined) {
    if (patch.underline) {
      next.underline = true
    } else {
      delete next.underline
    }
  }
  return hasRichTextStyleValue(next) ? next : null
}

function cloneRichTextStyle(style: SheetRichTextStyle | null | undefined) {
  return style && hasRichTextStyleValue(style) ? { ...style } : null
}

function buildRichTextStyleSlots(textLength: number, spans: SheetRichTextSpan[]) {
  const slots: Array<SheetRichTextStyle | null> = Array.from({ length: textLength }, () => null)
  normalizeRichTextSpans(spans, textLength).forEach((span) => {
    for (let index = span.start; index < span.end; index += 1) {
      slots[index] = mergeRichTextStyles(slots[index], span.style)
    }
  })
  return slots
}

function compressRichTextStyleSlots(slots: Array<SheetRichTextStyle | null>): SheetRichTextSpan[] {
  const spans: SheetRichTextSpan[] = []
  let start = 0
  while (start < slots.length) {
    const style = slots[start]
    let end = start + 1
    while (end < slots.length && areRichTextStylesEqual(style, slots[end])) {
      end += 1
    }
    if (style && hasRichTextStyleValue(style)) {
      spans.push({ start, end, style })
    }
    start = end
  }
  return spans
}

function buildRichTextSegments(text: string, richText: SheetRichText | null | undefined): SheetRichTextSegment[] {
  if (!text) {
    return []
  }
  const spans = normalizeRichTextSpans(richText?.spans, text.length)
  if (!spans.length) {
    return [{ text, style: null }]
  }
  const slots = buildRichTextStyleSlots(text.length, spans)
  const segments: SheetRichTextSegment[] = []
  let start = 0
  while (start < text.length) {
    const style = slots[start]
    let end = start + 1
    while (end < text.length && areRichTextStylesEqual(style, slots[end])) {
      end += 1
    }
    segments.push({ text: text.slice(start, end), style })
    start = end
  }
  return segments
}

function getRichTextSegmentStyle(style: SheetRichTextStyle | null | undefined) {
  if (!style) {
    return {}
  }
  const css: Record<string, string> = {}
  if (style.text_color) {
    css.color = style.text_color
  }
  if (style.background_color) {
    css.backgroundColor = style.background_color
  }
  if (style.bold) {
    css.fontWeight = '700'
  }
  if (style.italic) {
    css.fontStyle = 'italic'
  }
  if (style.underline) {
    css.textDecoration = 'underline'
    css.textUnderlineOffset = '2px'
  }
  return css
}

function applyRichTextSegmentDomStyle(element: HTMLElement, style: SheetRichTextStyle | null | undefined) {
  if (!style) {
    return
  }
  if (style.text_color) {
    element.style.color = style.text_color
  }
  if (style.background_color) {
    element.style.backgroundColor = style.background_color
  }
  if (style.bold) {
    element.style.fontWeight = '700'
  }
  if (style.italic) {
    element.style.fontStyle = 'italic'
  }
  if (style.underline) {
    element.style.textDecoration = 'underline'
    element.style.textUnderlineOffset = '2px'
  }
}

function renderRichTextCell(TD: HTMLTableCellElement, text: string, richText: SheetRichText) {
  TD.textContent = ''
  buildRichTextSegments(text, richText).forEach((segment) => {
    const span = document.createElement('span')
    span.className = 'sheet-rich-text-segment'
    span.textContent = segment.text
    applyRichTextSegmentDomStyle(span, segment.style)
    TD.appendChild(span)
  })
}

function getCellActionDisplayLabel(action: SheetCellAction, rawText: string) {
  return rawText.trim() || action.label?.trim() || SHEET_CELL_ACTION_LABELS[action.type]
}

function getCellActionButtonLabel(action: SheetCellAction, fallbackLabel: string) {
  return fallbackLabel
}

function getCellActionTitle(action: SheetCellAction) {
  if (action.type === SHEET_CELL_ACTION_EXCEL_IMPORT_RESET) {
    return '用 AI 识别新 Excel 的字段与格式，并按当前表格结构标准化导入'
  }
  if (action.type === SHEET_CELL_ACTION_REGISTRATION_ADD_STUDENT) {
    return '添加一条空白学员记录并打开详情编辑'
  }
  if (action.type === SHEET_CELL_ACTION_REGISTRATION_ORDER_MATCH) {
    return '按微信支付订单号补全订单日期、商户订单号、订单金额和已返款'
  }
  if (action.type === SHEET_CELL_ACTION_REGISTRATION_USER_MATCH) {
    return '本地用户库优先，未命中时可用 codepc_mi15 小鹅通兜底'
  }
  if (action.type === SHEET_CELL_ACTION_REGISTRATION_COMPOSITE_UPDATE) {
    return '补齐订单信息和用户ID，本地未命中时用 codepc_mi15 实时回查，并把新学员同步到考勤表'
  }
  if (action.type === SHEET_CELL_ACTION_ATTENDANCE_EXPORT) {
    return '导出考勤表，导出文件会按报名表学号把手机号补到昵称后面'
  }
  if (action.type === SHEET_CELL_ACTION_CLOCKIN_LINK_DETECT) {
    return '从名称管理器的“打卡根目录”开始识别共学、共修打卡数据页，并写回当前打卡配置'
  }
  if (action.type === SHEET_CELL_ACTION_ATTENDANCE_COURSE_UPDATE_DATA) {
    return '重新执行当前梵呗/念住/觉观/禅宗/修道班考勤表的 step2 和 step3，并更新返款相关数据'
  }
  return ''
}

function getActiveRegistrationRunForAction(actionType: SheetCellActionType) {
  const run = userMatchRunStatus.value
  if (!run || !isRegistrationMatchRunActive(run) || !isRegistrationAsyncAction(actionType)) {
    return null
  }
  return run
}

function getActiveClockinLinkDetectionRunForAction(actionType: SheetCellActionType) {
  const run = clockinLinkDetectionRunStatus.value
  if (!run || !isClockinLinkDetectionRunActive(run) || actionType !== SHEET_CELL_ACTION_CLOCKIN_LINK_DETECT) {
    return null
  }
  return run
}

function isCellActionBlockedByActiveRun(actionType: SheetCellActionType) {
  return !!getActiveRegistrationRunForAction(actionType) || !!getActiveClockinLinkDetectionRunForAction(actionType)
}

function getCellActionRunningLabel(action: SheetCellAction, label: string) {
  const run = getActiveRegistrationRunForAction(action.type)
  const clockinRun = getActiveClockinLinkDetectionRunForAction(action.type)
  if (sheetCellActionRunning.value === action.type) {
    return `${SHEET_CELL_ACTION_LABELS[action.type] || label}中`
  }
  if (clockinRun) {
    return `${SHEET_CELL_ACTION_LABELS[action.type] || label}中`
  }
  if (!run || run.action !== action.type) {
    return label
  }
  return `${SHEET_CELL_ACTION_LABELS[action.type] || label}中`
}

function renderCellActionButton(
  TD: HTMLTableCellElement,
  label: string,
  action: SheetCellAction,
  actionCell: { documentRow: number; column: number },
  rawText = '',
) {
  TD.textContent = ''
  const button = document.createElement('button')
  button.type = 'button'
  button.tabIndex = -1
  button.className = 'sheet-cell-action-button-inner'
  button.dataset.sheetActionType = action.type
  button.title = getCellActionTitle(action)
  const activeRun = getActiveRegistrationRunForAction(action.type)
  const activeClockinRun = getActiveClockinLinkDetectionRunForAction(action.type)
  const isRunningSelf = (!!activeRun && activeRun.action === action.type) || !!activeClockinRun || sheetCellActionRunning.value === action.type
  const isBlocked = isCellActionBlockedByActiveRun(action.type)
  const isPermissionDisabled = isSheetCellActionDisabledByPermission(action.type)
  if (isRunningSelf) {
    button.classList.add('is-running')
  } else if (isBlocked || isPermissionDisabled) {
    button.classList.add('is-disabled')
    button.disabled = true
  }
  button.textContent = getCellActionRunningLabel(action, getCellActionButtonLabel(action, label))
  const trigger = (event: Event) => {
    triggerSheetCellActionButtonFromEvent(event, action, actionCell)
  }
  button.addEventListener('pointerdown', (event) => {
    if (event.pointerType === 'mouse') {
      return
    }
    trigger(event)
  }, { capture: true })
  button.addEventListener('touchstart', trigger, { capture: true })
  button.addEventListener('mousedown', trigger, { capture: true })
  button.addEventListener('click', trigger, { capture: true })
  TD.appendChild(button)
}

function areDefaultSheetHeaders(headers: string[]) {
  return (
    headers.length === DEFAULT_SHEET_COLUMNS.length
    && headers.every((header, index) => header === DEFAULT_SHEET_COLUMNS[index])
  )
}

function hasMeaningfulSheetDocumentContent(document: SheetDocument) {
  const headers = normalizeHeaders(document.columns)
  const normalizedRows = trimTrailingBlankRows(document.rows.map((row) => normalizeRow(row, headers)))
  if (normalizedRows.length > 0 || !areDefaultSheetHeaders(headers)) {
    return true
  }

  return (
    normalizeHeaderGroups(document.header_groups, headers.length).length > 0
    || Object.keys(normalizeCellMetaMap(document.cell_meta, headers.length)).length > 0
    || Object.keys(normalizeEntityCellMap(document.entity_cells)).length > 0
    || Object.keys(normalizeColumnConfigs(document.column_configs, headers)).length > 0
  )
}

function buildCurrentPagePatchState(): SheetPagePatchState {
  return {
    paginationEnabled: paginationEnabled.value,
    page: currentPage.value,
    pageSize: pageSize.value,
    rowOffset: pageRowOffset.value,
    loadedRowCount: pageLoadedRowCount.value,
    rowIndexes: pageRowIndexes.value ? [...pageRowIndexes.value] : null,
    deletedRowIndexes: pendingDeletedPageRowIndexes.value.length
      ? [...pendingDeletedPageRowIndexes.value]
      : null,
  }
}

function cloneSheetDocumentSnapshot(document: SheetDocument): SheetDocument {
  return JSON.parse(JSON.stringify(document)) as SheetDocument
}

function buildLocalHistoryPageState(): SheetLocalHistoryPageState {
  return {
    ...buildCurrentPagePatchState(),
    pageCount: pageCount.value,
    totalRowCount: totalRowCount.value,
    unfilteredTotalRowCount: unfilteredTotalRowCount.value,
  }
}

function buildLocalHistorySnapshot(): SheetLocalHistorySnapshot {
  return {
    title: sheetTitle.value.trim() || '未命名表格',
    document: cloneSheetDocumentSnapshot(buildCurrentDocument()),
    pageState: buildLocalHistoryPageState(),
  }
}

function getLocalHistorySnapshotKey(snapshot: SheetLocalHistorySnapshot) {
  return JSON.stringify({
    title: snapshot.title,
    document: snapshot.document,
    pageState: snapshot.pageState,
  })
}

function buildLocalHistoryEntry(reason: string): SheetLocalHistoryEntry {
  const snapshot = buildLocalHistorySnapshot()
  return {
    ...snapshot,
    key: getLocalHistorySnapshotKey(snapshot),
    reason,
    createdAt: Date.now(),
  }
}

function trimLocalHistoryStack(stack: SheetLocalHistoryEntry[]) {
  while (stack.length > LOCAL_UNDO_STACK_LIMIT) {
    stack.shift()
  }
}

function clearNativeUndoRedoHistory() {
  getUndoRedoPlugin()?.clear?.()
}

function resetLocalUndoHistory() {
  localUndoStack.value = []
  localRedoStack.value = []
  clearNativeUndoRedoHistory()
}

function createLocalUndoEntry(reason = 'edit') {
  if (
    suppressPersistence
    || suppressLocalHistory
    || !sheetContentReady.value
    || !canPersistSheet.value
  ) {
    return null
  }

  return buildLocalHistoryEntry(reason)
}

function pushLocalUndoEntry(
  entry: SheetLocalHistoryEntry | null | undefined,
  options: { skipCurrentCompare?: boolean } = {},
) {
  if (!entry || suppressLocalHistory) {
    return
  }

  const lastEntry = localUndoStack.value[localUndoStack.value.length - 1]
  if (lastEntry?.key === entry.key) {
    return
  }
  if (!options.skipCurrentCompare && getLocalHistorySnapshotKey(buildLocalHistorySnapshot()) === entry.key) {
    return
  }

  localUndoStack.value.push(entry)
  trimLocalHistoryStack(localUndoStack.value)
  localRedoStack.value = []
  clearNativeUndoRedoHistory()
}

function pushLocalUndoSnapshot(reason = 'edit') {
  pushLocalUndoEntry(createLocalUndoEntry(reason), { skipCurrentCompare: true })
}

function restoreLocalHistorySnapshot(snapshot: SheetLocalHistorySnapshot) {
  suppressLocalHistory = true
  suppressPersistence = true
  try {
    sheetTitle.value = snapshot.title || '未命名表格'
    currentPage.value = normalizePositivePageNumber(snapshot.pageState.page, 1)
    pageSize.value = normalizePositivePageNumber(snapshot.pageState.pageSize, pageSize.value)
    pageCount.value = normalizePositivePageNumber(snapshot.pageState.pageCount, 1)
    totalRowCount.value = normalizeNonNegativeInt(snapshot.pageState.totalRowCount)
    unfilteredTotalRowCount.value = Math.max(
      totalRowCount.value,
      normalizeNonNegativeInt(snapshot.pageState.unfilteredTotalRowCount),
    )
    pageRowOffset.value = normalizeNonNegativeInt(snapshot.pageState.rowOffset)
    pageLoadedRowCount.value = normalizeNonNegativeInt(snapshot.pageState.loadedRowCount)
    pageRowIndexes.value = normalizePaginationRowIndexes(snapshot.pageState.rowIndexes)
    pendingDeletedPageRowIndexes.value = normalizePaginationDeletedRowIndexes(snapshot.pageState.deletedRowIndexes) ?? []

    beginSheetCoreRenderPhase()
    const snapshotDocument = cloneSheetDocumentSnapshot(snapshot.document)
    loadSheetDocument(normalizeSheetDocument(
      snapshotDocument,
      {},
      getDefaultSheetHeightMode(),
    ), snapshotDocument)
    sheetContentReady.value = true
    scheduleSheetRenderEnhancement()
    invalidateColumnFilterGlobalOptionsCache()
    clearNativeUndoRedoHistory()
  } finally {
    suppressPersistence = false
    suppressLocalHistory = false
  }

  scheduleRemoteSave(0)
  void refreshComputedRowHeights()
}

function undoLocalSheetChange() {
  const entry = localUndoStack.value.pop()
  if (!entry) {
    return false
  }

  const currentEntry = buildLocalHistoryEntry('redo')
  localRedoStack.value.push(currentEntry)
  trimLocalHistoryStack(localRedoStack.value)
  restoreLocalHistorySnapshot(entry)
  return true
}

function redoLocalSheetChange() {
  const entry = localRedoStack.value.pop()
  if (!entry) {
    return false
  }

  const currentEntry = buildLocalHistoryEntry('undo')
  localUndoStack.value.push(currentEntry)
  trimLocalHistoryStack(localUndoStack.value)
  restoreLocalHistorySnapshot(entry)
  return true
}

function undoSheetChange() {
  if (undoLocalSheetChange()) {
    return true
  }

  const undoRedoPlugin = getUndoRedoPlugin()
  if (!undoRedoPlugin?.isUndoAvailable?.() || !undoRedoPlugin.undo) {
    return false
  }
  undoRedoPlugin.undo()
  return true
}

function redoSheetChange() {
  if (redoLocalSheetChange()) {
    return true
  }

  const undoRedoPlugin = getUndoRedoPlugin()
  if (!undoRedoPlugin?.isRedoAvailable?.() || !undoRedoPlugin.redo) {
    return false
  }
  undoRedoPlugin.redo()
  return true
}

function canUndoSheetChange() {
  return localUndoStack.value.length > 0 || !!getUndoRedoPlugin()?.isUndoAvailable?.()
}

function canRedoSheetChange() {
  return localRedoStack.value.length > 0 || !!getUndoRedoPlugin()?.isRedoAvailable?.()
}

function normalizeDraftPageState(source: unknown): SheetPagePatchState | null {
  if (!source || typeof source !== 'object') {
    return null
  }

  const record = source as Record<string, unknown>
  return {
    paginationEnabled: record.paginationEnabled === true,
    page: normalizePositivePageNumber(record.page, currentPage.value),
    pageSize: normalizePositivePageNumber(record.pageSize, pageSize.value),
    rowOffset: normalizeNonNegativeInt(record.rowOffset, pageRowOffset.value),
    loadedRowCount: normalizeNonNegativeInt(record.loadedRowCount, pageLoadedRowCount.value),
    rowIndexes: normalizePaginationRowIndexes(record.rowIndexes),
    deletedRowIndexes: normalizePaginationDeletedRowIndexes(record.deletedRowIndexes),
  }
}

function arePaginationRowIndexesEqual(left?: number[] | null, right?: number[] | null) {
  const normalizedLeft = left ?? null
  const normalizedRight = right ?? null
  if (normalizedLeft === null || normalizedRight === null) {
    return normalizedLeft === normalizedRight
  }
  return normalizedLeft.length === normalizedRight.length
    && normalizedLeft.every((item, index) => item === normalizedRight[index])
}

function areDraftPaginationRowIndexesCompatible(pageState: SheetPagePatchState) {
  if (arePaginationRowIndexesEqual(pageState.rowIndexes, pageRowIndexes.value)) {
    return true
  }
  const deletedRowIndexes = pageState.deletedRowIndexes ?? []
  if (!deletedRowIndexes.length || !pageState.rowIndexes || !pageRowIndexes.value) {
    return false
  }
  const reconstructed = normalizePaginationDeletedRowIndexes([
    ...pageState.rowIndexes,
    ...deletedRowIndexes,
  ])
  return arePaginationRowIndexesEqual(reconstructed, pageRowIndexes.value)
}

function isDraftLoadedRowCountCompatible(pageState: SheetPagePatchState) {
  if (pageState.loadedRowCount === pageLoadedRowCount.value) {
    return true
  }
  const deletedCount = pageState.deletedRowIndexes?.length ?? 0
  return deletedCount > 0 && pageState.loadedRowCount + deletedCount === pageLoadedRowCount.value
}

function isDraftDocumentRowCountCompatibleWithPage(document: SheetDocument, pageState: SheetPagePatchState | null) {
  if (!pageState?.paginationEnabled) {
    return true
  }

  const headers = normalizeHeaders(document.columns)
  const rowCount = trimTrailingBlankRows(document.rows.map((row) => normalizeRow(row, headers))).length
  if (rowCount <= pageState.loadedRowCount) {
    return true
  }

  return pageState.page >= pageCount.value
}

function isSamePagePatchState(pageState: SheetPagePatchState | null) {
  if (!pageState) {
    return false
  }

  if (pageState.paginationEnabled !== paginationEnabled.value) {
    return false
  }
  if (!paginationEnabled.value) {
    return true
  }

  return (
    pageState.page === currentPage.value
    && pageState.pageSize === pageSize.value
    && pageState.rowOffset === pageRowOffset.value
    && isDraftLoadedRowCountCompatible(pageState)
    && areDraftPaginationRowIndexesCompatible(pageState)
  )
}

function readDraftPayload(): SheetDraftPayload | null {
  if (typeof window === 'undefined' || props.sheetId == null) {
    return null
  }
  if (!canPersistSheet.value) {
    clearDraftStorage()
    return null
  }

  try {
    const raw = window.localStorage.getItem(storageKey.value)
    if (!raw) {
      return null
    }
    const payload = JSON.parse(raw) as Record<string, unknown>
    const pageState = normalizeDraftPageState(payload.pageState)
    return {
      version: 1,
      updatedAt: normalizeTimestampMs(payload.updatedAt),
      sheetVersion: payload.sheetVersion == null ? null : Number(payload.sheetVersion),
      title: String(payload.title ?? '').trim() || '未命名表格',
      document: normalizeSheetDocument(payload.document, {
        rowOffset: pageState?.paginationEnabled ? pageState.rowOffset : 0,
      }, getDefaultSheetHeightMode()),
      pageState,
    }
  } catch (error) {
    console.warn('Failed to restore note sheet draft', error)
    window.localStorage.removeItem(storageKey.value)
    return null
  }
}

function persistDraftDocument(document: SheetDocument) {
  if (typeof window === 'undefined' || props.sheetId == null) {
    return
  }
  if (!canPersistSheet.value) {
    clearDraftStorage()
    return
  }

  const payload: SheetDraftPayload = {
    version: 1,
    updatedAt: Date.now(),
    sheetVersion: sheetVersion.value || null,
    title: sheetTitle.value.trim() || '未命名表格',
    document,
    pageState: buildCurrentPagePatchState(),
  }
  window.localStorage.setItem(storageKey.value, JSON.stringify(payload))
}

function clearDraftStorage() {
  if (typeof window === 'undefined' || props.sheetId == null) {
    return
  }
  window.localStorage.removeItem(storageKey.value)
}

function clearEditingColumnState() {
  editingColumnIndex.value = null
  editingColumnTitle.value = ''
  editingHeaderInputEl = null
}

function getHotInstance() {
  return hotTableRef.value?.hotInstance ?? null
}

function getUndoRedoPlugin() {
  return getHotInstance()?.getPlugin('undoRedo') as {
    isUndoAvailable?: () => boolean
    isRedoAvailable?: () => boolean
    undo?: () => void
    redo?: () => void
    clear?: () => void
  } | null
}

function getContextMenuPlugin() {
  return getHotInstance()?.getPlugin('contextMenu') as SheetContextMenuPlugin | null
}

function handleColumnSortParentMenuMouseUp(event: MouseEvent) {
  if (event.button !== 0) {
    return
  }

  event.preventDefault()
  event.stopPropagation()
  event.stopImmediatePropagation()
  getContextMenuPlugin()?.close?.()
  void handleSelectedColumnSort('asc')
}

function handleOpenCellLinkParentMenuMouseUp(event: MouseEvent) {
  if (event.button !== 0) {
    return
  }

  event.preventDefault()
  event.stopPropagation()
  event.stopImmediatePropagation()
  getContextMenuPlugin()?.close?.()
  openSelectedCellLinkDefault()
}

function bindContextMenuParentAction(
  menuHot: Handsontable,
  itemKey: string,
  title: string,
  onMouseUp: (event: MouseEvent) => void,
) {
  for (let rowIndex = 0; rowIndex < menuHot.countRows(); rowIndex += 1) {
    const item = menuHot.getSourceDataAtRow(rowIndex) as SheetContextMenuItem | null
    if (item?.key !== itemKey) {
      continue
    }
    const cell = menuHot.getCell(rowIndex, 0)
    if (cell) {
      cell.title = title
      cell.addEventListener('mouseup', onMouseUp, { capture: true })
    }
    break
  }
}

function handleAfterContextMenuShow(plugin: SheetContextMenuPlugin) {
  const menuHot = plugin.menu?.hotMenu
  if (!menuHot) {
    return
  }

  bindContextMenuParentAction(
    menuHot,
    'column_sort',
    '默认按当前列升序排序；悬浮可选择降序',
    handleColumnSortParentMenuMouseUp,
  )
  bindContextMenuParentAction(
    menuHot,
    'open_cell_link',
    '有链接时直接打开；无链接时进入设置',
    handleOpenCellLinkParentMenuMouseUp,
  )
}

function shouldEnableTouchContextMenuFallback() {
  if (typeof window === 'undefined' || typeof navigator === 'undefined') {
    return false
  }

  const maxTouchPoints = Number(navigator.maxTouchPoints || 0)
  const coarsePointer = window.matchMedia?.('(pointer: coarse)').matches ?? false
  const userAgent = navigator.userAgent || ''
  const isSafari = /Safari/i.test(userAgent)
    && !/(Chrome|Chromium|CriOS|FxiOS|Edg|OPR|Android)/i.test(userAgent)
  const isAppleTouchDevice = /iPad|iPhone|iPod/.test(userAgent)
    || (navigator.platform === 'MacIntel' && maxTouchPoints > 1)
  return coarsePointer || isAppleTouchDevice || isSafari
}

function isMobileOrTabletDevice() {
  if (typeof window === 'undefined' || typeof navigator === 'undefined') {
    return false
  }

  const maxTouchPoints = Number(navigator.maxTouchPoints || 0)
  const coarsePointer = window.matchMedia?.('(pointer: coarse)').matches ?? false
  const userAgent = navigator.userAgent || ''
  const platform = navigator.platform || ''
  const mobileOrTabletUserAgent = /Android|iPad|iPhone|iPod|Mobile|Tablet/i.test(userAgent)
  const appleTabletDesktopUserAgent = platform === 'MacIntel' && maxTouchPoints > 1
  return coarsePointer || mobileOrTabletUserAgent || appleTabletDesktopUserAgent
}

function shouldDefaultToStudentLookupView() {
  return sheetViewSettings.value.mobile_default_view === 'lookup' && isMobileOrTabletDevice()
}

function refreshContextMenuFallbackSelectionState() {
  hasContextMenuFallbackSelection.value = !!getHotInstance()?.getSelectedLast()
}

function openTouchContextMenuFallback(event: MouseEvent | TouchEvent) {
  event.preventDefault()
  event.stopPropagation()

  const hot = getHotInstance()
  const plugin = getContextMenuPlugin()
  if (!hot || !plugin?.open || !hasSelection()) {
    refreshContextMenuFallbackSelectionState()
    return
  }

  const rect = contextMenuFallbackButtonRef.value?.getBoundingClientRect()
  const left = rect ? rect.left : window.innerWidth - 64
  const top = rect ? rect.top : window.innerHeight - 96
  hot.listen()
  plugin.open({
    left: Math.max(12, Math.min(left, window.innerWidth - 12)),
    top: Math.max(12, Math.min(top, window.innerHeight - 12)),
  }, {
    above: 8,
    below: 8,
    left: 8,
    right: 8,
  })
}

function syncContextMenuSelectionFromEvent(event: MouseEvent) {
  const target = event.target
  if (!(target instanceof HTMLElement)) {
    return
  }

  const cell = target.closest('td, th') as HTMLElement | null
  if (!cell || !sheetFrameRef.value?.contains(cell)) {
    return
  }

  const rowMarkerValue = cell.dataset.sheetRowMarker
  if (rowMarkerValue != null) {
    const row = normalizeNonNegativeInt(rowMarkerValue, -1)
    if (row >= 0) {
      if (shouldPreserveSelectionForContextPointer(event, row, 0)) {
        return
      }
      selectRowFromMarker(row, event.shiftKey)
    }
    return
  }

  const headerLevel = normalizeNonNegativeInt(cell.dataset.sheetHeaderLevel, -1)
  const headerColumn = normalizeNonNegativeInt(cell.dataset.sheetHeaderColumn, -1)
  if (headerLevel < 0 || headerColumn < 0 || headerColumn >= columnHeaders.value.length) {
    return
  }

  const anchor = getMergeAnchorForGridCell(headerLevel, headerColumn)
  if (shouldPreserveSelectionForContextPointer(event, anchor.row, toHotColumnIndex(anchor.column))) {
    return
  }
  const anchoredHeaderLevel = getSheetHeaderGridLevel(anchor.row)
  selectedSheetHeaderCell.value = { column: anchor.column, headerLevel: anchoredHeaderLevel }
  clearColumnMarkerSelection()
  setFormulaBarGridCell(anchor.row, anchor.column)
  const hot = getHotInstance()
  if (hot) {
    hot.selectCell(anchor.row, toHotColumnIndex(anchor.column), anchor.row, toHotColumnIndex(anchor.column), true, false)
    hot.listen()
  }
  if (shouldRealignOverlayForSelection(anchor.row, anchor.column)) {
    scheduleSheetOverlayAlignment()
  }
}

function openSheetContextMenuAt(event: MouseEvent) {
  event.preventDefault()
  event.stopPropagation()
  event.stopImmediatePropagation()
  syncContextMenuSelectionFromEvent(event)
  showRichTextInlineToolbarFromContextMenu(event)

  const hot = getHotInstance()
  const plugin = getContextMenuPlugin()
  if (!hot || !plugin?.open || !hasSelection()) {
    refreshContextMenuFallbackSelectionState()
    return
  }

  hot.listen()
  plugin.open({
    left: event.clientX,
    top: event.clientY,
  }, {
    above: 8,
    below: 8,
    left: 8,
    right: 8,
  })
}

async function refreshComputedRowHeights(options: { force?: boolean } = {}) {
  const hot = getHotInstance()
  if (!hot) {
    return
  }
  if (!options.force && !shouldUseEnhancedSheetRenderSettings.value) {
    return
  }

  const trace = startSheetPerfTrace('sheet.rowHeights', {
    detail: {
      forced: !!options.force,
      rows: rows.value.length,
      columns: columnHeaders.value.length,
    },
  })
  try {
    hot.updateSettings({
      cells: sheetHotRenderCellMetaResolver.value,
      rowHeights: sheetHotRenderRowHeightResolver.value,
    })
    trace?.mark('update-settings')
    await nextTick()
    trace?.mark('next-tick')
    renderHotWithReason(hot, 'row-heights-refresh')
    trace?.mark('render')
    void updateSheetViewportHeight()
    trace?.finish({
      detail: {
        forced: !!options.force,
        rows: rows.value.length,
        columns: columnHeaders.value.length,
      },
    })
  } catch (error) {
    trace?.finish({
      detail: {
        forced: !!options.force,
        error: error instanceof Error ? error.message : String(error),
      },
    })
    throw error
  }
}

function hasSelection() {
  return !!getHotInstance()?.getSelectedLast()
}

function isSelectedByColumnHeader() {
  return !!getHotInstance()?.selection?.isSelectedByColumnHeader?.()
}

function isSelectedByRowHeader() {
  return !!getHotInstance()?.selection?.isSelectedByRowHeader?.()
}

function isSelectedByCorner() {
  return !!getHotInstance()?.selection?.isSelectedByCorner?.()
}

function isSelectedByRowMarkerSelection() {
  if (rowMarkerColumnCount.value <= 0) {
    return false
  }
  const selection = getHotInstance()?.getSelectedLast()
  if (!selection) {
    return false
  }
  const startRow = Math.min(selection[0], selection[2])
  const endRow = Math.max(selection[0], selection[2])
  const startColumn = Math.min(selection[1], selection[3])
  const endColumn = Math.max(selection[1], selection[3])
  return (
    endRow >= sheetHeaderRowCount.value
    && startRow >= 0
    && startColumn <= 0
    && endColumn >= getHotColumnCount() - 1
  )
}

function isSingleRowMarkerCellSelection(selection = getHotInstance()?.getSelectedLast()) {
  if (rowMarkerColumnCount.value <= 0 || !selection) {
    return false
  }
  return (
    selection[0] === selection[2]
    && selection[1] === 0
    && selection[3] === 0
    && selection[0] >= 0
  )
}

function selectFirstSheetCellInGridRow(gridRow: number) {
  const hot = getHotInstance()
  if (!hot || gridRow < 0 || columnHeaders.value.length <= 0) {
    return false
  }

  hot.selectCell(gridRow, toHotColumnIndex(0), gridRow, toHotColumnIndex(0), true, false)
  hot.listen()
  return true
}

function redirectSingleRowMarkerSelection(selection = getHotInstance()?.getSelectedLast()) {
  if (!isSingleRowMarkerCellSelection(selection)) {
    return false
  }
  return selectFirstSheetCellInGridRow(selection![0])
}

function shouldBlockRowMarkerKeyboardNavigation(event: KeyboardEvent) {
  if (
    rowMarkerColumnCount.value <= 0
    || event.ctrlKey
    || event.metaKey
    || event.altKey
    || event.isComposing
  ) {
    return false
  }

  const selection = getHotInstance()?.getSelectedLast()
  if (!selection) {
    return false
  }
  const startColumn = Math.min(selection[1], selection[3])
  if (event.key === 'ArrowLeft') {
    return startColumn <= rowMarkerColumnCount.value
  }
  if (event.key === 'Home') {
    return startColumn <= rowMarkerColumnCount.value
  }
  if (event.key === 'Tab' && event.shiftKey) {
    return startColumn <= rowMarkerColumnCount.value
  }
  return false
}

function isHotGridCellInsideSelection(gridRow: number, hotColumn: number) {
  const hot = getHotInstance()
  const selections = hot?.getSelected?.() as number[][] | undefined
  if (!selections?.length) {
    return false
  }

  return selections.some((selection) => {
    if (!Array.isArray(selection) || selection.length < 4) {
      return false
    }
    const startRow = Math.min(selection[0], selection[2])
    const endRow = Math.max(selection[0], selection[2])
    const startColumn = Math.min(selection[1], selection[3])
    const endColumn = Math.max(selection[1], selection[3])
    return (
      gridRow >= startRow
      && gridRow <= endRow
      && hotColumn >= startColumn
      && hotColumn <= endColumn
    )
  })
}

function shouldPreserveSelectionForContextPointer(event: MouseEvent, gridRow: number, hotColumn: number) {
  return (
    (event.button === 2 || event.type === 'contextmenu')
    && !event.shiftKey
    && gridRow >= 0
    && hotColumn >= 0
    && isHotGridCellInsideSelection(gridRow, hotColumn)
  )
}

function clearScheduledRowMarkerSelection() {
  if (rowMarkerSelectionTimer != null && typeof window !== 'undefined') {
    window.clearTimeout(rowMarkerSelectionTimer)
  }
  rowMarkerSelectionTimer = null
}

function clearRowMarkerSelectionAnchor() {
  rowMarkerSelectionAnchor = null
}

function getRowMarkerSelectionAnchor(gridRow: number, extendSelection: boolean) {
  if (!extendSelection) {
    return gridRow
  }

  const currentRowBounds = getSelectionRowBounds()
  const anchorDataRow = rowMarkerSelectionAnchor == null ? -1 : getDataRowIndex(rowMarkerSelectionAnchor)
  if (
    rowMarkerSelectionAnchor != null
    && isSelectedByRowMarkerSelection()
    && currentRowBounds
    && anchorDataRow >= currentRowBounds.start
    && anchorDataRow <= currentRowBounds.end
  ) {
    return rowMarkerSelectionAnchor
  }

  const selection = normalizeHotSelectionRange(getHotInstance()?.getSelectedLast())
  if (!selection) {
    return gridRow
  }

  if (selection[0] >= sheetHeaderRowCount.value) {
    return selection[0]
  }
  if (selection[2] >= sheetHeaderRowCount.value) {
    return selection[2]
  }
  return gridRow
}

function selectRowFromMarker(gridRow: number, extendSelection = false) {
  const hot = getHotInstance()
  if (!hot || gridRow < sheetHeaderRowCount.value) {
    return false
  }

  clearScheduledRowMarkerSelection()
  const anchorRow = getRowMarkerSelectionAnchor(gridRow, extendSelection)
  const startRow = Math.min(anchorRow, gridRow)
  const endRow = Math.max(anchorRow, gridRow)
  const run = () => {
    rowMarkerSelectionTimer = null
    const latestHot = getHotInstance()
    if (!latestHot) {
      return
    }

    rowMarkerSelectionAnchor = anchorRow
    latestHot.selectCell(startRow, 0, endRow, Math.max(0, getHotColumnCount() - 1), true, false)
    latestHot.listen()
    refreshContextMenuFallbackSelectionState()
  }

  if (typeof window === 'undefined') {
    run()
  } else {
    run()
    rowMarkerSelectionTimer = window.setTimeout(run, 0)
  }
  return true
}

function shouldShowRowActions() {
  return hasSelection() && (isSelectedByRowHeader() || isSelectedByCorner() || isSelectedByRowMarkerSelection())
}

function shouldShowColumnActions() {
  return hasSelection() && (isSelectedByColumnHeader() || isSelectedByCorner())
}

function isWholeRowSelection() {
  return isSelectedByRowHeader() || isSelectedByRowMarkerSelection()
}

function getMainScrollContainer() {
  return sheetFrameRef.value?.closest('.page-shell-main') as HTMLElement | null
}

function getTextMeasureContext() {
  if (textMeasureContext) {
    return textMeasureContext
  }

  if (typeof document === 'undefined') {
    return null
  }

  const canvas = document.createElement('canvas')
  textMeasureContext = canvas.getContext('2d')
  if (textMeasureContext) {
    textMeasureContext.font = TABLE_FONT
  }
  return textMeasureContext
}

function measureTextWidth(text: string, font = TABLE_FONT) {
  if (!text) {
    return 0
  }

  const cacheKey = `${font}::${text}`
  const cached = textMeasureCache.get(cacheKey)
  if (cached != null) {
    return cached
  }

  const context = getTextMeasureContext()
  if (context) {
    context.font = font
  }
  const width = context ? context.measureText(text).width : text.length * 14
  textMeasureCache.set(cacheKey, width)
  return width
}

function getAdaptiveColumnWidth(header: string) {
  const width = Math.ceil(measureTextWidth(header.trim() || '列', TABLE_HEADER_FONT)) + HEADER_WIDTH_PADDING
  return Math.min(Math.max(width, MIN_COLUMN_WIDTH), MAX_COLUMN_WIDTH)
}

function normalizeColumnWidthValue(value: unknown) {
  const numeric = Number(value)
  if (!Number.isFinite(numeric) || numeric <= 0) {
    return MIN_COLUMN_WIDTH
  }
  return Math.min(Math.max(Math.round(numeric), MIN_COLUMN_WIDTH), MAX_COLUMN_WIDTH)
}

function getColumnFontSizeFromConfig(config: SheetColumnConfig | undefined) {
  return normalizeColumnFontSize(config?.font_size)
}

function getColumnFontFamilyFromConfig(config: SheetColumnConfig | undefined) {
  return normalizeColumnFontFamily(config?.font_family)
}

function getContentFontFamilyCss(fontFamily: ColumnFontFamily) {
  return fontFamily === 'monospace' ? MONOSPACE_FONT_FAMILY : TABLE_FONT_FAMILY
}

function getColumnFontFamilyStyle(config: SheetColumnConfig | undefined) {
  const fontFamily = getColumnFontFamilyFromConfig(config)
  return fontFamily === 'default' ? '' : getContentFontFamilyCss(fontFamily)
}

function getCellFontFamilyStyle(fontFamily: CellFontFamily) {
  return getContentFontFamilyCss(fontFamily)
}

function getColumnCellFontFromSize(fontSize: number, fontFamily: ColumnFontFamily = 'default') {
  if (fontSize === DEFAULT_COLUMN_FONT_SIZE && fontFamily === 'default') {
    return TABLE_FONT
  }
  const resolvedFontSize = fontSize === DEFAULT_COLUMN_FONT_SIZE ? 14 : fontSize
  return `400 ${resolvedFontSize}px ${getContentFontFamilyCss(fontFamily)}`
}

function getColumnLineHeightFromFontSize(fontSize: number) {
  if (fontSize === DEFAULT_COLUMN_FONT_SIZE) {
    return TABLE_LINE_HEIGHT
  }
  return Math.max(TABLE_LINE_HEIGHT, Math.ceil(fontSize * 1.45))
}

function getAutoColumnWidth(
  columnIndex: number,
  headers = columnHeaders.value,
  sourceRows = rows.value,
  sourceConfigs: Record<string, SheetColumnConfig> = columnConfigs.value,
  sourceFormulaDisplayState?: FormulaDisplayState | null,
) {
  const header = headers[columnIndex] ?? createFallbackHeader(columnIndex)
  const columnConfig = sourceConfigs[header]
  const cellFont = getColumnCellFontFromSize(
    getColumnFontSizeFromConfig(columnConfig),
    getColumnFontFamilyFromConfig(columnConfig),
  )
  let width = getAdaptiveColumnWidth(header)
  const sampleLimit = Math.min(sourceRows.length, 40)
  let formulaDisplayForWidths = sourceFormulaDisplayState

  for (let rowIndex = 0; rowIndex < sampleLimit; rowIndex += 1) {
    const rawCellText = normalizeCellValue(sourceRows[rowIndex]?.[columnIndex] ?? '')
    if (isFormulaExpression(rawCellText) && formulaDisplayForWidths === undefined) {
      formulaDisplayForWidths = buildFormulaDisplayStateForRows(headers, sourceRows, sourceConfigs)
    }
    const cellText = getCellDisplayText(
      rowIndex,
      columnIndex,
      rawCellText,
      formulaDisplayForWidths ?? null,
      headers,
      sourceConfigs,
    ).trim()
    if (!cellText) {
      continue
    }
    width = Math.max(
      width,
      Math.min(
        Math.ceil(measureTextWidth(cellText, cellFont)) + HEADER_WIDTH_PADDING,
        MAX_COLUMN_WIDTH,
      ),
    )
  }

  return Math.min(Math.max(width, MIN_COLUMN_WIDTH), MAX_COLUMN_WIDTH)
}

function getEditingColumnInputWidth(title: string) {
  const width = Math.ceil(measureTextWidth(title || ' ', TABLE_HEADER_FONT)) + INLINE_HEADER_INPUT_PADDING
  return `${Math.min(Math.max(width, 32), MAX_COLUMN_WIDTH)}px`
}

function getEffectiveColumnWidth(columnIndex: number) {
  const hot = getHotInstance()
  const liveWidth = hot?.getColWidth(columnIndex)
  if (typeof liveWidth === 'number' && Number.isFinite(liveWidth) && liveWidth > 0) {
    return liveWidth
  }

  return columnWidths.value[columnIndex] ?? MIN_COLUMN_WIDTH
}

type ColumnWidthUpdateOptions = {
  refreshRowHeights?: boolean
  commitFixedWidth?: boolean
  commitAdaptiveWidth?: boolean
  save?: boolean
}

function setColumnWidthMode(columnIndex: number, widthMode: ColumnWidthMode) {
  if (!canEditConfig.value) {
    return false
  }

  const header = columnHeaders.value[columnIndex]
  if (!header) {
    return false
  }

  const currentNormalizedConfigs = normalizeColumnConfigs(columnConfigs.value, columnHeaders.value)
  const currentConfig = normalizeColumnConfig(currentNormalizedConfigs[header])
  if (currentConfig.width_mode === widthMode) {
    return false
  }

  const nextNormalizedConfigs = { ...currentNormalizedConfigs }
  const nextConfig = {
    ...currentConfig,
    width_mode: widthMode,
  }
  const storedConfig = createStoredColumnConfig(
    nextConfig,
    pickPreservedColumnConfig(currentNormalizedConfigs[header]),
  )
  if (storedConfig) {
    nextNormalizedConfigs[header] = storedConfig
  } else {
    delete nextNormalizedConfigs[header]
  }
  columnConfigs.value = nextNormalizedConfigs
  return true
}

function setColumnWidth(columnIndex: number, width: number, options: ColumnWidthUpdateOptions = {}) {
  if (columnIndex < 0 || columnIndex >= columnHeaders.value.length) {
    return
  }

  const nextWidth = normalizeColumnWidthValue(width)
  const currentWidth = normalizeColumnWidthValue(columnWidths.value[columnIndex] ?? getEffectiveColumnWidth(columnIndex))
  let changed = false
  const undoEntry = options.save ? createLocalUndoEntry('column-width') : null

  if (nextWidth !== currentWidth) {
    const nextWidths = [...columnWidths.value]
    nextWidths[columnIndex] = nextWidth
    columnWidths.value = nextWidths

    const hot = getHotInstance()
    if (hot) {
      hot.updateSettings({
        colWidths: [...nextWidths],
      })
      renderHotWithReason(hot, 'column-width-update')
    }
    changed = true
  }

  if (options.commitAdaptiveWidth) {
    changed = setColumnWidthMode(columnIndex, 'adaptive') || changed
  } else if (options.commitFixedWidth) {
    changed = setColumnWidthMode(columnIndex, 'fixed') || changed
  }

  if (!changed) {
    return
  }

  if (options.refreshRowHeights) {
    void refreshComputedRowHeights()
  }
  if (options.save) {
    pushLocalUndoEntry(undoEntry)
    const header = columnHeaders.value[columnIndex]
    const operations: NoteSheetPatchOperation[] = [{
      op: 'set-column-width',
      column_index: columnIndex,
      width: nextWidth,
    }]
    if (header) {
      operations.push({
        op: 'set-column-config',
        column_index: columnIndex,
        config: normalizeColumnConfigs(columnConfigs.value, columnHeaders.value)[header] ?? {},
      })
    }
    suppressNextRemoteSaveWatcher = true
    queueImmediateColumnConfigPatchSave(operations)
  }
}

function columnHasFormulaValue(columnIndex: number, sourceRows = rows.value) {
  return sourceRows.some((row) => isFormulaExpression(normalizeCellValue(row?.[columnIndex] ?? '')))
}

function refreshAdaptiveFormulaColumnWidths() {
  if (!formulaEngineClass.value || !columnHeaders.value.length) {
    return
  }

  const headers = normalizeHeaders(columnHeaders.value)
  const normalizedRows = rows.value.map((row) => normalizeRow(row, headers))
  const normalizedConfigs = normalizeColumnConfigs(columnConfigs.value, headers)
  const formulaDisplayForWidths = buildFormulaDisplayStateForRows(headers, normalizedRows, normalizedConfigs)
  const nextWidths = [...columnWidths.value]
  let changed = false

  headers.forEach((header, columnIndex) => {
    const columnConfig = normalizeColumnConfig(columnConfigs.value[header])
    if (columnConfig.width_mode !== 'adaptive' || !columnHasFormulaValue(columnIndex, normalizedRows)) {
      return
    }

    const nextWidth = getAutoColumnWidth(
      columnIndex,
      headers,
      normalizedRows,
      normalizedConfigs,
      formulaDisplayForWidths,
    )
    if (normalizeColumnWidthValue(nextWidths[columnIndex] ?? MIN_COLUMN_WIDTH) !== nextWidth) {
      nextWidths[columnIndex] = nextWidth
      changed = true
    }
  })

  if (!changed) {
    return
  }

  columnWidths.value = nextWidths
  refreshGridStructure()
  void refreshComputedRowHeights()
}

function getWrappedLineCount(text: string, availableWidth: number, font = TABLE_FONT) {
  if (!text) {
    return 1
  }

  if (!Number.isFinite(availableWidth) || availableWidth <= 0) {
    return 1
  }

  return text
    .split(/\r?\n/)
    .reduce((sum, segment) => {
      if (!segment) {
        return sum + 1
      }

      const normalizedSegment = segment.trim()
      if (!normalizedSegment) {
        return sum + 1
      }

      const containsCjk = /[\u3400-\u9FFF\uF900-\uFAFF]/.test(normalizedSegment)
      const containsWrapSeparator = /\s/.test(normalizedSegment)
      if (!containsCjk && !containsWrapSeparator) {
        return sum + 1
      }

      return sum + Math.max(1, Math.ceil(measureTextWidth(segment, font) / availableWidth))
    }, 0)
}

function resolveRowHeight(rowIndex: number) {
  const perfStart = getSheetPerfRenderCallbackStart()
  try {
    if (isSheetHeaderGridRow(rowIndex)) {
      if (rowIndex < normalizedHeaderGroups.value.length) {
        return 32
      }
      if (rowIndex === columnHeaderLevel.value) {
        return 36
      }
      return 92
    }

    const dataRowIndex = getDataRowIndex(rowIndex)
    const layoutState = rowHeightLayoutState.value
    if (!layoutState.hasWrappedColumns) {
      return layoutState.singleLineHeight
    }

    const row = rows.value[dataRowIndex] ?? []
    let maxContentHeight = layoutState.singleLineHeight - TABLE_CELL_VERTICAL_PADDING * 2 - TABLE_CELL_BORDER_WIDTH

    for (const columnLayout of layoutState.wrappedColumns) {
      const cellText = getCellTextForLayout(dataRowIndex, columnLayout.index, row[columnLayout.index] ?? '')
      if (!cellText) {
        maxContentHeight = Math.max(maxContentHeight, columnLayout.lineHeight)
        continue
      }

      const availableWidth = Math.max(
        getEffectiveColumnWidth(columnLayout.index) - TABLE_CELL_HORIZONTAL_PADDING * 2,
        12,
      )
      const cellFont = getColumnCellFontFromSize(columnLayout.fontSize, columnLayout.fontFamily)
      maxContentHeight = Math.max(
        maxContentHeight,
        getWrappedLineCount(cellText, availableWidth, cellFont) * columnLayout.lineHeight,
      )
    }

    return maxContentHeight + TABLE_CELL_VERTICAL_PADDING * 2 + TABLE_CELL_BORDER_WIDTH
  } finally {
    recordSheetPerfRenderCallback('rowHeight', perfStart)
  }
}

function resolveCoreRowHeight(rowIndex: number) {
  const perfStart = getSheetPerfRenderCallbackStart()
  try {
    if (isSheetHeaderGridRow(rowIndex)) {
      if (rowIndex < normalizedHeaderGroups.value.length) {
        return 32
      }
      if (rowIndex === columnHeaderLevel.value) {
        return 36
      }
      return 40
    }
    return rowHeightLayoutState.value.singleLineHeight
  } finally {
    recordSheetPerfRenderCallback('rowHeight', perfStart)
  }
}

function updateSheetViewportHeight(reason = 'unknown') {
  pendingSheetViewportHeightUpdateReasons.add(reason)
  if (pendingSheetViewportHeightUpdate) {
    return pendingSheetViewportHeightUpdate
  }
  pendingSheetViewportHeightUpdate = updateSheetViewportHeightNow(() => (
    Array.from(pendingSheetViewportHeightUpdateReasons).join('+') || 'unknown'
  )).finally(() => {
    pendingSheetViewportHeightUpdate = null
    pendingSheetViewportHeightUpdateReasons = new Set<string>()
  })
  return pendingSheetViewportHeightUpdate
}

async function updateSheetViewportHeightNow(getReason: () => string) {
  if (isSheetDocumentHidden()) {
    return
  }
  const perfStart = sheetPerfLoggingEnabled.value ? getSheetPerfNow() : 0
  const previousHeight = sheetViewportHeight.value
  const finishPerfLog = (
    nextHeight: number | 'auto',
    changed: boolean,
    rendered: boolean,
    detail: Record<string, unknown> = {},
  ) => {
    if (!perfStart) {
      return
    }
    const perfEnd = getSheetPerfNow()
    recordSheetPerfEvent('layout.viewportHeight', {
      duration: roundSheetPerfMs(perfEnd - perfStart),
      perfStart: roundSheetPerfMs(perfStart),
      perfEnd: roundSheetPerfMs(perfEnd),
      detail: {
        reason: getReason(),
        previousHeight,
        nextHeight,
        changed,
        rendered,
        ...detail,
      },
    })
  }

  await nextTick()

  const sheetFrame = sheetFrameRef.value
  if (!sheetFrame || props.sheetId == null || isContentHeightMode.value) {
    const changed = sheetViewportHeight.value !== 'auto'
    sheetViewportHeight.value = 'auto'
    if (changed) {
      renderCurrentHotWithReason('viewport-height-auto')
    }
    finishPerfLog('auto', changed, changed, {
      hasSheetFrame: !!sheetFrame,
      sheetId: props.sheetId,
      isContentHeightMode: isContentHeightMode.value,
    })
    return
  }

  const frameRect = sheetFrame.getBoundingClientRect()
  const containerHeight = Math.floor(sheetFrame.clientHeight || frameRect.height)
  const windowHeight = Math.floor(window.innerHeight || document.documentElement.clientHeight || 0)
  const viewportRemainingHeight = windowHeight > 0
    ? Math.floor(windowHeight - frameRect.top - SHEET_VIEWPORT_BOTTOM_GAP)
    : 0
  const availableHeight = viewportRemainingHeight > 0
    ? Math.min(containerHeight, viewportRemainingHeight)
    : containerHeight
  if (!Number.isFinite(availableHeight) || availableHeight <= 0) {
    finishPerfLog(previousHeight, false, false, {
      availableHeight,
      containerHeight,
      viewportRemainingHeight,
      windowHeight,
      frameTop: frameRect.top,
      frameClientHeight: sheetFrame.clientHeight,
      frameRectHeight: frameRect.height,
    })
    return
  }

  const changed = sheetViewportHeight.value !== availableHeight
  if (changed) {
    sheetViewportHeight.value = availableHeight
    renderCurrentHotWithReason('viewport-height-changed')
  }
  finishPerfLog(availableHeight, changed, changed, {
    containerHeight,
    viewportRemainingHeight,
    windowHeight,
    frameTop: frameRect.top,
    frameClientHeight: sheetFrame.clientHeight,
    frameRectHeight: frameRect.height,
  })
}

function handleWindowResize() {
  if (isSheetDocumentHidden()) {
    return
  }
  closeColumnNotePopover()
  scheduleRichTextInlineToolbarSync()
  updateRichTextContentEditorPosition()
  void updateSheetViewportHeight('windowResize')
}

function handleWindowScroll() {
  updateRichTextContentEditorPosition()
  scheduleRichTextInlineToolbarSync()
}

function handleSheetVisibilityChange() {
  if (isSheetDocumentHidden()) {
    sheetHiddenFrameSize = measureSheetFrameSize()
    if (sheetRenderEnhancementFrame != null || sheetRenderPhase.value !== 'ready') {
      finishSheetRenderEnhancement()
    }
    return
  }

  const previousFrameSize = sheetHiddenFrameSize
  sheetHiddenFrameSize = null
  const currentFrameSize = measureSheetFrameSize()
  if (previousFrameSize && currentFrameSize && !isSameSheetFrameSize(previousFrameSize, currentFrameSize)) {
    void updateSheetViewportHeight('visibilityRestore')
  }
}

function captureSheetScrollPosition() {
  const gridElement = sheetFrameRef.value?.querySelector('.ht_master .wtHolder') as HTMLElement | null
  const pageElement = getMainScrollContainer()
  return {
    gridLeft: gridElement?.scrollLeft ?? 0,
    gridTop: gridElement?.scrollTop ?? 0,
    pageLeft: pageElement?.scrollLeft ?? 0,
    pageTop: pageElement?.scrollTop ?? 0,
  }
}

function restoreSheetScrollPosition(position: ReturnType<typeof captureSheetScrollPosition>) {
  void nextTick(() => {
    const gridElement = sheetFrameRef.value?.querySelector('.ht_master .wtHolder') as HTMLElement | null
    const pageElement = getMainScrollContainer()
    if (gridElement) {
      gridElement.scrollLeft = position.gridLeft
      gridElement.scrollTop = position.gridTop
    }
    if (pageElement) {
      pageElement.scrollLeft = position.pageLeft
      pageElement.scrollTop = position.pageTop
    }
  })
}

function clearSheetOverlayAlignmentFrame() {
  if (sheetOverlayAlignmentFrame != null && typeof window !== 'undefined') {
    window.cancelAnimationFrame(sheetOverlayAlignmentFrame)
  }
  sheetOverlayAlignmentFrame = null
  sheetOverlayAlignmentPending = false
  if (sheetOverlayScrollSyncFrame != null && typeof window !== 'undefined') {
    window.cancelAnimationFrame(sheetOverlayScrollSyncFrame)
  }
  sheetOverlayScrollSyncFrame = null
}

function syncSheetOverlayScrollFromMaster() {
  const sheetFrame = sheetFrameRef.value
  const masterHolder = sheetFrame?.querySelector('.ht_master .wtHolder') as HTMLElement | null
  if (!sheetFrame || !masterHolder) {
    return
  }

  const { scrollLeft, scrollTop } = masterHolder
  const masterClientHeight = masterHolder.clientHeight
  sheetFrame.querySelectorAll<HTMLElement>('.ht_clone_top .wtHolder, .ht_clone_bottom .wtHolder')
    .forEach((holder) => {
      if (holder.scrollLeft !== scrollLeft) {
        holder.scrollLeft = scrollLeft
      }
    })
  sheetFrame.querySelectorAll<HTMLElement>('.ht_clone_inline_start .wtHolder, .ht_clone_left .wtHolder')
    .forEach((holder) => {
      if (masterClientHeight > 0 && holder.clientHeight !== masterClientHeight) {
        holder.style.height = `${masterClientHeight}px`
        holder.style.maxHeight = `${masterClientHeight}px`
      }
      if (holder.scrollTop !== scrollTop) {
        holder.scrollTop = scrollTop
      }
    })
}

function scheduleSheetOverlayScrollSyncFromMaster() {
  if (typeof window === 'undefined') {
    syncSheetOverlayScrollFromMaster()
    return
  }
  if (sheetOverlayScrollSyncFrame != null) {
    window.cancelAnimationFrame(sheetOverlayScrollSyncFrame)
  }
  sheetOverlayScrollSyncFrame = window.requestAnimationFrame(() => {
    sheetOverlayScrollSyncFrame = null
    syncSheetOverlayScrollFromMaster()
  })
}

function refreshSheetOverlayAlignment() {
  const hot = getHotInstance() as SheetHotWithInternalView | null
  if (!hot) {
    return
  }

  const view = hot.view
  const walkontable = view?._wt
  const overlays = walkontable?.wtOverlays
  try {
    syncSheetOverlayScrollFromMaster()
    view?.adjustElementsSize?.()
    overlays?.syncScrollPositions?.()
    overlays?.syncScrollWithMaster?.()
    overlays?.adjustElementsSize?.()
    overlays?.refresh?.(true)
    overlays?.refreshAll?.()
    walkontable?.draw?.(true)
    walkontable?.selectionManager?.refreshAllBorderHandleStyles?.()
    syncSheetOverlayScrollFromMaster()
    scheduleSheetOverlayScrollSyncFromMaster()
  } catch (error) {
    console.warn('Failed to align note sheet overlays:', error)
  }
}

function scheduleSheetOverlayAlignment() {
  if (sheetOverlayAlignmentPending) {
    return
  }
  sheetOverlayAlignmentPending = true
  void nextTick(() => {
    if (typeof window === 'undefined') {
      sheetOverlayAlignmentPending = false
      refreshSheetOverlayAlignment()
      return
    }
    sheetOverlayAlignmentFrame = window.requestAnimationFrame(() => {
      sheetOverlayAlignmentFrame = null
      sheetOverlayAlignmentPending = false
      refreshSheetOverlayAlignment()
      updateRichTextContentEditorPosition()
    })
  })
}

function shouldRealignOverlayForSelection(row: number, column: number) {
  if (row < 0 || column < 0) {
    return false
  }

  const merge = findMergedCellAtGridCell(row, column)
  return !!merge && (merge.rowspan > 1 || merge.colspan > 1)
}

function bindSheetLayoutObserver() {
  sheetLayoutObserver?.disconnect()
  sheetLayoutObserver = null

  if (typeof ResizeObserver === 'undefined') {
    return
  }

  const scrollContainer = getMainScrollContainer()
  if (!scrollContainer) {
    return
  }

  sheetLayoutObserver = new ResizeObserver(() => {
    if (isSheetDocumentHidden()) {
      return
    }
    void updateSheetViewportHeight('layoutResizeObserver')
  })
  sheetLayoutObserver.observe(scrollContainer)
}

function syncRowsFromGrid() {
  const hot = getHotInstance()
  if (!hot) {
    return rows.value
  }

  const sourceRows = hot.getSourceData() as unknown[]
  const currentHotGridRows = sheetHotGridRows.value
  if (
    sourceRows.length > currentHotGridRows.length
    && (workspaceLoading.value || suppressPersistence || sheetRenderPhase.value !== 'ready')
  ) {
    hot.loadData(currentHotGridRows)
    renderHotWithReason(hot, 'sync-rows-revert-during-load')
    return rows.value
  }
  rows.value = sourceRows
    .slice(sheetHeaderRowCount.value)
    .map((row) => normalizeRow(Array.isArray(row) ? row.slice(rowMarkerColumnCount.value) : row, columnHeaders.value))
  return rows.value
}

function refreshGridStructure() {
  const hot = getHotInstance()
  if (!hot) {
    return
  }

  updateHotSettingsWithMergeReset(hot, {
    colHeaders: sheetColumnHeaders.value,
    colWidths: [...sheetHotColumnWidths.value],
    rowHeaders: false,
    fixedRowsTop: sheetHeaderRowCount.value,
    fixedColumnsStart: fixedHotColumnsStart.value,
    hiddenColumns: {
      columns: [...hotHiddenColumnIndexes.value],
      indicators: false,
    },
    hiddenRows: {
      rows: [...sheetFilterHiddenRows.value],
      indicators: false,
    },
    ...getCurrentSheetHotRenderSettings(),
  })
  loadCurrentHotGridRows(hot)
  renderHotWithReason(hot, 'grid-structure-refresh')
}

function selectColumnMarker(columnIndex: number, extendSelection = false) {
  const hot = getHotInstance()
  if (!hot || columnIndex < 0 || columnIndex >= columnHeaders.value.length) {
    return false
  }

  clearEditingColumnState()
  closeColumnNotePopover()
  if (formulaBarFocused.value) {
    commitFormulaBarDraft()
  }
  clearSheetHeaderSelection()
  clearFormulaBarSelection()
  const anchor = extendSelection
    ? (columnMarkerSelectionAnchor ?? selectedColumnMarkerBounds.value?.start ?? columnIndex)
    : columnIndex
  const startColumn = Math.min(anchor, columnIndex)
  const endColumn = Math.max(anchor, columnIndex)
  const selected = startColumn === endColumn
    ? hot.selectColumns(toHotColumnIndex(startColumn))
    : hot.selectColumns(toHotColumnIndex(startColumn), toHotColumnIndex(endColumn))
  if (selected) {
    columnMarkerSelectionAnchor = anchor
  }
  hot.listen()
  syncColumnMarkerSelection()
  refreshContextMenuFallbackSelectionState()
  return selected
}

function normalizeMovedColumnIndexes(movedColumns: number[]) {
  return Array.from(new Set(
    movedColumns
      .filter((index) => Number.isInteger(index) && index >= 0 && index < columnHeaders.value.length),
  )).sort((left, right) => left - right)
}

function normalizeMovedRowIndexes(movedRows: number[]) {
  return Array.from(new Set(
    movedRows
      .map((index) => getDataRowIndex(index))
      .filter((index) => Number.isInteger(index) && index >= 0 && index < rows.value.length),
  )).sort((left, right) => left - right)
}

function countMoveFinalIndex(movedColumns: number[], dropIndex: number | undefined, fallbackFinalIndex: number) {
  if (dropIndex == null) {
    return fallbackFinalIndex
  }

  let lowerThanDropIndex = 0
  for (const columnIndex of movedColumns) {
    if (columnIndex < dropIndex) {
      lowerThanDropIndex += 1
    }
  }

  return dropIndex - lowerThanDropIndex
}

function getEffectiveMovedColumnsForDrag(movedColumns: number[]) {
  const normalizedMovedColumns = normalizeMovedColumnIndexes(movedColumns)
  const bounds = getSelectionColumnBounds()

  if (!bounds || bounds.start === bounds.end || isSelectedByCorner()) {
    return normalizedMovedColumns
  }

  if (!normalizedMovedColumns.length) {
    return normalizedMovedColumns
  }

  const selectionContainsDraggedColumn = normalizedMovedColumns.every((columnIndex) => (
    columnIndex >= bounds.start && columnIndex <= bounds.end
  ))
  if (!selectionContainsDraggedColumn) {
    return normalizedMovedColumns
  }

  return Array.from({ length: bounds.end - bounds.start + 1 }, (_, offset) => bounds.start + offset)
}

function getEffectiveMovedRowsForDrag(movedRows: number[]) {
  const normalizedMovedRows = normalizeMovedRowIndexes(movedRows)
  const bounds = getSelectionRowBounds()

  if (!bounds || bounds.start === bounds.end || isSelectedByCorner()) {
    return normalizedMovedRows
  }

  if (!normalizedMovedRows.length) {
    return normalizedMovedRows
  }

  const selectionContainsDraggedRow = normalizedMovedRows.every((rowIndex) => (
    rowIndex >= bounds.start && rowIndex <= bounds.end
  ))
  if (!selectionContainsDraggedRow) {
    return normalizedMovedRows
  }

  return Array.from({ length: bounds.end - bounds.start + 1 }, (_, offset) => bounds.start + offset)
}

function reorderItemsByMove<T>(items: T[], movedIndexes: number[], finalIndex: number) {
  if (!items.length || !movedIndexes.length) {
    return [...items]
  }

  const normalizedIndexes = Array.from(new Set(
    movedIndexes
      .filter((index) => Number.isInteger(index) && index >= 0 && index < items.length),
  )).sort((left, right) => left - right)

  if (!normalizedIndexes.length) {
    return [...items]
  }

  const movedIndexSet = new Set(normalizedIndexes)
  const movedItems = normalizedIndexes.map((index) => items[index] as T)
  const remainingItems = items.filter((_, index) => !movedIndexSet.has(index))
  const insertionIndex = Math.min(Math.max(finalIndex, 0), remainingItems.length)

  remainingItems.splice(insertionIndex, 0, ...movedItems)
  return remainingItems
}

function insertDataEntityRows(startIndex: number, amount: number) {
  if (amount <= 0) {
    return
  }
  const nextIds = [...dataRowEntityIds.value]
  nextIds.splice(
    Math.min(Math.max(startIndex, 0), nextIds.length),
    0,
    ...Array.from({ length: amount }, (_, offset) => (
      createSheetEntityId(`row_${getDocumentRowIndex(startIndex + offset)}`)
    )),
  )
  dataRowEntityIds.value = nextIds
}

function removeDataEntityRows(startIndex: number, amount: number) {
  if (amount <= 0) {
    return
  }
  const nextIds = [...dataRowEntityIds.value]
  const removedIds = nextIds.splice(Math.max(startIndex, 0), amount)
  dataRowEntityIds.value = nextIds
  if (!removedIds.length) {
    return
  }

  const removed = new Set(removedIds)
  const nextCells: SheetEntityCellMap = { ...entityCells.value }
  removed.forEach((rowId) => {
    delete nextCells[rowId]
  })
  entityCells.value = nextCells
}

function moveDataEntityRows(movedRows: number[], finalIndex: number) {
  dataRowEntityIds.value = reorderItemsByMove(dataRowEntityIds.value, movedRows, finalIndex)
}

function insertColumnEntityIds(startIndex: number, amount: number) {
  if (amount <= 0) {
    return
  }
  const nextIds = [...columnEntityIds.value]
  nextIds.splice(
    Math.min(Math.max(startIndex, 0), nextIds.length),
    0,
    ...Array.from({ length: amount }, (_, offset) => (
      createSheetEntityId(`col_${startIndex + offset}`)
    )),
  )
  columnEntityIds.value = nextIds
}

function removeColumnEntityIds(startIndex: number, amount: number) {
  if (amount <= 0) {
    return
  }
  const nextIds = [...columnEntityIds.value]
  const removedIds = nextIds.splice(Math.max(startIndex, 0), amount)
  columnEntityIds.value = nextIds
  if (!removedIds.length) {
    return
  }

  const removed = new Set(removedIds)
  const nextCells: SheetEntityCellMap = {}
  for (const [rowId, rowCells] of Object.entries(entityCells.value)) {
    const nextRowCells = { ...rowCells }
    removed.forEach((columnId) => {
      delete nextRowCells[columnId]
    })
    if (Object.keys(nextRowCells).length) {
      nextCells[rowId] = nextRowCells
    }
  }
  entityCells.value = nextCells
}

function moveColumnEntityIds(movedColumns: number[], finalIndex: number) {
  columnEntityIds.value = reorderItemsByMove(columnEntityIds.value, movedColumns, finalIndex)
}

function transformCellMetaPositions(
  source: SheetCellMetaMap,
  mapper: (position: { row: number; column: number }) => { row: number; column: number } | null,
) {
  const nextMeta: SheetCellMetaMap = {}
  for (const [key, meta] of Object.entries(source)) {
    const position = parseCellMetaKey(key)
    if (!position) {
      continue
    }

    const nextPosition = mapper(position)
    if (!nextPosition || nextPosition.row < 0 || nextPosition.column < 0) {
      continue
    }
    nextMeta[createCellMetaKey(nextPosition.row, nextPosition.column)] = meta
  }
  return normalizeCellMetaMap(nextMeta, columnHeaders.value.length)
}

function shiftCellMetaRows(startDocumentRow: number, amount: number) {
  if (amount === 0) {
    return
  }

  cellMeta.value = transformCellMetaPositions(cellMeta.value, ({ row, column }) => ({
    row: row >= startDocumentRow ? row + amount : row,
    column,
  }))
}

function removeCellMetaRows(startDocumentRow: number, amount: number) {
  if (amount <= 0) {
    return
  }
  const endDocumentRow = startDocumentRow + amount

  cellMeta.value = transformCellMetaPositions(cellMeta.value, ({ row, column }) => {
    if (row >= startDocumentRow && row < endDocumentRow) {
      return null
    }
    return {
      row: row >= endDocumentRow ? row - amount : row,
      column,
    }
  })
}

function shiftCellMetaColumns(startColumn: number, amount: number) {
  if (amount === 0) {
    return
  }

  cellMeta.value = transformCellMetaPositions(cellMeta.value, ({ row, column }) => ({
    row,
    column: column >= startColumn ? column + amount : column,
  }))
}

function removeCellMetaColumns(startColumn: number, amount: number) {
  if (amount <= 0) {
    return
  }
  const endColumn = startColumn + amount

  cellMeta.value = transformCellMetaPositions(cellMeta.value, ({ row, column }) => {
    if (column >= startColumn && column < endColumn) {
      return null
    }
    return {
      row,
      column: column >= endColumn ? column - amount : column,
    }
  })
}

function normalizeCurrentMergedCells(
  source = mergedCells.value,
  rowCount = getMergedCellsDocumentRowCount(),
  columnCount = columnHeaders.value.length,
) {
  return normalizeMergedCells(source, rowCount, columnCount)
}

function insertMergedCellRows(startRow: number, amount: number) {
  if (amount <= 0) {
    return
  }
  mergedCells.value = normalizeCurrentMergedCells(mergedCells.value.map((cell) => {
    if (cell.row < startRow && startRow < cell.row + cell.rowspan) {
      return { ...cell, rowspan: cell.rowspan + amount }
    }
    return cell.row >= startRow ? { ...cell, row: cell.row + amount } : cell
  }), getMergedCellsDocumentRowCount() + amount)
}

function removeMergedCellRows(startRow: number, amount: number) {
  if (amount <= 0) {
    return
  }
  const endRow = startRow + amount
  mergedCells.value = normalizeCurrentMergedCells(mergedCells.value.map((cell) => {
    const cellEnd = cell.row + cell.rowspan
    if (cellEnd <= startRow) {
      return cell
    }
    if (cell.row >= endRow) {
      return { ...cell, row: cell.row - amount }
    }
    const overlap = Math.min(cellEnd, endRow) - Math.max(cell.row, startRow)
    const nextRowspan = cell.rowspan - Math.max(0, overlap)
    const nextRow = cell.row >= startRow ? startRow : cell.row
    return { ...cell, row: nextRow, rowspan: nextRowspan }
  }).filter((cell) => cell.rowspan > 1 || cell.colspan > 1))
}

function insertDocumentGridRows(startDocumentRow: number, amount: number) {
  if (amount <= 0) {
    return
  }
  shiftCellMetaRows(startDocumentRow, amount)
  insertMergedCellRows(startDocumentRow, amount)
}

function removeDocumentGridRows(startDocumentRow: number, amount: number) {
  if (amount <= 0) {
    return
  }
  removeCellMetaRows(startDocumentRow, amount)
  removeMergedCellRows(startDocumentRow, amount)
}

function remapDocumentAnchorsForHeaderRowCountChange(previousHeaderRowCount: number, nextHeaderRowCount: number) {
  const delta = nextHeaderRowCount - previousHeaderRowCount
  if (delta === 0) {
    return
  }

  if (delta > 0) {
    insertDocumentGridRows(previousHeaderRowCount, delta)
    return
  }

  removeDocumentGridRows(nextHeaderRowCount, -delta)
}

function insertMergedCellColumns(startColumn: number, amount: number) {
  if (amount <= 0) {
    return
  }
  mergedCells.value = normalizeCurrentMergedCells(mergedCells.value.map((cell) => {
    if (cell.col < startColumn && startColumn < cell.col + cell.colspan) {
      return { ...cell, colspan: cell.colspan + amount }
    }
    return cell.col >= startColumn ? { ...cell, col: cell.col + amount } : cell
  }), getMergedCellsDocumentRowCount(), columnHeaders.value.length + amount)
}

function removeMergedCellColumns(startColumn: number, amount: number) {
  if (amount <= 0) {
    return
  }
  const endColumn = startColumn + amount
  mergedCells.value = normalizeCurrentMergedCells(mergedCells.value.map((cell) => {
    const cellEnd = cell.col + cell.colspan
    if (cellEnd <= startColumn) {
      return cell
    }
    if (cell.col >= endColumn) {
      return { ...cell, col: cell.col - amount }
    }
    const overlap = Math.min(cellEnd, endColumn) - Math.max(cell.col, startColumn)
    const nextColspan = cell.colspan - Math.max(0, overlap)
    const nextCol = cell.col >= startColumn ? startColumn : cell.col
    return { ...cell, col: nextCol, colspan: nextColspan }
  }).filter((cell) => cell.rowspan > 1 || cell.colspan > 1))
}

function buildMoveIndexMap(length: number, movedIndexes: number[], finalIndex: number) {
  const sourceIndexes = Array.from({ length }, (_, index) => index)
  const nextOrder = reorderItemsByMove(sourceIndexes, movedIndexes, finalIndex)
  const indexMap = new Map<number, number>()
  nextOrder.forEach((sourceIndex, nextIndex) => {
    indexMap.set(sourceIndex, nextIndex)
  })
  return indexMap
}

function remapRowsWithFormulaReferenceMaps(
  sourceRows: SheetRow[],
  rowIndexMap?: Map<number, number>,
  columnIndexMap?: Map<number, number>,
) {
  const headers = columnHeaders.value
  const nextRows = Array.from({ length: sourceRows.length }, () => createEmptyRow(headers.length))

  const headerRowCount = sheetHeaderRowCount.value
  const pageStart = getDocumentRowIndex(0)
  const pageEnd = pageStart + sourceRows.length
  const formulaRowIndexMapper = rowIndexMap
    ? (rowIndex: number) => {
        if (rowIndex < headerRowCount) {
          return rowIndex
        }
        const documentDataRowIndex = rowIndex - headerRowCount
        if (documentDataRowIndex < pageStart || documentDataRowIndex >= pageEnd) {
          return rowIndex
        }
        const localDataRowIndex = documentDataRowIndex - pageStart
        return headerRowCount + pageStart + (rowIndexMap.get(localDataRowIndex) ?? localDataRowIndex)
      }
    : undefined

  sourceRows.forEach((row, sourceRowIndex) => {
    const normalizedRow = normalizeRow(row, headers)
    const targetRowIndex = rowIndexMap?.get(sourceRowIndex) ?? sourceRowIndex
    if (targetRowIndex < 0 || targetRowIndex >= nextRows.length) {
      return
    }

    normalizedRow.forEach((cellValue, sourceColumnIndex) => {
      const targetColumnIndex = columnIndexMap?.get(sourceColumnIndex) ?? sourceColumnIndex
      if (targetColumnIndex < 0 || targetColumnIndex >= headers.length) {
        return
      }

      nextRows[targetRowIndex][targetColumnIndex] = remapFormulaCellReferences(
        cellValue,
        formulaRowIndexMapper,
        columnIndexMap ? (columnIndex) => columnIndexMap.get(columnIndex) ?? columnIndex : undefined,
      )
    })
  })

  return nextRows
}

function remapFormulaReferencesInRows(
  rowIndexMapper?: (rowIndex: number) => number | null,
  columnIndexMapper?: (columnIndex: number) => number | null,
) {
  if (!rowIndexMapper && !columnIndexMapper) {
    return rows.value
  }

  let changed = false
  const headers = columnHeaders.value
  const headerRowCount = sheetHeaderRowCount.value
  const formulaRowIndexMapper = rowIndexMapper
    ? (rowIndex: number) => {
        if (rowIndex < headerRowCount) {
          return rowIndex
        }
        const documentDataRowIndex = rowIndex - headerRowCount
        const nextDocumentDataRowIndex = rowIndexMapper(documentDataRowIndex)
        return nextDocumentDataRowIndex == null ? null : headerRowCount + nextDocumentDataRowIndex
      }
    : undefined
  const nextRows = rows.value.map((row, rowIndex) => (
    normalizeRow(row, headers).map((cellValue, columnIndex) => {
      if (!isFormulaExpression(cellValue)) {
        return cellValue
      }

      const nextValue = remapFormulaCellReferences(cellValue, formulaRowIndexMapper, columnIndexMapper)
      if (nextValue !== cellValue) {
        changed = true
      }
      return nextValue
    })
  ))

  if (!changed) {
    return rows.value
  }

  rows.value = nextRows
  loadCurrentHotGridRows(getHotInstance())
  return nextRows
}

function moveCellMetaColumns(movedColumns: number[], finalIndex: number) {
  const indexMap = buildMoveIndexMap(columnHeaders.value.length, movedColumns, finalIndex)
  cellMeta.value = transformCellMetaPositions(cellMeta.value, ({ row, column }) => ({
    row,
    column: indexMap.get(column) ?? column,
  }))
}

function moveCellMetaRows(movedRows: number[], finalIndex: number) {
  const pageStart = sheetHeaderRowCount.value + getDocumentRowIndex(0)
  const indexMap = buildMoveIndexMap(rows.value.length, movedRows, finalIndex)
  const pageEnd = pageStart + rows.value.length

  cellMeta.value = transformCellMetaPositions(cellMeta.value, ({ row, column }) => {
    if (row < pageStart || row >= pageEnd) {
      return { row, column }
    }
    const localRow = row - pageStart
    return {
      row: pageStart + (indexMap.get(localRow) ?? localRow),
      column,
    }
  })
}

function canMoveMergedCellsColumns(movedColumns: number[]) {
  const moved = new Set(movedColumns)
  return normalizeCurrentMergedCells().every((cell) => {
    let touched = 0
    for (let column = cell.col; column < cell.col + cell.colspan; column += 1) {
      if (moved.has(column)) {
        touched += 1
      }
    }
    return touched === 0 || touched === cell.colspan
  })
}

function moveMergedCellsColumns(movedColumns: number[], finalIndex: number) {
  const indexMap = buildMoveIndexMap(columnHeaders.value.length, movedColumns, finalIndex)
  mergedCells.value = normalizeCurrentMergedCells(mergedCells.value.map((cell) => {
    const mappedColumns = Array.from({ length: cell.colspan }, (_, offset) => indexMap.get(cell.col + offset) ?? cell.col + offset)
      .sort((left, right) => left - right)
    return { ...cell, col: mappedColumns[0] ?? cell.col }
  }))
}

function canMoveMergedCellsRows(movedRows: number[]) {
  const pageStart = sheetHeaderRowCount.value + getDocumentRowIndex(0)
  const moved = new Set(movedRows.map((row) => pageStart + row))
  return normalizeCurrentMergedCells().every((cell) => {
    let touched = 0
    for (let row = cell.row; row < cell.row + cell.rowspan; row += 1) {
      if (moved.has(row)) {
        touched += 1
      }
    }
    return touched === 0 || touched === cell.rowspan
  })
}

function moveMergedCellsRows(movedRows: number[], finalIndex: number) {
  const pageStart = sheetHeaderRowCount.value + getDocumentRowIndex(0)
  const indexMap = buildMoveIndexMap(rows.value.length, movedRows, finalIndex)
  mergedCells.value = normalizeCurrentMergedCells(mergedCells.value.map((cell) => {
    if (cell.row < pageStart || cell.row >= pageStart + rows.value.length) {
      return cell
    }
    const mappedRows = Array.from({ length: cell.rowspan }, (_, offset) => {
      const localRow = cell.row + offset - pageStart
      return pageStart + (indexMap.get(localRow) ?? localRow)
    }).sort((left, right) => left - right)
    return { ...cell, row: mappedRows[0] ?? cell.row }
  }))
}

function moveDataRowsToFinalIndex(movedRows: number[], finalIndex: number, reason = 'row-move') {
  const effectiveMovedRows = normalizeMovedRowIndexes(movedRows.map((row) => getGridRowIndex(row)))
  const effectiveFinalIndex = Math.min(Math.max(finalIndex, 0), rows.value.length - effectiveMovedRows.length)
  const effectiveMovePossible = (
    effectiveMovedRows.length > 0
    && effectiveFinalIndex >= 0
    && effectiveFinalIndex + effectiveMovedRows.length <= rows.value.length
    && canMoveMergedCellsRows(effectiveMovedRows)
  )

  if (!effectiveMovePossible) {
    return false
  }

  const rowIndexMap = buildMoveIndexMap(rows.value.length, effectiveMovedRows, effectiveFinalIndex)
  const orderChanged = Array.from({ length: rows.value.length }, (_, index) => index)
    .some((index) => (rowIndexMap.get(index) ?? index) !== index)
  if (!orderChanged) {
    return false
  }

  const nextRows = remapRowsWithFormulaReferenceMaps(rows.value, rowIndexMap)

  pushLocalUndoSnapshot(reason)
  clearEditingColumnState()
  moveDataEntityRows(effectiveMovedRows, effectiveFinalIndex)
  moveCellMetaRows(effectiveMovedRows, effectiveFinalIndex)
  moveMergedCellsRows(effectiveMovedRows, effectiveFinalIndex)
  rows.value = nextRows
  const movedRangeStart = effectiveFinalIndex
  const movedRangeEnd = effectiveFinalIndex + effectiveMovedRows.length - 1
  const hot = getHotInstance()
  if (hot) {
    loadCurrentHotGridRows(hot)
    renderHotWithReason(hot, 'row-move')
    void nextTick(() => {
      hot.selectRows(getGridRowIndex(movedRangeStart), getGridRowIndex(movedRangeEnd))
    })
  }
  void refreshComputedRowHeights()

  return true
}

function remapVisiblePageCellMetaRows(rowIndexMap: Map<number, number>) {
  const pageStart = sheetHeaderRowCount.value + getDocumentRowIndex(0)
  const pageEnd = pageStart + rows.value.length
  cellMeta.value = transformCellMetaPositions(cellMeta.value, ({ row, column }) => {
    if (row < pageStart || row >= pageEnd) {
      return { row, column }
    }
    const localRow = row - pageStart
    return {
      row: pageStart + (rowIndexMap.get(localRow) ?? localRow),
      column,
    }
  })
}

function handleBeforeColumnMove(
  movedColumns: number[],
  finalIndex: number,
  dropIndex: number | undefined,
  movePossible: boolean,
) {
  if (!canEditConfig.value) {
    return false
  }

  if (movedColumns.some((column) => isRowMarkerHotColumn(column))) {
    return false
  }

  const movedSheetColumns = movedColumns.map((column) => toSheetColumnIndex(column))
  const sheetFinalIndex = Math.max(0, toSheetColumnIndex(finalIndex))
  const sheetDropIndex = dropIndex == null ? undefined : Math.max(0, toSheetColumnIndex(dropIndex))
  const effectiveMovedColumns = getEffectiveMovedColumnsForDrag(movedSheetColumns)
  const effectiveFinalIndex = countMoveFinalIndex(effectiveMovedColumns, sheetDropIndex, sheetFinalIndex)
  const effectiveMovePossible = (
    movePossible
    && effectiveMovedColumns.length > 0
    && effectiveFinalIndex >= 0
    && effectiveFinalIndex + effectiveMovedColumns.length <= columnHeaders.value.length
    && canMoveMergedCellsColumns(effectiveMovedColumns)
  )

  if (!effectiveMovePossible) {
    return false
  }

  const nextHeaders = reorderItemsByMove(columnHeaders.value, effectiveMovedColumns, effectiveFinalIndex)
  const nextWidths = reorderItemsByMove(columnWidths.value, effectiveMovedColumns, effectiveFinalIndex)
  const columnIndexMap = buildMoveIndexMap(columnHeaders.value.length, effectiveMovedColumns, effectiveFinalIndex)
  const nextRows = remapRowsWithFormulaReferenceMaps(rows.value, undefined, columnIndexMap)

  const headersChanged = nextHeaders.some((header, index) => header !== columnHeaders.value[index])
  if (!headersChanged) {
    return false
  }

  pushLocalUndoSnapshot('column-move')
  clearEditingColumnState()
  moveColumnEntityIds(effectiveMovedColumns, effectiveFinalIndex)
  moveCellMetaColumns(effectiveMovedColumns, effectiveFinalIndex)
  moveMergedCellsColumns(effectiveMovedColumns, effectiveFinalIndex)
  columnHeaders.value = nextHeaders
  columnWidths.value = nextWidths
  rows.value = nextRows
  columnConfigs.value = normalizeColumnConfigs(columnConfigs.value, nextHeaders)
  const movedRangeStart = effectiveFinalIndex
  const movedRangeEnd = effectiveFinalIndex + effectiveMovedColumns.length - 1
  const hot = getHotInstance()
  if (hot) {
    updateHotSettingsWithMergeReset(hot, {
      colHeaders: sheetColumnHeaders.value,
      colWidths: [...sheetHotColumnWidths.value],
      fixedRowsTop: sheetHeaderRowCount.value,
      fixedColumnsStart: fixedHotColumnsStart.value,
      mergeCells: sheetHotRenderMergeCells.value,
    })
    loadCurrentHotGridRows(hot)
    renderHotWithReason(hot, 'column-move')
    void nextTick(() => {
      hot.selectColumns(toHotColumnIndex(movedRangeStart), toHotColumnIndex(movedRangeEnd))
    })
  } else {
    refreshGridStructure()
  }
  void refreshComputedRowHeights()

  return false
}

function handleBeforeRowMove(
  movedRows: number[],
  finalIndex: number,
  dropIndex: number | undefined,
  movePossible: boolean,
) {
  if (!canEditData.value) {
    return false
  }

  const effectiveMovedRows = getEffectiveMovedRowsForDrag(movedRows)
  const dataFinalIndex = Math.max(0, getDataRowIndex(finalIndex))
  const dataDropIndex = dropIndex == null ? undefined : Math.max(0, getDataRowIndex(dropIndex))
  const effectiveFinalIndex = countMoveFinalIndex(effectiveMovedRows, dataDropIndex, dataFinalIndex)
  const effectiveMovePossible = (
    movePossible
    && effectiveMovedRows.length > 0
    && effectiveFinalIndex >= 0
    && effectiveFinalIndex + effectiveMovedRows.length <= rows.value.length
    && canMoveMergedCellsRows(effectiveMovedRows)
  )

  if (!effectiveMovePossible) {
    return false
  }

  moveDataRowsToFinalIndex(effectiveMovedRows, effectiveFinalIndex, 'row-move')

  return false
}

function focusEditingColumnInput(select = true) {
  void nextTick(() => {
    const input = editingHeaderInputEl
    if (!input) {
      return
    }
    input.focus()
    if (select) {
      input.select()
    }
  })
}

function startInlineRenameColumn(columnIndex: number) {
  if (!ensureCanEditConfig()) {
    return
  }

  if (columnIndex < 0 || columnIndex >= columnHeaders.value.length) {
    return
  }

  editingColumnIndex.value = columnIndex
  editingColumnTitle.value = columnHeaders.value[columnIndex] ?? createFallbackHeader(columnIndex)
  refreshGridStructure()
  focusEditingColumnInput()
}

function commitInlineRenameColumn() {
  if (!canEditConfig.value) {
    clearEditingColumnState()
    refreshGridStructure()
    return
  }

  const columnIndex = editingColumnIndex.value
  if (columnIndex == null || columnIndex < 0 || columnIndex >= columnHeaders.value.length) {
    clearEditingColumnState()
    return
  }

  const currentHeader = columnHeaders.value[columnIndex] ?? createFallbackHeader(columnIndex)
  const nextHeader = editingColumnTitle.value.trim()

  if (nextHeader === currentHeader) {
    clearEditingColumnState()
    refreshGridStructure()
    return
  }

  if (!renameColumnHeaderAtIndex(columnIndex, nextHeader, { focusOnInvalid: true })) {
    return
  }

  clearEditingColumnState()
  refreshGridStructure()
}

function renameColumnHeaderAtIndex(
  columnIndex: number,
  nextHeaderSource: string,
  options: { focusOnInvalid?: boolean } = {},
) {
  if (columnIndex < 0 || columnIndex >= columnHeaders.value.length) {
    return false
  }

  const currentHeader = columnHeaders.value[columnIndex] ?? createFallbackHeader(columnIndex)
  const nextHeader = nextHeaderSource.trim()

  if (!nextHeader) {
    ElMessage.warning('字段名不能为空')
    if (options.focusOnInvalid) {
      focusEditingColumnInput()
    }
    return false
  }

  if (columnHeaders.value.some((header, index) => index !== columnIndex && header === nextHeader)) {
    ElMessage.warning('字段名不能重复')
    if (options.focusOnInvalid) {
      focusEditingColumnInput()
    }
    return false
  }

  if (nextHeader === currentHeader) {
    return false
  }

  const nextHeaders = [...columnHeaders.value]
  nextHeaders[columnIndex] = nextHeader
  columnHeaders.value = nextHeaders
  const nextWidths = [...columnWidths.value]
  nextWidths[columnIndex] = Math.max(nextWidths[columnIndex] ?? MIN_COLUMN_WIDTH, getAdaptiveColumnWidth(nextHeader))
  columnWidths.value = nextWidths

  const nextConfigs = { ...columnConfigs.value }
  const currentConfig = nextConfigs[currentHeader]
  delete nextConfigs[currentHeader]
  if (currentConfig) {
    nextConfigs[nextHeader] = { ...currentConfig }
  }
  columnConfigs.value = nextConfigs
  return true
}

function setColumnNoteAtIndex(columnIndex: number, nextNoteSource: string) {
  const header = columnHeaders.value[columnIndex]
  if (!header) {
    return false
  }

  const nextNote = normalizeColumnNote(nextNoteSource)
  const currentNote = getColumnNote(columnIndex)
  if (nextNote === currentNote) {
    return false
  }

  const nextConfigs = { ...columnConfigs.value }
  const nextConfig: SheetColumnConfig = { ...(nextConfigs[header] ?? {}) }
  if (nextNote) {
    nextConfig.note = nextNote
  } else {
    delete nextConfig.note
  }
  nextConfigs[header] = nextConfig
  const previousHeaderRowCount = sheetHeaderRowCount.value
  const normalizedNextConfigs = normalizeColumnConfigs(nextConfigs, columnHeaders.value)
  const willHaveColumnNoteEntityRow = hasColumnNoteEntityRow.value || nextNote !== ''
  const nextHeaderRowCount = getSheetHeaderRowCountForColumnNoteEntity(willHaveColumnNoteEntityRow)
  const nextRows = remapRowsFormulaReferencesForHeaderRowCountChange(
    rows.value,
    previousHeaderRowCount,
    nextHeaderRowCount,
  )
  columnConfigs.value = normalizedNextConfigs
  if (nextRows !== rows.value) {
    rows.value = nextRows
  }
  remapDocumentAnchorsForHeaderRowCountChange(previousHeaderRowCount, nextHeaderRowCount)
  if (willHaveColumnNoteEntityRow) {
    materializeColumnNotePrefixRow({ [columnIndex]: nextNote })
  }
  return true
}

function setHeaderGroupLabelAtGridCell(rowIndex: number, columnIndex: number, nextLabelSource: string) {
  if (rowIndex < 0 || rowIndex >= normalizedHeaderGroups.value.length || columnIndex < 0) {
    return false
  }

  const nextGroups = normalizedHeaderGroups.value.map((row) => row.map((cell) => ({ ...cell })))
  const row = nextGroups[rowIndex]
  if (!row) {
    return false
  }

  let startColumn = 0
  for (let cellIndex = 0; cellIndex < row.length; cellIndex += 1) {
    const cell = row[cellIndex]
    const colspan = Math.max(1, cell.colspan ?? 1)
    const endColumn = startColumn + colspan - 1
    if (columnIndex >= startColumn && columnIndex <= endColumn) {
      const nextLabel = normalizeCellValue(nextLabelSource)
      if (nextLabel === cell.label) {
        return false
      }
      row[cellIndex] = { ...cell, label: nextLabel }
      headerGroups.value = normalizeHeaderGroups(nextGroups, columnHeaders.value.length)
      return true
    }
    startColumn += colspan
  }

  return false
}

function applySheetHeaderGridChange(gridRowIndex: number, columnIndex: number, nextValue: unknown) {
  if (columnIndex < 0 || !isSheetHeaderGridRow(gridRowIndex)) {
    return false
  }

  const textValue = normalizeCellValue(nextValue)
  const clearRichTextAfterChange = (changed: boolean) => {
    if (changed) {
      const documentRow = getDocumentGridRowIndex(gridRowIndex)
      if (isFormulaExpression(textValue)) {
        clearCellRichTextFormat(documentRow, columnIndex)
      } else {
        clearCellRichText(documentRow, columnIndex)
      }
    }
    return changed
  }
  if (gridRowIndex < normalizedHeaderGroups.value.length) {
    return clearRichTextAfterChange(setHeaderGroupLabelAtGridCell(gridRowIndex, columnIndex, textValue))
  }
  if (gridRowIndex === columnHeaderLevel.value) {
    return clearRichTextAfterChange(renameColumnHeaderAtIndex(columnIndex, textValue))
  }
  if (gridRowIndex === columnNoteHeaderLevel.value) {
    return clearRichTextAfterChange(setColumnNoteAtIndex(columnIndex, textValue))
  }
  return false
}

function cancelInlineRenameColumn() {
  clearEditingColumnState()
  refreshGridStructure()
}

function isManualColumnResizerMouseTarget(event: MouseEvent) {
  const target = event.target
  return target instanceof Element && !!target.closest('.manualColumnResizer')
}

function isSheetCellActionButtonMouseTarget(event: MouseEvent) {
  const target = event.target
  return target instanceof Element && !!target.closest('.sheet-cell-action-button-inner')
}

function shouldTriggerSheetCellActionFromMouseEvent(event: MouseEvent) {
  return isSheetCellActionButtonMouseTarget(event) || touchContextMenuFallbackEnabled.value
}

function normalizeHotSelectionRange(value: unknown): SheetSelectionRange | null {
  if (!Array.isArray(value) || value.length < 4) {
    return null
  }
  const range = value.slice(0, 4).map((item) => Number(item))
  return range.every((item) => Number.isInteger(item))
    ? range as SheetSelectionRange
    : null
}

function shouldDeferCellSelectionForDrag(event: MouseEvent) {
  return (
    touchContextMenuFallbackEnabled.value
    && event.button === 0
    && !event.ctrlKey
    && !event.metaKey
    && !isFormulaReferencePickMode()
    && !formulaReferenceRangeState
  )
}

function disableNativeCellSelection(controller?: CellMouseSelectionController) {
  if (controller) {
    controller.row = false
    controller.column = false
    controller.cell = false
  }
}

function stopNativeCellSelectionForDeferredDrag(
  event: MouseEvent,
  controller?: CellMouseSelectionController,
) {
  disableNativeCellSelection(controller)
  event.stopImmediatePropagation()
}

function isCellLinkOpenMouseEvent(event: MouseEvent) {
  return event.button === 0 && (event.ctrlKey || event.metaKey) && !event.altKey
}

function clearFormulaReferenceInteractionState() {
  finishFormulaReferenceRange()
  clearFormulaReferencePreviewRange()
  clearFormulaReferenceReplacementSpan()
  clearFormulaReferencePointerDownReset()
  formulaReferencePointerDown = false
}

function clearCellLinkOpenPointerGuard() {
  window.removeEventListener('mousemove', handleCellLinkOpenPointerGuardEvent, true)
  window.removeEventListener('mouseover', handleCellLinkOpenPointerGuardEvent, true)
  window.removeEventListener('mouseup', handleCellLinkOpenPointerGuardMouseUp)
  window.removeEventListener('click', handleCellLinkOpenPointerGuardEvent, true)
  if (cellLinkOpenPointerGuardTimer != null) {
    window.clearTimeout(cellLinkOpenPointerGuardTimer)
    cellLinkOpenPointerGuardTimer = null
  }
  cellLinkOpenPointerGuardActive = false
  cellLinkOpenPendingLink = null
  cellLinkOpenPendingCompleted = false
}

function completePendingCellLinkOpen() {
  if (!cellLinkOpenPointerGuardActive || cellLinkOpenPendingCompleted || !cellLinkOpenPendingLink) {
    return
  }

  const link = cellLinkOpenPendingLink
  cellLinkOpenPendingCompleted = true
  openCellLink(link)
}

function handleCellLinkOpenPointerGuardEvent(event: MouseEvent) {
  if (!cellLinkOpenPointerGuardActive) {
    return
  }

  event.preventDefault()
  event.stopImmediatePropagation()
  if (event.type === 'click') {
    completePendingCellLinkOpen()
    clearCellLinkOpenPointerGuard()
  }
}

function handleCellLinkOpenPointerGuardMouseUp(event: MouseEvent) {
  if (!cellLinkOpenPointerGuardActive) {
    return
  }

  event.preventDefault()
  completePendingCellLinkOpen()
  if (cellLinkOpenPointerGuardTimer != null) {
    window.clearTimeout(cellLinkOpenPointerGuardTimer)
  }
  cellLinkOpenPointerGuardTimer = window.setTimeout(() => {
    clearCellLinkOpenPointerGuard()
  }, 250)
}

function beginCellLinkOpenPointerGuard(link: SheetCellLink) {
  clearCellLinkOpenPointerGuard()
  cellLinkOpenPointerGuardActive = true
  cellLinkOpenPendingLink = link
  cellLinkOpenPendingCompleted = false
  window.addEventListener('mousemove', handleCellLinkOpenPointerGuardEvent, true)
  window.addEventListener('mouseover', handleCellLinkOpenPointerGuardEvent, true)
  window.addEventListener('mouseup', handleCellLinkOpenPointerGuardMouseUp)
  window.addEventListener('click', handleCellLinkOpenPointerGuardEvent, true)
  cellLinkOpenPointerGuardTimer = window.setTimeout(() => {
    clearCellLinkOpenPointerGuard()
  }, 1200)
}

function selectCellForLinkOpen(gridRowIndex: number, columnIndex: number) {
  const hotColumn = toHotColumnIndex(columnIndex)
  if (gridRowIndex < 0 || hotColumn < 0) {
    return
  }

  clearFormulaReferenceInteractionState()
  if (formulaBarFocused.value) {
    commitFormulaBarDraft()
    blurFormulaBarInput()
  }

  const editor = getActiveOpenedEditor()
  if (editor && typeof editor.finishEditing === 'function') {
    editor.finishEditing(false)
  }

  const applySelection = () => {
    const hot = getHotInstance()
    if (hot && !hot.isDestroyed) {
      hot.selectCell(gridRowIndex, hotColumn, gridRowIndex, hotColumn, true, false)
      hot.listen()
    } else {
      setFormulaBarGridCell(gridRowIndex, columnIndex)
    }
    syncColumnMarkerSelection()
    refreshContextMenuFallbackSelectionState()
  }

  applySelection()
  window.setTimeout(applySelection, 0)
}

function openCellLinkFromMouseEvent(
  event: MouseEvent,
  controller: CellMouseSelectionController,
  link: SheetCellLink | null,
  gridRowIndex: number,
  columnIndex: number,
) {
  if (!link || !isCellLinkOpenMouseEvent(event)) {
    return false
  }

  disableNativeCellSelection(controller)
  event.preventDefault()
  event.stopImmediatePropagation()
  selectCellForLinkOpen(gridRowIndex, columnIndex)
  beginCellLinkOpenPointerGuard(link)
  return true
}

function clearDeferredCellSelectionState() {
  window.removeEventListener('mousemove', handleDeferredCellSelectionPointerMove, true)
  window.removeEventListener('mouseup', handleDeferredCellSelectionWindowMouseUp)
  deferredCellSelectionState = null
}

function markDeferredCellSelectionDragFromPoint(clientX: number, clientY: number) {
  const state = deferredCellSelectionState
  if (!state || state.dragged) {
    return
  }
  const distance = Math.hypot(clientX - state.startX, clientY - state.startY)
  if (distance >= DEFERRED_CELL_SELECTION_DRAG_THRESHOLD_PX) {
    state.dragged = true
  }
}

function handleDeferredCellSelectionPointerMove(event: MouseEvent) {
  markDeferredCellSelectionDragFromPoint(event.clientX, event.clientY)
}

function restoreSelectionBeforeDeferredCellDrag(state: DeferredCellSelectionState) {
  const hot = getHotInstance()
  if (hot && state.previousSelection) {
    hot.selectCell(
      state.previousSelection[0],
      state.previousSelection[1],
      state.previousSelection[2],
      state.previousSelection[3],
      true,
      false,
    )
  } else {
    hot?.deselectCell?.()
  }
  formulaBarCell.value = state.previousFormulaBarCell
    ? { ...state.previousFormulaBarCell }
    : null
  selectedSheetHeaderCell.value = state.previousSheetHeaderCell
    ? { ...state.previousSheetHeaderCell }
    : null
  syncFormulaBarDraftFromSelectedCell(true)
  refreshContextMenuFallbackSelectionState()
}

function selectDeferredCell(row: number, hotColumn: number) {
  const column = toSheetColumnIndex(hotColumn)
  if (row < 0 || column < 0) {
    return
  }

  const anchor = getMergeAnchorForGridCell(row, column)
  const hot = getHotInstance()
  if (hot) {
    hot.selectCell(anchor.row, toHotColumnIndex(anchor.column), anchor.row, toHotColumnIndex(anchor.column), true, false)
    hot.listen()
  } else {
    setFormulaBarGridCell(anchor.row, anchor.column)
  }
}

function finishDeferredCellSelectionFromCell(event: MouseEvent, coords: { row: number; col: number }) {
  const state = deferredCellSelectionState
  if (!state) {
    return false
  }

  markDeferredCellSelectionDragFromPoint(event.clientX, event.clientY)
  const isSameCell = coords.row === state.startRow && coords.col === state.startHotColumn
  clearDeferredCellSelectionState()

  if (!state.dragged && isSameCell) {
    selectDeferredCell(state.startRow, state.startHotColumn)
  } else {
    restoreSelectionBeforeDeferredCellDrag(state)
  }

  event.stopImmediatePropagation()
  return true
}

function handleDeferredCellSelectionWindowMouseUp() {
  const state = deferredCellSelectionState
  if (!state) {
    return
  }
  clearDeferredCellSelectionState()
  if (state.dragged) {
    restoreSelectionBeforeDeferredCellDrag(state)
  } else {
    selectDeferredCell(state.startRow, state.startHotColumn)
  }
}

function beginDeferredCellSelectionForDrag(event: MouseEvent, coords: { row: number; col: number }) {
  const previousFormulaBarCell = formulaBarCell.value ? { ...formulaBarCell.value } : null
  const previousSheetHeaderCell = selectedSheetHeaderCell.value ? { ...selectedSheetHeaderCell.value } : null
  deferredCellSelectionState = {
    startRow: coords.row,
    startHotColumn: coords.col,
    startX: event.clientX,
    startY: event.clientY,
    dragged: false,
    previousSelection: normalizeHotSelectionRange(getHotInstance()?.getSelectedLast()),
    previousFormulaBarCell,
    previousSheetHeaderCell,
  }
  window.addEventListener('mousemove', handleDeferredCellSelectionPointerMove, true)
  window.addEventListener('mouseup', handleDeferredCellSelectionWindowMouseUp)
}

function handleBeforeCellMouseDown(
  event: MouseEvent,
  coords: { row: number; col: number },
  _td: HTMLTableCellElement,
  controller: CellMouseSelectionController,
) {
  markSheetPerfInput({
    kind: 'mouse',
    row: coords.row,
    hotColumn: coords.col,
    button: event.button,
  })

  if (coords.row < 0) {
    return
  }

  if (coords.col < 0) {
    return
  }

  if (shouldPreserveSelectionForContextPointer(event, coords.row, coords.col)) {
    disableNativeCellSelection(controller)
    event.stopImmediatePropagation()
    return
  }

  if (isRowMarkerHotColumn(coords.col)) {
    event.preventDefault()
    event.stopImmediatePropagation()
    if (controller) {
      controller.row = false
      controller.column = false
      controller.cell = false
    }
    clearSheetHeaderSelection()
    clearFormulaBarSelection()
    selectRowFromMarker(coords.row, event.shiftKey)
    return
  }

  const column = toSheetColumnIndex(coords.col)
  if (column < 0) {
    return
  }

  const anchor = getMergeAnchorForGridCell(coords.row, column)

  if (isSheetHeaderGridRow(coords.row) && isManualColumnResizerMouseTarget(event)) {
    return
  }

  const sheetCellAction = event.button === 0
    ? getSheetCellActionAtDocumentCell(anchor.documentRow, anchor.column)
    : null
  if (sheetCellAction && shouldTriggerSheetCellActionFromMouseEvent(event)) {
    disableNativeCellSelection(controller)
    triggerSheetCellActionButtonFromEvent(event, sheetCellAction, {
      documentRow: anchor.documentRow,
      column: anchor.column,
    })
    return
  }

  if (isSheetHeaderGridRow(coords.row)) {
    const headerLevel = getSheetHeaderGridLevel(anchor.row)
    const headerLink = headerLevel === columnHeaderLevel.value
      ? getCellLinkAt(anchor.documentRow, anchor.column) ?? getColumnHeaderLink(anchor.column)
      : null
    if (openCellLinkFromMouseEvent(event, controller, headerLink, anchor.row, anchor.column)) {
      return
    }

    if (
      event.button === 0
      && insertFormulaReferenceText(getCellReferenceLabelForSheetRow(anchor.documentRow, anchor.column))
    ) {
      markFormulaReferencePointerDown()
      stopFormulaReferenceCellSelection(event, controller)
      return
    }

    if (shouldDeferCellSelectionForDrag(event)) {
      beginDeferredCellSelectionForDrag(event, coords)
      stopNativeCellSelectionForDeferredDrag(event, controller)
      return
    }
    selectedSheetHeaderCell.value = { column: anchor.column, headerLevel }
    return
  }

  clearSheetHeaderSelection()
  if (event.button !== 0) {
    return
  }

  const dataRow = getDataRowIndex(anchor.row)
  if (dataRow < 0) {
    return
  }
  if (shouldDeferCellSelectionForDrag(event)) {
    beginDeferredCellSelectionForDrag(event, coords)
    stopNativeCellSelectionForDeferredDrag(event, controller)
    return
  }
  const link = getCellLinkAt(anchor.documentRow, anchor.column)
  if (openCellLinkFromMouseEvent(event, controller, link, anchor.row, anchor.column)) {
    return
  }
  if (beginFormulaReferenceRange(dataRow, anchor.column)) {
    stopFormulaReferenceCellSelection(event, controller)
    return
  }
}

function handleBeforeCellMouseOver(
  event: MouseEvent,
  coords: { row: number; col: number },
  _td: HTMLTableCellElement,
  controller: CellMouseSelectionController,
) {
  if (cellLinkOpenPointerGuardActive) {
    disableNativeCellSelection(controller)
    event.preventDefault()
    event.stopImmediatePropagation()
    return
  }

  if (deferredCellSelectionState) {
    if (
      coords.row !== deferredCellSelectionState.startRow
      || coords.col !== deferredCellSelectionState.startHotColumn
    ) {
      deferredCellSelectionState.dragged = true
    }
    markDeferredCellSelectionDragFromPoint(event.clientX, event.clientY)
    stopNativeCellSelectionForDeferredDrag(event, controller)
    return
  }

  if (!formulaReferenceRangeState || coords.row < 0 || coords.col < 0) {
    return
  }
  const column = toSheetColumnIndex(coords.col)
  if (column < 0) {
    return
  }
  const dataRow = getDataRowIndex(coords.row)
  if (dataRow < 0) {
    return
  }

  if (event.buttons !== 1) {
    finishFormulaReferenceRange({ restoreFocus: true })
    return
  }

  updateFormulaReferenceRange(dataRow, column)
  stopFormulaReferenceCellSelection(event, controller)
}

function handleBeforeCellMouseUp(
  event: MouseEvent,
  coords: { row: number; col: number },
  _td: HTMLTableCellElement,
  controller: CellMouseSelectionController,
) {
  if (cellLinkOpenPointerGuardActive) {
    disableNativeCellSelection(controller)
    event.preventDefault()
    return
  }

  if (finishDeferredCellSelectionFromCell(event, coords)) {
    return
  }

  if (!formulaReferenceRangeState) {
    return
  }

  if (coords.row >= 0 && coords.col >= 0) {
    const column = toSheetColumnIndex(coords.col)
    const dataRow = getDataRowIndex(coords.row)
    if (dataRow >= 0 && column >= 0) {
      updateFormulaReferenceRange(dataRow, column)
    }
  }
  finishFormulaReferenceRange({ restoreFocus: true })
  event.preventDefault()
}

function handleHeaderMouseDown(event: MouseEvent, coords: { row: number; col: number }) {
  const column = coords.col >= 0 ? toSheetColumnIndex(coords.col) : -1
  const dataRow = coords.row >= 0 ? getDataRowIndex(coords.row) : -1
  if (dataRow >= 0 && column >= 0 && event.button === 0 && isFormulaReferencePickMode()) {
    markFormulaReferencePointerDown()
    return
  }

  clearSheetHeaderSelection()
}

function applyHeaderCellStyle(
  column: number,
  th: HTMLTableHeaderCellElement,
  headerLevel: number,
  explicitCellStyle: SheetCellStyle | null = null,
) {
  th.style.removeProperty('background-color')
  th.style.removeProperty('color')
  th.style.removeProperty('font-weight')

  if (column < 0 || headerLevel < 0) {
    return
  }

  if (isRegistrationStandardUserIdHeaderColumn(column, headerLevel)) {
    th.style.setProperty('background-color', REGISTRATION_STANDARD_USER_ID_HEADER_BACKGROUND, 'important')
    th.style.setProperty('font-weight', '600')
    return
  }

  if (explicitCellStyle?.background_color || explicitCellStyle?.text_color) {
    if (explicitCellStyle.background_color) {
      th.style.setProperty('background-color', explicitCellStyle.background_color, 'important')
    }
    if (explicitCellStyle.text_color) {
      th.style.setProperty('color', explicitCellStyle.text_color, 'important')
    }
    th.style.setProperty('font-weight', '600')
    return
  }

  const baseStyle = nestedHeaderStyleRows.value[headerLevel]?.[column] ?? null
  const style = headerLevel === columnHeaderLevel.value
    ? resolveGridFieldHeaderStyle(column, baseStyle)
    : baseStyle
  if (!style) {
    return
  }

  if (style.background_color) {
    th.style.setProperty('background-color', style.background_color, 'important')
  }
  if (style.text_color) {
    th.style.setProperty('color', style.text_color, 'important')
  }
  if (style.background_color || style.text_color) {
    th.style.setProperty('font-weight', '600')
  }
}

function applyCellMetaStyle(TD: HTMLTableCellElement, style: SheetCellStyle | null) {
  if (style?.background_color) {
    TD.style.setProperty('background-color', style.background_color, 'important')
  }
  if (style?.text_color) {
    TD.style.setProperty('color', style.text_color, 'important')
  }
  if (style?.font_family) {
    TD.style.setProperty('font-family', getCellFontFamilyStyle(style.font_family), 'important')
  }
  if (style?.font_size) {
    TD.style.setProperty('font-size', `${style.font_size}px`, 'important')
    TD.style.setProperty('line-height', `${getColumnLineHeightFromFontSize(style.font_size)}px`, 'important')
  }
  if (style?.text_align) {
    TD.style.setProperty('text-align', style.text_align, 'important')
  }
  if (style?.vertical_align) {
    TD.style.setProperty('vertical-align', style.vertical_align, 'important')
  }
}

function resetRenderedCellState(TD: HTMLTableCellElement) {
  TD.classList.remove(
    'htDimmed',
    'sheet-cell-has-link',
    'sheet-cell-has-action',
    'sheet-cell-formula',
    'sheet-cell-formula-error',
    'sheet-cell-formula-reference-preview',
    'sheet-cell-single-line',
    'sheet-cell-wrap',
    'sheet-freeze-column-boundary',
    'sheet-freeze-row-boundary',
    'sheet-row-marker-cell',
    'sheet-grid-header-cell',
    'sheet-grid-group-header-cell',
    'sheet-grid-field-header-cell',
    'sheet-grid-field-header-cell-filtered',
    'sheet-grid-note-header-cell',
  )
  TD.style.removeProperty('background-color')
  TD.style.removeProperty('color')
  TD.style.removeProperty('font-family')
  TD.style.removeProperty('font-size')
  TD.style.removeProperty('font-weight')
  TD.style.removeProperty('line-height')
  TD.style.removeProperty('text-align')
  TD.style.removeProperty('vertical-align')
  if (TD.dataset.hyperlinkUrl) {
    delete TD.dataset.hyperlinkUrl
  }
  if (TD.dataset.sheetRowMarker) {
    delete TD.dataset.sheetRowMarker
  }
  if (TD.title) {
    TD.removeAttribute('title')
  }
  TD.onmousedown = null
}

function renderFieldHeaderCell(TD: HTMLTableCellElement, column: number) {
  const headerTitle = columnHeaders.value[column] ?? createFallbackHeader(column)
  if (editingColumnIndex.value !== column) {
    if (editingHeaderInputEl && editingHeaderInputEl.closest('td') === TD) {
      editingHeaderInputEl = null
    }
    TD.textContent = ''
    const label = document.createElement('span')
    label.className = 'sheet-header-label'
    const cellStyle = getCellStyleAt(getDocumentGridRowIndex(columnHeaderLevel.value), column)
    if (cellStyle?.text_align === 'left') {
      label.style.justifyContent = 'flex-start'
    } else if (cellStyle?.text_align === 'right') {
      label.style.justifyContent = 'flex-end'
    } else if (cellStyle?.text_align === 'center') {
      label.style.justifyContent = 'center'
    }

    const titleEl = document.createElement('span')
    titleEl.className = 'sheet-header-title'
    titleEl.textContent = headerTitle
    const note = getColumnNote(column)
    const headerLink = getCellLinkAt(getDocumentGridRowIndex(columnHeaderLevel.value), column) ?? getColumnHeaderLink(column)
    if (headerLink) {
      TD.classList.add('sheet-cell-has-link')
      TD.dataset.hyperlinkUrl = headerLink.url
      titleEl.classList.add('has-link')
      titleEl.dataset.hyperlinkUrl = headerLink.url
    }
    if (note && columnNoteDisplayMode.value === 'hover') {
      const title = headerLink ? `${note}\n${headerLink.url}` : note
      titleEl.setAttribute('aria-label', title)
      label.addEventListener('mouseenter', () => {
        openColumnNotePopover(column, label.getBoundingClientRect())
      })
      label.addEventListener('mouseleave', () => {
        closeColumnNotePopover()
      })
    } else if (headerLink) {
      titleEl.title = headerLink.url
      titleEl.setAttribute('aria-label', headerLink.url)
      TD.title = headerLink.url
    }
    label.appendChild(titleEl)
    if (isColumnFilterEnabled(column)) {
      const filterButton = document.createElement('button')
      filterButton.type = 'button'
      filterButton.className = 'sheet-header-filter-button'
      filterButton.classList.toggle('is-active', isColumnFilterActive(column))
      filterButton.title = isColumnFilterActive(column) ? '筛选已生效' : '筛选'
      filterButton.setAttribute('aria-label', `${headerTitle} 筛选`)
      filterButton.innerHTML = '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M2.5 3.5h11L9.2 8.4v3.2l-2.4 1.1V8.4L2.5 3.5Z"/></svg>'
      filterButton.addEventListener('mousedown', (event) => {
        event.stopPropagation()
      })
      filterButton.addEventListener('click', (event) => {
        event.preventDefault()
        event.stopPropagation()
        closeColumnNotePopover()
        openColumnFilterPopover(column, filterButton.getBoundingClientRect())
      })
      label.appendChild(filterButton)
    }
    TD.appendChild(label)
    return
  }

  const currentInput = TD.querySelector('.sheet-header-rename-input') as HTMLInputElement | null
  if (currentInput) {
    currentInput.value = editingColumnTitle.value
    currentInput.style.width = getEditingColumnInputWidth(editingColumnTitle.value)
    editingHeaderInputEl = currentInput
    return
  }

  TD.textContent = ''
  const input = document.createElement('input')
  input.className = 'sheet-header-rename-input'
  input.value = editingColumnTitle.value
  input.style.width = getEditingColumnInputWidth(editingColumnTitle.value)
  input.setAttribute('maxlength', '120')
  input.addEventListener('input', () => {
    editingColumnTitle.value = input.value
    input.style.width = getEditingColumnInputWidth(editingColumnTitle.value)
  })
  input.addEventListener('click', (event) => event.stopPropagation())
  input.addEventListener('mousedown', (event) => event.stopPropagation())
  input.addEventListener('dblclick', (event) => event.stopPropagation())
  input.addEventListener('keydown', (event) => {
    if (event.key === 'Enter') {
      event.preventDefault()
      commitInlineRenameColumn()
      return
    }
    if (event.key === 'Escape') {
      event.preventDefault()
      cancelInlineRenameColumn()
    }
  })
  input.addEventListener('blur', () => {
    commitInlineRenameColumn()
  })
  TD.appendChild(input)
  editingHeaderInputEl = input
  focusEditingColumnInput()
}

function renderRowMarkerCell(TD: HTMLTableCellElement, row: number) {
  resetRenderedCellState(TD)
  TD.classList.add('sheet-row-marker-cell')
  TD.classList.toggle('sheet-freeze-row-boundary', isFreezeRowBoundary(row))
  TD.dataset.sheetRowMarker = String(row)
  TD.onmousedown = (event) => {
    if (event.button !== 0 && event.button !== 2) {
      return
    }
    if (shouldPreserveSelectionForContextPointer(event, row, 0)) {
      return
    }
    clearSheetHeaderSelection()
    clearFormulaBarSelection()
    if (!selectRowFromMarker(row, event.shiftKey)) {
      return
    }
    if (event.button === 0) {
      event.preventDefault()
      event.stopPropagation()
    }
  }
  setRenderedCellText(TD, getSheetRowHeaderLabel(row))
}

function renderSheetHeaderGridCell(TD: HTMLTableCellElement, row: number, column: number, value: string) {
  resetRenderedCellState(TD)
  TD.classList.add('sheet-grid-header-cell')
  applyFreezePaneBoundaryClasses(TD, row, column)
  TD.dataset.sheetHeaderLevel = String(row)
  TD.dataset.sheetHeaderColumn = String(column)

  const documentRow = getDocumentGridRowIndex(row)
  const formulaCell = isFormulaExpression(value)
    ? getFormulaCellModelAtGridRow(row, column)
    : null
  const formulaText = formulaCell?.text ?? null
  const action = getCellActionAt(documentRow, column)
  if (action) {
    if (row < normalizedHeaderGroups.value.length) {
      TD.classList.add('sheet-grid-group-header-cell')
    } else if (row === columnHeaderLevel.value) {
      TD.classList.add('sheet-grid-field-header-cell')
    } else {
      TD.classList.add('sheet-grid-note-header-cell')
    }
    TD.classList.add('sheet-cell-has-action')
    const cellStyle = getCellStyleAt(documentRow, column)
    applyHeaderCellStyle(column, TD as unknown as HTMLTableHeaderCellElement, row, cellStyle)
    applyCellMetaStyle(TD, cellStyle)
    renderCellActionButton(TD, getCellActionDisplayLabel(action, value), action, {
      documentRow,
      column,
    }, value)
    const actionTitle = getCellActionTitle(action)
    if (actionTitle) {
      TD.title = actionTitle
    }
    return
  }

  if (row < normalizedHeaderGroups.value.length) {
    TD.classList.add('sheet-grid-group-header-cell')
    const cellStyle = getCellStyleAt(documentRow, column)
    applyHeaderCellStyle(column, TD as unknown as HTMLTableHeaderCellElement, row, cellStyle)
    applyCellMetaStyle(TD, cellStyle)
    const link = getCellLinkAt(documentRow, column)
    if (link) {
      TD.classList.add('sheet-cell-has-link')
      TD.dataset.hyperlinkUrl = link.url
      TD.title = link.url
    }
    const richText = formulaText == null ? getCellRichTextAt(documentRow, column, value) : null
    if (richText) {
      renderRichTextCell(TD, value, richText)
    } else {
      setRenderedCellText(TD, formulaText ?? value)
    }
    TD.classList.toggle('sheet-cell-formula', formulaText != null)
    TD.classList.toggle('sheet-cell-formula-error', formulaText != null && (isFormulaErrorValue(formulaCell?.value) || formulaCell.text.startsWith('#')))
    return
  }

  if (row === columnHeaderLevel.value) {
    TD.classList.add('sheet-grid-field-header-cell')
    TD.classList.toggle('sheet-grid-field-header-cell-filtered', isColumnFilterActive(column))
    const cellStyle = getCellStyleAt(documentRow, column)
    applyHeaderCellStyle(column, TD as unknown as HTMLTableHeaderCellElement, row, cellStyle)
    applyCellMetaStyle(TD, cellStyle)
    renderFieldHeaderCell(TD, column)
    return
  }

  TD.classList.add('sheet-grid-note-header-cell')
  const note = value || (hasMaterializedColumnNoteRow.value ? '' : getColumnNote(column))
  const renderedNote = formulaText ?? note
  applyCellMetaStyle(TD, getCellStyleAt(documentRow, column))
  const link = getCellLinkAt(documentRow, column)
  if (link) {
    TD.classList.add('sheet-cell-has-link')
    TD.dataset.hyperlinkUrl = link.url
  }
  const richText = formulaText == null ? getCellRichTextAt(documentRow, column, note) : null
  if (richText) {
    renderRichTextCell(TD, note, richText)
  } else {
    setRenderedCellText(TD, renderedNote)
  }
  TD.classList.toggle('sheet-cell-formula', formulaText != null)
  TD.classList.toggle('sheet-cell-formula-error', formulaText != null && (isFormulaErrorValue(formulaCell?.value) || formulaCell.text.startsWith('#')))
  if (link) {
    TD.title = link.url
  }
}

function renderCoreSheetHeaderGridCell(TD: HTMLTableCellElement, row: number, column: number, value: string) {
  resetRenderedCellState(TD)
  TD.classList.add('sheet-grid-header-cell')
  if (row < normalizedHeaderGroups.value.length) {
    TD.classList.add('sheet-grid-group-header-cell')
  } else if (row === columnHeaderLevel.value) {
    TD.classList.add('sheet-grid-field-header-cell')
  } else {
    TD.classList.add('sheet-grid-note-header-cell')
  }
  applyFreezePaneBoundaryClasses(TD, row, column)
  TD.dataset.sheetHeaderLevel = String(row)
  TD.dataset.sheetHeaderColumn = String(column)
  setRenderedCellText(TD, value)
}

function handleAfterGetColHeader(hotColumn: number, th: HTMLTableHeaderCellElement, headerLevel: number) {
  th.classList.remove(
    'sheet-col-marker',
    'sheet-row-marker-col-header',
    'sheet-column-marker-header-selected',
    'sheet-freeze-column-boundary',
  )
  th.classList.add('sheet-col-marker')
  if (hotColumn < 0) {
    th.dataset.sheetHeaderColumn = ''
    return
  }
  if (isRowMarkerHotColumn(hotColumn)) {
    th.classList.add('sheet-row-marker-col-header')
    th.dataset.sheetHeaderColumn = ''
    return
  }
  const column = toSheetColumnIndex(hotColumn)
  th.dataset.sheetHeaderColumn = String(column)
  th.classList.toggle('sheet-column-marker-header-selected', isColumnMarkerSelected(column))
  th.classList.toggle('sheet-freeze-column-boundary', isFreezeColumnBoundary(column))
  if (column < 0) {
    return
  }
}

function handleAfterGetRowHeader(row: number, th: HTMLTableHeaderCellElement) {
  th.classList.toggle('sheet-freeze-row-boundary', isFreezeRowBoundary(row))
}

function getColumnMarkerLabel(index: number) {
  return sheetViewSettings.value.column_marker_style === 'numbers'
    ? String(index + 1)
    : getExcelColumnLabel(index)
}

function areSheetViewSettingsEqual(left: SheetViewSettings, right: SheetViewSettings) {
  const normalizedLeft = normalizeSheetViewSettings(left)
  const normalizedRight = normalizeSheetViewSettings(right)
  return (
    normalizedLeft.show_row_numbers === normalizedRight.show_row_numbers
    && normalizedLeft.row_marker_numbering === normalizedRight.row_marker_numbering
    && normalizedLeft.row_marker_origin === normalizedRight.row_marker_origin
    && normalizedLeft.show_column_markers === normalizedRight.show_column_markers
    && normalizedLeft.column_marker_style === normalizedRight.column_marker_style
    && normalizedLeft.column_note_display === normalizedRight.column_note_display
    && normalizedLeft.height_mode === normalizedRight.height_mode
    && normalizedLeft.mobile_default_view === normalizedRight.mobile_default_view
    && normalizedLeft.frozen_column_count === normalizedRight.frozen_column_count
    && normalizedLeft.pagination.enabled === normalizedRight.pagination.enabled
    && normalizedLeft.pagination.page_size === normalizedRight.pagination.page_size
  )
}

function createColumnFilterEnabledDraft(
  headers = columnHeaders.value,
  sourceConfigs: Record<string, SheetColumnConfig> = columnConfigs.value,
) {
  return Object.fromEntries(headers.map((header) => [
    header,
    normalizeColumnConfig(sourceConfigs[header]).filter_enabled,
  ]))
}

function setSheetSettingsAllColumnFilters(enabled: boolean) {
  sheetSettingsColumnFilterDraft.value = Object.fromEntries(
    columnHeaders.value.map((header) => [header, enabled]),
  )
}

function buildColumnConfigsWithFilterDraft(
  sourceConfigs: Record<string, SheetColumnConfig>,
  headers: string[],
  filterDraft: Record<string, boolean>,
) {
  const normalizedConfigs = normalizeColumnConfigs(sourceConfigs, headers)
  const nextConfigs: Record<string, SheetColumnConfig> = { ...normalizedConfigs }
  for (const header of headers) {
    const currentConfig = normalizeColumnConfig(normalizedConfigs[header])
    currentConfig.filter_enabled = filterDraft[header] === true
    const preservedConfig = pickPreservedColumnConfig(normalizedConfigs[header])
    const storedConfig = createStoredColumnConfig(currentConfig, preservedConfig)
    if (storedConfig) {
      nextConfigs[header] = storedConfig
    } else {
      delete nextConfigs[header]
    }
  }
  return normalizeColumnConfigs(nextConfigs, headers)
}

function createDefinedNameDraftRow(
  item?: Partial<NoteSheetDefinedNameItem>,
  fallbackScopeKey: DefinedNameScopeKey = getCurrentDefinedNameWorksheetScopeKey(),
): DefinedNameDraftRow {
  return {
    key: `${Date.now()}-${Math.random().toString(36).slice(2)}`,
    scopeKey: item?.scope === 'workbook' ? 'workbook' : fallbackScopeKey,
    name: normalizeCellValue(item?.name).trim(),
    formula: normalizeDefinedNameFormula(item?.formula),
    comment: normalizeCellValue(item?.comment).trim(),
  }
}

function refreshDefinedNameDraftRows() {
  const worksheetRows = definedNameWorksheetScopes.value.flatMap((scope) => (
    normalizeDefinedNameItems(scope.names, 'worksheet')
      .map((item) => createDefinedNameDraftRow(item, getDefinedNameWorksheetScopeKey(scope.sheet_id)))
  ))
  definedNameDraftRows.value = [
    ...normalizeDefinedNameItems(workbookDefinedNames.value, 'workbook')
      .map((item) => createDefinedNameDraftRow(item, 'workbook')),
    ...worksheetRows,
  ]
}

async function openDefinedNamesDialog() {
  if (props.sheetId == null) {
    return
  }
  if (!ensureCanEditConfig()) {
    return
  }

  definedNamesDialogVisible.value = true
  definedNamesError.value = ''
  definedNamesLoading.value = true
  try {
    const response = props.workbookId != null
      ? await fetchWorkbookDefinedNames(props.workbookId)
      : await fetchSheetDefinedNames(props.sheetId, { workbookId: props.workbookId })
    syncDefinedNamesFromResponse(response)
  } catch (error) {
    definedNamesError.value = '名称管理器加载失败'
    console.warn('Failed to load defined names:', error)
  } finally {
    definedNamesLoading.value = false
    refreshDefinedNameDraftRows()
  }
}

function closeDefinedNamesDialog() {
  definedNamesDialogVisible.value = false
}

function addDefinedNameDraftRow(scope: 'workbook' | 'worksheet' = 'workbook') {
  const scopeKey = scope === 'workbook' ? 'workbook' : getCurrentDefinedNameWorksheetScopeKey()
  definedNameDraftRows.value = [
    ...definedNameDraftRows.value,
    createDefinedNameDraftRow({ scope }, scopeKey),
  ]
}

function removeDefinedNameDraftRow(index: number) {
  definedNameDraftRows.value = definedNameDraftRows.value.filter((_, rowIndex) => rowIndex !== index)
}

function validateDefinedNameDraftRows() {
  const scopedNames = new Map<string, Set<string>>()
  const workbookNames: NoteSheetDefinedNameItem[] = []
  const worksheetNamesBySheetId = new Map<number, NoteSheetDefinedNameItem[]>()
  definedNameWorksheetScopes.value.forEach((scope) => {
    worksheetNamesBySheetId.set(scope.sheet_id, [])
  })
  for (const row of definedNameDraftRows.value) {
    const name = normalizeCellValue(row.name).trim()
    const formula = normalizeDefinedNameFormula(row.formula)
    const comment = normalizeCellValue(row.comment).trim()
    const scopeKey = row.scopeKey === 'workbook' ? 'workbook' : row.scopeKey
    const sheetId = parseDefinedNameWorksheetScopeKey(scopeKey)
    if (!name && !formula && !comment) {
      continue
    }
    if (scopeKey !== 'workbook' && sheetId == null) {
      return { error: '请选择具体的工作表作用域' }
    }
    if (!name) {
      return { error: '名称不能为空' }
    }
    if (!isDefinedNameValid(name)) {
      return { error: `名称不合法：${name}` }
    }
    if (!formula) {
      return { error: `公式不能为空：${name}` }
    }
    const key = name.toLowerCase()
    const namesInScope = scopedNames.get(scopeKey) ?? new Set<string>()
    if (namesInScope.has(key)) {
      return { error: `同一作用域内名称重复：${name}` }
    }
    namesInScope.add(key)
    scopedNames.set(scopeKey, namesInScope)
    const item = {
      name,
      formula,
      comment,
      scope: scopeKey === 'workbook' ? 'workbook' : 'worksheet',
    } satisfies NoteSheetDefinedNameItem
    if (scopeKey === 'workbook') {
      workbookNames.push(item)
    } else if (sheetId != null) {
      const names = worksheetNamesBySheetId.get(sheetId) ?? []
      names.push(item)
      worksheetNamesBySheetId.set(sheetId, names)
    }
  }
  return { workbookNames, worksheetNamesBySheetId }
}

async function applyDefinedNamesDialog() {
  if (props.sheetId == null || !ensureCanEditConfig()) {
    closeDefinedNamesDialog()
    return
  }
  const validated = validateDefinedNameDraftRows()
  if ('error' in validated && validated.error) {
    definedNamesError.value = validated.error
    return
  }
  const workbookNames = validated.workbookNames ?? []
  const worksheetNamesBySheetId = validated.worksheetNamesBySheetId ?? new Map<number, NoteSheetDefinedNameItem[]>()
  if (workbookNames.length && props.workbookId == null) {
    definedNamesError.value = '工作簿名称需要在工作簿内使用'
    return
  }

  definedNamesSaving.value = true
  definedNamesError.value = ''
  try {
    await flushRemoteSave()
    if (props.workbookId != null) {
      const workbookResponse = await updateWorkbookDefinedNames(
        props.workbookId,
        serializeDefinedNameItems(workbookNames),
        { worksheets: serializeDefinedNameWorksheetScopes(worksheetNamesBySheetId) },
      )
      syncDefinedNamesFromResponse(workbookResponse)
    } else {
      const currentSheetId = Number(props.sheetId)
      const sheetResponse = await updateSheetDefinedNames(
        props.sheetId,
        serializeDefinedNameItems(worksheetNamesBySheetId.get(currentSheetId) ?? []),
        { workbookId: props.workbookId, baseVersion: Number(sheetVersion.value || 1) },
      )
      syncDefinedNamesFromResponse(sheetResponse)
    }
    refreshFormulaDisplayState()
    renderCurrentHotWithReason('defined-names-save')
    closeDefinedNamesDialog()
    ElMessage.success('名称管理器已保存')
  } catch (error) {
    console.warn('Failed to save defined names:', error)
    if (getNoteSheetApiErrorStatus(error) === 409) {
      sheetRemoteConflictActive = true
      persistDraftDocument(buildCurrentDocument())
      definedNamesError.value = '工作表已被其他人更新，已保留本地草稿，请刷新后合并'
    } else {
      definedNamesError.value = '名称管理器保存失败'
    }
  } finally {
    definedNamesSaving.value = false
  }
}

function openSheetSettings() {
  if (props.sheetId == null) {
    return
  }
  if (!ensureCanEditConfig()) {
    return
  }

  sheetSettingsDraft.value = {
    ...sheetViewSettings.value,
    pagination: { ...sheetViewSettings.value.pagination },
  }
  sheetSettingsColumnFilterDraft.value = createColumnFilterEnabledDraft()
  sheetSettingsDialogVisible.value = true
}

function closeSheetSettings() {
  sheetSettingsDialogVisible.value = false
}

async function applySheetSettings() {
  if (!ensureCanEditConfig()) {
    closeSheetSettings()
    return
  }

  const nextSettings = normalizeSheetViewSettings(sheetSettingsDraft.value, columnHeaders.value.length)
  const nextColumnConfigs = buildColumnConfigsWithFilterDraft(
    columnConfigs.value,
    columnHeaders.value,
    sheetSettingsColumnFilterDraft.value,
  )
  const currentColumnConfigs = normalizeColumnConfigs(columnConfigs.value, columnHeaders.value)
  const columnFiltersChanged = JSON.stringify(nextColumnConfigs) !== JSON.stringify(currentColumnConfigs)
  closeSheetSettings()

  if (areSheetViewSettingsEqual(sheetViewSettings.value, nextSettings) && !columnFiltersChanged) {
    return
  }

  const previousSettings = {
    ...sheetViewSettings.value,
    pagination: { ...sheetViewSettings.value.pagination },
  }
  const previousColumnConfigs = columnConfigs.value
  const previousRows = rows.value
  const previousCellMeta = cellMeta.value
  const previousColumnEntityIds = columnEntityIds.value
  const previousHeaderRowEntityIds = headerRowEntityIds.value
  const previousDataRowEntityIds = dataRowEntityIds.value
  const previousEntityCells = entityCells.value
  const previousMergedCells = mergedCells.value
  const previousSheetHeaderPrefixRows = sheetHeaderPrefixRows.value
  const undoEntry = createLocalUndoEntry('sheet-settings')

  const paginationChanged = (
    sheetViewSettings.value.pagination.enabled !== nextSettings.pagination.enabled
    || sheetViewSettings.value.pagination.page_size !== nextSettings.pagination.page_size
  )
  const previousHeaderRowCount = sheetHeaderRowCount.value
  const willHaveColumnNoteEntityRow = shouldHaveColumnNoteEntityRowForSettings(nextSettings)
  const nextHeaderRowCount = getSheetHeaderRowCountForSettings(nextSettings)
  const nextRows = remapRowsFormulaReferencesForHeaderRowCountChange(
    rows.value,
    previousHeaderRowCount,
    nextHeaderRowCount,
  )

  if (nextRows !== rows.value) {
    rows.value = nextRows
  }
  remapDocumentAnchorsForHeaderRowCountChange(previousHeaderRowCount, nextHeaderRowCount)
  if (willHaveColumnNoteEntityRow && !hasMaterializedColumnNoteRow.value) {
    materializeColumnNotePrefixRow()
  }
  sheetViewSettings.value = nextSettings
  if (columnFiltersChanged) {
    columnConfigs.value = nextColumnConfigs
  }
  refreshGridStructure()
  await refreshComputedRowHeights()
  await updateSheetViewportHeight()

  if (paginationChanged) {
    try {
      const saved = await saveDocumentSnapshot(buildCurrentDocument())
      if (saved) {
        sheetTitle.value = saved.title || sheetTitle.value
        sheetVersion.value = Number(saved.version || 1)
        emitSheetSync(saved)
        clearDraftStorage()
      }
    } catch (error) {
      console.warn('Failed to save sheet settings', error)
      sheetViewSettings.value = previousSettings
      columnConfigs.value = previousColumnConfigs
      rows.value = previousRows
      cellMeta.value = previousCellMeta
      columnEntityIds.value = previousColumnEntityIds
      headerRowEntityIds.value = previousHeaderRowEntityIds
      dataRowEntityIds.value = previousDataRowEntityIds
      entityCells.value = previousEntityCells
      mergedCells.value = previousMergedCells
      sheetHeaderPrefixRows.value = previousSheetHeaderPrefixRows
      refreshGridStructure()
      await refreshComputedRowHeights()
      await updateSheetViewportHeight()
      ElMessage.error('设置表格保存失败')
      return
    }
    currentPage.value = 1
    pageSize.value = nextSettings.pagination.page_size
    await restoreInitialDocument()
    pushLocalUndoEntry(undoEntry)
    void updateSheetViewportHeight()
    return
  }

  pushLocalUndoEntry(undoEntry)
  scheduleRemoteSave()
}

function loadSheetDocument(document: SheetDocument, sourceDocument?: unknown) {
  const traceDetail = {
    sourceDocument: sourceDocument != null,
    sourceRows: document.rows.length,
    sourceGridRows: document.grid_rows?.length ?? 0,
    sourceColumns: document.columns.length,
    sourceMergedCells: document.merged_cells?.length ?? 0,
  }
  const trace = startSheetPerfTrace('sheet.loadDocument', {
    detail: traceDetail,
  })
  clearEditingColumnState()
  clearFormulaBarSelection()
  clearColumnMarkerSelection()
  clearRowMarkerSelectionAnchor()
  clearSheetHeaderSelection()
  hasContextMenuFallbackSelection.value = false
  closeColumnNotePopover()
  closeColumnFilterPopover()
  columnSettingsDialogVisible.value = false
  columnSettingsColumnIndex.value = null
  columnSettingsSelectionBounds.value = null
  closeCellLinkDialog()
  closeCellStyleDialog()
  closeCellRichTextDialog()
  cancelRichTextContentEditor()
  const normalizedHeaders = normalizeHeaders(document.columns)
  loadedDocumentDataRowCount.value = document.rows.length
  const initialRows = document.rows.length
    ? document.rows.map((row) => normalizeRow(row, normalizedHeaders))
    : [createEmptyRow(normalizedHeaders.length)]
  trace?.mark('normalize-rows')

  suppressNextFormulaDisplayStructureWatcher = true
  columnHeaders.value = normalizedHeaders
  headerGroups.value = normalizeHeaderGroups(document.header_groups, normalizedHeaders.length)
  columnConfigs.value = normalizeColumnConfigs(document.column_configs, normalizedHeaders)
  sheetDefinedNames.value = normalizeDefinedNameItems(document.defined_names, 'worksheet')
  const documentHeaderRowFallback = normalizeHeaderGroups(document.header_groups, normalizedHeaders.length).length + 1
  const dataStartRow = normalizeNonNegativeInt(document.data_start_row, documentHeaderRowFallback)
  const fieldRowIndex = normalizeNonNegativeInt(document.field_row_index, Math.max(0, dataStartRow - 1))
  sheetHeaderPrefixRows.value = Array.isArray(document.grid_rows)
    ? document.grid_rows
      .slice(0, dataStartRow)
      .map((row) => normalizeRow(row, normalizedHeaders))
    : []
  columnConfigs.value = mergeGridNoteRowIntoColumnConfigs(
    columnConfigs.value,
    Array.isArray(document.grid_rows) ? document.grid_rows.map((row) => normalizeRow(row, normalizedHeaders)) : [],
    normalizedHeaders,
    fieldRowIndex,
    dataStartRow,
    { overwrite: true },
  )
  syncColumnNotesFromHeaderPrefixRows()
  trace?.mark('normalize-headers')
  const normalizedMergedCells = normalizeMergedCells(
    document.merged_cells,
    Math.max(document.grid_rows?.length ?? 0, sheetHeaderRowCount.value + initialRows.length, getMergedCellsSourceRowCount(document.merged_cells)),
    normalizedHeaders.length,
  )
  mergedCells.value = normalizedMergedCells
  const repairedRows = repairCoveredMergedCellValuesInDataRows(
    initialRows,
    normalizedMergedCells,
    normalizedHeaders,
    dataStartRow,
  )
  const normalizedRows = repairedRows.length ? repairedRows : [createEmptyRow(normalizedHeaders.length)]
  trace?.mark('normalize-merge-cells')
  const cachedCellMeta = normalizedDocumentCellMetaCache.get(document)
  cellMeta.value = cachedCellMeta
    ?? finalizeNormalizedSheetCellMeta(
      mergeSourceDocumentInlineLinksIntoCellMeta(
        normalizeCellMetaMap(document.cell_meta, normalizedHeaders.length),
        sourceDocument ?? document,
        dataStartRow,
        normalizedHeaders,
      ),
      Array.isArray(document.grid_rows)
        ? document.grid_rows.map((row) => normalizeRow(row, normalizedHeaders))
        : [
          normalizedHeaders,
          ...document.rows.map((row) => normalizeRow(row, normalizedHeaders)),
        ],
      normalizedHeaders,
      dataStartRow,
    )
  trace?.mark('cell-meta')
  sheetViewSettings.value = normalizeSheetViewSettings(
    document.view_settings,
    normalizedHeaders.length,
    getDefaultSheetHeightMode(),
  )
  pageSize.value = sheetViewSettings.value.pagination.page_size
  const cachedFormulaDisplayState = normalizedDocumentFormulaDisplayCache.get(document)
  const formulaDisplayCacheReusable = shouldReuseCachedFormulaDisplayState(
    cachedFormulaDisplayState,
    normalizedHeaders,
    normalizedRows,
  )
  const formulaDisplayForWidths = formulaDisplayCacheReusable
    ? cachedFormulaDisplayState
    ?? buildFormulaDisplayStateForRows(normalizedHeaders, normalizedRows, columnConfigs.value)
    : buildFormulaDisplayStateForRows(normalizedHeaders, normalizedRows, columnConfigs.value)
  columnWidths.value = document.column_widths?.length
    ? document.column_widths.slice(0, normalizedHeaders.length)
    : normalizedHeaders.map((_, index) => getAutoColumnWidth(
      index,
      normalizedHeaders,
      normalizedRows,
      columnConfigs.value,
      formulaDisplayForWidths,
  ))
  trace?.mark('column-widths')
  rows.value = normalizedRows
  initializeSheetEntitiesFromDocument(
    document,
    normalizedHeaders,
    sheetHeaderRowCount.value,
    columnHeaderLevel.value,
    normalizedRows,
    cellMeta.value,
  )
  formulaDisplayState.value = formulaDisplayForWidths
  trace?.mark('entities-formulas')
  trace?.mark(getHotInstance() ? 'hot-deferred-to-vue' : 'hot-not-mounted')
  trace?.finish({
    detail: {
      ...traceDetail,
      rows: rows.value.length,
      columns: columnHeaders.value.length,
      gridRows: sheetHotGridRows.value.length,
      gridColumns: sheetHotGridRows.value[0]?.length ?? 0,
      mergedCells: mergedCells.value.length,
      hotApplied: false,
      hotDeferredToVue: !!getHotInstance(),
      formulaDisplayCacheHit: formulaDisplayCacheReusable,
      cellMetaCacheHit: !!cachedCellMeta,
    },
  })
}

function clearSaveTimer() {
  if (saveTimer) {
    clearTimeout(saveTimer)
    saveTimer = null
  }
}

function clearSheetFilterReloadTimer() {
  if (sheetFilterReloadTimer) {
    clearTimeout(sheetFilterReloadTimer)
    sheetFilterReloadTimer = null
  }
}

function resetSheetFilterReloadState() {
  clearSheetFilterReloadTimer()
  pendingSheetFilterReloadKey = ''
  activeSheetFilterReloadKey = ''
  completedSheetFilterReloadKey = ''
  failedSheetFilterReloadKey = ''
}

function normalizePaginationRowIndexes(value: unknown) {
  if (!Array.isArray(value)) {
    return null
  }
  return value
    .map((item) => Number(item))
    .filter((item) => Number.isInteger(item) && item >= 0)
}

function normalizePaginationDeletedRowIndexes(value: unknown) {
  const indexes = normalizePaginationRowIndexes(value)
  if (!indexes) {
    return null
  }
  return Array.from(new Set(indexes)).sort((left, right) => left - right)
}

function addPendingDeletedPageRowIndexes(indexes: number[]) {
  if (!indexes.length) {
    return
  }
  pendingDeletedPageRowIndexes.value = normalizePaginationDeletedRowIndexes([
    ...pendingDeletedPageRowIndexes.value,
    ...indexes,
  ]) ?? []
}

function removePendingDeletedPageRowIndexes(indexes: number[]) {
  if (!indexes.length || !pendingDeletedPageRowIndexes.value.length) {
    return
  }
  const removed = new Set(indexes)
  pendingDeletedPageRowIndexes.value = pendingDeletedPageRowIndexes.value.filter((index) => !removed.has(index))
}

function applyPaginationState(pagination?: NoteSheetPaginationState | null) {
  if (!pagination) {
    currentPage.value = 1
    pageCount.value = 1
    totalRowCount.value = trimTrailingBlankRows(rows.value.map((row) => normalizeRow(row, columnHeaders.value))).length
    unfilteredTotalRowCount.value = totalRowCount.value
    pageRowOffset.value = 0
    pageLoadedRowCount.value = totalRowCount.value
    pageRowIndexes.value = null
    return
  }

  currentPage.value = normalizePositivePageNumber(pagination.page, currentPage.value)
  pageSize.value = normalizePositivePageNumber(pagination.page_size, pageSize.value)
  pageCount.value = normalizePositivePageNumber(pagination.page_count, 1)
  totalRowCount.value = normalizeNonNegativeInt(pagination.total_rows)
  unfilteredTotalRowCount.value = Math.max(
    totalRowCount.value,
    normalizeNonNegativeInt(pagination.unfiltered_total_rows),
  )
  pageRowOffset.value = normalizeNonNegativeInt(pagination.row_offset)
  pageLoadedRowCount.value = normalizeNonNegativeInt(pagination.loaded_row_count)
  pageRowIndexes.value = normalizePaginationRowIndexes(pagination.row_indexes)
}

function shouldUsePagedPatchForSave() {
  return pageRowIndexes.value !== null || pageLoadedRowCount.value < totalRowCount.value
}

function buildUpdatePagePatch() {
  if (!shouldUsePagedPatchForSave()) {
    return undefined
  }

  const rowIndexes = pageRowIndexes.value !== null && pageRowIndexes.value.length === rows.value.length
    ? [...pageRowIndexes.value]
    : undefined
  const deletedRowIndexes = pendingDeletedPageRowIndexes.value.length
    ? [...pendingDeletedPageRowIndexes.value]
    : undefined

  return {
    page: currentPage.value,
    page_size: pageSize.value,
    row_offset: pageRowOffset.value,
    loaded_row_count: pageLoadedRowCount.value,
    row_indexes: rowIndexes,
    deleted_row_indexes: deletedRowIndexes,
  }
}

async function saveDocumentSnapshot(document: SheetDocument, pagePatch = buildUpdatePagePatch()) {
  if (props.sheetId == null || !canPersistSheet.value) {
    return null
  }

  return updateNoteSheet(props.sheetId, {
    ...(canEditConfig.value ? { title: sheetTitle.value.trim() || '未命名表格' } : {}),
    document_json: document,
    base_version: Number(sheetVersion.value || 1),
    page_patch: pagePatch,
  }, {
    workbookId: props.workbookId,
  })
}

function emitSheetSync(detail: NoteSheetDetail) {
  const workbookItems = detail.workbook_items ?? []
  sheetWorkbookItems.value = workbookItems
  emit('sheetSync', {
    id: detail.id,
    title: detail.title || '未命名表格',
    version: Number(detail.version || 1),
    updatedAt: Number(detail.updated_at || 0),
    parentWorkbookId: Number.isInteger(detail.parent_workbook_id) ? Number(detail.parent_workbook_id) : null,
    workbookItems,
  })
}

function buildClientPagedSheetDetail(detail: NoteSheetDetail): NoteSheetDetail {
  if (detail.pagination) {
    return detail
  }

  const fullDocument = normalizeSheetDocument(detail.document_json, {}, getDefaultSheetHeightMode())
  const settings = normalizeSheetViewSettings(fullDocument.view_settings, fullDocument.columns.length)
  if (!settings.pagination.enabled) {
    return detail
  }

  const pageSize = settings.pagination.page_size
  const allRows = fullDocument.rows.map((row) => normalizeRow(row, fullDocument.columns))
  const pageCount = Math.max(1, allRows.length ? Math.ceil(allRows.length / pageSize) : 1)
  const page = Math.min(Math.max(currentPage.value || 1, 1), pageCount)
  const rowOffset = Math.min((page - 1) * pageSize, allRows.length)
  const pageRows = allRows.slice(rowOffset, rowOffset + pageSize)
  const dataStartRow = normalizeNonNegativeInt(fullDocument.data_start_row, 0)
  const headerRows = Array.isArray(fullDocument.grid_rows)
    ? fullDocument.grid_rows.slice(0, dataStartRow).map((row) => normalizeRow(row, fullDocument.columns))
    : []
  const pageDocument: SheetDocument = {
    ...fullDocument,
    rows: pageRows,
    grid_rows: [...headerRows, ...pageRows],
  }

  return {
    ...detail,
    document_json: pageDocument as unknown as Record<string, unknown>,
    pagination: {
      page,
      page_size: pageSize,
      total_rows: allRows.length,
      page_count: pageCount,
      row_offset: rowOffset,
      loaded_row_count: pageRows.length,
    },
  }
}

function applyRemoteSheetDetail(
  detail: NoteSheetDetail,
  options?: { applyInitialWorkspaceView?: boolean },
) {
  const effectiveDetail = buildClientPagedSheetDetail(detail)
  const effectiveDocument = normalizeSheetDocument(effectiveDetail.document_json, {}, getDefaultSheetHeightMode())
  suppressPersistence = true
  try {
    remoteAccessCapabilities.value = effectiveDetail.access?.capabilities ?? null
    sheetTitle.value = effectiveDetail.title || '未命名表格'
    sheetVersion.value = Number(effectiveDetail.version || 1)
    sheetRemoteConflictActive = false
    applyPaginationState(effectiveDetail.pagination)
    pendingDeletedPageRowIndexes.value = []
    emitSheetSync(effectiveDetail)
    beginSheetCoreRenderPhase()
    loadSheetDocument(
      effectiveDocument,
      effectiveDetail.document_json,
    )
    sheetContentReady.value = true
    loadedSheetContentIdentity = getSheetContentIdentity(effectiveDetail.id, props.workbookId ?? null)
    cacheRemoteSheetDetail(effectiveDetail, {
      workbookId: props.workbookId ?? null,
      document: effectiveDocument,
      sourceDocument: effectiveDetail.document_json,
    })
    scheduleSheetRenderEnhancement()
    suppressReadOnlyActionWarningsForSheetRender()
    restoreStudentLookupSelectionFromLocalStorage()
    restoreSheetWorkspaceViewFromLocalStorage({
      applyInitialWorkspaceView: options?.applyInitialWorkspaceView === true,
    })
    changeSerial = 0
    lastQueuedSerial = 0
    savedChangeSerial = 0
    resetLocalUndoHistory()
    invalidateColumnFilterGlobalOptionsCache()
    clearDraftStorage()
    void refreshAttendanceCourseScriptStatuses()
  } finally {
    suppressPersistence = false
  }
}

function applyInlineSheetDocument() {
  sheetLoadSettled.value = true
  if (!props.inlineDocument) {
    suppressPersistence = true
    resetWorkspaceState()
    sheetContentReady.value = false
    suppressPersistence = false
    return
  }

  suppressPersistence = true
  try {
    remoteAccessCapabilities.value = INLINE_READONLY_ACCESS_CAPABILITIES
    workbookDefinedNames.value = []
    definedNameWorksheetScopes.value = []
    sheetTitle.value = props.inlineTitle || '未命名表格'
    sheetVersion.value = 0
    beginSheetCoreRenderPhase()
    loadSheetDocument(
      normalizeSheetDocument(props.inlineDocument, {}, getDefaultSheetHeightMode()),
      props.inlineDocument,
    )
    applyPaginationState(null)
    pendingDeletedPageRowIndexes.value = []
    sheetContentReady.value = true
    loadedSheetContentIdentity = ''
    resetHotInitialGridRowsLoaded()
    scheduleSheetRenderEnhancement()
    suppressReadOnlyActionWarningsForSheetRender()
    restoreStudentLookupSelectionFromLocalStorage()
    restoreSheetWorkspaceViewFromLocalStorage()
    changeSerial = 0
    lastQueuedSerial = 0
    savedChangeSerial = 0
    resetLocalUndoHistory()
    invalidateColumnFilterGlobalOptionsCache()
    clearSaveTimer()
    void refreshAttendanceCourseScriptStatuses()
  } finally {
    suppressPersistence = false
  }
}

function findHeaderIndex(headers: string[], target: string) {
  return headers.findIndex((header) => normalizeCellValue(header).trim() === target)
}

function applyRegistrationRunSheetColumns(detail: NoteSheetDetail, headersToSync: string[]) {
  const remoteDocument = normalizeSheetDocument(detail.document_json, {}, getDefaultSheetHeightMode())
  const remoteColumns = normalizeHeaders(remoteDocument.columns)
  const columnPairs = headersToSync
    .map((header) => ({
      current: findHeaderIndex(columnHeaders.value, header),
      remote: findHeaderIndex(remoteColumns, header),
    }))
    .filter((pair) => pair.current >= 0 && pair.remote >= 0)

  if (!columnPairs.length) {
    applyRemoteSheetDetail(detail)
    return
  }

  const remoteRows = remoteDocument.rows.map((row) => normalizeRow(row, remoteColumns))
  const currentRows = rows.value.map((row) => normalizeRow(row, columnHeaders.value))
  const currentBaseOffset = effectivePaginationEnabled.value ? pageRowOffset.value : 0
  const remoteBaseOffset = detail.pagination?.row_offset ?? 0
  const remoteIsPaged = !!detail.pagination
  let changed = false

  for (let rowIndex = 0; rowIndex < currentRows.length; rowIndex += 1) {
    const remoteRowIndex = remoteIsPaged
      ? rowIndex + currentBaseOffset - remoteBaseOffset
      : rowIndex + currentBaseOffset
    const remoteRow = remoteRows[remoteRowIndex]
    if (!remoteRow) {
      continue
    }

    for (const pair of columnPairs) {
      const nextValue = remoteRow[pair.remote] ?? ''
      if (currentRows[rowIndex][pair.current] !== nextValue) {
        currentRows[rowIndex][pair.current] = nextValue
        changed = true
      }
    }
  }

  suppressPersistence = true
  try {
    remoteAccessCapabilities.value = detail.access?.capabilities ?? remoteAccessCapabilities.value
    sheetTitle.value = detail.title || sheetTitle.value
    sheetVersion.value = Number(detail.version || sheetVersion.value || 1)
    invalidateColumnFilterGlobalOptionsCache()
    emitSheetSync(detail)
    if (changed) {
      rows.value = currentRows
      refreshFormulaDisplayState()
      refreshGridStructure()
      void refreshComputedRowHeights()
    }
    sheetContentReady.value = true
  } finally {
    suppressPersistence = false
  }
}

function applyRegistrationActionRunSheetDetail(status: NoteSheetRegistrationMatchRunResponse) {
  if (!status.sheet) {
    return
  }
  if (status.action === SHEET_CELL_ACTION_REGISTRATION_USER_MATCH) {
    applyRegistrationRunSheetColumns(status.sheet, REGISTRATION_USER_MATCH_HEADERS)
    return
  }
  if (status.action === SHEET_CELL_ACTION_REGISTRATION_ORDER_MATCH) {
    applyRegistrationRunSheetColumns(status.sheet, REGISTRATION_ORDER_MATCH_HEADERS)
    return
  }
  if (status.action === SHEET_CELL_ACTION_REGISTRATION_COMPOSITE_UPDATE) {
    applyRegistrationRunSheetColumns(status.sheet, [
      ...REGISTRATION_ORDER_MATCH_HEADERS,
      ...REGISTRATION_USER_MATCH_HEADERS,
    ])
    return
  }
  applyRemoteSheetDetail(status.sheet)
}

function applyClockinLinkDetectionRunSheetDetail(status: NoteSheetClockinLinkDetectionRunResponse) {
  if (status.sheet) {
    applyRemoteSheetDetail(status.sheet)
  }
}

async function flushRemoteSave() {
  if (saveInFlight) {
    await saveInFlightPromise
    return
  }
  if (suppressPersistence || props.sheetId == null) {
    return
  }
  if (!canPersistSheet.value) {
    clearSaveTimer()
    clearDraftStorage()
    return
  }

  clearSaveTimer()
  saveInFlight = true
  const serial = lastQueuedSerial
  const run = (async () => {
    const document = buildCurrentDocument()
    const pagePatch = buildUpdatePagePatch()
    const savedDeletedRowIndexes = pagePatch?.deleted_row_indexes ? [...pagePatch.deleted_row_indexes] : []
    const savedRowIndexes = pageRowIndexes.value ? [...pageRowIndexes.value] : null
    const shouldRestoreSavedRowIndexes = (
      savedRowIndexes !== null
      && buildActiveSheetQueryFilters().active
      && savedRowIndexes.length === rows.value.length
    )
    const savedFilteredPageState = shouldRestoreSavedRowIndexes
      ? {
        pageCount: pageCount.value,
        totalRowCount: totalRowCount.value,
        unfilteredTotalRowCount: unfilteredTotalRowCount.value,
        pageRowOffset: pageRowOffset.value,
        pageLoadedRowCount: pageLoadedRowCount.value,
      }
      : null

    try {
      const saved = await saveDocumentSnapshot(document, pagePatch)
      if (!saved) {
        return
      }
      removePendingDeletedPageRowIndexes(savedDeletedRowIndexes)
      sheetTitle.value = saved.title || sheetTitle.value
      sheetVersion.value = Number(saved.version || 1)
      applyPaginationState(saved.pagination)
      if (shouldRestoreSavedRowIndexes && saved.pagination && !Array.isArray(saved.pagination.row_indexes)) {
        pageRowIndexes.value = savedRowIndexes
        if (savedFilteredPageState) {
          pageCount.value = savedFilteredPageState.pageCount
          totalRowCount.value = savedFilteredPageState.totalRowCount
          unfilteredTotalRowCount.value = savedFilteredPageState.unfilteredTotalRowCount
          pageRowOffset.value = savedFilteredPageState.pageRowOffset
          pageLoadedRowCount.value = savedFilteredPageState.pageLoadedRowCount
        }
      }
      emitSheetSync(saved)
      cacheRemoteSheetDetail(saved, {
        workbookId: props.workbookId ?? null,
      })
      savedChangeSerial = Math.max(savedChangeSerial, serial)
      sheetRemoteConflictActive = false

      if (serial === changeSerial) {
        clearDraftStorage()
      } else {
        persistDraftDocument(buildCurrentDocument())
      }
    } catch (error) {
      if (getNoteSheetApiErrorStatus(error) === 409) {
        sheetRemoteConflictActive = true
        persistDraftDocument(document)
        invalidateSheetDocumentCache(props.sheetId, props.workbookId ?? null)
        ElMessage.warning('工作表已被其他人更新，已保留本地草稿，请刷新后合并')
        return
      }
      console.warn('Failed to save note sheet', error)
      persistDraftDocument(document)
    } finally {
      saveInFlight = false
      if (!sheetRemoteConflictActive && lastQueuedSerial > serial) {
        void flushRemoteSave()
      }
    }
  })()
  saveInFlightPromise = run
  try {
    await run
  } finally {
    if (saveInFlightPromise === run) {
      saveInFlightPromise = null
    }
  }
}

function scheduleRemoteSave(delayMs = REMOTE_SAVE_DEBOUNCE_MS) {
  if (suppressPersistence || props.sheetId == null) {
    return
  }
  if (!canPersistSheet.value) {
    clearSaveTimer()
    clearDraftStorage()
    return
  }

  persistDraftDocument(buildCurrentDocument())
  changeSerial += 1
  lastQueuedSerial = changeSerial
  invalidateColumnFilterGlobalOptionsCache()
  if (sheetRemoteConflictActive) {
    clearSaveTimer()
    return
  }
  clearSaveTimer()
  saveTimer = setTimeout(() => {
    void flushRemoteSave()
  }, Math.max(0, delayMs))
}

function normalizeSortText(value: unknown) {
  return normalizeCellValue(value).trim()
}

function parseSortNumber(value: unknown) {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return value
  }
  const text = normalizeSortText(value)
  if (!text) {
    return null
  }
  const numeric = Number(text.replace(/,/g, ''))
  return Number.isFinite(numeric) ? numeric : null
}

function compareLocalSortValues(left: unknown, right: unknown) {
  const leftText = normalizeSortText(left)
  const rightText = normalizeSortText(right)
  if (!leftText && !rightText) {
    return 0
  }
  if (!leftText) {
    return 1
  }
  if (!rightText) {
    return -1
  }

  const leftNumber = parseSortNumber(left)
  const rightNumber = parseSortNumber(right)
  if (leftNumber != null && rightNumber != null) {
    return leftNumber - rightNumber
  }

  return leftText.localeCompare(rightText, 'zh-Hans-CN', {
    numeric: true,
    sensitivity: 'base',
  })
}

function sortColumnLocally(columnIndex: number, direction: SortDirection) {
  const undoEntry = createLocalUndoEntry('column-sort')
  const decoratedRows = rows.value.map((row, rowIndex) => ({
    row: normalizeRow(row, columnHeaders.value),
    rowIndex,
    value: getCellSemanticValue(rowIndex, columnIndex, row[columnIndex]),
  }))
  const directionFactor = direction === 'asc' ? 1 : -1
  decoratedRows.sort((left, right) => {
    const compared = compareLocalSortValues(left.value, right.value)
    return compared === 0
      ? left.rowIndex - right.rowIndex
      : compared * directionFactor
  })

  const rowIndexMap = new Map<number, number>()
  decoratedRows.forEach((item, nextIndex) => {
    rowIndexMap.set(item.rowIndex, nextIndex)
  })
  rows.value = decoratedRows.map((item) => item.row)
  dataRowEntityIds.value = decoratedRows.map((item) => dataRowEntityIds.value[item.rowIndex] ?? createSheetEntityId('row_sort'))
  remapVisiblePageCellMetaRows(rowIndexMap)

  const hot = getHotInstance()
  if (hot) {
    loadCurrentHotGridRows(hot)
    renderHotWithReason(hot, 'sort-rows')
  }
  syncRowsFromGrid()
  refreshFormulaDisplayState()
  syncFormulaBarDraftFromSelectedCell()
  void refreshComputedRowHeights()
  pushLocalUndoEntry(undoEntry)
}

async function sortColumn(columnIndex: number, direction: SortDirection) {
  if (props.sheetId == null) {
    return
  }

  if (!canEditData.value) {
    if (!canUseLocalView.value) {
      warnReadOnlyAction()
      return
    }
    sortColumnLocally(columnIndex, direction)
    return
  }

  const undoEntry = createLocalUndoEntry('column-sort')
  workspaceLoading.value = true
  try {
    await flushRemoteSave()
    const detail = await sortNoteSheet(props.sheetId, {
      base_version: Number(sheetVersion.value || 1),
      column_index: columnIndex,
      direction,
    }, {
      workbookId: props.workbookId,
    })
    applyRemoteSheetDetail(detail)
    pushLocalUndoEntry(undoEntry)
    void updateSheetViewportHeight()
  } catch (error) {
    console.warn('Failed to sort note sheet', error)
    if (getNoteSheetApiErrorStatus(error) === 409) {
      sheetRemoteConflictActive = true
      ElMessage.warning('工作表已被其他人更新，已保留本地草稿，请刷新后合并')
    } else {
      ElMessage.error('排序失败')
    }
  } finally {
    workspaceLoading.value = false
  }
}

async function handleSelectedColumnSort(direction: SortDirection) {
  const columnIndex = getSingleSelectedColumnIndex()
  if (columnIndex == null) {
    return
  }

  await sortColumn(columnIndex, direction)
}

