    return
  }

  workspaceLoading.value = true
  try {
    await flushRemoteSave()
    const result = await organizeAttendanceCourseScripts(props.sheetId, {
      workbookId: props.workbookId,
    })
    void refreshAttendanceCourseScriptStatuses()

    const movedCount = result.moved.length
    if (movedCount > 0) {
      ElMessage.success(`已整理 ${movedCount} 个py脚本`)
    } else {
      ElMessage.info('py脚本位置已是最新')
    }
  } catch (error) {
    console.warn('Failed to organize attendance course scripts', error)
    ElMessage.error('整理py脚本失败')
  } finally {
    workspaceLoading.value = false
  }
}

async function handleUpdateAttendanceLinkCountsFromSelection(fieldKey: AttendanceLinkCountFieldKey) {
  if (props.sheetId == null || workspaceLoading.value) {
    return
  }
  if (!ensureCanRunSheetActions()) {
    return
  }
  const selectedCell = getSelectedAttendanceLinkCountCell(fieldKey)
  if (!canUpdateAttendanceLinkCountsFromColumn(fieldKey) && !selectedCell) {
    return
  }

  workspaceLoading.value = true
  try {
    await flushRemoteSave()
    const result = await updateAttendanceLinkCounts(props.sheetId, {
      base_version: Number(sheetVersion.value || 1),
      field_key: fieldKey,
      row_index: selectedCell?.documentRow,
    }, {
      workbookId: props.workbookId,
    })
    applyRemoteSheetDetail(result.sheet)
    void updateSheetViewportHeight()

    const updatedCount = result.updated.length
    if (updatedCount > 0) {
      ElMessage.success(`已更新 ${updatedCount} 行`)
    } else {
      const reasonText = result.skipped.map((item) => item.reason).filter(Boolean).join('；')
      ElMessage.info(reasonText || '没有可更新的数据')
    }
  } catch (error) {
    console.warn('Failed to update attendance link counts', error)
    if (getNoteSheetApiErrorStatus(error) === 409) {
      sheetRemoteConflictActive = true
      ElMessage.warning('工作表已被其他人更新，已保留本地草稿，请刷新后合并')
    } else {
      ElMessage.error('更新数据失败')
    }
  } finally {
    workspaceLoading.value = false
  }
}

function resolveFetchPaginationPreference(localDraft: SheetDraftPayload | null) {
  void localDraft

  if (sheetVersion.value > 0) {
    return {
      paginate: sheetViewSettings.value.pagination.enabled,
      pageSize: sheetViewSettings.value.pagination.page_size,
    }
  }

  return null
}

function getActiveColumnFiltersForQuery() {
  const filters: Record<string, ColumnFilterState> = {}
  activeColumnFilterEntries.value.forEach((entry) => {
    filters[entry.header] = getColumnFilterState(entry.header)
  })
  return filters
}

function getActiveExternalRowFilterProgramsForQuery() {
  return [
    ...normalizedBaseExternalRowFilterPrograms.value,
    normalizedExternalRowFilterProgram.value,
  ]
    .filter((program) => isExternalRowFilterProgramActive(program))
    .map((program) => ({
      default: program.default,
      rules: program.rules.map((rule) => ({
        action: rule.action,
        matcher: {
          kind: rule.matcher.kind,
          field: rule.matcher.field,
          op: rule.matcher.op,
          value: rule.matcher.value,
          values: rule.matcher.values,
        },
      })),
    }))
}

function buildActiveSheetQueryFilters() {
  const columnFiltersForQuery = getActiveColumnFiltersForQuery()
  const rowFilterPrograms = getActiveExternalRowFilterProgramsForQuery()
  return {
    columnFilters: columnFiltersForQuery,
    rowFilterPrograms,
    active: Object.keys(columnFiltersForQuery).length > 0 || rowFilterPrograms.length > 0,
  }
}

function buildSheetFilterReloadKey(filters = buildActiveSheetQueryFilters()) {
  return JSON.stringify({
    sheetId: props.sheetId,
    workbookId: props.workbookId ?? null,
    pageSize: pageSize.value,
    filters,
  })
}

function isCurrentSheetFilterPaginationReady(filters = buildActiveSheetQueryFilters()) {
  return filters.active ? pageRowIndexes.value !== null : pageRowIndexes.value === null
}

function cloneJsonValue<T>(value: T): T {
  if (value === undefined) {
    return value
  }
  return JSON.parse(JSON.stringify(value)) as T
}

function getSheetContentIdentity(sheetId: number | null | undefined, workbookId: number | null | undefined) {
  return sheetId == null ? '' : `${workbookId ?? 'sheet'}:${sheetId}`
}

function buildSheetDocumentCacheQueryKey(options: {
  sheetId: number
  workbookId: number | null
  page?: number
  pageSize?: number
  paginate?: boolean
  includeWorkbookContext?: boolean
}) {
  return JSON.stringify({
    sheetId: options.sheetId,
    workbookId: options.workbookId,
    page: options.paginate ? (options.page ?? currentPage.value) : null,
    pageSize: options.paginate ? (options.pageSize ?? pageSize.value) : null,
    paginate: options.paginate === true,
    includeWorkbookContext: options.includeWorkbookContext === true,
    filters: buildActiveSheetQueryFilters(),
  })
}

function getSheetDocumentCacheEntry(queryKey: string, sheetId: number, workbookId: number | null) {
  const entry = sheetDocumentCache.get(queryKey)
  if (!entry || entry.sheetId !== sheetId || entry.workbookId !== workbookId) {
    return null
  }
  return entry
}

function getLatestSheetDocumentCacheEntry(sheetId: number, workbookId: number | null) {
  let latest: SheetDocumentCacheEntry | null = null
  for (const entry of sheetDocumentCache.values()) {
    if (entry.sheetId !== sheetId || entry.workbookId !== workbookId) {
      continue
    }
    if (!latest || entry.cachedAt > latest.cachedAt) {
      latest = entry
    }
  }
  return latest
}

function invalidateSheetDocumentCache(sheetId?: number | null, workbookId?: number | null) {
  if (sheetId == null) {
    sheetDocumentCache.clear()
    return
  }
  for (const [key, entry] of sheetDocumentCache.entries()) {
    if (entry.sheetId === sheetId && (workbookId === undefined || entry.workbookId === workbookId)) {
      sheetDocumentCache.delete(key)
    }
  }
}

function cacheRemoteSheetDetail(
  detail: NoteSheetDetail,
  options: {
    queryKey?: string
    workbookId?: number | null
    document?: SheetDocument
    sourceDocument?: unknown
  } = {},
) {
  const sheetId = Number(detail.id)
  if (!Number.isInteger(sheetId)) {
    return
  }
  const workbookId = options.workbookId ?? props.workbookId ?? null
  const queryKey = options.queryKey ?? buildSheetDocumentCacheQueryKey({
    sheetId,
    workbookId,
    page: detail.pagination?.page,
    pageSize: detail.pagination?.page_size,
    paginate: !!detail.pagination,
    includeWorkbookContext: workbookId == null,
  })
  const normalizedDocument = options.document
    ? cloneSheetDocumentSnapshot(options.document)
    : normalizeSheetDocument(detail.document_json, {}, getDefaultSheetHeightMode())
  sheetDocumentCache.set(queryKey, {
    workbookId,
    sheetId,
    queryKey,
    version: Number(detail.version || 1),
    updatedAt: Number(detail.updated_at || 0),
    cachedAt: Date.now(),
    title: detail.title || '未命名表格',
    document: cloneSheetDocumentSnapshot(normalizedDocument),
    sourceDocument: cloneJsonValue(options.sourceDocument ?? detail.document_json ?? normalizedDocument),
    pagination: detail.pagination ? cloneJsonValue(detail.pagination) : null,
    accessCapabilities: detail.access?.capabilities ? cloneJsonValue(detail.access.capabilities) : null,
    parentWorkbookId: Number.isInteger(detail.parent_workbook_id) ? Number(detail.parent_workbook_id) : null,
    workbookItems: cloneJsonValue(detail.workbook_items ?? []),
  })
}

function scheduleRemoteSheetDetailCacheAfterSheetLoad(
  detail: NoteSheetDetail,
  options: {
    queryKey?: string
    workbookId?: number | null
    document?: SheetDocument
    sourceDocument?: unknown
  },
  isCurrent?: () => boolean,
) {
  const runCache = () => {
    if (isCurrent && !isCurrent()) {
      return
    }
    const cacheTrace = startSheetPerfTrace('sheet.cacheRemoteDetail', {
      detail: {
        sheetId: Number(detail.id),
        workbookId: options.workbookId ?? props.workbookId ?? null,
      },
    })
    try {
      cacheRemoteSheetDetail(detail, options)
      cacheTrace?.finish({
        detail: {
          stale: false,
        },
      })
    } catch (error) {
      cacheTrace?.finish({
        detail: {
          stale: !!isCurrent && !isCurrent(),
          error: error instanceof Error ? error.message : String(error),
        },
      })
      console.warn('Failed to cache sheet detail after load:', error)
    }
  }

  if (typeof window === 'undefined') {
    runCache()
    return
  }
  window.requestAnimationFrame(() => {
    window.requestAnimationFrame(() => {
      window.setTimeout(runCache, 0)
    })
  })
}

function applySheetDocumentCacheEntry(entry: SheetDocumentCacheEntry) {
  suppressPersistence = true
  try {
    remoteAccessCapabilities.value = entry.accessCapabilities ?? null
    sheetTitle.value = entry.title || '未命名表格'
    sheetVersion.value = Number(entry.version || 1)
    applyPaginationState(entry.pagination)
    pendingDeletedPageRowIndexes.value = []
    sheetWorkbookItems.value = cloneJsonValue(entry.workbookItems)
    beginSheetCoreRenderPhase()
    loadSheetDocument(
      cloneSheetDocumentSnapshot(entry.document),
      cloneJsonValue(entry.sourceDocument),
    )
    sheetContentReady.value = true
    sheetLoadSettled.value = false
    loadedSheetContentIdentity = getSheetContentIdentity(entry.sheetId, entry.workbookId)
    scheduleSheetRenderEnhancement()
    resetLocalUndoHistory()
    invalidateColumnFilterGlobalOptionsCache()
  } finally {
    suppressPersistence = false
  }
}

async function fetchNoteSheetForCurrentView(
  options?: {
    page?: number
    pageSize?: number
    paginate?: boolean
    workbookId?: number | null
    includeWorkbookContext?: boolean
  },
) {
  if (props.sheetId == null) {
    return null
  }

  const activeFilters = buildActiveSheetQueryFilters()
  if (options?.paginate === true && activeFilters.active) {
    return queryNoteSheet(props.sheetId, {
      page: options.page,
      page_size: options.pageSize,
      paginate: true,
      column_filters: activeFilters.columnFilters,
      row_filter_programs: activeFilters.rowFilterPrograms,
    }, {
      workbookId: options.workbookId,
      includeWorkbookContext: options.includeWorkbookContext,
    })
  }

  return fetchNoteSheet(props.sheetId, options)
}

function getUsableInitialSheetDetail(detail: NoteSheetDetail | null | undefined) {
  return detail && props.sheetId != null && detail.id === props.sheetId ? detail : null
}

function getUsableDefinedNamesContext(
  detail: NoteSheetDetail,
  requestSheetId: number,
  definedNamesWorkbookId: number | null,
) {
  const context = detail.defined_names_context
  if (!context || context.sheet_id !== requestSheetId) {
    return null
  }
  const contextWorkbookId = Number(context.workbook_id)
  if (
    definedNamesWorkbookId != null
    && Number.isInteger(contextWorkbookId)
    && contextWorkbookId !== definedNamesWorkbookId
  ) {
    return null
  }
  return context
}

function isCurrentRestoreInitialDocumentRequest(seq: number, sheetId: number, workbookId: number | null) {
  return (
    seq === restoreInitialDocumentSeq
    && props.sheetId === sheetId
    && (props.workbookId ?? null) === workbookId
  )
}

async function syncDefinedNamesForRestoreRequest(
  requestSeq: number,
  requestSheetId: number,
  requestWorkbookId: number | null,
  definedNamesWorkbookId: number | null,
) {
  try {
    const response = await fetchSheetDefinedNames(requestSheetId, { workbookId: definedNamesWorkbookId })
    if (!isCurrentRestoreInitialDocumentRequest(requestSeq, requestSheetId, requestWorkbookId)) {
      return false
    }
    return syncDefinedNamesFromResponse(response)
  } catch (error) {
    if (getNoteSheetApiErrorStatus(error) !== 404) {
      console.warn('Failed to load note sheet defined names:', error)
    }
    if (isCurrentRestoreInitialDocumentRequest(requestSeq, requestSheetId, requestWorkbookId)) {
      const formulaContextChanged = workbookDefinedNames.value.length > 0
        || sheetDefinedNames.value.length > 0
      workbookDefinedNames.value = []
      sheetDefinedNames.value = []
      definedNameWorksheetScopes.value = []
      return formulaContextChanged
    }
  }
  return false
}

function scheduleDefinedNamesSyncAfterSheetLoad(
  requestSeq: number,
  requestSheetId: number,
  requestWorkbookId: number | null,
  definedNamesWorkbookId: number | null,
) {
  void syncDefinedNamesForRestoreRequest(
    requestSeq,
    requestSheetId,
    requestWorkbookId,
    definedNamesWorkbookId,
  ).then((formulaContextChanged) => {
    if (!isCurrentRestoreInitialDocumentRequest(requestSeq, requestSheetId, requestWorkbookId)) {
      return
    }
    if (!formulaContextChanged) {
      return
    }
    refreshFormulaDisplayState()
    syncFormulaBarDraftFromSelectedCell(true)
    refreshAdaptiveFormulaColumnWidths()
    renderCurrentHotWithReason('deferred-defined-names-sync')
  })
}

function sheetDocumentHasFormulaExpressions(document: SheetDocument) {
  const headers = normalizeHeaders(document.columns)
  const rowGroups = [
    document.grid_rows,
    document.rows,
  ].filter((rows): rows is SheetStoredRow[] => Array.isArray(rows))

  return rowGroups.some((rows) => (
    rows.some((row) => normalizeRow(row, headers).some(isFormulaExpression))
  ))
}

function scheduleFilteredPaginationReload() {
  if (props.sheetId == null || !paginationEnabled.value) {
    return
  }

  const filters = buildActiveSheetQueryFilters()
  const reloadKey = buildSheetFilterReloadKey(filters)
  if (
    reloadKey === pendingSheetFilterReloadKey
    || reloadKey === activeSheetFilterReloadKey
    || reloadKey === failedSheetFilterReloadKey
    || (reloadKey === completedSheetFilterReloadKey && isCurrentSheetFilterPaginationReady(filters))
  ) {
    return
  }

  pendingSheetFilterReloadKey = reloadKey
  clearSheetFilterReloadTimer()
  sheetFilterReloadTimer = setTimeout(runScheduledSheetFilterReload, 80)
}

function runScheduledSheetFilterReload() {
  sheetFilterReloadTimer = null
  if (!pendingSheetFilterReloadKey) {
    return
  }
  if (!sheetContentReady.value || workspaceLoading.value) {
    sheetFilterReloadTimer = setTimeout(runScheduledSheetFilterReload, 80)
    return
  }

  const reloadKey = pendingSheetFilterReloadKey
  pendingSheetFilterReloadKey = ''
  activeSheetFilterReloadKey = reloadKey
  currentPage.value = 1
  void restoreInitialDocument({ preserveContent: true }).then(() => {
    completedSheetFilterReloadKey = reloadKey
    if (failedSheetFilterReloadKey === reloadKey) {
      failedSheetFilterReloadKey = ''
    }
  }).catch((error) => {
    failedSheetFilterReloadKey = reloadKey
    console.warn('Failed to reload filtered sheet page', error)
  }).finally(() => {
    activeSheetFilterReloadKey = ''
    if (pendingSheetFilterReloadKey) {
      clearSheetFilterReloadTimer()
      sheetFilterReloadTimer = setTimeout(runScheduledSheetFilterReload, 80)
    }
    void updateSheetViewportHeight()
  })
}

async function restoreInitialDocument(options?: RestoreInitialDocumentOptions) {
  if (props.sheetId == null) {
    return
  }

  const requestSeq = ++restoreInitialDocumentSeq
  const requestSheetId = props.sheetId
  const requestWorkbookId = props.workbookId ?? null
  const includeWorkbookContext = requestWorkbookId == null
  const requestContentIdentity = getSheetContentIdentity(requestSheetId, requestWorkbookId)
  const alreadyRenderingRequestedSheet = loadedSheetContentIdentity === requestContentIdentity
  let localDraft = readDraftPayload()
  const initialCacheQueryKey = buildSheetDocumentCacheQueryKey({
    sheetId: requestSheetId,
    workbookId: requestWorkbookId,
    page: currentPage.value,
    pageSize: pageSize.value,
    paginate: paginationEnabled.value,
    includeWorkbookContext,
  })
  const cachedEntry = !localDraft && !alreadyRenderingRequestedSheet
    ? (
      getSheetDocumentCacheEntry(initialCacheQueryKey, requestSheetId, requestWorkbookId)
      ?? getLatestSheetDocumentCacheEntry(requestSheetId, requestWorkbookId)
    )
    : null
  const shouldPreserveContent = (
    options?.preserveContent === true
    && sheetContentReady.value
    && alreadyRenderingRequestedSheet
  )
  const shouldClearOnError = options?.clearOnError === true
  const initialDetail = getUsableInitialSheetDetail(options?.initialDetail ?? props.initialDetail)
  const traceDetail = {
    requestSheetId,
    requestWorkbookId,
    preserveContent: shouldPreserveContent,
    cachedPlaceholder: !!cachedEntry,
    hasInitialDetail: !!initialDetail,
  }
  const trace = startSheetPerfTrace('sheet.load', {
    detail: traceDetail,
  })
  markBootPerf('note-sheet-workspace.restore.start', traceDetail)
  workspaceLoading.value = true
  if (!shouldPreserveContent) {
    if (cachedEntry) {
      applySheetDocumentCacheEntry(cachedEntry)
    } else {
      sheetContentReady.value = false
      loadedSheetContentIdentity = ''
      resetHotInitialGridRowsLoaded()
      sheetLoadSettled.value = false
    }
  }
  sheetLoadErrorText.value = ''
  suppressPersistence = true
  try {
    trace?.mark('draft')
    const activeFilters = buildActiveSheetQueryFilters()
    const shouldUseInitialDetail = !!initialDetail && sheetVersion.value <= 0 && !localDraft && !activeFilters.active
    const paginationPreference = shouldUseInitialDetail ? null : resolveFetchPaginationPreference(localDraft)
    let remote: NoteSheetDetail | null = shouldUseInitialDetail
      ? initialDetail
      : await markBootPerfAsync(
          'note-sheet-workspace.fetchSheet',
          () => fetchNoteSheetForCurrentView(paginationPreference
            ? {
              page: paginationPreference.paginate ? currentPage.value : undefined,
              pageSize: paginationPreference.paginate ? paginationPreference.pageSize : undefined,
              paginate: paginationPreference.paginate,
              workbookId: requestWorkbookId,
              includeWorkbookContext,
            }
            : {
              workbookId: requestWorkbookId,
              includeWorkbookContext,
            }),
        )
    trace?.mark(shouldUseInitialDetail ? 'initial-detail' : 'fetch')
    markBootPerf(shouldUseInitialDetail ? 'note-sheet-workspace.initialDetail.ready' : 'note-sheet-workspace.fetchSheet.ready', {
      hasRemote: !!remote,
      sheetId: remote?.id ?? null,
    })
    if (!isCurrentRestoreInitialDocumentRequest(requestSeq, requestSheetId, requestWorkbookId)) {
      return
    }
    if (!remote) {
      if (!shouldPreserveContent || shouldClearOnError) {
        sheetContentReady.value = false
        loadedSheetContentIdentity = ''
        resetHotInitialGridRowsLoaded()
      }
      emit('missing', requestSheetId)
      return
    }

    remoteAccessCapabilities.value = remote.access?.capabilities ?? null
    if (!canPersistSheet.value) {
      localDraft = null
      clearDraftStorage()
    }

    applyPaginationState(remote.pagination)
    markBootPerf('note-sheet-workspace.normalize.start')
    let remoteDocument = normalizeSheetDocument(remote.document_json, {}, getDefaultSheetHeightMode())
    trace?.mark('normalize')
    markBootPerf('note-sheet-workspace.normalize.end', {
      columns: remoteDocument.columns.length,
      gridRows: remoteDocument.grid_rows?.length ?? null,
      rows: remoteDocument.rows.length,
    })
    const remoteSettings = normalizeSheetViewSettings(remoteDocument.view_settings, remoteDocument.columns.length)
    if (
      paginationPreference
      && paginationPreference.paginate !== remoteSettings.pagination.enabled
    ) {
      remote = await fetchNoteSheetForCurrentView(remoteSettings.pagination.enabled
        ? {
          page: currentPage.value,
          pageSize: remoteSettings.pagination.page_size,
          paginate: true,
          workbookId: requestWorkbookId,
          includeWorkbookContext,
        }
        : {
          paginate: false,
          workbookId: requestWorkbookId,
          includeWorkbookContext,
        })
      trace?.mark('refetch-pagination-mode')
      if (!isCurrentRestoreInitialDocumentRequest(requestSeq, requestSheetId, requestWorkbookId)) {
        return
      }
      if (!remote) {
        if (!shouldPreserveContent || shouldClearOnError) {
          sheetContentReady.value = false
          loadedSheetContentIdentity = ''
          resetHotInitialGridRowsLoaded()
        }
        emit('missing', requestSheetId)
        return
      }
      remoteAccessCapabilities.value = remote.access?.capabilities ?? null
      applyPaginationState(remote.pagination)
      remoteDocument = normalizeSheetDocument(remote.document_json, {}, getDefaultSheetHeightMode())
    }

    if (remote.pagination && pageRowIndexes.value === null && buildActiveSheetQueryFilters().active) {
      remote = await fetchNoteSheetForCurrentView({
        page: currentPage.value,
        pageSize: remote.pagination.page_size,
        paginate: true,
        workbookId: requestWorkbookId,
        includeWorkbookContext,
      })
      trace?.mark('refetch-filtered-page')
      if (!isCurrentRestoreInitialDocumentRequest(requestSeq, requestSheetId, requestWorkbookId)) {
        return
      }
      if (!remote) {
        if (!shouldPreserveContent || shouldClearOnError) {
          sheetContentReady.value = false
          loadedSheetContentIdentity = ''
          resetHotInitialGridRowsLoaded()
        }
        emit('missing', requestSheetId)
        return
      }
      remoteAccessCapabilities.value = remote.access?.capabilities ?? null
      applyPaginationState(remote.pagination)
      remoteDocument = normalizeSheetDocument(remote.document_json, {}, getDefaultSheetHeightMode())
    }

    sheetTitle.value = remote.title || '未命名表格'
    sheetVersion.value = Number(remote.version || 1)
    emitSheetSync(remote)

    let activeDocument = remoteDocument
    let activeSourceDocument: unknown = remote.document_json
    let shouldSyncLocalDraft = false
    if (
      localDraft?.document
      && isSamePagePatchState(localDraft.pageState)
      && isDraftDocumentRowCountCompatibleWithPage(localDraft.document, localDraft.pageState)
    ) {
      const remoteUpdatedAt = normalizeTimestampMs(remote.updated_at)
      const remoteSheetVersion = Number(remote.version || 1)
      const localDraftSheetVersion = Number(localDraft.sheetVersion)
      const localDraftVersionStillCurrent = (
        Number.isFinite(localDraftSheetVersion)
        && localDraftSheetVersion === remoteSheetVersion
      )
      const localDraftIsNewer = localDraft.updatedAt > remoteUpdatedAt
      const localDraftIsMeaningful = hasMeaningfulSheetDocumentContent(localDraft.document)
      const remoteDocumentIsMeaningful = hasMeaningfulSheetDocumentContent(remoteDocument)
      const localDraftHeaderPrefixCompatible = isRemoteHeaderPrefixCompatibleWithLocalDraft(
        localDraft.document,
        remoteDocument,
      )
      const localDraftPreservesRemoteLinks = isDraftPreservingRemoteCellLinks(
        localDraft.document,
        remoteDocument,
      )
      if (
        localDraftVersionStillCurrent
        && localDraftIsNewer
        && localDraftHeaderPrefixCompatible
        && localDraftPreservesRemoteLinks
        && (localDraftIsMeaningful || !remoteDocumentIsMeaningful)
      ) {
        activeDocument = mergeRemoteHeaderPrefixIntoLocalDraft(localDraft.document, remoteDocument)
        activeSourceDocument = localDraft.document
        sheetTitle.value = localDraft.title || sheetTitle.value
        if (localDraft.pageState) {
          pageRowOffset.value = localDraft.pageState.rowOffset
          pageLoadedRowCount.value = localDraft.pageState.loadedRowCount
          pageRowIndexes.value = localDraft.pageState.rowIndexes ?? null
          pendingDeletedPageRowIndexes.value = localDraft.pageState.deletedRowIndexes ?? []
        }
        shouldSyncLocalDraft = true
      } else {
        clearDraftStorage()
        pendingDeletedPageRowIndexes.value = []
      }
    } else {
      pendingDeletedPageRowIndexes.value = []
    }

    const definedNamesWorkbookId = Number.isInteger(remote.parent_workbook_id)
      ? Number(remote.parent_workbook_id)
      : requestWorkbookId
    const embeddedDefinedNamesContext = getUsableDefinedNamesContext(remote, requestSheetId, definedNamesWorkbookId)
    if (embeddedDefinedNamesContext) {
      syncDefinedNamesFromResponse(embeddedDefinedNamesContext)
      trace?.mark('defined-names-embedded')
    } else {
      scheduleDefinedNamesSyncAfterSheetLoad(requestSeq, requestSheetId, requestWorkbookId, definedNamesWorkbookId)
      trace?.mark('defined-names-deferred')
    }
    if (!isCurrentRestoreInitialDocumentRequest(requestSeq, requestSheetId, requestWorkbookId)) {
      return
    }
    if (sheetDocumentHasFormulaExpressions(activeDocument) && !formulaEngineClass.value) {
      markBootPerf('note-sheet-workspace.formulaEngine.preload.start')
      const formulaEnginePreloadResult = await waitForInitialFormulaEnginePreload(loadFormulaEngineClass())
      trace?.mark(`formula-engine-preload-${formulaEnginePreloadResult}`)
      markBootPerf('note-sheet-workspace.formulaEngine.preload.end', {
        result: formulaEnginePreloadResult,
      })
      if (!isCurrentRestoreInitialDocumentRequest(requestSeq, requestSheetId, requestWorkbookId)) {
        return
      }
    }
    beginSheetCoreRenderPhase()
    markBootPerf('note-sheet-workspace.loadSheetDocument.start')
    loadSheetDocument(activeDocument, activeSourceDocument)
    trace?.mark('load-document')
    markBootPerf('note-sheet-workspace.loadSheetDocument.end', {
      rows: rows.value.length,
      columns: columnHeaders.value.length,
    })
    sheetContentReady.value = true
    loadedSheetContentIdentity = requestContentIdentity
    trace?.mark('content-ready-state')
    markBootPerf('note-sheet-workspace.contentReady')
    scheduleRemoteSheetDetailCacheAfterSheetLoad(remote, {
      workbookId: requestWorkbookId,
      document: remoteDocument,
      sourceDocument: remote.document_json,
    }, () => isCurrentRestoreInitialDocumentRequest(requestSeq, requestSheetId, requestWorkbookId))
    trace?.mark('cache-remote-detail-deferred')
    sheetLoadErrorText.value = ''
    suppressReadOnlyActionWarningsForSheetRender()
    restoreStudentLookupSelectionFromLocalStorage()
    restoreSheetWorkspaceViewFromLocalStorage({
      applyInitialWorkspaceView: options?.applyInitialWorkspaceView === true,
    })
    trace?.mark('restore-local-ui-state')
    changeSerial = 0
    lastQueuedSerial = 0
    savedChangeSerial = 0
    resetLocalUndoHistory()
    invalidateColumnFilterGlobalOptionsCache()
    trace?.mark('reset-runtime-state')
    markBootPerf('note-sheet-workspace.before-nextTick')
    await nextTick()
    trace?.mark('next-tick')
    markBootPerf('note-sheet-workspace.after-nextTick')
    if (!isCurrentRestoreInitialDocumentRequest(requestSeq, requestSheetId, requestWorkbookId)) {
      return
    }
    const initialHotLoadDataResult = await waitForHotInitialGridRowsLoaded('restore-initial-document')
    trace?.mark(`initial-hot-load-data-${initialHotLoadDataResult}`)
    markBootPerf('note-sheet-workspace.initialHotLoadData.result', {
      result: initialHotLoadDataResult,
    })
    if (!isCurrentRestoreInitialDocumentRequest(requestSeq, requestSheetId, requestWorkbookId)) {
      return
    }
    scheduleSheetRenderEnhancement(() => isCurrentRestoreInitialDocumentRequest(
      requestSeq,
      requestSheetId,
      requestWorkbookId,
    ))
    suppressPersistence = false

    if (shouldSyncLocalDraft) {
      scheduleRemoteSave(0)
    }
    scheduleInitialSheetActionStatusRefresh()
  } catch (error) {
    const status = getNoteSheetApiErrorStatus(error)
    const message = status === 401 || status === 403
      ? '没有权限访问该工作表'
      : '工作表加载失败'
    if (!isCurrentRestoreInitialDocumentRequest(requestSeq, requestSheetId, requestWorkbookId)) {
      return
    }
    if (!shouldPreserveContent || shouldClearOnError) {
      sheetContentReady.value = false
      loadedSheetContentIdentity = ''
      resetHotInitialGridRowsLoaded()
    }
    sheetLoadErrorText.value = message
    console.warn('Failed to load note sheet document:', error)
    emit('loadError', {
      sheetId: requestSheetId,
      status,
      message,
    })
  } finally {
    const isCurrentRequest = isCurrentRestoreInitialDocumentRequest(requestSeq, requestSheetId, requestWorkbookId)
    if (isCurrentRequest) {
      suppressPersistence = false
    }
    if (isCurrentRequest && (!shouldPreserveContent || shouldClearOnError)) {
      sheetLoadSettled.value = true
    }
    if (isCurrentRequest && !sheetContentReady.value) {
      finishSheetRenderEnhancement()
    }
    if (isCurrentRequest) {
      workspaceLoading.value = false
    }
    markBootPerf('note-sheet-workspace.restore.finally', {
      current: isCurrentRequest,
      contentReady: sheetContentReady.value,
      rows: rows.value.length,
      columns: columnHeaders.value.length,
      workspaceLoading: workspaceLoading.value,
    })
    trace?.finish({
      detail: {
        ...traceDetail,
        stale: !isCurrentRequest,
        rowCount: rows.value.length,
        columnCount: columnHeaders.value.length,
        currentPage: currentPage.value,
        pageSize: pageSize.value,
        pageRowOffset: pageRowOffset.value,
        totalRowCount: totalRowCount.value,
        filteredPage: pageRowIndexes.value !== null,
      },
    })
  }
}

async function handlePageChange(nextPage: number) {
  if (!effectivePaginationEnabled.value) {
    return
  }

  const normalizedPage = normalizePositivePageNumber(nextPage, currentPage.value)
  if (normalizedPage === currentPage.value || props.sheetId == null || workspaceLoading.value) {
    return
  }

  await flushRemoteSave()
  currentPage.value = normalizedPage
  await restoreInitialDocument()
  void updateSheetViewportHeight()
}

function normalizeSheetGridChanges(changes: unknown): SheetGridChangeRecord[] {
  if (!Array.isArray(changes)) {
    return []
  }

  return changes
    .map((change) => {
      if (!Array.isArray(change) || change.length < 4) {
        return null
      }
      const rowIndex = Number(change[0])
      const hotColumnIndex = Number(change[1])
      const columnIndex = toSheetColumnIndex(hotColumnIndex)
      if (
        !Number.isInteger(rowIndex)
        || !Number.isInteger(hotColumnIndex)
        || rowIndex < 0
        || columnIndex < 0
      ) {
        return null
      }
      return {
        rowIndex,
        hotColumnIndex,
        columnIndex,
        previousValue: change[2],
        nextValue: change[3],
      } satisfies SheetGridChangeRecord
    })
    .filter((record): record is SheetGridChangeRecord => !!record)
}

function hasEffectiveSheetGridChanges(changes: unknown) {
  return normalizeSheetGridChanges(changes).some((record) => (
    normalizeCellValue(record.previousValue) !== normalizeCellValue(record.nextValue)
  ))
}

function isImmediateCellPatchSource(source?: string) {
  return (
    source == null
    || source === 'edit'
    || source === 'CopyPaste.cut'
    || source === 'CopyPaste.paste'
    || source === 'Autofill.fill'
    || source === 'formula-bar'
    || source === 'row-detail'
    || source === 'UndoRedo.undo'
    || source === 'UndoRedo.redo'
  )
}

function buildImmediateCellPatchOperations(records: SheetGridChangeRecord[], source?: string) {
  if (!isImmediateCellPatchSource(source)) {
    return null
  }

  const operations: NoteSheetPatchOperation[] = []
  for (const record of records) {
    if (normalizeCellValue(record.previousValue) === normalizeCellValue(record.nextValue)) {
      continue
    }
    if (isSheetHeaderGridRow(record.rowIndex)) {
      return null
    }
    if (!canEditDataColumn(record.columnIndex)) {
      return null
    }
    const dataRow = getDataRowIndex(record.rowIndex)
    if (dataRow < 0) {
      return null
    }
    const merge = findMergedCellAtGridCell(record.rowIndex, record.columnIndex)
    if (merge && (merge.rowspan > 1 || merge.colspan > 1)) {
      return null
    }
    operations.push({
      op: 'set-cell-value',
      row_index: getDocumentRowIndex(dataRow),
      column_index: record.columnIndex,
      value: normalizeCellInputValueForColumn(record.nextValue, record.columnIndex),
    })
  }

  return operations.length ? operations : []
}

function queueImmediateSheetPatchSave(operations: NoteSheetPatchOperation[], failureMessage = '表格保存失败，已保留本地草稿') {
  if (props.sheetId == null || !operations.length) {
    return
  }
  const sheetId = props.sheetId
  const workbookId = props.workbookId
  persistDraftDocument(buildCurrentDocument())
  changeSerial += 1
  lastQueuedSerial = changeSerial
  const serial = changeSerial
  invalidateColumnFilterGlobalOptionsCache()
  if (sheetRemoteConflictActive) {
    ElMessage.warning('工作表已被其他人更新，已保留本地草稿，请刷新后合并')
    return
  }
  cellPatchQueue = cellPatchQueue
    .catch(() => undefined)
    .then(async () => {
      cellPatchInFlight = true
      const result = await patchNoteSheet(
        sheetId,
        {
          base_version: Number(sheetVersion.value || 1),
          ops: operations,
        },
        {
          workbookId,
        },
      )
      sheetVersion.value = Number(result.version || sheetVersion.value || 1)
      savedChangeSerial = Math.max(savedChangeSerial, serial)
      sheetRemoteConflictActive = false
      if (serial === changeSerial) {
        clearDraftStorage()
      } else {
        persistDraftDocument(buildCurrentDocument())
      }
    })
    .catch((error) => {
      console.warn('Failed to patch note sheet', error)
      persistDraftDocument(buildCurrentDocument())
      if (getNoteSheetApiErrorStatus(error) === 409) {
        sheetRemoteConflictActive = true
        ElMessage.warning('工作表已被其他人更新，已保留本地草稿，请刷新后合并')
      } else {
        ElMessage.error(failureMessage)
      }
    })
    .finally(() => {
      cellPatchInFlight = false
    })
}

function queueImmediateCellPatchSave(operations: NoteSheetPatchOperation[]) {
  queueImmediateSheetPatchSave(operations, '单元格保存失败，已保留本地草稿')
}

function queueImmediateColumnConfigPatchSave(operations: NoteSheetPatchOperation[]) {
  queueImmediateSheetPatchSave(operations, '字段设置保存失败，已保留本地草稿')
}

function queueImmediateMergePatchSave(operations: NoteSheetPatchOperation[]) {
  queueImmediateSheetPatchSave(operations, '合并单元格保存失败，已保留本地草稿')
}

function buildCellMetaPatchOperations(results: Array<SheetCellMetaPatchResult | null | undefined>) {
  const operations: NoteSheetPatchOperation[] = []
  results.forEach((result) => {
    if (!result) {
      return
    }
    const dataRowIndex = result.documentRow - sheetHeaderRowCount.value
    if (dataRowIndex < 0) {
      return
    }
    operations.push({
      op: 'set-cell-meta',
      row_index: dataRowIndex,
      column_index: result.column,
      meta: result.meta ? { ...result.meta } : {},
    })
  })
  return operations
}

function queueImmediateCellMetaPatchSave(results: Array<SheetCellMetaPatchResult | null | undefined>) {
  const hasMetaChanges = results.some((result) => !!result)
  const operations = buildCellMetaPatchOperations(results)
  if (!operations.length) {
    if (hasMetaChanges) {
      scheduleRemoteSave(0)
    }
    return
  }
  queueImmediateSheetPatchSave(operations, '单元格格式保存失败，已保留本地草稿')
}

function buildDataCellValuePatchOperation(documentRow: number, columnIndex: number, value: unknown) {
  const dataRowIndex = documentRow - sheetHeaderRowCount.value
  if (dataRowIndex < 0 || !canEditDataColumn(columnIndex)) {
    return null
  }
  return {
    op: 'set-cell-value',
    row_index: dataRowIndex,
    column_index: columnIndex,
    value,
  } satisfies NoteSheetPatchOperation
}

function queueImmediateDataCellValueAndMetaPatchSave(
  documentRow: number,
  columnIndex: number,
  value: unknown,
  metaResult: SheetCellMetaPatchResult | null | undefined,
  valueChanged: boolean,
  failureMessage = '单元格保存失败，已保留本地草稿',
) {
  const operations: NoteSheetPatchOperation[] = []
  if (valueChanged) {
    const valueOperation = buildDataCellValuePatchOperation(documentRow, columnIndex, value)
    if (!valueOperation) {
      scheduleRemoteSave(0)
      return
    }
    operations.push(valueOperation)
  }
  operations.push(...buildCellMetaPatchOperations([metaResult]))
  if (operations.length) {
    queueImmediateSheetPatchSave(operations, failureMessage)
  } else if (metaResult) {
    scheduleRemoteSave(0)
  }
}

function buildColumnConfigPatchOperation(columnIndex: number): NoteSheetPatchOperation | null {
  const header = columnHeaders.value[columnIndex]
  if (!header) {
    return null
  }
  return {
    op: 'set-column-config',
    column_index: columnIndex,
    config: normalizeColumnConfigs(columnConfigs.value, columnHeaders.value)[header] ?? {},
  }
}

function clearSelectedEditableDataCellsFromKeyboard(event: KeyboardEvent) {
  if (event.key !== 'Delete' && event.key !== 'Backspace') {
    return false
  }
  if (event.ctrlKey || event.metaKey || event.altKey || getActiveOpenedEditor()) {
    return false
  }

  const cells = getSelectedDataCells()
  if (!cells.length || cells.some((cell) => !canEditDataColumn(cell.column))) {
    return false
  }

  const operations: NoteSheetPatchOperation[] = []
  const nextRows = rows.value.map((row) => normalizeRow(row, columnHeaders.value))
  let changed = false
  for (const cell of cells) {
    const currentValue = normalizeCellValue(nextRows[cell.row]?.[cell.column] ?? '')
    if (!currentValue) {
      continue
    }
    if (!nextRows[cell.row]) {
      nextRows[cell.row] = createEmptyRow(columnHeaders.value.length)
    }
    nextRows[cell.row][cell.column] = ''
    operations.push({
      op: 'set-cell-value',
      row_index: getDocumentRowIndex(cell.row),
      column_index: cell.column,
      value: '',
    })
    changed = true
  }

  if (!changed) {
    event.preventDefault()
    event.stopImmediatePropagation()
    return true
  }

  pushLocalUndoSnapshot('cell-clear')
  suppressNextRemoteSaveWatcher = true
  rows.value = nextRows
  refreshFormulaDisplayState()
  syncFormulaBarDraftFromSelectedCell(true)
  const hot = getHotInstance()
  loadCurrentHotGridRows(hot)
  renderHotWithReason(hot, 'cell-clear')
  queueImmediateCellPatchSave(operations)
  event.preventDefault()
  event.stopImmediatePropagation()
  return true
}

function clearCoveredMergedCellValuesInRows(nextRows: SheetRow[], merge: SheetMergedCell) {
  for (let documentRow = merge.row; documentRow < merge.row + merge.rowspan; documentRow += 1) {
    const gridRow = getCurrentGridRowIndexFromDocumentRow(documentRow)
    const dataRow = getDataRowIndex(gridRow)
    if (dataRow < 0 || dataRow >= nextRows.length) {
      continue
    }
    if (!nextRows[dataRow]) {
      nextRows[dataRow] = createEmptyRow(columnHeaders.value.length)
    }
    for (let column = merge.col; column < merge.col + merge.colspan; column += 1) {
      if (documentRow === merge.row && column === merge.col) {
        continue
      }
      if (column >= 0 && column < columnHeaders.value.length) {
        nextRows[dataRow][column] = ''
      }
    }
  }
}

function syncCoveredMergedCellChangesToAnchors(changes: unknown) {
  const records = normalizeSheetGridChanges(changes)
  if (!records.length) {
    return false
  }

  let changed = false
  const nextRows = rows.value.map((row) => normalizeRow(row, columnHeaders.value))
  records.forEach((record) => {
    const merge = findMergedCellAtGridCell(record.rowIndex, record.columnIndex)
    if (!merge || (merge.rowspan <= 1 && merge.colspan <= 1)) {
      return
    }

    const anchor = getMergeAnchorForGridCell(record.rowIndex, record.columnIndex)
    const nextValue = normalizeCellValue(record.nextValue)
    if (isSheetHeaderGridRow(anchor.row)) {
      changed = applySheetHeaderGridChange(anchor.row, anchor.column, nextValue) || changed
      return
    }

    const targetDataRow = getDataRowIndex(anchor.row)
    if (targetDataRow < 0 || anchor.column < 0 || anchor.column >= columnHeaders.value.length) {
      return
    }

    if (!nextRows[targetDataRow]) {
      nextRows[targetDataRow] = createEmptyRow(columnHeaders.value.length)
    }
    nextRows[targetDataRow][anchor.column] = normalizeCellInputValueForColumn(nextValue, anchor.column)
    clearCoveredMergedCellValuesInRows(nextRows, merge)

    const sourceDataRow = getDataRowIndex(record.rowIndex)
    if (
      sourceDataRow >= 0
      && sourceDataRow < nextRows.length
      && record.columnIndex >= 0
      && record.columnIndex < columnHeaders.value.length
      && (sourceDataRow !== targetDataRow || record.columnIndex !== anchor.column)
    ) {
      nextRows[sourceDataRow][record.columnIndex] = ''
    }
    changed = true
  })

  if (changed) {
    rows.value = nextRows
  }
  return changed
}

function clearRichTextForGridChanges(changes: unknown, source?: string) {
  if (
    source === 'loadData'
    || source === 'external-update'
    || source === 'MergeCells'
    || source === 'rich-text-dialog'
    || source === 'rich-text-inline'
  ) {
    return []
  }

  const records = normalizeSheetGridChanges(changes)
  const metaPatchResults: SheetCellMetaPatchResult[] = []
  records.forEach((record) => {
    const previousValue = normalizeCellValue(record.previousValue)
    const nextValue = normalizeCellValue(record.nextValue)
    if (previousValue === nextValue && !isFormulaExpression(nextValue)) {
      return
    }
    if (isFormulaExpression(nextValue)) {
      const result = clearCellRichTextFormat(getDocumentGridRowIndex(record.rowIndex), record.columnIndex)
      if (result) {
        metaPatchResults.push(result)
      }
    } else {
      const result = clearCellRichText(getDocumentGridRowIndex(record.rowIndex), record.columnIndex)
      if (result) {
        metaPatchResults.push(result)
      }
    }
  })
  return metaPatchResults
}

function handleAfterChange(_changes: unknown, source?: string) {
  if (source === 'loadData' || source === 'external-update' || source === 'MergeCells') {
    return
  }
  const changeRecords = normalizeSheetGridChanges(_changes)
  const hasEffectiveChanges = changeRecords.some((record) => (
    normalizeCellValue(record.previousValue) !== normalizeCellValue(record.nextValue)
  ))
  const immediateCellPatchOperations = buildImmediateCellPatchOperations(changeRecords, source)
  finishFormulaReferenceRange()
  clearFormulaReferencePreviewRange()
  const metaPatchResults = [
    ...clearRichTextForGridChanges(_changes, source),
    ...clearLinksForCutGridChanges(changeRecords, source),
    ...consumePendingClipboardLinkMetaPatchResults(),
  ]
  syncRowsFromGrid()
  const mergedAnchorSynced = syncCoveredMergedCellChangesToAnchors(_changes)
  const registrationDefaultsUpdated = handleRegistrationSubmittedAtUserChanges(_changes, source)
  refreshFormulaDisplayState()
  syncFormulaBarDraftFromSelectedCell()
  if (mergedAnchorSynced || registrationDefaultsUpdated) {
    refreshGridStructure()
  } else {
    renderCurrentHotWithReason('cell-change')
  }
  if (hasEffectiveChanges || metaPatchResults.length) {
    if (immediateCellPatchOperations && !mergedAnchorSynced && !registrationDefaultsUpdated) {
      suppressNextRemoteSaveWatcher = true
      queueImmediateCellPatchSave([
        ...immediateCellPatchOperations,
        ...buildCellMetaPatchOperations(metaPatchResults),
      ])
    } else if (source === 'rich-text-inline' || source === 'rich-text-dialog') {
      // Rich text commit paths explicitly save value + meta as one patch.
    } else {
      scheduleRemoteSave(0)
    }
  }
}

function readCopyPasteRangeNumber(record: Record<string, unknown>, keys: string[]) {
  for (const key of keys) {
    const value = Number(record[key])
    if (Number.isInteger(value)) {
      return value
    }
  }
  return null
}

function normalizeCopyPasteRange(coord: unknown): SheetCopyPasteRange | null {
  if (!coord || typeof coord !== 'object') {
    return null
  }

  const record = coord as Record<string, unknown>
  const startRow = readCopyPasteRangeNumber(record, ['startRow', 'fromRow', 'row'])
  const endRow = readCopyPasteRangeNumber(record, ['endRow', 'toRow', 'row'])
  const startColumn = readCopyPasteRangeNumber(record, ['startCol', 'startColumn', 'fromCol', 'fromColumn', 'col', 'column'])
  const endColumn = readCopyPasteRangeNumber(record, ['endCol', 'endColumn', 'toCol', 'toColumn', 'col', 'column'])
  if (startRow == null || endRow == null || startColumn == null || endColumn == null) {
    return null
  }

  return {
    startRow: Math.min(startRow, endRow),
    endRow: Math.max(startRow, endRow),
    startColumn: Math.min(startColumn, endColumn),
    endColumn: Math.max(startColumn, endColumn),
  }
}

function isMatrix(value: unknown): value is unknown[][] {
  return Array.isArray(value) && value.every((row) => Array.isArray(row))
}

function stringifyCopyPasteMatrix(matrix: unknown[][]) {
  return matrix.map((row) => row.map((cell) => normalizeCellValue(cell)))
}

function areCopyPasteMatricesEqual(left: string[][], right: unknown[][]) {
  if (left.length !== right.length) {
    return false
  }
  return left.every((leftRow, rowIndex) => {
    const rightRow = right[rowIndex]
    return Array.isArray(rightRow)
      && leftRow.length === rightRow.length
      && leftRow.every((leftCell, columnIndex) => leftCell === normalizeCellValue(rightRow[columnIndex]))
  })
}

function cloneClipboardLinkMeta(documentRow: number, columnIndex: number): SheetCellMeta | null {
  const link = getCellLinkAt(documentRow, columnIndex)
  return link ? { link: { ...link } } : null
}

function consumePendingClipboardLinkMetaPatchResults() {
  const results = pendingClipboardLinkMetaPatchResults
  pendingClipboardLinkMetaPatchResults = []
  return results
}

function clearLinksForCutGridChanges(records: SheetGridChangeRecord[], source?: string) {
  if (source !== 'CopyPaste.cut') {
    return []
  }

  const results: SheetCellMetaPatchResult[] = []
  records.forEach((record) => {
    if (normalizeCellValue(record.nextValue)) {
      return
    }
    const documentRow = getDocumentGridRowIndex(record.rowIndex)
    if (!getCellLinkAt(documentRow, record.columnIndex)) {
      return
    }
    const result = updateCellMetaEntry(documentRow, record.columnIndex, (entry) => {
      const nextEntry = { ...entry }
      delete nextEntry.link
      return nextEntry
    })
    if (result) {
      results.push(result)
    }
  })
  return results
}

function applyClipboardLinksToPasteTarget(clipboard: SheetInternalClipboard, targetDataStartRow: number, targetStartColumn: number, data: unknown[][]) {
  const results: SheetCellMetaPatchResult[] = []
  data.forEach((row, rowOffset) => {
    if (!Array.isArray(row)) {
      return
    }
    row.forEach((_, columnOffset) => {
      const sourceMeta = clipboard.linkMetaData[rowOffset]?.[columnOffset] ?? null
      const targetDataRow = targetDataStartRow + rowOffset
      const targetColumn = targetStartColumn + columnOffset
      if (targetColumn < 0 || targetColumn >= columnHeaders.value.length) {
        return
      }
      const targetDocumentRow = getDocumentGridRowIndexForDataRow(targetDataRow)
      if (targetDocumentRow < sheetHeaderRowCount.value) {
        return
      }
      const currentLink = getCellLinkAt(targetDocumentRow, targetColumn)
      if (!sourceMeta?.link && !currentLink) {
        return
      }
      if (
        sourceMeta?.link
        && currentLink
        && currentLink.url === sourceMeta.link.url
        && normalizeCellValue(currentLink.title) === normalizeCellValue(sourceMeta.link.title)
      ) {
        return
      }
      const result = updateCellMetaEntry(targetDocumentRow, targetColumn, (entry) => {
        const nextEntry = { ...entry }
        if (sourceMeta?.link) {
          nextEntry.link = { ...sourceMeta.link }
        } else {
          delete nextEntry.link
        }
        return nextEntry
      })
      if (result) {
        results.push(result)
      }
    })
  })
  return results
}

function handleBeforeCopy(data: unknown[][], coords: unknown[], mode: SheetClipboardMode = 'copy') {
  const rejectCut = () => {
    sheetInternalClipboard = null
    return mode === 'cut' ? false : undefined
  }

  if (!isMatrix(data) || data.length <= 0 || !Array.isArray(coords) || coords.length <= 0) {
    return rejectCut()
  }

  const range = normalizeCopyPasteRange(coords[0])
  if (!range) {
    return rejectCut()
  }
  const sheetColumnRange = getSheetColumnRangeFromHotRange(range.startColumn, range.endColumn)
  if (!sheetColumnRange) {
    return rejectCut()
  }
  const documentRange = {
    startRow: getDocumentGridRowIndex(range.startRow),
    endRow: getDocumentGridRowIndex(range.endRow),
    startColumn: sheetColumnRange.start,
    endColumn: sheetColumnRange.end,
  }
  const visibleData = data.map((row, rowOffset) => (
    row.map((_, columnOffset) => {
      const gridRow = range.startRow + rowOffset
      const hotColumn = range.startColumn + columnOffset
      if (isRowMarkerHotColumn(hotColumn)) {
        return getSheetRowHeaderLabel(gridRow)
      }
      const column = toSheetColumnIndex(hotColumn)
      if (column < 0) {
        return ''
      }
      const anchor = getMergeAnchorForGridCell(gridRow, column)
      return anchor.row === gridRow && anchor.column === column
        ? getCellDisplayText(getDataRowIndex(anchor.row), anchor.column, getGridCellRawValue(anchor.row, anchor.column))
        : ''
    })
  ))

  if (
    range.startRow < sheetHeaderRowCount.value
    || hotRangeIncludesRowMarker(range.startColumn, range.endColumn)
    || rangePartiallyIntersectsMergedCells(documentRange)
  ) {
    if (mode === 'cut') {
      sheetInternalClipboard = null
      return false
    }
    visibleData.forEach((row, rowIndex) => {
      row.forEach((cell, columnIndex) => {
        if (Array.isArray(data[rowIndex])) {
          data[rowIndex][columnIndex] = cell
        }
      })
    })
    return
  }

  const rawData = data.map((row, rowOffset) => (
    row.map((_, columnOffset) => {
      const sourceRow = getDataRowIndex(range.startRow + rowOffset)
      const sourceColumn = sheetColumnRange.start + columnOffset
      return getRawCellValue(sourceRow, sourceColumn)
    })
  ))
  const displayData = rawData.map((row, rowOffset) => (
    row.map((rawValue, columnOffset) => {
      const sourceRow = getDataRowIndex(range.startRow + rowOffset)
      const sourceColumn = sheetColumnRange.start + columnOffset
      return getCellDisplayText(sourceRow, sourceColumn, rawValue)
    })
  ))
  const linkMetaData = rawData.map((row, rowOffset) => (
    row.map((_, columnOffset) => (
      cloneClipboardLinkMeta(
        getDocumentGridRowIndex(range.startRow + rowOffset),
        sheetColumnRange.start + columnOffset,
      )
    ))
  ))

  sheetInternalClipboard = {
    sheetId: props.sheetId,
    mode,
    sourceStartRow: getDataRowIndex(range.startRow),
    sourceStartColumn: sheetColumnRange.start,
    rawData,
    displayData,
    linkMetaData,
    createdAt: Date.now(),
  }

  displayData.forEach((row, rowIndex) => {
    if (!Array.isArray(data[rowIndex])) {
      return
    }
    row.forEach((cell, columnIndex) => {
      data[rowIndex][columnIndex] = cell
    })
  })
  return true
}

function getInternalClipboardForPaste(data: unknown[][]) {
  if (!sheetInternalClipboard || sheetInternalClipboard.sheetId !== props.sheetId) {
    return null
  }
  if (Date.now() - sheetInternalClipboard.createdAt > 5 * 60 * 1000) {
    sheetInternalClipboard = null
    return null
  }
  if (
    !areCopyPasteMatricesEqual(sheetInternalClipboard.displayData, data)
    && !areCopyPasteMatricesEqual(sheetInternalClipboard.rawData, data)
  ) {
    return null
  }
  return sheetInternalClipboard
}

function handleBeforeCut(data: unknown[][], coords: unknown[]) {
  if (!canEditData.value && !canEditPartialData.value) {
    warnReadOnlyAction()
    return false
  }
  return handleBeforeCopy(data, coords, 'cut')
}

function getGridRowCountForExpansionGuard() {
  const hot = getHotInstance()
  return Math.max(rows.value.length, (hot?.countSourceRows() ?? sheetHeaderRowCount.value) - sheetHeaderRowCount.value)
}

function isPagedRowExpansionAllowed(requiredEndRow: number) {
  if (!effectivePaginationEnabled.value) {
    return true
  }
  if (!Number.isInteger(requiredEndRow) || requiredEndRow < 0) {
    return true
  }

  const currentRowCount = getGridRowCountForExpansionGuard()
  if (requiredEndRow < currentRowCount) {
    return true
  }

  return currentPage.value >= pageCount.value
}

function ensurePagedRowExpansionAllowed(requiredEndRow: number, message = PAGED_ROW_EXPANSION_MESSAGE) {
  if (isPagedRowExpansionAllowed(requiredEndRow)) {
    return true
  }

  ElMessage.error(message)
  return false
}

function getPasteRequiredEndRow(data: unknown[][], targetRange: SheetCopyPasteRange) {
  const pastedRowCount = data.length
  const selectionRowCount = targetRange.endRow - targetRange.startRow + 1
  const targetRowCount = Math.max(pastedRowCount, selectionRowCount)
  return targetRange.startRow + targetRowCount - 1
}

function getPasteRequiredEndColumn(data: unknown[][], targetRange: SheetCopyPasteRange) {
  const pastedColumnCount = Math.max(0, ...data.map((row) => row.length))
  const selectionColumnCount = targetRange.endColumn - targetRange.startColumn + 1
  const targetColumnCount = Math.max(pastedColumnCount, selectionColumnCount)
  return targetRange.startColumn + targetColumnCount - 1
}

function shouldGuardBulkRowExpansionSource(source?: string) {
  return source === 'CopyPaste.paste' || source === 'Autofill.fill'
}

function getChangesRequiredEndRow(changes: unknown[]) {
  let endRow = -1
  for (const change of changes) {
    if (!Array.isArray(change) || change.length < 4) {
      continue
    }

    const rowIndex = Number(change[0])
    if (Number.isInteger(rowIndex)) {
      const dataRowIndex = getDataRowIndex(rowIndex)
      if (dataRowIndex >= 0) {
        endRow = Math.max(endRow, dataRowIndex)
      }
    }
  }
  return endRow
}

function areChangedColumnsEditable(changes: unknown[]) {
  if (canEditData.value) {
    return true
  }
  for (const change of changes) {
    if (!Array.isArray(change) || change.length < 4) {
      continue
    }

    const hotColumnIndex = Number(change[1])
    const columnIndex = toSheetColumnIndex(hotColumnIndex)
    if (!Number.isInteger(hotColumnIndex) || columnIndex < 0) {
      continue
    }
    if (!editableDataColumnSet.value.has(columnIndex)) {
      return false
    }
  }
  return true
}

function handleBeforePaste(data: unknown[][], coords: unknown[]) {
  pendingClipboardLinkMetaPatchResults = []
  if (!canEditData.value && !canEditPartialData.value) {
    warnReadOnlyAction()
    return false
  }

  if (!isMatrix(data) || !Array.isArray(coords) || coords.length <= 0) {
    return
  }

  const clipboard = getInternalClipboardForPaste(data)
  const targetRange = normalizeCopyPasteRange(coords[0])
  if (!targetRange) {
    return
  }
  const targetColumnRange = getSheetColumnRangeFromHotRange(targetRange.startColumn, targetRange.endColumn)
  if (!targetColumnRange || hotRangeIncludesRowMarker(targetRange.startColumn, targetRange.endColumn)) {
    warnReadOnlyAction()
    return false
  }
  const targetSheetRange = {
    ...targetRange,
    startColumn: targetColumnRange.start,
    endColumn: targetColumnRange.end,
  }
  if (targetRange.startRow < sheetHeaderRowCount.value) {
    warnReadOnlyAction()
    return false
  }
  const targetDocumentRange = {
    startRow: getDocumentGridRowIndex(targetRange.startRow),
    endRow: getDocumentGridRowIndex(targetRange.endRow),
    startColumn: targetSheetRange.startColumn,
    endColumn: getPasteRequiredEndColumn(data, targetSheetRange),
  }
  if (rangePartiallyIntersectsMergedCells(targetDocumentRange)) {
    ElMessage.warning('粘贴范围不能只覆盖合并单元格的一部分')
    return false
  }
  const targetDataStartRow = getDataRowIndex(targetRange.startRow)
  const targetDataRange = {
    ...targetSheetRange,
    startRow: targetDataStartRow,
    endRow: getDataRowIndex(targetRange.endRow),
  }
  if (!isColumnRangeEditable(targetSheetRange.startColumn, getPasteRequiredEndColumn(data, targetSheetRange))) {
    warnReadOnlyColumnAction()
    return false
  }
  if (!canEditData.value && getPasteRequiredEndRow(data, targetDataRange) >= getGridRowCountForExpansionGuard()) {
    warnReadOnlyAction()
    return false
  }
  if (!ensurePagedRowExpansionAllowed(getPasteRequiredEndRow(data, targetDataRange))) {
    return false
  }
  if (!clipboard) {
    return
  }
  pendingClipboardLinkMetaPatchResults = applyClipboardLinksToPasteTarget(
    clipboard,
    targetDataStartRow,
    targetSheetRange.startColumn,
    data,
  )

  clipboard.rawData.forEach((row, rowOffset) => {
    if (!Array.isArray(data[rowOffset])) {
      return
    }
    row.forEach((rawValue, columnOffset) => {
      const sourceRow = clipboard.sourceStartRow + rowOffset
      const sourceColumn = clipboard.sourceStartColumn + columnOffset
      const targetRow = targetDataStartRow + rowOffset
      const targetColumn = targetSheetRange.startColumn + columnOffset
      data[rowOffset][columnOffset] = isFormulaExpression(rawValue)
        ? shiftFormulaCellReferences(rawValue, targetRow - sourceRow, targetColumn - sourceColumn)
        : rawValue
    })
  })
}

function shouldTrimWhitespaceForColumn(columnIndex: number) {
  const header = columnHeaders.value[columnIndex]
  if (!header) {
    return true
  }
  return normalizeColumnConfig(columnConfigs.value[header]).trim_whitespace
}

function getColumnValueType(columnIndex: number) {
  const header = columnHeaders.value[columnIndex]
  if (!header) {
    return 'text'
  }
  return normalizeColumnConfig(columnConfigs.value[header]).value_type
}

function normalizeCellInputValueForColumn(value: string, columnIndex: number) {
  const valueType = getColumnValueType(columnIndex)
  const trimmedValue = shouldTrimWhitespaceForColumn(columnIndex) ? value.trim() : value
  if (isFormulaExpression(trimmedValue)) {
    return normalizeFormulaInputExpression(trimmedValue)
  }
  if (valueType === 'multi_text') {
    return normalizeMultiTextValue(trimmedValue)
  }
  if (valueType === 'date') {
    return normalizeDateInputValue(trimmedValue)
  }
  if (valueType === 'percent') {
    return normalizePercentInputValue(trimmedValue)
  }
  return trimmedValue
}

function getHeaderColumnIndex(header: string) {
  return columnHeaders.value.findIndex((column) => normalizeCellValue(column).trim() === header)
}

function isRegistrationSubmittedAtDefaultEnabled() {
  const headers = new Set(columnHeaders.value.map((column) => normalizeCellValue(column).trim()))
  return (
    headers.has(STUDENT_LOOKUP_SUBMITTED_AT_HEADER)
    && headers.has(STUDENT_LOOKUP_REAL_NAME_HEADER)
    && (headers.has('微信昵称') || headers.has(STUDENT_LOOKUP_NICKNAME_HEADER))
    && (headers.has('手机号') || headers.has('微信支付订单号'))
  )
}

function padDateTimePart(value: number) {
  return String(value).padStart(2, '0')
}

function formatLocalDateTimeForRegistrationInput(value: Date) {
  return `${value.getFullYear()}/${padDateTimePart(value.getMonth() + 1)}/${padDateTimePart(value.getDate())} ${padDateTimePart(value.getHours())}:${padDateTimePart(value.getMinutes())}`
}

function formatLocalDateForRegistrationMeta(value: Date) {
  return `${value.getFullYear()}-${padDateTimePart(value.getMonth() + 1)}-${padDateTimePart(value.getDate())}`
}

function formatLocalDateTimeForRegistrationMeta(value: Date) {
  return `${formatLocalDateForRegistrationMeta(value)} ${padDateTimePart(value.getHours())}:${padDateTimePart(value.getMinutes())}:${padDateTimePart(value.getSeconds())}`
}

function createLocalDateFromFormulaParts(parts: FormulaDateParts) {
  return new Date(
    parts.year,
    parts.month - 1,
    parts.day,
    parts.hour ?? 0,
    parts.minute ?? 0,
    parts.second ?? 0,
  )
}

function addLocalMonths(value: Date, months: number) {
  const next = new Date(value)
  const targetMonth = next.getMonth() + months
  const originalDate = next.getDate()
  next.setDate(1)
  next.setMonth(targetMonth)
  const maxDate = new Date(next.getFullYear(), next.getMonth() + 1, 0).getDate()
  next.setDate(Math.min(originalDate, maxDate))
  return next
}

function getRegistrationCutoffDate(now = new Date()) {
  const cutoff = addLocalMonths(new Date(now.getFullYear(), now.getMonth(), now.getDate()), -2)
  cutoff.setHours(0, 0, 0, 0)
  return cutoff
}

function getRegistrationSubmittedAtDate(value: unknown) {
  const parts = parseDateDisplayValue(value)
  return parts ? createLocalDateFromFormulaParts(parts) : null
}

function createDefaultRegistrationSubmittedAtValue(now = new Date()) {
  return normalizeDateInputValue(formatLocalDateTimeForRegistrationInput(now))
}

function applyRegistrationTrackingValuesToRow(row: SheetRow, submittedAtValue: unknown, now = new Date()) {
  const groupColumn = getHeaderColumnIndex(REGISTRATION_TRACKING_GROUP_HEADER)
  const statusColumn = getHeaderColumnIndex(REGISTRATION_TRACKING_STATUS_HEADER)
  const deadlineColumn = getHeaderColumnIndex(REGISTRATION_TRACKING_DEADLINE_HEADER)
  const frozenAtColumn = getHeaderColumnIndex(REGISTRATION_TRACKING_FROZEN_AT_HEADER)
  if (groupColumn < 0 && statusColumn < 0 && deadlineColumn < 0 && frozenAtColumn < 0) {
    return false
  }

  let changed = false
  const setCell = (column: number, value: string) => {
    if (column < 0 || column >= row.length || normalizeCellValue(row[column]) === value) {
      return
    }
    row[column] = value
    changed = true
  }

  const submittedAt = getRegistrationSubmittedAtDate(submittedAtValue)
  if (!submittedAt) {
    setCell(groupColumn, '')
    setCell(statusColumn, '')
    setCell(deadlineColumn, '')
    setCell(frozenAtColumn, '')
    return changed
  }

  const submittedDate = new Date(submittedAt.getFullYear(), submittedAt.getMonth(), submittedAt.getDate())
  const active = submittedDate >= getRegistrationCutoffDate(now)
  setCell(groupColumn, active ? REGISTRATION_ACTIVE_GROUP : REGISTRATION_FROZEN_GROUP)
  setCell(statusColumn, active ? REGISTRATION_ACTIVE_STATUS : REGISTRATION_FROZEN_STATUS)
  setCell(deadlineColumn, formatLocalDateForRegistrationMeta(addLocalMonths(submittedDate, 2)))
  if (frozenAtColumn >= 0) {
    if (active) {
      setCell(frozenAtColumn, '')
    } else if (!normalizeCellValue(row[frozenAtColumn]).trim()) {
      setCell(frozenAtColumn, formatLocalDateTimeForRegistrationMeta(now))
    }
  }
  return changed
}

function isAutoRegistrationSubmittedAtStyle(style: SheetCellStyle | null | undefined) {
  return (
    normalizeCssColor(style?.text_color) === REGISTRATION_AUTO_SUBMITTED_AT_TEXT_COLOR
    && !normalizeCssColor(style?.background_color)
    && !style?.font_family
    && !style?.font_size
    && !style?.text_align
    && !style?.vertical_align
  )
}

function markRegistrationSubmittedAtAsAuto(nextMeta: SheetCellMetaMap, documentRow: number, columnIndex: number) {
  const key = createCellMetaKey(documentRow, columnIndex)
  const entry = { ...(nextMeta[key] ?? {}) }
  entry.style = {
    ...(entry.style ?? {}),
    text_color: REGISTRATION_AUTO_SUBMITTED_AT_TEXT_COLOR,
  }
  const normalized = normalizeCellMetaEntry(entry)
  if (normalized) {
    nextMeta[key] = normalized
  }
  updateEntityCellEntry(documentRow, columnIndex, (entry) => replaceEntityCellMeta(entry, normalized))
}

function clearAutoRegistrationSubmittedAtStyle(nextMeta: SheetCellMetaMap, documentRow: number, columnIndex: number) {
  const key = createCellMetaKey(documentRow, columnIndex)
  const entry = nextMeta[key]
  if (!entry || !isAutoRegistrationSubmittedAtStyle(entry.style)) {
    return false
  }

  const nextEntry: SheetCellMeta = { ...entry }
  delete nextEntry.style
  const normalized = normalizeCellMetaEntry(nextEntry)
  if (normalized) {
    nextMeta[key] = normalized
  } else {
    delete nextMeta[key]
  }
  updateEntityCellEntry(documentRow, columnIndex, (entityEntry) => replaceEntityCellMeta(entityEntry, normalized))
  return true
}

function applyDefaultRegistrationSubmittedAtRows(startDataIndex: number, amount: number, startDocumentDataIndex: number) {
  if (!isRegistrationSubmittedAtDefaultEnabled()) {
    return false
  }
  const submittedAtColumn = getHeaderColumnIndex(STUDENT_LOOKUP_SUBMITTED_AT_HEADER)
  if (submittedAtColumn < 0) {
    return false
  }

  const nextRows = rows.value.map((row) => normalizeRow(row, columnHeaders.value))
  const nextMeta = { ...cellMeta.value }
  const now = new Date()
  const defaultValue = createDefaultRegistrationSubmittedAtValue(now)
  let changed = false

  for (let offset = 0; offset < amount; offset += 1) {
    const rowIndex = startDataIndex + offset
    if (rowIndex < 0 || rowIndex >= nextRows.length) {
      continue
    }
    const row = nextRows[rowIndex]
    if (normalizeCellValue(row[submittedAtColumn]).trim()) {
      continue
    }
    row[submittedAtColumn] = defaultValue
    applyRegistrationTrackingValuesToRow(row, defaultValue, now)
    markRegistrationSubmittedAtAsAuto(
      nextMeta,
      sheetHeaderRowCount.value + startDocumentDataIndex + offset,
      submittedAtColumn,
    )
    changed = true
  }

  if (!changed) {
    return false
  }

  rows.value = nextRows
  cellMeta.value = normalizeCellMetaMap(nextMeta, columnHeaders.value.length)
  return true
}

function handleRegistrationSubmittedAtUserChanges(changes: unknown, source?: string) {
  if (!isRegistrationSubmittedAtDefaultEnabled()) {
    return false
  }
  const submittedAtColumn = getHeaderColumnIndex(STUDENT_LOOKUP_SUBMITTED_AT_HEADER)
  if (submittedAtColumn < 0) {
    return false
  }
  const records = normalizeSheetGridChanges(changes).filter((record) => (
    record.columnIndex === submittedAtColumn
    && getDataRowIndex(record.rowIndex) >= 0
  ))
  if (!records.length) {
    return false
  }

  const nextRows = rows.value.map((row) => normalizeRow(row, columnHeaders.value))
  const nextMeta = { ...cellMeta.value }
  const now = new Date()
  let changed = false

  records.forEach((record) => {
    const dataRow = getDataRowIndex(record.rowIndex)
    if (dataRow < 0 || dataRow >= nextRows.length) {
      return
    }
    const documentRow = sheetHeaderRowCount.value + getDocumentRowIndex(dataRow)
    if (source !== 'loadData' && source !== 'external-update') {
      changed = clearAutoRegistrationSubmittedAtStyle(nextMeta, documentRow, submittedAtColumn) || changed
    }
    changed = applyRegistrationTrackingValuesToRow(
      nextRows[dataRow],
      nextRows[dataRow][submittedAtColumn],
      now,
    ) || changed
  })

  if (!changed) {
    return false
  }

  rows.value = nextRows
  cellMeta.value = normalizeCellMetaMap(nextMeta, columnHeaders.value.length)
  return true
}

function handleBeforeChange(changes: unknown, source?: string) {
  if (
    !Array.isArray(changes)
    || source === 'loadData'
    || source === 'external-update'
    || source === 'MergeCells'
  ) {
    return
  }

  changes.forEach((change) => {
    if (!Array.isArray(change) || change.length < 4) {
      return
    }
    const rowIndex = Number(change[0])
    const hotColumnIndex = Number(change[1])
    const columnIndex = toSheetColumnIndex(hotColumnIndex)
    if (!Number.isInteger(rowIndex) || !Number.isInteger(hotColumnIndex) || rowIndex < 0 || columnIndex < 0) {
      if (Number.isInteger(rowIndex) && Number.isInteger(hotColumnIndex) && isRowMarkerHotColumn(hotColumnIndex)) {
        change[3] = change[2]
      }
      return
    }
    const anchor = getMergeAnchorForGridCell(rowIndex, columnIndex)
    if (anchor.row !== rowIndex || anchor.column !== columnIndex) {
      change[0] = anchor.row
      change[1] = toHotColumnIndex(anchor.column)
    }
  })

  const headerChanges = changes.filter((change) => (
    Array.isArray(change)
    && getDataRowIndex(Number(change[0])) < 0
  ))
  if (headerChanges.length > 0) {
    if (!canEditConfig.value) {
      warnReadOnlyAction()
      return false
    }

    let changed = false
    if (hasEffectiveSheetGridChanges(headerChanges)) {
      pushLocalUndoSnapshot('header-edit')
    }
    headerChanges.forEach((change) => {
      const rowIndex = Number(change[0])
      const hotColumnIndex = Number(change[1])
      const columnIndex = toSheetColumnIndex(hotColumnIndex)
      if (!Number.isInteger(rowIndex) || !Number.isInteger(hotColumnIndex) || columnIndex < 0) {
        return
      }
      changed = applySheetHeaderGridChange(rowIndex, columnIndex, change[3]) || changed
    })
    if (changed) {
      clearEditingColumnState()
      refreshGridStructure()
      void refreshComputedRowHeights()
    }
    return false
  }

  if (!canEditData.value && !canEditPartialData.value) {
    return false
  }

  if (!areChangedColumnsEditable(changes)) {
    warnReadOnlyColumnAction()
    return false
  }
  if (!canEditData.value && getChangesRequiredEndRow(changes) >= getGridRowCountForExpansionGuard()) {
    warnReadOnlyAction()
    return false
  }

  if (
    shouldGuardBulkRowExpansionSource(source)
    && !ensurePagedRowExpansionAllowed(
      getChangesRequiredEndRow(changes),
      source === 'Autofill.fill' ? PAGED_AUTO_ROW_INSERT_MESSAGE : PAGED_ROW_EXPANSION_MESSAGE,
    )
  ) {
    return false
  }

  for (const change of changes) {
    if (!Array.isArray(change) || change.length < 4) {
      continue
    }

    const hotColumnIndex = Number(change[1])
    const columnIndex = toSheetColumnIndex(hotColumnIndex)
    if (!Number.isInteger(hotColumnIndex) || columnIndex < 0) {
      continue
    }

    const nextValue = change[3]
    if (typeof nextValue === 'string') {
      change[3] = normalizeCellInputValueForColumn(nextValue, columnIndex)
    }
  }

  if (hasEffectiveSheetGridChanges(changes)) {
    pushLocalUndoSnapshot('cell-edit')
  }
}

function handleBeforeAutofill(
  selectionData: unknown[][],
  sourceRange: SheetAutofillRange,
  targetRange: SheetAutofillRange,
  direction: SheetAutofillDirection,
) {
  if (!canEditData.value && !canEditPartialData.value) {
    warnReadOnlyAction()
    return false
  }
  const targetBounds = normalizeAutofillRange(targetRange)
  const sourceBounds = normalizeAutofillRange(sourceRange)
  const sourceColumnRange = getSheetColumnRangeFromHotRange(sourceBounds.startColumn, sourceBounds.endColumn)
  const targetColumnRange = getSheetColumnRangeFromHotRange(targetBounds.startColumn, targetBounds.endColumn)
  if (
    !sourceColumnRange
    || !targetColumnRange
    || hotRangeIncludesRowMarker(sourceBounds.startColumn, sourceBounds.endColumn)
    || hotRangeIncludesRowMarker(targetBounds.startColumn, targetBounds.endColumn)
  ) {
    warnReadOnlyAction()
    return false
  }
  if (sourceBounds.startRow < sheetHeaderRowCount.value || targetBounds.startRow < sheetHeaderRowCount.value) {
    warnReadOnlyAction()
    return false
  }
  const targetDataEndRow = getDataRowIndex(targetBounds.endRow)
  if (!isColumnRangeEditable(targetColumnRange.start, targetColumnRange.end)) {
    warnReadOnlyColumnAction()
    return false
  }
  if (!canEditData.value && targetDataEndRow >= getGridRowCountForExpansionGuard()) {
    warnReadOnlyAction()
    return false
  }
  if (!ensurePagedRowExpansionAllowed(targetDataEndRow, PAGED_AUTO_ROW_INSERT_MESSAGE)) {
    return false
  }
  return buildFormulaAutofillData(
    shiftAutofillRange(sourceRange, -sheetHeaderRowCount.value, -rowMarkerColumnCount.value),
    shiftAutofillRange(targetRange, -sheetHeaderRowCount.value, -rowMarkerColumnCount.value),
    direction,
  ) ?? selectionData
}

function handleBeforeCreateRow(index = 0, amount = 1, source?: string) {
  if (!canEditData.value) {
    if (source !== 'auto') {
      warnReadOnlyAction()
    }
    return false
  }
  if (source !== 'auto') {
    return
  }

  const startRow = normalizeNonNegativeInt(getDataRowIndex(index), getGridRowCountForExpansionGuard())
  const rowAmount = Math.max(1, normalizePositivePageNumber(amount, 1))
  const requiredEndRow = Math.max(getGridRowCountForExpansionGuard(), startRow) + rowAmount - 1
  if (!ensurePagedRowExpansionAllowed(requiredEndRow, PAGED_AUTO_ROW_INSERT_MESSAGE)) {
    return false
  }
  pushLocalUndoSnapshot('row-insert')
}

function handleAfterCreateRow(index = 0, amount = 1) {
  suppressNextRemoteSaveWatcher = true
  const dataIndex = Math.max(0, getDataRowIndex(index))
  const documentDataIndex = getDocumentRowIndex(dataIndex)
  const documentGridRow = sheetHeaderRowCount.value + documentDataIndex
  const insertionTemplate = pendingRowInsertionTemplate
  insertDocumentGridRows(documentGridRow, amount)
  insertDataEntityRows(dataIndex, amount)
  applyRowInsertionTemplateCellStyles(documentGridRow, amount, insertionTemplate)
  syncRowsFromGrid()
  remapFormulaReferencesInRows((rowIndex) => (rowIndex >= documentDataIndex ? rowIndex + amount : rowIndex))
  if (applyDefaultRegistrationSubmittedAtRows(dataIndex, amount, documentDataIndex)) {
    const hot = getHotInstance()
    loadCurrentHotGridRows(hot)
    renderHotWithReason(hot, 'insert-row-registration-defaults')
  }
  const insertedIds = dataRowEntityIds.value.slice(dataIndex, dataIndex + amount)
  const insertedRows = rows.value.slice(dataIndex, dataIndex + amount).map((row) => normalizeRow(row, columnHeaders.value))
  let afterRowId = dataIndex > 0 ? dataRowEntityIds.value[dataIndex - 1] ?? null : null
  const operations: NoteSheetPatchOperation[] = insertedIds.map((rowId, offset) => {
    const operation: NoteSheetPatchOperation = {
      op: 'insert-row',
      after_row_id: afterRowId,
      row_id: rowId,
      row: insertedRows[offset] ?? createEmptyRow(columnHeaders.value.length),
    }
    afterRowId = rowId
    return operation
  })
  queueImmediateSheetPatchSave(operations, '插入行保存失败，已保留本地草稿')
}

function handleAfterRemoveRow(index = 0, amount = 1) {
  suppressNextRemoteSaveWatcher = true
  const dataIndex = Math.max(0, getDataRowIndex(index))
  const removedRowIds = dataRowEntityIds.value.slice(dataIndex, dataIndex + amount)
  const documentDataIndex = getDocumentRowIndex(dataIndex)
  const removedPageRowIndexes = pageRowIndexes.value
    ? pageRowIndexes.value.slice(dataIndex, dataIndex + amount)
    : []
  removeDataEntityRows(dataIndex, amount)
  if (removedPageRowIndexes.length) {
    normalizePaginationDeletedRowIndexes(removedPageRowIndexes)?.slice().reverse().forEach((rowIndex) => {
      removeDocumentGridRows(sheetHeaderRowCount.value + rowIndex, 1)
    })
  } else {
    removeDocumentGridRows(sheetHeaderRowCount.value + documentDataIndex, amount)
  }
  syncRowsFromGrid()
  if (pageRowIndexes.value !== null) {
    const nextRowIndexes = [...pageRowIndexes.value]
    nextRowIndexes.splice(dataIndex, amount)
    pageRowIndexes.value = nextRowIndexes
    addPendingDeletedPageRowIndexes(removedPageRowIndexes)
    const removedCount = removedPageRowIndexes.length
    if (removedCount > 0) {
      pageLoadedRowCount.value = Math.max(0, pageLoadedRowCount.value - removedCount)
      totalRowCount.value = Math.max(0, totalRowCount.value - removedCount)
      unfilteredTotalRowCount.value = Math.max(totalRowCount.value, unfilteredTotalRowCount.value - removedCount)
      pageCount.value = Math.max(1, Math.ceil(totalRowCount.value / pageSize.value))
    }
  }
  const deletedDocumentRowIndexes = normalizePaginationDeletedRowIndexes(removedPageRowIndexes)
  if (deletedDocumentRowIndexes?.length) {
    const deletedRowIndexSet = new Set(deletedDocumentRowIndexes)
    remapFormulaReferencesInRows((rowIndex) => {
      if (deletedRowIndexSet.has(rowIndex)) {
        return null
      }
      const shift = deletedDocumentRowIndexes.filter((deletedRowIndex) => deletedRowIndex < rowIndex).length
      return rowIndex - shift
    })
  } else {
    const endIndex = documentDataIndex + amount
    remapFormulaReferencesInRows((rowIndex) => {
      if (rowIndex >= documentDataIndex && rowIndex < endIndex) {
        return null
      }
      return rowIndex >= endIndex ? rowIndex - amount : rowIndex
    })
  }
  queueImmediateSheetPatchSave(
    removedRowIds.map((rowId): NoteSheetPatchOperation => ({
      op: 'delete-row',
      row_id: rowId,
    })),
    '删除行保存失败，已保留本地草稿',
  )
}

function handleAfterCreateCol(hotIndex: number, amount: number) {
  suppressNextRemoteSaveWatcher = true
  const index = Math.max(0, toSheetColumnIndex(hotIndex))
  const insertionTemplate = pendingColumnInsertionTemplate
  const nextHeaders = [...columnHeaders.value]
  nextHeaders.splice(index, 0, ...createCustomColumnNames(amount, nextHeaders))
  columnHeaders.value = nextHeaders
  const nextWidths = [...columnWidths.value]
  nextWidths.splice(
    index,
    0,
    ...Array.from({ length: amount }, (_, offset) => (
      insertionTemplate?.targetIndex === index
        ? insertionTemplate.width
        : getAdaptiveColumnWidth(nextHeaders[index + offset] ?? createFallbackHeader(index + offset))
    )),
  )
  columnWidths.value = nextWidths
  columnConfigs.value = applyColumnInsertionTemplate(nextHeaders, index, amount, insertionTemplate)
  insertColumnEntityIds(index, amount)
  shiftCellMetaColumns(index, amount)
  applyColumnInsertionTemplateCellStyles(index, amount, insertionTemplate)
  insertMergedCellColumns(index, amount)
  refreshGridStructure()
  syncRowsFromGrid()
  remapFormulaReferencesInRows(undefined, (columnIndex) => (
    columnIndex >= index ? columnIndex + amount : columnIndex
  ))
  let afterColumnId = index > 0 ? columnEntityIds.value[index - 1] ?? null : null
  const normalizedConfigs = normalizeColumnConfigs(columnConfigs.value, columnHeaders.value)
  const operations: NoteSheetPatchOperation[] = Array.from({ length: amount }, (_, offset) => {
    const columnIndex = index + offset
    const columnId = columnEntityIds.value[columnIndex]
    const header = columnHeaders.value[columnIndex] ?? createFallbackHeader(columnIndex)
    const operation: NoteSheetPatchOperation = {
      op: 'insert-column',
      after_column_id: afterColumnId,
      column_id: columnId,
      column: {
        header,
        width: normalizeColumnWidthValue(columnWidths.value[columnIndex] ?? getEffectiveColumnWidth(columnIndex)),
        config: normalizedConfigs[header] ?? {},
      },
    }
    afterColumnId = columnId
    return operation
  })
  queueImmediateSheetPatchSave(operations, '插入列保存失败，已保留本地草稿')
}

function handleBeforeRemoveCol(hotIndex: number, amount: number) {
  if (isRowMarkerHotColumn(hotIndex)) {
    return false
  }
  return columnHeaders.value.length - amount >= 1
}

function handleAfterRemoveCol(hotIndex: number, amount: number) {
  suppressNextRemoteSaveWatcher = true
  const index = Math.max(0, toSheetColumnIndex(hotIndex))
  const removedColumnIds = columnEntityIds.value.slice(index, index + amount)
  const nextHeaders = [...columnHeaders.value]
  nextHeaders.splice(index, amount)
  columnHeaders.value = nextHeaders.length ? nextHeaders : [createFallbackHeader(0)]
  const nextWidths = [...columnWidths.value]
  nextWidths.splice(index, amount)
  columnWidths.value = columnHeaders.value.length
    ? nextWidths.slice(0, columnHeaders.value.length)
    : [getAdaptiveColumnWidth(columnHeaders.value[0])]
  columnConfigs.value = normalizeColumnConfigs(columnConfigs.value, columnHeaders.value)
  removeColumnEntityIds(index, amount)
  removeCellMetaColumns(index, amount)
  removeMergedCellColumns(index, amount)
  refreshGridStructure()
  syncRowsFromGrid()
  const endIndex = index + amount
  remapFormulaReferencesInRows(undefined, (columnIndex) => {
    if (columnIndex >= index && columnIndex < endIndex) {
      return null
    }
    return columnIndex >= endIndex ? columnIndex - amount : columnIndex
  })
  queueImmediateSheetPatchSave(
    removedColumnIds.map((columnId): NoteSheetPatchOperation => ({
      op: 'delete-column',
      column_id: columnId,
    })),
    '删除列保存失败，已保留本地草稿',
  )
}

function getSelectionColumnBounds() {
  const hot = getHotInstance()
  const selection = hot?.getSelectedLast()
  if (!selection) {
    return null
  }

  const startCol = Math.min(selection[1], selection[3])
  const endCol = Math.max(selection[1], selection[3])
  if (endCol < 0) {
    return null
  }

  return getSheetColumnRangeFromHotRange(startCol, endCol)
}

function getSelectionRowBounds() {
  const hot = getHotInstance()
  const selection = hot?.getSelectedLast()
  if (!selection) {
    return null
  }

  const startRow = Math.min(selection[0], selection[2])
  const endRow = Math.max(selection[0], selection[2])
  const startDataRow = Math.max(getDataRowIndex(startRow), 0)
  const endDataRow = getDataRowIndex(endRow)
  if (endDataRow < 0) {
    return null
  }

  return {
    start: startDataRow,
    end: endDataRow,
  }
}

function hasSingleColumnSelection() {
  const bounds = getSelectionColumnBounds()
  return !!bounds && bounds.start === bounds.end
}

function hasColumnHeaderSelection() {
  return isSelectedByColumnHeader() && !isSelectedByCorner() && !!getSelectionColumnBounds()
}

function getColumnSettingsContextBounds() {
  if (isSelectedByColumnHeader() && !isSelectedByCorner()) {
    return getSelectionColumnBounds()
  }

  const headerCellColumn = getSelectedColumnHeaderCellIndex()
  return headerCellColumn == null
    ? null
    : { start: headerCellColumn, end: headerCellColumn }
}

function hasColumnSettingsContextSelection() {
  return !!getColumnSettingsContextBounds()
}

function hasSingleColumnHeaderSelection() {
  return isSelectedByColumnHeader() && hasSingleColumnSelection()
}

function getSingleSelectedColumnIndex() {
  const bounds = getSelectionColumnBounds()
  if (!bounds || bounds.start !== bounds.end || !isSelectedByColumnHeader()) {
    return null
  }
  return bounds.start
}

function getSingleFreezePaneTargetColumnIndex() {
  const selectedColumn = getSingleSelectedColumnIndex()
  if (selectedColumn != null) {
    return selectedColumn
  }
  return getSelectedColumnHeaderCellIndex()
}

function hasFreezePaneContextSelection() {
  return hasColumnHeaderSelection() || !!selectedSheetHeaderCell.value
}

function canFreezePaneAtSelection() {
  return canEditConfig.value && getSingleFreezePaneTargetColumnIndex() != null
}

function canUnfreezePanesFromSelection() {
  return canEditConfig.value && fixedColumnsStart.value > 0 && hasFreezePaneContextSelection()
}

function shouldShowFreezePaneContextMenuGroup() {
  return canFreezePaneAtSelection() || canUnfreezePanesFromSelection()
}

function setFrozenColumnCount(columnCount: number) {
  if (!ensureCanEditConfig()) {
    return
  }

  const nextCount = normalizeFrozenColumnCount(columnCount, columnHeaders.value.length)
  const currentCount = fixedColumnsStart.value
  if (nextCount === currentCount && sheetViewSettings.value.frozen_column_count === nextCount) {
    return
  }

  const undoEntry = createLocalUndoEntry('freeze-pane')
  sheetViewSettings.value = normalizeSheetViewSettings({
    ...sheetViewSettings.value,
    frozen_column_count: nextCount,
  }, columnHeaders.value.length)
  refreshGridStructure()
  pushLocalUndoEntry(undoEntry)
  scheduleRemoteSave(0)

  if (nextCount > 0) {
    ElMessage.success(`已冻结到 ${getColumnMarkerLabel(nextCount - 1)} 列`)
  } else {
    ElMessage.success('已取消冻结窗口')
  }
}

function freezePanesAtSelectedColumn() {
  const columnIndex = getSingleFreezePaneTargetColumnIndex()
  if (columnIndex == null) {
    return
  }
  setFrozenColumnCount(columnIndex + 1)
}

function isFreezeColumnBoundary(columnIndex: number) {
  return fixedColumnsStart.value > 0 && columnIndex === fixedColumnsStart.value - 1
}

function isFreezeRowBoundary(rowIndex: number) {
  return sheetHeaderRowCount.value > 0 && rowIndex === sheetHeaderRowCount.value - 1
}

function applyFreezePaneBoundaryClasses(element: HTMLElement, rowIndex: number, columnIndex: number) {
  element.classList.toggle('sheet-freeze-column-boundary', isFreezeColumnBoundary(columnIndex))
  element.classList.toggle('sheet-freeze-row-boundary', isFreezeRowBoundary(rowIndex))
}

function areColumnMarkerBoundsEqual(
  left: { start: number; end: number } | null,
  right: { start: number; end: number } | null,
) {
  return left?.start === right?.start && left?.end === right?.end
}

function clearColumnMarkerSelection() {
  selectedColumnMarkerBounds.value = null
  columnMarkerSelectionAnchor = null
}

function clearSheetHeaderSelection() {
  if (!selectedSheetHeaderCell.value) {
    return
  }
  selectedSheetHeaderCell.value = null
}

function isSheetHeaderCellSelected(column: number, headerLevel: number) {
  return (
    selectedSheetHeaderCell.value?.column === column
    && selectedSheetHeaderCell.value.headerLevel === headerLevel
  )
}

function syncColumnMarkerSelection() {
  if (!isSelectedByColumnHeader() || isSelectedByCorner()) {
    if (selectedColumnMarkerBounds.value || columnMarkerSelectionAnchor != null) {
      clearColumnMarkerSelection()
    }
    return
  }

  const nextBounds = getSelectionColumnBounds()
  if (!areColumnMarkerBoundsEqual(selectedColumnMarkerBounds.value, nextBounds)) {
    selectedColumnMarkerBounds.value = nextBounds
  }
  if (
    nextBounds
    && (
      columnMarkerSelectionAnchor == null
      || columnMarkerSelectionAnchor < nextBounds.start
      || columnMarkerSelectionAnchor > nextBounds.end
    )
  ) {
    columnMarkerSelectionAnchor = nextBounds.start
  }
}

function isColumnMarkerSelected(columnIndex: number) {
  const bounds = selectedColumnMarkerBounds.value
  return !!bounds && columnIndex >= bounds.start && columnIndex <= bounds.end
}

function getDocumentRowIndex(rowIndex: number) {
  const rowIndexes = pageRowIndexes.value
  if (rowIndexes !== null && rowIndex >= 0 && rowIndex < rowIndexes.length) {
    return rowIndexes[rowIndex]
  }
  return (effectivePaginationEnabled.value ? pageRowOffset.value : 0) + rowIndex
}

function getDataRowIndex(gridRowIndex: number) {
  return gridRowIndex - sheetHeaderRowCount.value
}

function getGridRowIndex(dataRowIndex: number) {
  return dataRowIndex + sheetHeaderRowCount.value
}

function joinSheetCellClassNames(...classes: Array<string | null | undefined | false>) {
  return classes.filter(Boolean).join(' ') || undefined
}

function getCutRowClassName(row: number) {
  if (!cutRowBounds || isSheetHeaderGridRow(row)) {
    return null
  }
  const dataRow = getDataRowIndex(row)
  if (dataRow < cutRowBounds.start || dataRow > cutRowBounds.end) {
    return null
  }
  return joinSheetCellClassNames(
    'sheet-cut-row-cell',
    dataRow === cutRowBounds.start && 'sheet-cut-row-cell--start',
    dataRow === cutRowBounds.end && 'sheet-cut-row-cell--end',
  )
}

function getSheetCellDocumentRow(rowIndex: number) {
  return getDocumentGridRowIndex(rowIndex)
}

function isSheetHeaderGridRow(rowIndex: number) {
  return rowIndex >= 0 && rowIndex < sheetHeaderRowCount.value
}

function getSheetHeaderGridLevel(rowIndex: number) {
  if (rowIndex < 0 || rowIndex >= sheetHeaderRowCount.value) {
    return -1
  }
  return rowIndex
}

function getSheetRowHeaderLabel(gridRowIndex: number) {
  const rowIndex = getDataRowIndex(gridRowIndex)
  const numbering = sheetViewSettings.value.row_marker_numbering
  const documentDataRowIndex = rowIndex >= 0 ? getDocumentRowIndex(rowIndex) : rowIndex
  const pageOffset = effectivePaginationEnabled.value && numbering === 'global' ? pageRowOffset.value : 0

  if (sheetViewSettings.value.row_marker_origin === 'sheet_zero') {
    if (gridRowIndex < 0) {
      return ''
    }
    if (rowIndex < 0) {
      return String(gridRowIndex)
    }
    if (numbering === 'global' && pageRowIndexes.value !== null) {
      return String(sheetHeaderRowCount.value + documentDataRowIndex)
    }
    return String(pageOffset + sheetHeaderRowCount.value + rowIndex)
  }

  if (sheetViewSettings.value.row_marker_origin === 'sheet') {
    if (gridRowIndex < 0) {
      return ''
    }
    if (rowIndex < 0) {
      return String(gridRowIndex + 1)
    }
    if (numbering === 'global' && pageRowIndexes.value !== null) {
      return String(sheetHeaderRowCount.value + documentDataRowIndex + 1)
    }
    return String(pageOffset + sheetHeaderRowCount.value + rowIndex + 1)
  }

  if (rowIndex < 0) {
    return ''
  }
  if (numbering === 'global' && pageRowIndexes.value !== null) {
    return String(documentDataRowIndex + 1)
  }
  return String(pageOffset + rowIndex + 1)
}

function clearFormulaBarSelection() {
  clearScheduledFormulaBarDraftSync()
  finishFormulaReferenceRange()
  clearFormulaReferencePreviewRange()
  clearFormulaReferenceReplacementSpan()
  clearScheduledInlineEditorFormulaBarSync()
  clearFormulaReferencePointerDownReset()
  formulaReferencePointerDown = false
  formulaBarCell.value = null
  formulaBarDraft.value = ''
  formulaBarFocused.value = false
}

function getRawCellValue(rowIndex: number, columnIndex: number) {
  return normalizeCellValue(rows.value[rowIndex]?.[columnIndex] ?? '')
}

function createFormulaBarCellFromGridCell(gridRowIndex: number, columnIndex: number): FormulaBarCell | null {
  if (
    !Number.isInteger(gridRowIndex)
    || !Number.isInteger(columnIndex)
    || gridRowIndex < 0
    || columnIndex < 0
    || columnIndex >= columnHeaders.value.length
    || gridRowIndex >= sheetGridRows.value.length
  ) {
    return null
  }

  const anchor = getMergeAnchorForGridCell(gridRowIndex, columnIndex)
  if (anchor.row < 0 || anchor.column < 0 || anchor.column >= columnHeaders.value.length) {
    return null
  }
  return {
    gridRow: anchor.row,
    dataRow: getDataRowIndex(anchor.row),
    column: anchor.column,
    documentGridRow: anchor.documentRow,
  }
}

function getFormulaBarCellRawValue(cell: FormulaBarCell) {
  return cell.dataRow >= 0
    ? getRawCellValue(cell.dataRow, cell.column)
    : getGridCellRenderSourceValue(cell.gridRow, cell.column)
}

function getCellEditText(columnIndex: number, rawValue: unknown) {
  const normalizedValue = normalizeCellValue(rawValue)
  if (isFormulaExpression(normalizedValue)) {
    return normalizedValue
  }

  const columnConfig = normalizeColumnConfig(getColumnConfigByIndex(columnIndex))
  if (columnConfig.value_type === 'date') {
    return formatDateEditText(normalizedValue)
  }
  if (columnConfig.value_type === 'percent') {
    return formatPercentDisplayValue(normalizedValue, columnConfig.display_format)
  }
  return normalizedValue
}

function getFormulaBarCellEditText(cell: FormulaBarCell) {
  const rawValue = getFormulaBarCellRawValue(cell)
  return cell.dataRow >= 0 ? getCellEditText(cell.column, rawValue) : rawValue
}

function syncFormulaBarDraftFromSelectedCell(force = false) {
  const trace = startSheetPerfTrace('formulaBar.sync', {
    force,
    formulaBarFocused: formulaBarFocused.value,
  })
  const cell = formulaBarCell.value
  if (!cell) {
    formulaBarDraft.value = ''
    trace?.finish({ exit: 'empty' })
    return
  }
  if (formulaBarFocused.value && !force) {
    trace?.finish({
      exit: 'focused',
      address: getSheetPerfCellAddress(cell),
      valueLength: getSheetPerfCellValueLength(cell),
    })
    return
  }
  const editText = getFormulaBarCellEditText(cell)
  trace?.mark('readEditText')
  formulaBarDraft.value = editText
  trace?.mark('assignDraft')
  trace?.finish({
    exit: 'synced',
    address: getSheetPerfCellAddress(cell),
    dataRow: cell.dataRow,
    column: cell.column,
    documentGridRow: cell.documentGridRow,
    valueLength: normalizeCellValue(editText).length,
  })
}

function clearScheduledFormulaBarDraftSync() {
  if (formulaBarDraftSyncFrame == null) {
    return
  }
  window.cancelAnimationFrame(formulaBarDraftSyncFrame)
  formulaBarDraftSyncFrame = null
}

function scheduleFormulaBarDraftFromSelectedCell(force = false) {
  clearScheduledFormulaBarDraftSync()
  const scheduledAt = sheetPerfLoggingEnabled.value ? getSheetPerfNow() : 0
  formulaBarDraftSyncFrame = window.requestAnimationFrame(() => {
    const trace = startSheetPerfTrace('formulaBar.rafSync', {
      force,
      waitMs: scheduledAt ? roundSheetPerfMs(getSheetPerfNow() - scheduledAt) : undefined,
      formulaBarFocused: formulaBarFocused.value,
    })
    formulaBarDraftSyncFrame = null
    syncFormulaBarDraftFromSelectedCell(force)
    trace?.mark('sync')
    const cell = formulaBarCell.value
    trace?.finish({
      address: getSheetPerfCellAddress(cell),
      dataRow: cell?.dataRow,
      column: cell?.column,
      documentGridRow: cell?.documentGridRow,
      valueLength: getSheetPerfCellValueLength(cell),
    })
  })
}

function isSameFormulaBarCell(rowIndex: number, columnIndex: number) {
  const cell = formulaBarCell.value
  return !!cell && cell.gridRow === rowIndex && cell.column === columnIndex
}

function isFormulaReferencePickMode() {
  return !!formulaBarCell.value && formulaBarFocused.value && formulaBarDraft.value.startsWith('=')
}

function getSheetFormulaRowIndex(dataRowIndex: number) {
  return sheetHeaderRowCount.value + getDocumentRowIndex(dataRowIndex)
}

function getCellReferenceLabelForSheetRow(sheetRowIndex: number, columnIndex: number) {
  return `${getExcelColumnLabel(columnIndex)}${sheetRowIndex + 1}`
}

function getCellReferenceLabel(rowIndex: number, columnIndex: number) {
  return getCellReferenceLabelForSheetRow(getSheetFormulaRowIndex(rowIndex), columnIndex)
}

function getCellReferenceRangeLabel(startRow: number, startColumn: number, endRow: number, endColumn: number) {
  const topRow = Math.min(startRow, endRow)
  const bottomRow = Math.max(startRow, endRow)
  const leftColumn = Math.min(startColumn, endColumn)
  const rightColumn = Math.max(startColumn, endColumn)
  const startReference = getCellReferenceLabel(topRow, leftColumn)
  const endReference = getCellReferenceLabel(bottomRow, rightColumn)
  return startReference === endReference ? startReference : `${startReference}:${endReference}`
}

function normalizeFormulaReferenceRangeBounds(bounds: FormulaReferenceRangeBounds | null) {
  if (!bounds) {
    return null
  }
  return {
    startRow: Math.min(bounds.startRow, bounds.currentRow),
    endRow: Math.max(bounds.startRow, bounds.currentRow),
    startColumn: Math.min(bounds.startColumn, bounds.currentColumn),
    endColumn: Math.max(bounds.startColumn, bounds.currentColumn),
  }
}

function areFormulaReferenceRangeBoundsEqual(
  left: FormulaReferenceRangeBounds | null,
  right: FormulaReferenceRangeBounds | null,
) {
  const normalizedLeft = normalizeFormulaReferenceRangeBounds(left)
  const normalizedRight = normalizeFormulaReferenceRangeBounds(right)
  return normalizedLeft?.startRow === normalizedRight?.startRow
    && normalizedLeft?.endRow === normalizedRight?.endRow
    && normalizedLeft?.startColumn === normalizedRight?.startColumn
    && normalizedLeft?.endColumn === normalizedRight?.endColumn
}

function isCellInFormulaReferencePreview(rowIndex: number, columnIndex: number) {
  const bounds = normalizeFormulaReferenceRangeBounds(formulaReferencePreviewRange.value)
  return !!bounds
    && rowIndex >= bounds.startRow
    && rowIndex <= bounds.endRow
    && columnIndex >= bounds.startColumn
    && columnIndex <= bounds.endColumn
}

function getFormulaBarNativeInput() {
  return formulaBarInputRef.value?.input ?? null
}

function getActiveOpenedEditor() {
  const editor = getHotInstance()?.getActiveEditor() as SheetActiveEditor | undefined
  if (!editor?.isOpened?.()) {
    return null
  }
  return editor
}

function getEditorTextInput(editor: SheetActiveEditor) {
  const input = editor.TEXTAREA
  return input instanceof HTMLInputElement || input instanceof HTMLTextAreaElement ? input : null
}

function getActiveEditorDraft(editor: SheetActiveEditor) {
  const input = getEditorTextInput(editor)
  return normalizeCellValue(input?.value ?? editor.getValue?.() ?? '')
}

function getEditorCellElement(editor: SheetActiveEditor) {
  if (editor.TD instanceof HTMLElement && editor.TD.isConnected) {
    return editor.TD
  }
  if (typeof editor.row !== 'number' || typeof editor.col !== 'number') {
    return null
  }
  const column = toSheetColumnIndex(editor.col)
  if (column < 0) {
    return null
  }
  const anchor = getMergeAnchorForGridCell(editor.row, column)
  return getHotInstance()?.getCell(anchor.row, toHotColumnIndex(anchor.column), true) ?? null
}

function getEditorInputHolder(editor: SheetActiveEditor, input: HTMLInputElement | HTMLTextAreaElement) {
  if (editor.TEXTAREA_PARENT instanceof HTMLElement) {
    return editor.TEXTAREA_PARENT
  }
  return input.closest('.handsontableInputHolder') as HTMLElement | null
}

function normalizeEditorBackgroundColor(color: string) {
  return color && color !== 'rgba(0, 0, 0, 0)' && color !== 'transparent' ? color : '#fff'
}

function styleInlineEditorAsCell(editor: SheetActiveEditor) {
  const input = getEditorTextInput(editor)
  const cell = getEditorCellElement(editor)
  if (!input || !cell) {
    return
  }

  const rect = cell.getBoundingClientRect()
  const rootElement = getHotInstance()?.rootElement
  const rootRect = rootElement instanceof HTMLElement ? rootElement.getBoundingClientRect() : null
  const style = window.getComputedStyle(cell)
  const holder = getEditorInputHolder(editor, input)
  if (holder && rootRect) {
    holder.classList.add('sheet-inline-cell-editor-holder')
    holder.style.position = 'absolute'
    holder.style.left = `${Math.round(rect.left - rootRect.left)}px`
    holder.style.top = `${Math.round(rect.top - rootRect.top)}px`
    holder.style.right = 'auto'
    holder.style.bottom = 'auto'
    holder.style.width = `${Math.max(1, Math.round(rect.width))}px`
    holder.style.height = `${Math.max(1, Math.round(rect.height))}px`
    holder.style.margin = '0'
    holder.style.overflow = 'hidden'
    holder.style.transform = 'none'
    holder.style.opacity = '1'
    holder.style.zIndex = '3600'
  }

  input.classList.add('sheet-inline-cell-editor')
  input.style.boxSizing = 'border-box'
  input.style.position = 'relative'
  input.style.left = '0'
  input.style.top = '0'
  input.style.width = '100%'
  input.style.height = '100%'
  input.style.minWidth = `${Math.max(1, Math.round(rect.width))}px`
  input.style.minHeight = `${Math.max(1, Math.round(rect.height))}px`
  input.style.maxWidth = `${Math.max(1, Math.round(rect.width))}px`
  input.style.maxHeight = `${Math.max(1, Math.round(rect.height))}px`
  input.style.margin = '0'
  input.style.padding = `${style.paddingTop} ${style.paddingRight} ${style.paddingBottom} ${style.paddingLeft}`
  input.style.border = '0'
  input.style.borderRadius = '0'
  input.style.outline = '0'
  input.style.boxShadow = 'inset 0 0 0 2px #2563eb'
  input.style.backgroundColor = normalizeEditorBackgroundColor(style.backgroundColor)
  input.style.color = style.color
  input.style.fontFamily = style.fontFamily
  input.style.fontSize = style.fontSize
  input.style.fontWeight = style.fontWeight
  input.style.fontStyle = style.fontStyle
  input.style.lineHeight = style.lineHeight === 'normal' ? `${TABLE_LINE_HEIGHT}px` : style.lineHeight
  input.style.textAlign = style.textAlign
  input.style.whiteSpace = style.whiteSpace === 'nowrap' ? 'pre' : 'pre-wrap'
  input.style.overflowWrap = style.overflowWrap
  input.style.wordBreak = style.wordBreak
  input.style.resize = 'none'
  input.style.overflow = 'auto'
}

function scheduleInlineEditorCellStyleSync() {
  void nextTick(() => {
    const editor = getActiveOpenedEditor()
    if (!editor) {
      return
    }
    styleInlineEditorAsCell(editor)
    window.requestAnimationFrame(() => {
      const latestEditor = getActiveOpenedEditor()
      if (latestEditor) {
        styleInlineEditorAsCell(latestEditor)
      }
    })
  })
}

function areSheetCellsSame(left: SelectedSheetCell | null | undefined, right: SelectedSheetCell | null | undefined) {
  return !!left
    && !!right
    && left.row === right.row
    && left.column === right.column
    && left.documentRow === right.documentRow
}

function getRichTextContentEditorText() {
  const editor = richTextContentEditorRef.value
  if (!editor) {
    return richTextContentEditor.value.text
  }
  return normalizeCellValue(editor.innerText.replace(/\r\n/g, '\n'))
}

function getTextOffsetFromRangeBoundary(root: HTMLElement, node: Node, offset: number) {
  const range = document.createRange()
  range.selectNodeContents(root)
  try {
    range.setEnd(node, offset)
    return range.toString().length
  } catch {
    return root.innerText.length
  } finally {
    range.detach()
  }
}

function getRichTextContentEditorSelectionOffsets() {
  const editor = richTextContentEditorRef.value
  const selection = window.getSelection()
  if (!editor || !selection || selection.rangeCount <= 0) {
    return null
  }

  const range = selection.getRangeAt(0)
  if (!editor.contains(range.startContainer) || !editor.contains(range.endContainer)) {
    return null
  }

  const textLength = richTextContentEditor.value.text.length
  const start = getTextOffsetFromRangeBoundary(editor, range.startContainer, range.startOffset)
  const end = getTextOffsetFromRangeBoundary(editor, range.endContainer, range.endOffset)
  return {
    selectionStart: Math.max(0, Math.min(Math.min(start, end), textLength)),
    selectionEnd: Math.max(0, Math.min(Math.max(start, end), textLength)),
  }
}

function getTextNodeAndOffsetForContentEditor(root: HTMLElement, offset: number) {
  const targetOffset = Math.max(0, offset)
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT)
  let currentOffset = 0
  let node = walker.nextNode()
  while (node) {
    const text = node.textContent ?? ''
    const nextOffset = currentOffset + text.length
    if (targetOffset <= nextOffset) {
      return {
        node,
        offset: Math.max(0, Math.min(targetOffset - currentOffset, text.length)),
      }
    }
    currentOffset = nextOffset
    node = walker.nextNode()
  }
  return { node: root, offset: root.childNodes.length }
}

function setRichTextContentEditorSelection(start: number, end = start) {
  const editor = richTextContentEditorRef.value
  if (!editor) {
    return
  }
  const textLength = richTextContentEditor.value.text.length
  const rangeStart = Math.max(0, Math.min(start, textLength))
  const rangeEnd = Math.max(0, Math.min(end, textLength))
  const startPoint = getTextNodeAndOffsetForContentEditor(editor, rangeStart)
  const endPoint = getTextNodeAndOffsetForContentEditor(editor, rangeEnd)
  const range = document.createRange()
  range.setStart(startPoint.node, startPoint.offset)
  range.setEnd(endPoint.node, endPoint.offset)
  const selection = window.getSelection()
  selection?.removeAllRanges()
  selection?.addRange(range)
}

function transformRichTextSpansForTextChange(
  previousText: string,
  nextText: string,
  previousSpans: SheetRichTextSpan[],
) {
  if (previousText === nextText) {
    return normalizeRichTextSpans(previousSpans, nextText.length)
  }

  let prefix = 0
  while (
    prefix < previousText.length
    && prefix < nextText.length
    && previousText[prefix] === nextText[prefix]
  ) {
    prefix += 1
  }

  let suffix = 0
  while (
    suffix < previousText.length - prefix
    && suffix < nextText.length - prefix
    && previousText[previousText.length - 1 - suffix] === nextText[nextText.length - 1 - suffix]
  ) {
    suffix += 1
  }

  const previousSlots = buildRichTextStyleSlots(previousText.length, previousSpans)
  const insertedLength = nextText.length - prefix - suffix
  const oldSuffixStart = previousText.length - suffix
  const inheritedStyle = cloneRichTextStyle(previousSlots[prefix - 1] ?? previousSlots[prefix] ?? null)
  const nextSlots: Array<SheetRichTextStyle | null> = []

  for (let index = 0; index < prefix; index += 1) {
    nextSlots.push(cloneRichTextStyle(previousSlots[index]))
  }
  for (let index = 0; index < insertedLength; index += 1) {
    nextSlots.push(cloneRichTextStyle(inheritedStyle))
  }
  for (let index = 0; index < suffix; index += 1) {
    nextSlots.push(cloneRichTextStyle(previousSlots[oldSuffixStart + index]))
  }

  return compressRichTextStyleSlots(nextSlots.slice(0, nextText.length))
}

function isActiveRichTextContentEditorForCell(cell: SelectedSheetCell | null | undefined) {
  return richTextContentEditor.value.visible && areSheetCellsSame(richTextContentEditor.value.cell, cell)
}

function updateRichTextContentEditorPosition() {
  const state = richTextContentEditor.value
  const cell = state.cell
  if (!state.visible || !cell) {
    return
  }
  const TD = getHotInstance()?.getCell(cell.row, toHotColumnIndex(cell.column), true)
  if (!TD) {
    closeRichTextContentEditor({ save: true })
    return
  }

  const rect = TD.getBoundingClientRect()
  richTextContentEditor.value = {
    ...state,
    left: Math.round(rect.left),
    top: Math.round(rect.top),
    width: Math.max(1, Math.round(rect.width)),
    height: Math.max(1, Math.round(rect.height)),
  }
}

function syncFormulaBarFromRichTextContentEditor(text: string) {
  const editorCell = richTextContentEditor.value.cell
  const cell = formulaBarCell.value
  if (
    !editorCell
    || !cell
    || cell.gridRow !== editorCell.row
    || cell.column !== editorCell.column
    || cell.documentGridRow !== editorCell.documentRow
  ) {
    return
  }
  formulaBarDraft.value = text
}

function commitRichTextContentEditor(options: { close?: boolean; save?: boolean } = {}) {
  const state = richTextContentEditor.value
  const cell = state.cell
  if (!state.visible || !cell) {
    return null
  }

  const finalText = cell.row < sheetHeaderRowCount.value
    ? getRichTextContentEditorText()
    : normalizeCellInputValueForColumn(getRichTextContentEditorText(), cell.column)
  const hot = getHotInstance()
  const valueChanged = getGridCellRawValue(cell.row, cell.column) !== finalText
  if (valueChanged) {
    if (hot) {
      hot.setDataAtCell(cell.row, toHotColumnIndex(cell.column), finalText, 'rich-text-inline')
    } else {
      setSheetCellRawValueAtDocumentCell(cell.documentRow, cell.column, finalText)
    }
  }

  let metaResult: SheetCellMetaPatchResult | null = null
  if (isFormulaExpression(finalText)) {
    metaResult = clearCellRichTextFormat(cell.documentRow, cell.column)
  } else {
    metaResult = setCellRichText(cell.documentRow, cell.column, { spans: state.spans }, finalText)
  }
  syncFormulaBarFromRichTextContentEditor(finalText)
  refreshFormulaDisplayState()
  if (options.save !== false) {
    queueImmediateDataCellValueAndMetaPatchSave(
      cell.documentRow,
      cell.column,
      finalText,
      metaResult,
      valueChanged,
      '富文本保存失败，已保留本地草稿',
    )
  }
  if (options.close) {
    richTextContentEditor.value = {
      ...state,
      visible: false,
      cell: null,
      text: '',
      spans: [],
    }
    hideRichTextInlineToolbar({ force: true })
  }
  return finalText
}

function closeRichTextContentEditor(options: { save?: boolean } = {}) {
  commitRichTextContentEditor({ close: true, save: options.save })
}

function cancelRichTextContentEditor() {
  const state = richTextContentEditor.value
  richTextContentEditor.value = {
    ...state,
    visible: false,
    cell: null,
    text: '',
    spans: [],
  }
  hideRichTextInlineToolbar({ force: true })
  syncFormulaBarDraftFromSelectedCell(true)
  renderCurrentHotWithReason('rich-text-editor-close')
}

function focusRichTextContentEditor(selectionStart: number, selectionEnd = selectionStart) {
  void nextTick(() => {
    const editor = richTextContentEditorRef.value
    if (!editor || !richTextContentEditor.value.visible) {
      return
    }
    editor.focus()
    setRichTextContentEditorSelection(selectionStart, selectionEnd)
    scheduleRichTextInlineToolbarSync()
  })
}

function startRichTextContentEditorFromActiveEditor(editor: SheetActiveEditor) {
  if (typeof editor.row !== 'number' || typeof editor.col !== 'number') {
    return false
  }
  const column = toSheetColumnIndex(editor.col)
  if (column < 0) {
    return false
  }
  const anchor = getMergeAnchorForGridCell(editor.row, column)
  const cell: SelectedSheetCell = {
    row: anchor.row,
    column: anchor.column,
    documentRow: anchor.documentRow,
  }
  if (!canEditCellRichTextTarget(cell)) {
    return false
  }

  const input = getEditorTextInput(editor)
  const text = getActiveEditorDraft(editor)
  if (isFormulaExpression(text)) {
    return false
  }
  const TD = getEditorCellElement(editor)
  if (!TD) {
    return false
  }

  const rect = TD.getBoundingClientRect()
  const style = window.getComputedStyle(TD)
  const selection = normalizeTextSelection(input, text)
  const richText = getCellRichTextAt(cell.documentRow, cell.column, text)
  const editorStyle: Record<string, string> = {
    backgroundColor: normalizeEditorBackgroundColor(style.backgroundColor),
    color: style.color,
    fontFamily: style.fontFamily,
    fontSize: style.fontSize,
    fontWeight: style.fontWeight,
    fontStyle: style.fontStyle,
    lineHeight: style.lineHeight === 'normal' ? `${TABLE_LINE_HEIGHT}px` : style.lineHeight,
    textAlign: style.textAlign,
    padding: `${style.paddingTop} ${style.paddingRight} ${style.paddingBottom} ${style.paddingLeft}`,
    whiteSpace: style.whiteSpace === 'nowrap' ? 'pre' : 'pre-wrap',
    overflowWrap: style.overflowWrap,
    wordBreak: style.wordBreak,
  }

  editor.finishEditing?.(true)
  richTextContentEditor.value = {
    visible: true,
    cell,
    text,
    spans: richText?.spans ?? [],
    left: Math.round(rect.left),
    top: Math.round(rect.top),
    width: Math.max(1, Math.round(rect.width)),
    height: Math.max(1, Math.round(rect.height)),
    style: editorStyle,
  }
  syncFormulaBarFromRichTextContentEditor(text)
  focusRichTextContentEditor(selection.selectionStart, selection.selectionEnd)
  return true
}

function handleRichTextContentEditorInput() {
  const state = richTextContentEditor.value
  if (!state.visible || !state.cell) {
    return
  }
  const selection = getRichTextContentEditorSelectionOffsets()
  const previousText = state.text
  const nextText = getRichTextContentEditorText()
  const nextSpans = transformRichTextSpansForTextChange(previousText, nextText, state.spans)
  richTextContentEditor.value = {
    ...state,
    text: nextText,
    spans: nextSpans,
  }
  syncFormulaBarFromRichTextContentEditor(nextText)
  if (selection) {
    focusRichTextContentEditor(selection.selectionStart, selection.selectionEnd)
  }
}

function handleRichTextContentEditorKeyDown(event: KeyboardEvent) {
  event.stopPropagation()
  if (event.key === 'Escape') {
    event.preventDefault()
    cancelRichTextContentEditor()
    return
  }
  if ((event.ctrlKey || event.metaKey) && !event.altKey) {
    const shortcutKey = event.key.toLowerCase()
    if (shortcutKey === 'b' || shortcutKey === 'i' || shortcutKey === 'u') {
      event.preventDefault()
      if (shortcutKey === 'b') {
        applyRichTextInlineToolbarPatch({ bold: true })
      } else if (shortcutKey === 'i') {
        applyRichTextInlineToolbarPatch({ italic: true })
      } else {
        applyRichTextInlineToolbarPatch({ underline: true })
      }
      return
    }
  }
  if (event.key === 'Enter' && !event.shiftKey && !event.altKey && !event.ctrlKey && !event.metaKey) {
    event.preventDefault()
    closeRichTextContentEditor({ save: true })
    getHotInstance()?.listen?.()
    return
  }
  if (event.key === 'Tab') {
    event.preventDefault()
    closeRichTextContentEditor({ save: true })
    getHotInstance()?.listen?.()
  }
}

function handleRichTextContentEditorPaste(event: ClipboardEvent) {
  const text = event.clipboardData?.getData('text/plain') ?? ''
  if (!text) {
    return
  }
  event.preventDefault()
  document.execCommand('insertText', false, text)
}

function commitPendingSheetGridEdit() {
  if (richTextContentEditor.value.visible) {
    closeRichTextContentEditor({ save: true })
  }
  if (formulaBarFocused.value) {
    commitFormulaBarDraft()
  }

  const editor = getActiveOpenedEditor()
  if (!editor) {
    syncRowsFromGrid()
    return
  }

  const rowIndex = Number(editor.row)
  const columnIndex = toSheetColumnIndex(Number(editor.col))
  const draftValue = getActiveEditorDraft(editor)
  if (typeof editor.finishEditing === 'function') {
    editor.finishEditing(false)
  } else if (Number.isInteger(rowIndex) && Number.isInteger(columnIndex) && rowIndex >= 0 && columnIndex >= 0) {
    const anchor = getMergeAnchorForGridCell(rowIndex, columnIndex)
    if (isSheetHeaderGridRow(anchor.row)) {
      applySheetHeaderGridChange(anchor.row, anchor.column, draftValue)
    } else {
      const dataRow = getDataRowIndex(anchor.row)
      if (dataRow >= 0) {
        const nextRows = rows.value.map((row) => normalizeRow(row, columnHeaders.value))
        if (!nextRows[dataRow]) {
          nextRows[dataRow] = createEmptyRow(columnHeaders.value.length)
        }
        nextRows[dataRow][anchor.column] = normalizeCellInputValueForColumn(draftValue, anchor.column)
        rows.value = nextRows
      }
    }
  }
  syncRowsFromGrid()
}

function normalizeTextSelection(input: HTMLInputElement | HTMLTextAreaElement | null, currentValue: string) {
  const selectionStart = input?.selectionStart ?? currentValue.length
  const selectionEnd = input?.selectionEnd ?? selectionStart
  return {
    selectionStart: Math.max(0, Math.min(selectionStart, currentValue.length)),
    selectionEnd: Math.max(0, Math.min(selectionEnd, currentValue.length)),
  }
}

function isFormulaReferenceTargetSame(
  left: FormulaReferenceEditTarget,
  right: FormulaReferenceEditTarget,
) {
  if (left.kind !== right.kind) {
    return false
  }
  return left.kind === 'formula-bar' || left.editor === (right as { kind: 'inline'; editor: SheetActiveEditor }).editor
}

function clearFormulaReferenceReplacementSpan() {
  formulaReferenceReplacementSpan = null
}

function setFormulaReferenceReplacementSpan(
  target: FormulaReferenceEditTarget,
  start: number,
  text: string,
) {
  formulaReferenceReplacementSpan = {
    target,
    start,
    end: start + text.length,
    text,
  }
}

function getFormulaReferenceReplacementSpan(
  target: FormulaReferenceEditTarget,
  currentValue: string,
  selectionStart: number,
  selectionEnd: number,
) {
  const span = formulaReferenceReplacementSpan
  if (!span) {
    return null
  }

  const validSpan = (
    isFormulaReferenceTargetSame(span.target, target)
    && span.start >= 0
    && span.end >= span.start
    && span.end <= currentValue.length
    && currentValue.slice(span.start, span.end) === span.text
  )
  if (!validSpan) {
    clearFormulaReferenceReplacementSpan()
    return null
  }

  if (selectionStart !== selectionEnd || selectionStart !== span.end) {
    return null
  }

  return span
}

function getFormulaReferenceReplacementBounds(target: FormulaReferenceInsertionTarget) {
  const selectionStart = Math.min(target.selectionStart, target.selectionEnd)
  const selectionEnd = Math.max(target.selectionStart, target.selectionEnd)
  const replacementSpan = getFormulaReferenceReplacementSpan(
    target,
    target.currentValue,
    selectionStart,
    selectionEnd,
  )
  return replacementSpan
    ? { selectionStart: replacementSpan.start, selectionEnd: replacementSpan.end }
    : { selectionStart, selectionEnd }
}

function isFormulaReferenceEditingKey(event: KeyboardEvent) {
  if (event.ctrlKey || event.metaKey || event.altKey) {
    return false
  }
  return event.key.length === 1 || event.key === 'Backspace' || event.key === 'Delete'
}

function isFormulaReferenceEditableMouseTarget(target: Node) {
  const formulaBarInput = getFormulaBarNativeInput()
  if (formulaBarInput && formulaBarInput.contains(target)) {
    return true
  }

  const activeEditor = getActiveOpenedEditor()
  const editorInput = activeEditor ? getEditorTextInput(activeEditor) : null
  return !!editorInput && editorInput.contains(target)
}

function getFormulaReferenceEditTarget(target: FormulaReferenceInsertionTarget): FormulaReferenceEditTarget {
  return target.kind === 'inline'
    ? { kind: 'inline', editor: target.editor }
    : { kind: 'formula-bar' }
}

function getFormulaReferenceTargetCell(target: FormulaReferenceEditTarget) {
  if (target.kind === 'inline' && typeof target.editor.row === 'number' && typeof target.editor.col === 'number') {
    const dataRow = getDataRowIndex(target.editor.row)
    const column = toSheetColumnIndex(target.editor.col)
    return dataRow >= 0 && column >= 0 ? { row: dataRow, column } : null
  }

  const cell = formulaBarCell.value
  return cell && cell.dataRow >= 0 ? { row: cell.dataRow, column: cell.column } : null
}

function getFormulaReferenceArrowDirection(event: KeyboardEvent): FormulaReferenceArrowDirection | null {
  if (event.ctrlKey || event.metaKey || event.altKey || event.isComposing) {
    return null
  }

  switch (event.key) {
    case 'ArrowUp':
      return { rowDelta: -1, columnDelta: 0 }
    case 'ArrowDown':
      return { rowDelta: 1, columnDelta: 0 }
    case 'ArrowLeft':
      return { rowDelta: 0, columnDelta: -1 }
    case 'ArrowRight':
      return { rowDelta: 0, columnDelta: 1 }
    default:
      return null
  }
}

function clampFormulaReferenceRow(rowIndex: number) {
  return Math.max(0, Math.min(rowIndex, Math.max(0, rows.value.length - 1)))
}

function clampFormulaReferenceColumn(columnIndex: number) {
  return Math.max(0, Math.min(columnIndex, Math.max(0, columnHeaders.value.length - 1)))
}

function moveFormulaReferenceBounds(
  bounds: FormulaReferenceRangeBounds,
  direction: FormulaReferenceArrowDirection,
) {
  const topRow = Math.min(bounds.startRow, bounds.currentRow)
  const bottomRow = Math.max(bounds.startRow, bounds.currentRow)
  const leftColumn = Math.min(bounds.startColumn, bounds.currentColumn)
  const rightColumn = Math.max(bounds.startColumn, bounds.currentColumn)
  const maxRow = Math.max(0, rows.value.length - 1)
  const maxColumn = Math.max(0, columnHeaders.value.length - 1)

  let rowDelta = direction.rowDelta
  let columnDelta = direction.columnDelta
  if (topRow + rowDelta < 0) {
    rowDelta = -topRow
  } else if (bottomRow + rowDelta > maxRow) {
    rowDelta = maxRow - bottomRow
  }
  if (leftColumn + columnDelta < 0) {
    columnDelta = -leftColumn
  } else if (rightColumn + columnDelta > maxColumn) {
    columnDelta = maxColumn - rightColumn
  }

  return {
    startRow: bounds.startRow + rowDelta,
    startColumn: bounds.startColumn + columnDelta,
    currentRow: bounds.currentRow + rowDelta,
    currentColumn: bounds.currentColumn + columnDelta,
  }
}

function extendFormulaReferenceBounds(
  bounds: FormulaReferenceRangeBounds,
  direction: FormulaReferenceArrowDirection,
) {
  return {
    ...bounds,
    currentRow: clampFormulaReferenceRow(bounds.currentRow + direction.rowDelta),
    currentColumn: clampFormulaReferenceColumn(bounds.currentColumn + direction.columnDelta),
  }
}

function getFormulaReferenceKeyboardBounds(
  target: FormulaReferenceInsertionTarget,
  direction: FormulaReferenceArrowDirection,
  extendRange: boolean,
) {
  const selectionStart = Math.min(target.selectionStart, target.selectionEnd)
  const selectionEnd = Math.max(target.selectionStart, target.selectionEnd)
  const replacementSpan = getFormulaReferenceReplacementSpan(
    target,
    target.currentValue,
    selectionStart,
    selectionEnd,
  )
  if (replacementSpan && formulaReferencePreviewRange.value) {
    return extendRange
      ? extendFormulaReferenceBounds(formulaReferencePreviewRange.value, direction)
      : moveFormulaReferenceBounds(formulaReferencePreviewRange.value, direction)
  }

  const targetCell = getFormulaReferenceTargetCell(target)
  if (!targetCell) {
    return null
  }

  const rowIndex = clampFormulaReferenceRow(targetCell.row + direction.rowDelta)
  const columnIndex = clampFormulaReferenceColumn(targetCell.column + direction.columnDelta)
  return {
    startRow: rowIndex,
    startColumn: columnIndex,
    currentRow: rowIndex,
    currentColumn: columnIndex,
  }
}

function setFormulaReferenceTargetCaret(target: FormulaReferenceEditTarget, cursorPosition: number) {
  const input = target.kind === 'inline'
    ? getEditorTextInput(target.editor)
    : getFormulaBarNativeInput()
  input?.setSelectionRange(cursorPosition, cursorPosition)
}

function applyFormulaReferenceRangeFromKeyboard(
  target: FormulaReferenceInsertionTarget,
  bounds: FormulaReferenceRangeBounds,
) {
  const editTarget = getFormulaReferenceEditTarget(target)
  const { selectionStart, selectionEnd } = getFormulaReferenceReplacementBounds(target)
  const reference = getCellReferenceRangeLabel(
    bounds.startRow,
    bounds.startColumn,
    bounds.currentRow,
    bounds.currentColumn,
  )
  const nextValue = `${target.currentValue.slice(0, selectionStart)}${reference}${target.currentValue.slice(selectionEnd)}`
  const cursorPosition = selectionStart + reference.length

  setFormulaReferenceTargetValue(editTarget, nextValue)
  setFormulaReferenceReplacementSpan(editTarget, selectionStart, reference)
  setFormulaReferencePreviewRange(bounds)
  renderCurrentHotWithReason('formula-reference-insert')
  setFormulaReferenceTargetCaret(editTarget, cursorPosition)
}

function handleFormulaReferenceArrowKey(event: KeyboardEvent) {
  const direction = getFormulaReferenceArrowDirection(event)
  if (!direction) {
    return false
  }

  const target = getFormulaReferenceInsertionTarget()
  if (!target) {
    return false
  }

  const bounds = getFormulaReferenceKeyboardBounds(target, direction, event.shiftKey)
  if (!bounds) {
    return false
  }

  event.preventDefault()
  event.stopImmediatePropagation()
  applyFormulaReferenceRangeFromKeyboard(target, bounds)
  return true
}

function getFormulaReferenceInsertionTarget(): FormulaReferenceInsertionTarget | null {
  const editor = getActiveOpenedEditor()
  if (editor) {
    const currentValue = getActiveEditorDraft(editor)
    if (currentValue.startsWith('=')) {
      const selection = normalizeTextSelection(getEditorTextInput(editor), currentValue)
      return {
        kind: 'inline',
        editor,
        currentValue,
        ...selection,
      }
    }
  }

  if (!isFormulaReferencePickMode()) {
    return null
  }

  const currentValue = formulaBarDraft.value
  const selection = normalizeTextSelection(getFormulaBarNativeInput(), currentValue)
  return {
    kind: 'formula-bar',
    currentValue,
    ...selection,
  }
}

function isInlineFormulaReferencePickMode() {
  const editor = getActiveOpenedEditor()
  if (!editor) {
    return false
  }
  return getActiveEditorDraft(editor).startsWith('=')
}

function stopFormulaReferenceCellSelection(event: MouseEvent, controller?: CellMouseSelectionController) {
  if (controller) {
    controller.row = false
    controller.column = false
    controller.cell = false
  }
  event.preventDefault()
  event.stopImmediatePropagation()
}

function focusFormulaReferenceTarget(target: FormulaReferenceEditTarget, cursorPosition: number) {
  void nextTick(() => {
    if (target.kind === 'inline') {
      const input = getEditorTextInput(target.editor)
      input?.setSelectionRange(cursorPosition, cursorPosition)
      target.editor.focus?.()
      return
    }

    const input = getFormulaBarNativeInput()
    input?.setSelectionRange(cursorPosition, cursorPosition)
    formulaBarInputRef.value?.focus?.()
  })
}

function setFormulaReferenceTargetValue(
  target: FormulaReferenceEditTarget,
  value: string,
) {
  if (target.kind === 'inline') {
    target.editor.setValue?.(value)
    const input = getEditorTextInput(target.editor)
    if (input) {
      input.value = value
    }
    syncFormulaBarFromInlineEditor(target.editor, value)
  } else {
    formulaBarDraft.value = value
    const input = getFormulaBarNativeInput()
    if (input && input.value !== value) {
      input.value = value
    }
  }
}

function blurFormulaBarInput() {
  formulaBarFocused.value = false
  formulaBarInputRef.value?.blur?.()
  getFormulaBarNativeInput()?.blur()
}

function clearFormulaReferencePointerDownReset() {
  if (formulaReferencePointerDownResetTimer == null) {
    return
  }
  window.clearTimeout(formulaReferencePointerDownResetTimer)
  formulaReferencePointerDownResetTimer = null
}

function markFormulaReferencePointerDown() {
  formulaReferencePointerDown = true
  clearFormulaReferencePointerDownReset()
  formulaReferencePointerDownResetTimer = window.setTimeout(() => {
    formulaReferencePointerDown = false
    formulaReferencePointerDownResetTimer = null
    if (formulaBarFocused.value && document.activeElement !== getFormulaBarNativeInput()) {
      formulaBarFocused.value = false
      commitFormulaBarDraft()
    }
  }, 300)
}

function paintFormulaReferencePreview() {
  const root = sheetFrameRef.value
  if (!root) {
    return
  }

  root
    .querySelectorAll('.sheet-cell-formula-reference-preview')
    .forEach((cell) => cell.classList.remove('sheet-cell-formula-reference-preview'))

  const bounds = normalizeFormulaReferenceRangeBounds(formulaReferencePreviewRange.value)
  const hot = getHotInstance()
  if (!bounds || !hot) {
    return
  }

  for (let rowIndex = bounds.startRow; rowIndex <= bounds.endRow; rowIndex += 1) {
    for (let columnIndex = bounds.startColumn; columnIndex <= bounds.endColumn; columnIndex += 1) {
      hot.getCell(getGridRowIndex(rowIndex), columnIndex)?.classList.add('sheet-cell-formula-reference-preview')
    }
  }
}

function setFormulaReferencePreviewRange(bounds: FormulaReferenceRangeBounds | null) {
  if (areFormulaReferenceRangeBoundsEqual(formulaReferencePreviewRange.value, bounds)) {
    return
  }
  formulaReferencePreviewRange.value = bounds
  paintFormulaReferencePreview()
}

function clearFormulaReferencePreviewRange() {
  if (!formulaReferencePreviewRange.value) {
    return
  }
  setFormulaReferencePreviewRange(null)
}

function renderFormulaReferenceRange(state: FormulaReferenceRangeState) {
  const reference = getCellReferenceRangeLabel(
    state.startRow,
    state.startColumn,
    state.currentRow,
    state.currentColumn,
  )
  const nextValue = `${state.prefix}${reference}${state.suffix}`
  const referenceStart = state.prefix.length
  state.cursorPosition = referenceStart + reference.length
  setFormulaReferenceTargetValue(state.target, nextValue)
  setFormulaReferenceReplacementSpan(state.target, referenceStart, reference)
  setFormulaReferencePreviewRange({
    startRow: state.startRow,
    startColumn: state.startColumn,
    currentRow: state.currentRow,
    currentColumn: state.currentColumn,
  })
}

function beginFormulaReferenceRange(rowIndex: number, columnIndex: number) {
  const target = getFormulaReferenceInsertionTarget()
  if (!target) {
    return false
  }

  clearScheduledFormulaReferenceRangeFinish()
  const { selectionStart, selectionEnd } = getFormulaReferenceReplacementBounds(target)
  formulaReferenceRangeState = {
    target: target.kind === 'inline'
      ? { kind: 'inline', editor: target.editor }
      : { kind: 'formula-bar' },
    prefix: target.currentValue.slice(0, selectionStart),
    suffix: target.currentValue.slice(selectionEnd),
    startRow: rowIndex,
    startColumn: columnIndex,
    currentRow: rowIndex,
    currentColumn: columnIndex,
    cursorPosition: selectionStart,
  }
  window.addEventListener('mouseup', handleFormulaReferenceWindowMouseUp, true)
  renderFormulaReferenceRange(formulaReferenceRangeState)
  return true
}

function updateFormulaReferenceRange(rowIndex: number, columnIndex: number) {
  if (!formulaReferenceRangeState) {
    return
  }

  if (
    formulaReferenceRangeState.currentRow === rowIndex
    && formulaReferenceRangeState.currentColumn === columnIndex
  ) {
    return
  }

  formulaReferenceRangeState.currentRow = rowIndex
  formulaReferenceRangeState.currentColumn = columnIndex
  renderFormulaReferenceRange(formulaReferenceRangeState)
}

function finishFormulaReferenceRange(options: { restoreFocus?: boolean } = {}) {
  clearScheduledFormulaReferenceRangeFinish()
  const finishedState = formulaReferenceRangeState
  formulaReferenceRangeState = null
  window.removeEventListener('mouseup', handleFormulaReferenceWindowMouseUp, true)
  if (options.restoreFocus && finishedState) {
    focusFormulaReferenceTarget(finishedState.target, finishedState.cursorPosition)
  }
}

function handleFormulaReferenceWindowMouseUp() {
  scheduleFormulaReferenceRangeFinish({ restoreFocus: true })
}

function clearScheduledFormulaReferenceRangeFinish() {
  if (formulaReferenceRangeFinishTimer == null) {
    return
  }
  window.clearTimeout(formulaReferenceRangeFinishTimer)
  formulaReferenceRangeFinishTimer = null
}

function scheduleFormulaReferenceRangeFinish(options: { restoreFocus?: boolean } = {}) {
  clearScheduledFormulaReferenceRangeFinish()
  formulaReferenceRangeFinishTimer = window.setTimeout(() => {
    formulaReferenceRangeFinishTimer = null
    finishFormulaReferenceRange(options)
  }, 0)
}

function insertFormulaReferenceText(reference: string) {
  const target = getFormulaReferenceInsertionTarget()
  if (!target) {
    return false
  }

  const editTarget = getFormulaReferenceEditTarget(target)
  const { selectionStart, selectionEnd } = getFormulaReferenceReplacementBounds(target)
  const nextValue = `${target.currentValue.slice(0, selectionStart)}${reference}${target.currentValue.slice(selectionEnd)}`
  const cursorPosition = selectionStart + reference.length

  setFormulaReferenceTargetValue(editTarget, nextValue)
  setFormulaReferenceReplacementSpan(editTarget, selectionStart, reference)
  focusFormulaReferenceTarget(editTarget, cursorPosition)
  return true
}

function insertFormulaReferenceIntoDraft(rowIndex: number, columnIndex: number) {
  return insertFormulaReferenceText(getCellReferenceLabel(rowIndex, columnIndex))
}

function syncFormulaBarFromInlineEditor(editor: SheetActiveEditor, value: string) {
  if (typeof editor.row !== 'number' || typeof editor.col !== 'number') {
    return
  }
  const cell = createFormulaBarCellFromGridCell(editor.row, toSheetColumnIndex(editor.col))
  if (!cell) {
    return
  }
  formulaBarCell.value = cell
  formulaBarDraft.value = value
}

function syncInlineEditorToCellEditText(editor: SheetActiveEditor) {
  if (typeof editor.row !== 'number' || typeof editor.col !== 'number') {
    return
  }

  const cell = createFormulaBarCellFromGridCell(editor.row, toSheetColumnIndex(editor.col))
  if (!cell) {
    return
  }
  const rawValue = getFormulaBarCellRawValue(cell)
  const editText = getFormulaBarCellEditText(cell)
  if (editText === rawValue || getActiveEditorDraft(editor) !== rawValue) {
    return
  }

  editor.setValue?.(editText)
  const input = getEditorTextInput(editor)
  if (input) {
    input.value = editText
    input.select()
  }
}

function isEditorForFormulaBarCell(editor: SheetActiveEditor) {
  const cell = formulaBarCell.value
  if (!cell || typeof editor.row !== 'number' || typeof editor.col !== 'number') {
    return false
  }
  const editorCell = createFormulaBarCellFromGridCell(editor.row, toSheetColumnIndex(editor.col))
  return !!editorCell && editorCell.gridRow === cell.gridRow && editorCell.column === cell.column
}

function syncFormulaBarFromActiveInlineEditor() {
  const editor = getActiveOpenedEditor()
  if (!editor) {
    return false
  }

  syncFormulaBarFromInlineEditor(editor, getActiveEditorDraft(editor))
  return true
}

function clearScheduledInlineEditorFormulaBarSync() {
  if (inlineEditorFormulaBarSyncTimer == null) {
    return
  }
  window.clearTimeout(inlineEditorFormulaBarSyncTimer)
  inlineEditorFormulaBarSyncTimer = null
}

function scheduleInlineEditorFormulaBarSync() {
  clearScheduledInlineEditorFormulaBarSync()
  if (!getActiveOpenedEditor()) {
    return
  }
  inlineEditorFormulaBarSyncTimer = window.setTimeout(() => {
    inlineEditorFormulaBarSyncTimer = null
    syncFormulaBarFromActiveInlineEditor()
  }, 0)
}

function syncActiveInlineEditorFromFormulaBarDraft(value: string) {
  const richTextEditorCell = richTextContentEditor.value.cell
  const formulaCell = formulaBarCell.value
  if (
    richTextContentEditor.value.visible
    && richTextEditorCell
    && formulaCell
    && formulaCell.gridRow === richTextEditorCell.row
    && formulaCell.column === richTextEditorCell.column
    && formulaCell.documentGridRow === richTextEditorCell.documentRow
  ) {
    const previousText = richTextContentEditor.value.text
    richTextContentEditor.value = {
      ...richTextContentEditor.value,
      text: value,
      spans: transformRichTextSpansForTextChange(previousText, value, richTextContentEditor.value.spans),
    }
    focusRichTextContentEditor(Math.min(value.length, value.length))
    return
  }

  const editor = getActiveOpenedEditor()
  if (!editor || !isEditorForFormulaBarCell(editor)) {
    return
  }

  editor.setValue?.(value)
  const input = getEditorTextInput(editor)
  if (input && input.value !== value) {
    input.value = value
  }
}

function handleInlineEditorInput(event: Event) {
  const editor = getActiveOpenedEditor()
  const input = editor ? getEditorTextInput(editor) : null
  if (!editor || event.target !== input) {
    return
  }

  clearFormulaReferenceReplacementSpan()
  syncFormulaBarFromInlineEditor(editor, input.value)
  scheduleRichTextInlineToolbarSync()
}

function handleAfterBeginEditing() {
  const editor = getActiveOpenedEditor()
  if (editor) {
    closeRichTextContentEditor({ save: true })
    syncInlineEditorToCellEditText(editor)
    if (startRichTextContentEditorFromActiveEditor(editor)) {
      scheduleInlineEditorFormulaBarSync()
      scheduleRichTextInlineToolbarSync()
      return
    }
  }
  scheduleInlineEditorCellStyleSync()
  scheduleInlineEditorFormulaBarSync()
  scheduleRichTextInlineToolbarSync()
}

function isUndoShortcut(event: KeyboardEvent) {
  return (event.ctrlKey || event.metaKey)
    && !event.altKey
    && !event.shiftKey
    && event.key.toLowerCase() === 'z'
}

function isRedoShortcut(event: KeyboardEvent) {
  return (event.ctrlKey || event.metaKey)
    && !event.altKey
    && (
      (!event.shiftKey && event.key.toLowerCase() === 'y')
      || (event.shiftKey && event.key.toLowerCase() === 'z')
    )
}

function isTextEditingTarget(target: EventTarget | null) {
  return target instanceof HTMLInputElement
    || target instanceof HTMLTextAreaElement
    || (target instanceof HTMLElement && target.isContentEditable)
}

function isFormulaBarDraftSyncedWithCell() {
  const cell = formulaBarCell.value
  if (!cell) {
    return false
  }
  return formulaBarDraft.value === getFormulaBarCellEditText(cell)
}

function canRouteFormulaBarUndoRedo(event: KeyboardEvent) {
  return event.target instanceof HTMLElement
    && !!event.target.closest('.sheet-formula-input')
    && isFormulaBarDraftSyncedWithCell()
}

function handleUndoRedoShortcut(event: KeyboardEvent, options: { allowSyncedFormulaBar?: boolean } = {}) {
  const wantsUndo = isUndoShortcut(event)
  const wantsRedo = isRedoShortcut(event)
  if (!wantsUndo && !wantsRedo) {
    return false
  }

  if (getActiveOpenedEditor()) {
    return false
  }

  const routeFormulaBarShortcut = options.allowSyncedFormulaBar && canRouteFormulaBarUndoRedo(event)
  if (isTextEditingTarget(event.target) && !routeFormulaBarShortcut) {
    return false
  }

  if (wantsUndo) {
    if (!undoSheetChange()) {
      return false
    }
    event.preventDefault()
    return true
  }

  if (!redoSheetChange()) {
    return false
  }
  event.preventDefault()
  return true
}

function handleBeforeKeyDown(event: KeyboardEvent) {
  if (isSheetNavigationKey(event)) {
    markSheetPerfInput({
      kind: 'keyboard',
      key: event.key,
    })
  }

  if (shouldBlockRowMarkerKeyboardNavigation(event)) {
    event.preventDefault()
    event.stopImmediatePropagation()
    redirectSingleRowMarkerSelection()
    return false
  }
  if (handleUndoRedoShortcut(event)) {
    return false
  }
  if (handleFormulaReferenceArrowKey(event)) {
    return false
  }
  if (clearSelectedEditableDataCellsFromKeyboard(event)) {
    return false
  }
  return undefined
}

function handleAfterDocumentKeyDown(event: KeyboardEvent) {
  if (isFormulaReferenceEditingKey(event)) {
    clearFormulaReferenceReplacementSpan()
  }
  scheduleInlineEditorFormulaBarSync()
  scheduleRichTextInlineToolbarSync()
}

function handleFormulaBarKeyDown(event: KeyboardEvent) {
  if (handleUndoRedoShortcut(event, { allowSyncedFormulaBar: true })) {
    return
  }
  if (handleFormulaReferenceArrowKey(event)) {
    return
  }
  if (isFormulaReferenceEditingKey(event)) {
    clearFormulaReferenceReplacementSpan()
  }
}

function insertFormulaReferenceIntoActiveEditor(rowIndex: number, columnIndex: number) {
  return insertFormulaReferenceText(getCellReferenceLabel(rowIndex, columnIndex))
}

function commitFormulaBarDraft() {
  const cell = formulaBarCell.value
  if (!cell) {
    return
  }

  if (cell.dataRow < 0) {
    if (!canEditConfig.value) {
      syncFormulaBarDraftFromSelectedCell(true)
      clearFormulaReferenceReplacementSpan()
      clearFormulaReferencePreviewRange()
      return
    }

    const nextValue = normalizeCellValue(formulaBarDraft.value)
    if (nextValue === getFormulaBarCellRawValue(cell)) {
      formulaBarDraft.value = nextValue
      clearFormulaReferenceReplacementSpan()
      clearFormulaReferencePreviewRange()
      return
    }

    pushLocalUndoSnapshot('header-edit')
    if (applySheetHeaderGridChange(cell.gridRow, cell.column, nextValue)) {
      clearEditingColumnState()
      refreshGridStructure()
      refreshFormulaDisplayState()
      void refreshComputedRowHeights()
    }
    syncFormulaBarDraftFromSelectedCell(true)
    clearFormulaReferenceReplacementSpan()
    clearFormulaReferencePreviewRange()
    renderCurrentHotWithReason('formula-bar-commit-structure')
    return
  }

  if (!canEditDataColumn(cell.column)) {
    syncFormulaBarDraftFromSelectedCell(true)
    clearFormulaReferenceReplacementSpan()
    clearFormulaReferencePreviewRange()
    return
  }

  const nextValue = normalizeCellInputValueForColumn(formulaBarDraft.value, cell.column)
  if (nextValue === getRawCellValue(cell.dataRow, cell.column)) {
    formulaBarDraft.value = getCellEditText(cell.column, nextValue)
    clearFormulaReferenceReplacementSpan()
    clearFormulaReferencePreviewRange()
    return
  }

  const hot = getHotInstance()
  if (hot) {
    hot.setDataAtCell(cell.gridRow, toHotColumnIndex(cell.column), nextValue, 'formula-bar')
  } else {
    pushLocalUndoSnapshot('cell-edit')
    const nextRows = rows.value.map((row) => normalizeRow(row, columnHeaders.value))
    if (!nextRows[cell.dataRow]) {
      nextRows[cell.dataRow] = createEmptyRow(columnHeaders.value.length)
    }
    nextRows[cell.dataRow][cell.column] = nextValue
    rows.value = nextRows
  }

  syncRowsFromGrid()
  syncFormulaBarDraftFromSelectedCell(true)
  clearFormulaReferenceReplacementSpan()
  clearFormulaReferencePreviewRange()
  renderCurrentHotWithReason('formula-bar-commit-value')
  void refreshComputedRowHeights()
}

function setFormulaBarGridCell(gridRowIndex: number, columnIndex: number) {
  const nextCell = createFormulaBarCellFromGridCell(gridRowIndex, columnIndex)
  if (!nextCell) {
    clearFormulaBarSelection()
    return
  }

  if (formulaBarFocused.value && !isSameFormulaBarCell(nextCell.gridRow, nextCell.column)) {
    commitFormulaBarDraft()
  }

  formulaBarCell.value = nextCell
  scheduleFormulaBarDraftFromSelectedCell(true)
}

function updateFormulaBarDraft(value: string) {
  if (!canEditFormulaBarCell()) {
    syncFormulaBarDraftFromSelectedCell(true)
    return
  }
  clearFormulaReferenceReplacementSpan()
  formulaBarDraft.value = value
  syncActiveInlineEditorFromFormulaBarDraft(value)
}

function handleFormulaBarFocus() {
  clearScheduledFormulaBarDraftSync()
  syncFormulaBarDraftFromSelectedCell(true)
  formulaBarFocused.value = true
}

function handleFormulaBarBlur() {
  if (formulaReferencePointerDown) {
    return
  }
  formulaBarFocused.value = false
  commitFormulaBarDraft()
}

function resetFormulaBarDraft() {
  clearFormulaReferenceReplacementSpan()
  syncFormulaBarDraftFromSelectedCell(true)
}

function commitFormulaBarDraftAndExit() {
  commitFormulaBarDraft()
  blurFormulaBarInput()
}

function resetFormulaBarDraftAndExit() {
  resetFormulaBarDraft()
  clearFormulaReferencePreviewRange()
  blurFormulaBarInput()
}

function handleAfterSelection(row: number, hotColumn: number) {
  const inputTiming = consumeSheetPerfInputMarker()
  const trace = startSheetPerfTrace('selection.after', {
    row,
    hotColumn,
    waitMs: inputTiming?.waitMs,
    detail: inputTiming
      ? {
          inputKind: inputTiming.marker.kind,
          inputKey: inputTiming.marker.key,
          inputButton: inputTiming.marker.button,
          inputRow: inputTiming.marker.row,
          inputHotColumn: inputTiming.marker.hotColumn,
        }
      : undefined,
  })
  const finishPerf = (exit: string, detail: SheetPerfLogContext = {}) => {
    const cell = formulaBarCell.value
    trace?.finish({
      exit,
      formulaBarFocused: formulaBarFocused.value,
      address: getSheetPerfCellAddress(cell),
      dataRow: cell?.dataRow,
      column: cell?.column,
      documentGridRow: cell?.documentGridRow,
      ...detail,
    })
  }

  refreshContextMenuFallbackSelectionState()
  trace?.mark('contextMenuSelection')
  if (deferredCellSelectionState) {
    finishPerf('deferred')
    return
  }
  if (hotColumn >= 0 && isSingleRowMarkerCellSelection()) {
    trace?.mark('rowMarkerRedirect')
    redirectSingleRowMarkerSelection()
    finishPerf('rowMarkerRedirect')
    return
  }
  const column = hotColumn >= 0 ? toSheetColumnIndex(hotColumn) : hotColumn
  trace?.mark('resolveColumn')
  if (hotColumn >= 0 && column < 0) {
    clearSheetHeaderSelection()
    trace?.mark('clearHeader')
    clearFormulaBarSelection()
    trace?.mark('clearFormulaBar')
    syncColumnMarkerSelection()
    trace?.mark('columnMarker')
    finishPerf('invalidHotColumn', { column })
    return
  }
  if (isSheetHeaderGridRow(row) && column >= 0) {
    const anchor = getMergeAnchorForGridCell(row, column)
    const headerLevel = getSheetHeaderGridLevel(anchor.row)
    trace?.mark('headerAnchor')
    if (!isSheetHeaderCellSelected(anchor.column, headerLevel)) {
      selectedSheetHeaderCell.value = { column: anchor.column, headerLevel }
    }
    trace?.mark('headerState')
    setFormulaBarGridCell(anchor.row, anchor.column)
    trace?.mark('formulaBar')
    syncColumnMarkerSelection()
    trace?.mark('columnMarker')
    if (shouldRealignOverlayForSelection(row, column)) {
      scheduleSheetOverlayAlignment()
      trace?.mark('overlayAlignment')
    }
    finishPerf('header', {
      row: anchor.row,
      column: anchor.column,
      documentGridRow: anchor.documentRow,
    })
    return
  }
  clearSheetHeaderSelection()
  trace?.mark('clearHeader')
  if (formulaReferenceRangeState) {
    syncColumnMarkerSelection()
    trace?.mark('columnMarker')
    finishPerf('formulaReferenceRange', { column })
    return
  }

  const dataRow = row >= 0 ? getDataRowIndex(row) : -1
  trace?.mark('resolveDataRow')
  if (formulaReferencePointerDown && dataRow >= 0 && column >= 0 && isFormulaReferencePickMode()) {
    clearFormulaReferencePointerDownReset()
    formulaReferencePointerDown = false
    const anchor = getMergeAnchorForGridCell(row, column)
    trace?.mark('referenceAnchor')
    insertFormulaReferenceIntoDraft(getDataRowIndex(anchor.row), anchor.column)
    trace?.mark('insertFormulaReference')
    syncColumnMarkerSelection()
    trace?.mark('columnMarker')
    finishPerf('formulaReferencePick', {
      row: anchor.row,
      column: anchor.column,
      dataRow: getDataRowIndex(anchor.row),
      documentGridRow: anchor.documentRow,
    })
    return
  }

  clearFormulaReferencePointerDownReset()
  formulaReferencePointerDown = false
  clearFormulaReferencePreviewRange()
  trace?.mark('clearFormulaReference')
  if (row >= 0 && column >= 0) {
    const anchor = getMergeAnchorForGridCell(row, column)
    trace?.mark('cellAnchor')
    setFormulaBarGridCell(anchor.row, anchor.column)
    trace?.mark('formulaBar')
    if (shouldRealignOverlayForSelection(row, column)) {
      scheduleSheetOverlayAlignment()
      trace?.mark('overlayAlignment')
    }
  } else {
    clearFormulaBarSelection()
    trace?.mark('clearFormulaBar')
  }
  syncColumnMarkerSelection()
  trace?.mark('columnMarker')
  finishPerf(row >= 0 && column >= 0 ? 'cell' : 'cleared', { column })
}

function handleAfterDeselect() {
  closeRichTextContentEditor({ save: true })
  clearFormulaBarSelection()
  clearColumnMarkerSelection()
  clearRowMarkerSelectionAnchor()
  clearSheetHeaderSelection()
  hasContextMenuFallbackSelection.value = false
  hideRichTextInlineToolbar({ force: true })
}

function getSingleSelectedDataCell() {
  const selection = getHotInstance()?.getSelectedLast()
  if (!selection) {
    return null
  }

  const startRow = Math.min(selection[0], selection[2])
  const endRow = Math.max(selection[0], selection[2])
  const columnRange = getSheetColumnRangeFromHotRange(selection[1], selection[3])
  if (!columnRange) {
    return null
  }
  const startColumn = columnRange.start
  const endColumn = columnRange.end
  const anchor = getMergeAnchorForGridCell(startRow, startColumn)
  const dataRow = getDataRowIndex(anchor.row)
  if (
    dataRow < 0
    || startColumn < 0
    || startRow !== endRow
    || startColumn !== endColumn
  ) {
    return null
  }

  return {
    row: dataRow,
    column: anchor.column,
    documentRow: getDocumentRowIndex(dataRow),
  }
}

function getSelectedDataCells(): SelectedDataCell[] {
  const hot = getHotInstance()
  const selections = hot?.getSelected?.() as number[][] | undefined
  if (!selections?.length || rows.value.length <= 0 || columnHeaders.value.length <= 0) {
    return []
  }

  const cells: SelectedDataCell[] = []
  const seen = new Set<string>()
  for (const selection of selections) {
    if (!Array.isArray(selection) || selection.length < 4) {
      continue
    }

    const startRow = Math.max(getDataRowIndex(Math.min(selection[0], selection[2])), 0)
    const endRow = Math.min(getDataRowIndex(Math.max(selection[0], selection[2])), rows.value.length - 1)
    const columnRange = getSheetColumnRangeFromHotRange(selection[1], selection[3])
    if (!columnRange) {
      continue
    }
    const startColumn = columnRange.start
    const endColumn = columnRange.end
    if (startRow > endRow || startColumn > endColumn) {
      continue
    }

    for (let row = startRow; row <= endRow; row += 1) {
      const documentRow = getDocumentRowIndex(row)
      for (let column = startColumn; column <= endColumn; column += 1) {
        const key = createCellMetaKey(documentRow, column)
        if (seen.has(key)) {
          continue
        }
        seen.add(key)
        cells.push({ row, column, documentRow })
      }
    }
  }

  return cells
}

function getSingleSelectedSheetCell() {
  const cells = getSelectedSheetCells()
  return cells.length === 1 ? cells[0] : null
}

function getSelectedSheetCells(): SelectedSheetCell[] {
  const hot = getHotInstance()
  const selections = hot?.getSelected?.() as number[][] | undefined
  if (!selections?.length || sheetGridRows.value.length <= 0 || columnHeaders.value.length <= 0) {
    return []
  }

  const cells: SelectedSheetCell[] = []
  const seen = new Set<string>()
  for (const selection of selections) {
    if (!Array.isArray(selection) || selection.length < 4) {
      continue
    }

    const startRow = Math.max(Math.min(selection[0], selection[2]), 0)
    const endRow = Math.min(Math.max(selection[0], selection[2]), sheetGridRows.value.length - 1)
    const columnRange = getSheetColumnRangeFromHotRange(selection[1], selection[3])
    if (!columnRange) {
      continue
    }
    const startColumn = columnRange.start
    const endColumn = columnRange.end
    if (startRow > endRow || startColumn > endColumn) {
      continue
    }

    for (let row = startRow; row <= endRow; row += 1) {
      for (let column = startColumn; column <= endColumn; column += 1) {
        const anchor = getMergeAnchorForGridCell(row, column)
        const key = createCellMetaKey(anchor.documentRow, anchor.column)
        if (seen.has(key)) {
          continue
        }
        seen.add(key)
        cells.push({ row: anchor.row, column: anchor.column, documentRow: anchor.documentRow })
      }
    }
  }

  return normalizeSheetCellsToMergeAnchors(cells)
}

function hasSingleDataCellSelection() {
  return !!getSingleSelectedDataCell()
}

function hasDataCellSelection() {
  return getSelectedDataCells().length > 0
}

function hasSheetCellSelection() {
  return getSelectedSheetCells().length > 0
}

function hasSingleSheetCellSelection() {
  return !!getSingleSelectedSheetCell()
}

function getSelectedGridCellBounds() {
  const selection = getHotInstance()?.getSelectedLast()
  if (!selection) {
    return null
  }
  const startRow = Math.min(selection[0], selection[2])
  const endRow = Math.max(selection[0], selection[2])
  const columnRange = getSheetColumnRangeFromHotRange(selection[1], selection[3])
  if (endRow < 0 || !columnRange) {
    return null
  }
  return {
    startRow: Math.max(startRow, 0),
    endRow: Math.min(endRow, sheetGridRows.value.length - 1),
    startColumn: columnRange.start,
    endColumn: columnRange.end,
  }
}

function getSelectedDocumentCellBounds() {
  const bounds = getSelectedGridCellBounds()
  if (!bounds || bounds.startRow > bounds.endRow || bounds.startColumn > bounds.endColumn) {
    return null
  }
  return {
    startRow: getDocumentGridRowIndex(bounds.startRow),
    endRow: getDocumentGridRowIndex(bounds.endRow),
    startColumn: bounds.startColumn,
    endColumn: bounds.endColumn,
  }
}

function doMergedCellsIntersectRange(
  cell: SheetMergedCell,
  range: { startRow: number; endRow: number; startColumn: number; endColumn: number },
) {
  return (
    cell.row <= range.endRow
    && cell.row + cell.rowspan - 1 >= range.startRow
    && cell.col <= range.endColumn
    && cell.col + cell.colspan - 1 >= range.startColumn
  )
}

function selectionCrossesDataStart(range: { startRow: number; endRow: number }) {
  return range.startRow < sheetHeaderRowCount.value && range.endRow >= sheetHeaderRowCount.value
}

function getMergedCellsDocumentRowCount() {
  return Math.max(sheetHeaderRowCount.value + totalRowCount.value, sheetHeaderRowCount.value + rows.value.length, sheetGridRows.value.length)
}

function canMergeSelectedCells() {
  if (isWholeRowSelection()) {
    return false
  }

  const range = getSelectedDocumentCellBounds()
  if (!range) {
    return false
  }
  if (range.startRow === range.endRow && range.startColumn === range.endColumn) {
    return false
  }
  if (selectionCrossesDataStart(range)) {
    return false
  }
  return !normalizeMergedCells(
    mergedCells.value,
    getMergedCellsDocumentRowCount(),
    columnHeaders.value.length,
  ).some((cell) => doMergedCellsIntersectRange(cell, range))
}

function rangeFullyContainsMergedCell(
  range: { startRow: number; endRow: number; startColumn: number; endColumn: number },
  cell: SheetMergedCell,
) {
  return (
    range.startRow <= cell.row
    && range.endRow >= cell.row + cell.rowspan - 1
    && range.startColumn <= cell.col
    && range.endColumn >= cell.col + cell.colspan - 1
  )
}

function rangePartiallyIntersectsMergedCells(range: { startRow: number; endRow: number; startColumn: number; endColumn: number }) {
  return normalizeCurrentMergedCells().some((cell) => (
    doMergedCellsIntersectRange(cell, range)
    && !rangeFullyContainsMergedCell(range, cell)
  ))
}

function mergeSelectedCells() {
  if (!ensureCanEditConfig() || !canMergeSelectedCells()) {
    return
  }
  commitPendingSheetGridEdit()
  const range = getSelectedDocumentCellBounds()
  if (!range) {
    return
  }
  const nextCell: SheetMergedCell = {
    row: range.startRow,
    col: range.startColumn,
    rowspan: range.endRow - range.startRow + 1,
    colspan: range.endColumn - range.startColumn + 1,
  }
  const undoEntry = createLocalUndoEntry('merge-cells')
  const anchorSynced = syncMergedCellAnchorFromVisibleGrid(nextCell)
  if (!anchorSynced) {
    suppressNextRemoteSaveWatcher = true
  }
  mergedCells.value = normalizeMergedCells(
    [...mergedCells.value, nextCell],
    getMergedCellsDocumentRowCount(),
    columnHeaders.value.length,
  )
  refreshGridStructure()
  if (anchorSynced) {
    refreshFormulaDisplayState()
  }
  pushLocalUndoEntry(undoEntry)
  if (anchorSynced) {
    scheduleRemoteSave(0)
  } else {
    queueImmediateMergePatchSave([{
      op: 'merge-cells',
      row: nextCell.row,
      col: nextCell.col,
      rowspan: nextCell.rowspan,
      colspan: nextCell.colspan,
    }])
  }
}

function getSelectedMergedCells() {
  const range = getSelectedDocumentCellBounds()
  if (!range) {
    return []
  }
  return normalizeMergedCells(
    mergedCells.value,
    getMergedCellsDocumentRowCount(),
    columnHeaders.value.length,
  ).filter((cell) => doMergedCellsIntersectRange(cell, range))
}

function hasSelectedMergedCell() {
  return getSelectedMergedCells().length > 0
}

function setSheetCellRawValueAtDocumentCell(documentRow: number, columnIndex: number, value: string) {
  const gridRow = getCurrentGridRowIndexFromDocumentRow(documentRow)
  if (gridRow < 0 || columnIndex < 0 || columnIndex >= columnHeaders.value.length) {
    return false
  }

  if (gridRow < sheetHeaderRowCount.value) {
    const changed = applySheetHeaderGridChange(gridRow, columnIndex, value)
    if (changed) {
      setEntityCellRawValue(documentRow, columnIndex, value)
    }
    return changed
  }

  const dataRow = getDataRowIndex(gridRow)
  if (dataRow < 0 || dataRow >= rows.value.length) {
    return false
  }

  const nextRows = rows.value.map((row) => normalizeRow(row, columnHeaders.value))
  if (!nextRows[dataRow]) {
    nextRows[dataRow] = createEmptyRow(columnHeaders.value.length)
  }
  nextRows[dataRow][columnIndex] = normalizeCellInputValueForColumn(value, columnIndex)
  rows.value = nextRows
  setEntityCellRawValue(documentRow, columnIndex, nextRows[dataRow][columnIndex])
  return true
}

function syncMergedCellAnchorFromVisibleGrid(cell: SheetMergedCell) {
  const gridRow = getCurrentGridRowIndexFromDocumentRow(cell.row)
  if (gridRow < 0 || cell.col < 0 || cell.col >= columnHeaders.value.length) {
    return false
  }

  const visibleValue = (
    getLiveGridCellRawValue(gridRow, cell.col)
    || getGridCellRawValue(gridRow, cell.col)
    || getGridCellRenderSourceValue(gridRow, cell.col)
    || inferBlankHeaderMergeLabel(sheetGridRows.value, columnHeaders.value, cell, columnHeaderLevel.value)
  )
  if (!visibleValue) {
    return false
  }

  return setSheetCellRawValueAtDocumentCell(cell.row, cell.col, visibleValue)
}

function unmergeSelectedCells() {
  if (!ensureCanEditConfig()) {
    return
  }
  commitPendingSheetGridEdit()
  const selected = getSelectedMergedCells()
  if (!selected.length) {
    return
  }
  const undoEntry = createLocalUndoEntry('unmerge-cells')
  let anchorSynced = false
  selected.forEach((cell) => {
    anchorSynced = syncMergedCellAnchorFromVisibleGrid(cell) || anchorSynced
  })
  const selectedKeys = new Set(selected.map((cell) => `${cell.row}:${cell.col}`))
  if (!anchorSynced) {
    suppressNextRemoteSaveWatcher = true
  }
  mergedCells.value = normalizeMergedCells(
    mergedCells.value.filter((cell) => !selectedKeys.has(`${cell.row}:${cell.col}`)),
    getMergedCellsDocumentRowCount(),
    columnHeaders.value.length,
  )
  refreshGridStructure()
  pushLocalUndoEntry(undoEntry)
  if (anchorSynced) {
    refreshFormulaDisplayState()
    scheduleRemoteSave(0)
  } else {
    queueImmediateMergePatchSave(selected.map((cell): NoteSheetPatchOperation => ({
      op: 'unmerge-cells',
      row: cell.row,
      col: cell.col,
    })))
  }
}

function getCellMetaAt(documentRow: number, columnIndex: number) {
  return mergeCellMetaEntries(
    cellMeta.value[createCellMetaKey(documentRow, columnIndex)] ?? null,
    getEntityCellMeta(getEntityCellAt(documentRow, columnIndex)),
  )
}

function getCellLinkAt(documentRow: number, columnIndex: number) {
  if (documentRow >= 0 && documentRow < sheetHeaderRowCount.value) {
    const headerRow = sheetGridRows.value[documentRow]
    const inlineLink = Array.isArray(headerRow) ? normalizeCellLink(headerRow[columnIndex]) : null
    if (inlineLink) {
      return inlineLink
    }
  }
  return getCellMetaAt(documentRow, columnIndex)?.link ?? null
}

function getCellActionAt(documentRow: number, columnIndex: number) {
  const action = getCellMetaAt(documentRow, columnIndex)?.action ?? null
  if (!action || action.type === SHEET_CELL_ACTION_ATTENDANCE_COURSE_UPDATE_DATA) {
    return null
  }
  return isSheetCellActionAllowedAt(action, documentRow, columnIndex) ? action : null
}

function getCellStyleAt(documentRow: number, columnIndex: number) {
  return getCellMetaAt(documentRow, columnIndex)?.style ?? null
}

function getCellFormatTypeAt(documentRow: number, columnIndex: number): CellFormatType {
  const meta = getCellMetaAt(documentRow, columnIndex)
  return meta?.cell_type === 'rich_text' || meta?.rich_text ? 'rich_text' : 'normal'
}

function isRichTextCellAt(documentRow: number, columnIndex: number) {
  return getCellFormatTypeAt(documentRow, columnIndex) === 'rich_text'
}

function getCellRichTextAt(documentRow: number, columnIndex: number, text: string) {
  if (isFormulaExpression(text)) {
    return null
  }
  return normalizeRichTextForText(getCellMetaAt(documentRow, columnIndex)?.rich_text, text)
}

function hasCellRichTextAt(documentRow: number, columnIndex: number) {
  return !!getCellMetaAt(documentRow, columnIndex)?.rich_text
}

function updateCellMetaEntry(
  documentRow: number,
  columnIndex: number,
  updater: (entry: SheetCellMeta) => SheetCellMeta,
): SheetCellMetaPatchResult | null {
  const anchor = getMergeAnchorForDocumentCell(documentRow, columnIndex)
  const targetRow = anchor.documentRow
  const targetColumn = anchor.column
  const nextMeta = { ...cellMeta.value }
  const key = createCellMetaKey(targetRow, targetColumn)
  const nextEntry = normalizeCellMetaEntry(updater({ ...(nextMeta[key] ?? {}) }))
  updateEntityCellEntry(targetRow, targetColumn, (entry) => {
    const currentMeta = getEntityCellMeta(entry) ?? nextMeta[key] ?? {}
    const updatedMeta = normalizeCellMetaEntry(updater({ ...currentMeta }))
    return replaceEntityCellMeta(entry, updatedMeta)
  })
  if (nextEntry) {
    nextMeta[key] = nextEntry
  } else {
    delete nextMeta[key]
  }
  cellMeta.value = normalizeCellMetaMap(nextMeta, columnHeaders.value.length)
  renderCurrentHotWithReason('cell-meta-set')
  return {
    documentRow: targetRow,
    column: targetColumn,
    meta: nextEntry,
  }
}

function setCellLink(documentRow: number, columnIndex: number, url: string) {
  const normalizedUrl = normalizeHyperlinkUrl(url)
  return updateCellMetaEntry(documentRow, columnIndex, (entry) => {
    const nextEntry = { ...entry }
    if (normalizedUrl) {
      nextEntry.link = { url: normalizedUrl }
    } else {
      delete nextEntry.link
    }
    return nextEntry
  })
}

function setColumnHeaderLink(columnIndex: number, url: string) {
  const header = columnHeaders.value[columnIndex]
  if (!header) {
    return
  }

  const normalizedLink = normalizeCellLink({ url })
  const nextConfigs = { ...columnConfigs.value }
  const nextConfig: SheetColumnConfig = { ...(nextConfigs[header] ?? {}) }
  if (normalizedLink) {
    nextConfig.header_link = normalizedLink
  } else {
    delete nextConfig.header_link
  }
  nextConfigs[header] = nextConfig
  columnConfigs.value = normalizeColumnConfigs(nextConfigs, columnHeaders.value)
  refreshGridStructure()
}

function setCellStyle(documentRow: number, columnIndex: number, styleSource: unknown) {
  const normalizedStyle = normalizeCellStyle(styleSource)
  return updateCellMetaEntry(documentRow, columnIndex, (entry) => {
    const nextEntry = { ...entry }
    if (normalizedStyle) {
      nextEntry.style = normalizedStyle
    } else {
      delete nextEntry.style
    }
    return nextEntry
  })
}

function setCellRichText(documentRow: number, columnIndex: number, richTextSource: unknown, text: string) {
  const normalizedRichText = isFormulaExpression(text)
    ? null
    : normalizeRichTextForText(richTextSource, text)
  return updateCellMetaEntry(documentRow, columnIndex, (entry) => {
    const nextEntry = { ...entry }
    if (normalizedRichText) {
      nextEntry.cell_type = 'rich_text'
      nextEntry.rich_text = normalizedRichText
    } else {
      delete nextEntry.rich_text
    }
    return nextEntry
  })
}

function clearCellRichText(documentRow: number, columnIndex: number) {
  if (!hasCellRichTextAt(documentRow, columnIndex)) {
    return null
  }
  return updateCellMetaEntry(documentRow, columnIndex, (entry) => {
    const nextEntry = { ...entry }
    delete nextEntry.rich_text
    return nextEntry
  })
}

function clearCellRichTextFormat(documentRow: number, columnIndex: number) {
  const meta = getCellMetaAt(documentRow, columnIndex)
  if (!meta?.cell_type && !meta?.rich_text) {
    return null
  }
  return updateCellMetaEntry(documentRow, columnIndex, (entry) => {
    const nextEntry = { ...entry }
    delete nextEntry.cell_type
    delete nextEntry.rich_text
    return nextEntry
  })
}

function updateCellMetaEntries(
  cells: SelectedSheetCell[],
  updater: (entry: SheetCellMeta, cell: SelectedSheetCell) => SheetCellMeta,
): SheetCellMetaPatchResult[] {
  const anchorCells = normalizeSheetCellsToMergeAnchors(cells)
  if (!anchorCells.length) {
    return []
  }

  const nextMeta = { ...cellMeta.value }
  const results: SheetCellMetaPatchResult[] = []
  anchorCells.forEach((cell) => {
    const key = createCellMetaKey(cell.documentRow, cell.column)
    const nextEntry = normalizeCellMetaEntry(updater({ ...(nextMeta[key] ?? {}) }, cell))
    updateEntityCellEntry(cell.documentRow, cell.column, (entry) => {
      const currentMeta = getEntityCellMeta(entry) ?? nextMeta[key] ?? {}
      const updatedMeta = normalizeCellMetaEntry(updater({ ...currentMeta }, cell))
      return replaceEntityCellMeta(entry, updatedMeta)
    })
    if (nextEntry) {
      nextMeta[key] = nextEntry
    } else {
      delete nextMeta[key]
    }
    results.push({
      documentRow: cell.documentRow,
      column: cell.column,
      meta: nextEntry,
    })
  })
  cellMeta.value = normalizeCellMetaMap(nextMeta, columnHeaders.value.length)
  renderCurrentHotWithReason('cell-meta-batch-set')
  return results
}

function getCommonSelectedCellStyle(cells: SelectedSheetCell[], field: SheetCellStyleField) {
  if (!cells.length) {
    return ''
  }

  const firstValue = getCellStyleAt(cells[0].documentRow, cells[0].column)?.[field] ?? ''
  const hasMixedValue = cells.some((cell) => (
    (getCellStyleAt(cell.documentRow, cell.column)?.[field] ?? '') !== firstValue
  ))
  return hasMixedValue ? '' : firstValue
}

function getCommonSelectedCellFormatType(cells: SelectedSheetCell[]) {
  if (!cells.length) {
    return ''
  }

  const firstValue = getCellFormatTypeAt(cells[0].documentRow, cells[0].column)
  const hasMixedValue = cells.some((cell) => (
    getCellFormatTypeAt(cell.documentRow, cell.column) !== firstValue
  ))
  return hasMixedValue ? '' : firstValue
}

function cloneCellStyle(style: SheetCellStyle | null | undefined) {
  return normalizeCellStyle(style ? { ...style } : null)
}

function getBaseCellStyleForCopy(cell: SelectedSheetCell) {
  const headerStyle = cell.row >= 0 && cell.row < nestedHeaderStyleRows.value.length
    ? nestedHeaderStyleRows.value[cell.row]?.[cell.column] ?? null
    : null
  const explicitStyle = getCellStyleAt(cell.documentRow, cell.column)

  if (!headerStyle) {
    const header = columnHeaders.value[cell.column]
    const columnFontFamily = header
      ? getColumnFontFamilyFromConfig(columnConfigs.value[header])
      : 'default'
    const columnFontSize = header
      ? getColumnFontSizeFromConfig(columnConfigs.value[header])
      : DEFAULT_COLUMN_FONT_SIZE
    const inheritedStyle: SheetCellStyle = {}
    if (columnFontFamily !== 'default') {
      inheritedStyle.font_family = columnFontFamily
    }
    if (columnFontSize !== DEFAULT_COLUMN_FONT_SIZE) {
      inheritedStyle.font_size = columnFontSize
    }
    return normalizeCellStyle({
      ...inheritedStyle,
      ...(explicitStyle ?? {}),
    })
  }
  return normalizeCellStyle({
    ...headerStyle,
    ...(explicitStyle ?? {}),
  })
}

function hasCopiedCellFormat() {
  return copiedCellFormat.value !== null
}

function copySelectedCellFormat() {
  const cell = getSingleSelectedSheetCell()
  if (!cell) {
    return
  }

  copiedCellFormat.value = {
    cell_type: getCellFormatTypeAt(cell.documentRow, cell.column),
    style: getBaseCellStyleForCopy(cell),
  }
  ElMessage.success('已复制格式')
}

function pasteCellFormatToSelectedCells() {
  if (!ensureCanEditConfig()) {
    return
  }

  const format = copiedCellFormat.value
  if (!format) {
    ElMessage.warning('请先复制格式')
    return
  }

  const cells = getSelectedSheetCells()
  if (!cells.length) {
    return
  }

  const copiedStyle = cloneCellStyle(format.style)
  const copiedCellType = format.cell_type
  const rejectedKeys = new Set<string>()
  if (copiedCellType === 'rich_text') {
    normalizeSheetCellsToMergeAnchors(cells).forEach((cell) => {
      if (!canUseRichTextFormatForCell(cell)) {
        rejectedKeys.add(createCellMetaKey(cell.documentRow, cell.column))
      }
    })
  }
  const undoEntry = createLocalUndoEntry('cell-format')
  const metaPatchResults = updateCellMetaEntries(cells, (entry, cell) => {
    const nextEntry = { ...entry }
    const key = createCellMetaKey(cell.documentRow, cell.column)
    if (copiedCellType === 'rich_text' && !rejectedKeys.has(key)) {
      nextEntry.cell_type = 'rich_text'
    } else {
      delete nextEntry.cell_type
      delete nextEntry.rich_text
    }
    if (copiedStyle) {
      nextEntry.style = { ...copiedStyle }
    } else {
      delete nextEntry.style
    }
    return nextEntry
  })
  pushLocalUndoEntry(undoEntry)
  queueImmediateCellMetaPatchSave(metaPatchResults)
  if (rejectedKeys.size) {
    ElMessage.warning('公式或动作单元格不支持富文本类型，已跳过')
  }
  ElMessage.success(cells.length > 1 ? '已粘贴格式到选区' : '已粘贴格式')
}

function getRichTextTargetRange(target: RichTextInlineToolbarTarget | null) {
  if (!target) {
    return null
  }
  const textLength = target.text.length
  const start = Math.max(0, Math.min(target.selectionStart, target.selectionEnd, textLength))
  const end = Math.max(0, Math.min(Math.max(target.selectionStart, target.selectionEnd), textLength))
  return start < end ? { start, end } : null
}

function isEditorForSheetCell(editor: SheetActiveEditor, cell: SelectedSheetCell) {
  if (typeof editor.row !== 'number' || typeof editor.col !== 'number') {
    return false
  }
  const column = toSheetColumnIndex(editor.col)
  if (column < 0) {
    return false
  }
  const anchor = getMergeAnchorForGridCell(editor.row, column)
  return anchor.row === cell.row
    && anchor.column === cell.column
    && anchor.documentRow === cell.documentRow
}

function getRichTextContentEditorTarget() {
  const state = richTextContentEditor.value
  const cell = state.cell
  if (!state.visible || !cell || !canEditCellRichTextTarget(cell)) {
    return null
  }

  const selection = getRichTextContentEditorSelectionOffsets()
  if (!selection) {
    return null
  }

  const target: RichTextInlineToolbarTarget = {
    cell,
    text: state.text,
    selectionStart: selection.selectionStart,
    selectionEnd: selection.selectionEnd,
    scope: 'selection',
  }
  return getRichTextTargetRange(target) ? target : null
}

function getRichTextInlineEditorTarget() {
  const editor = getActiveOpenedEditor()
  if (!editor || typeof editor.row !== 'number' || typeof editor.col !== 'number') {
    return null
  }

  const column = toSheetColumnIndex(editor.col)
  if (column < 0) {
    return null
  }

  const input = getEditorTextInput(editor)
  if (!input) {
    return null
  }

  const anchor = getMergeAnchorForGridCell(editor.row, column)
  const cell: SelectedSheetCell = {
    row: anchor.row,
    column: anchor.column,
    documentRow: anchor.documentRow,
  }
  if (!canEditCellRichTextTarget(cell)) {
    return null
  }

  const text = getActiveEditorDraft(editor)
  if (isFormulaExpression(text)) {
    return null
  }

  const selection = normalizeTextSelection(input, text)
  const target: RichTextInlineToolbarTarget = {
    cell,
    text,
    selectionStart: selection.selectionStart,
    selectionEnd: selection.selectionEnd,
    scope: 'selection',
  }
  return getRichTextTargetRange(target) ? target : null
}

function getSelectedRichTextToolbarCellTarget() {
  const cell = getSelectedCellRichTextDialogTarget()
  if (!cell || !canEditCellRichTextTarget(cell)) {
    return null
  }

  const text = getCellRawTextForRichText(cell)
  if (!text || isFormulaExpression(text)) {
    return null
  }

  return {
    cell,
    text,
    selectionStart: 0,
    selectionEnd: text.length,
    scope: 'cell',
  } satisfies RichTextInlineToolbarTarget
}

function getRichTextInlineToolbarPosition(element: HTMLElement, anchor?: { x: number; y: number }) {
  const rect = element.getBoundingClientRect()
  const toolbarWidth = 260
  const toolbarHeight = 40
  const anchorX = anchor?.x ?? rect.left
  const anchorY = anchor?.y ?? rect.top
  const x = Math.max(8, Math.min(anchorX, window.innerWidth - toolbarWidth - 8))
  const preferredY = anchor ? anchorY - toolbarHeight - 8 : rect.top - toolbarHeight - 8
  const fallbackY = anchor ? anchorY + 8 : rect.bottom + 8
  const y = preferredY >= 8
    ? preferredY
    : Math.min(fallbackY, window.innerHeight - toolbarHeight - 8)
  return { x, y: Math.max(8, y) }
}

function getRichTextInlineToolbarPositionFromPoint(x: number, y: number) {
  const toolbarWidth = 260
  const toolbarHeight = 40
  const left = Math.max(8, Math.min(x, window.innerWidth - toolbarWidth - 8))
  const preferredTop = y - toolbarHeight - 8
  const fallbackTop = y + 8
  const top = preferredTop >= 8
    ? preferredTop
    : Math.min(fallbackTop, window.innerHeight - toolbarHeight - 8)
  return { x: left, y: Math.max(8, top) }
}

function hideRichTextInlineToolbar(options: { force?: boolean } = {}) {
  if (!options.force && activeRichTextInlineToolbarColorField.value) {
    return
  }
  richTextInlineToolbar.value = {
    visible: false,
    x: 0,
    y: 0,
    target: null,
  }
  activeRichTextInlineToolbarColorField.value = null
}

function updateRichTextInlineToolbarFromActiveEditor(anchor?: { x: number; y: number }) {
  const contentEditorTarget = getRichTextContentEditorTarget()
  const contentEditor = richTextContentEditorRef.value
  if (contentEditorTarget && contentEditor) {
    const position = getRichTextInlineToolbarPosition(contentEditor, anchor)
    richTextInlineToolbar.value = {
      visible: true,
      x: position.x,
      y: position.y,
      target: contentEditorTarget,
    }
    return
  }

  const target = getRichTextInlineEditorTarget()
  const editor = getActiveOpenedEditor()
  const input = editor ? getEditorTextInput(editor) : null
  if (!target || !input) {
    if (richTextInlineToolbar.value.target?.scope === 'cell') {
      return
    }
    hideRichTextInlineToolbar()
    return
  }

  const position = getRichTextInlineToolbarPosition(input, anchor)
  richTextInlineToolbar.value = {
    visible: true,
    x: position.x,
    y: position.y,
    target,
  }
}

function showRichTextInlineToolbarFromContextMenu(event: MouseEvent) {
  const target = getRichTextContentEditorTarget() ?? getRichTextInlineEditorTarget() ?? getSelectedRichTextToolbarCellTarget()
  if (!target) {
    hideRichTextInlineToolbar()
    return
  }

  const position = getRichTextInlineToolbarPositionFromPoint(event.clientX, event.clientY)
  richTextInlineToolbar.value = {
    visible: true,
    x: position.x,
    y: position.y,
    target,
  }
}

function scheduleRichTextInlineToolbarSync() {
  void nextTick(() => {
    updateRichTextInlineToolbarFromActiveEditor()
  })
}

function getRichTextInlineToolbarApplyTarget() {
  const contentEditorTarget = getRichTextContentEditorTarget()
  if (contentEditorTarget) {
    return contentEditorTarget
  }

  const currentTarget = getRichTextInlineEditorTarget()
  if (currentTarget) {
    return currentTarget
  }

  const storedTarget = richTextInlineToolbar.value.target
  if (!storedTarget || !getRichTextTargetRange(storedTarget)) {
    return null
  }
  return storedTarget
}

function commitRichTextInlineToolbarText(target: RichTextInlineToolbarTarget) {
  if (isActiveRichTextContentEditorForCell(target.cell)) {
    const finalText = commitRichTextContentEditor({ close: false, save: false })
    return finalText == null || isFormulaExpression(finalText) ? null : finalText
  }

  const text = normalizeCellValue(target.text)
  if (isFormulaExpression(text)) {
    return null
  }

  const finalText = target.cell.row < sheetHeaderRowCount.value
    ? text
    : normalizeCellInputValueForColumn(text, target.cell.column)

  if (getGridCellRawValue(target.cell.row, target.cell.column) !== finalText) {
    const hot = getHotInstance()
    if (hot) {
      hot.setDataAtCell(target.cell.row, toHotColumnIndex(target.cell.column), finalText, 'rich-text-inline')
    } else {
      setSheetCellRawValueAtDocumentCell(target.cell.documentRow, target.cell.column, finalText)
    }
  }
  return finalText
}

function restoreRichTextInlineEditorSelection(target: RichTextInlineToolbarTarget, finalText: string) {
  if (isActiveRichTextContentEditorForCell(target.cell)) {
    richTextContentEditor.value = {
      ...richTextContentEditor.value,
      text: finalText,
      spans: getCellRichTextAt(target.cell.documentRow, target.cell.column, finalText)?.spans ?? [],
    }
    const range = getRichTextTargetRange({
      ...target,
      text: finalText,
    })
    const caretStart = range?.start ?? Math.min(target.selectionStart, finalText.length)
    const caretEnd = range?.end ?? caretStart
    focusRichTextContentEditor(caretStart, caretEnd)
    return
  }

  const editor = getActiveOpenedEditor()
  if (!editor || !isEditorForSheetCell(editor, target.cell)) {
    return
  }

  editor.setValue?.(finalText)
  const input = getEditorTextInput(editor)
  if (!input) {
    return
  }
  if (input.value !== finalText) {
    input.value = finalText
  }
  const range = getRichTextTargetRange({
    ...target,
    text: finalText,
  })
  const caretStart = range?.start ?? Math.min(target.selectionStart, finalText.length)
  const caretEnd = range?.end ?? caretStart
  input.setSelectionRange(caretStart, caretEnd)
  editor.focus?.()
}

function applyRichTextInlineToolbarPatch(patch: SheetRichTextStyle) {
  const target = getRichTextInlineToolbarApplyTarget()
  const range = getRichTextTargetRange(target)
  if (!target || !range) {
    ElMessage.warning('请先选择需要设置的文字')
    hideRichTextInlineToolbar({ force: true })
    return
  }

  const undoEntry = createLocalUndoEntry('rich-text')
  const previousText = getGridCellRawValue(target.cell.row, target.cell.column)
  const finalText = commitRichTextInlineToolbarText(target)
  if (finalText == null) {
    ElMessage.warning('公式单元格不支持富文本')
    const metaResult = clearCellRichTextFormat(target.cell.documentRow, target.cell.column)
    pushLocalUndoEntry(undoEntry)
    queueImmediateCellMetaPatchSave([metaResult])
    hideRichTextInlineToolbar({ force: true })
    return
  }

  const normalizedRange = {
    start: Math.min(range.start, finalText.length),
    end: Math.min(range.end, finalText.length),
  }
  if (normalizedRange.start >= normalizedRange.end) {
    ElMessage.warning('请先选择需要设置的文字')
    hideRichTextInlineToolbar({ force: true })
    return
  }

  const currentRichText = getCellRichTextAt(target.cell.documentRow, target.cell.column, finalText)
  const slots = buildRichTextStyleSlots(finalText.length, currentRichText?.spans ?? [])
  for (let index = normalizedRange.start; index < normalizedRange.end; index += 1) {
    slots[index] = mergeRichTextStyles(slots[index], patch)
  }

  const metaResult = setCellRichText(target.cell.documentRow, target.cell.column, { spans: compressRichTextStyleSlots(slots) }, finalText)
  refreshFormulaDisplayState()
  syncFormulaBarDraftFromSelectedCell(true)
  pushLocalUndoEntry(undoEntry)
  queueImmediateDataCellValueAndMetaPatchSave(
    target.cell.documentRow,
    target.cell.column,
    finalText,
    metaResult,
    previousText !== finalText,
    '富文本保存失败，已保留本地草稿',
  )
  restoreRichTextInlineEditorSelection(target, finalText)
  richTextInlineToolbar.value = {
    ...richTextInlineToolbar.value,
    target: {
      ...target,
      text: finalText,
      selectionEnd: target.scope === 'cell' ? finalText.length : target.selectionEnd,
    },
  }
}

function clearRichTextInlineToolbarSelectionStyle() {
  const target = getRichTextInlineToolbarApplyTarget()
  const range = getRichTextTargetRange(target)
  if (!target || !range) {
    ElMessage.warning('请先选择需要清除格式的文字')
    hideRichTextInlineToolbar({ force: true })
    return
  }

  const undoEntry = createLocalUndoEntry('rich-text')
  const previousText = getGridCellRawValue(target.cell.row, target.cell.column)
  const finalText = commitRichTextInlineToolbarText(target)
  if (finalText == null) {
    ElMessage.warning('公式单元格不支持富文本')
    pushLocalUndoEntry(undoEntry)
    hideRichTextInlineToolbar({ force: true })
    return
  }

  const currentRichText = getCellRichTextAt(target.cell.documentRow, target.cell.column, finalText)
  const slots = buildRichTextStyleSlots(finalText.length, currentRichText?.spans ?? [])
  const start = Math.min(range.start, finalText.length)
  const end = Math.min(range.end, finalText.length)
  for (let index = start; index < end; index += 1) {
    slots[index] = null
  }

  const metaResult = setCellRichText(target.cell.documentRow, target.cell.column, { spans: compressRichTextStyleSlots(slots) }, finalText)
  refreshFormulaDisplayState()
  syncFormulaBarDraftFromSelectedCell(true)
  pushLocalUndoEntry(undoEntry)
  queueImmediateDataCellValueAndMetaPatchSave(
    target.cell.documentRow,
    target.cell.column,
    finalText,
    metaResult,
    previousText !== finalText,
    '富文本保存失败，已保留本地草稿',
  )
  restoreRichTextInlineEditorSelection(target, finalText)
}

function setRichTextInlineToolbarColor(field: SheetRichTextColorField, value: string) {
  const color = normalizeCssColor(value)
  const nextColors = {
    ...richTextInlineToolbarColors.value,
    [field]: color || richTextInlineToolbarColors.value[field],
  }
  richTextInlineToolbarColors.value = nextColors
  saveRichTextInlineToolbarColorsPreference(nextColors)
  if (!color) {
    return
  }
  applyRichTextInlineToolbarPatch(field === 'text_color'
    ? { text_color: color }
    : { background_color: color })
}

function applyRichTextInlineToolbarCurrentColor(field: SheetRichTextColorField) {
  const color = normalizeCssColor(richTextInlineToolbarColors.value[field])
  if (!color) {
    ElMessage.warning('当前颜色无效')
    return
  }
  applyRichTextInlineToolbarPatch(field === 'text_color'
    ? { text_color: color }
    : { background_color: color })
}

function toggleRichTextInlineToolbarColorPopover(field: SheetRichTextColorField) {
  activeRichTextInlineToolbarColorField.value = activeRichTextInlineToolbarColorField.value === field ? null : field
}

function handleRichTextInlineToolbarColorPopoverVisibleChange(field: SheetRichTextColorField, visible: boolean) {
  activeRichTextInlineToolbarColorField.value = visible ? field : null
  if (!visible) {
    scheduleRichTextInlineToolbarSync()
  }
}

function getRichTextInlineToolbarSwatchStyle(field: SheetRichTextColorField) {
  return { backgroundColor: richTextInlineToolbarColors.value[field] }
}

function handleRichTextInlineToolbarPointerDown(event: MouseEvent) {
  if (event.target instanceof HTMLElement && event.target.closest('.standard-color-picker-surface')) {
    return
  }
  event.preventDefault()
  event.stopPropagation()
}

function handleRichTextInlineSelectionEvent() {
  scheduleRichTextInlineToolbarSync()
}

function getRichTextSelectionRange() {
  const textLength = cellRichTextDraftText.value.length
  const start = Math.max(0, Math.min(cellRichTextSelection.value.start, cellRichTextSelection.value.end, textLength))
  const end = Math.max(0, Math.min(Math.max(cellRichTextSelection.value.start, cellRichTextSelection.value.end), textLength))
  return start < end ? { start, end } : null
}

function updateCellRichTextSelectionFromTextarea() {
  const textarea = cellRichTextTextareaRef.value
  if (!textarea) {
    return
  }
  cellRichTextSelection.value = {
    start: textarea.selectionStart ?? 0,
    end: textarea.selectionEnd ?? 0,
  }
}

function focusCellRichTextTextarea() {
  void nextTick(() => {
    const textarea = cellRichTextTextareaRef.value
    if (!textarea) {
      return
    }
    textarea.focus()
    updateCellRichTextSelectionFromTextarea()
  })
}

function applyRichTextPatchToDraftSelection(patch: SheetRichTextStyle) {
  const range = getRichTextSelectionRange()
  if (!range) {
    ElMessage.warning('请先选择需要设置的文字')
    focusCellRichTextTextarea()
    return
  }
  const slots = buildRichTextStyleSlots(cellRichTextDraftText.value.length, cellRichTextDraftSpans.value)
  for (let index = range.start; index < range.end; index += 1) {
    slots[index] = mergeRichTextStyles(slots[index], patch)
  }
  cellRichTextDraftSpans.value = compressRichTextStyleSlots(slots)
  focusCellRichTextTextarea()
}

function clearRichTextDraftSelectionStyle() {
  const range = getRichTextSelectionRange()
  if (!range) {
    ElMessage.warning('请先选择需要清除格式的文字')
    focusCellRichTextTextarea()
    return
  }
  const slots = buildRichTextStyleSlots(cellRichTextDraftText.value.length, cellRichTextDraftSpans.value)
  for (let index = range.start; index < range.end; index += 1) {
    slots[index] = null
  }
  cellRichTextDraftSpans.value = compressRichTextStyleSlots(slots)
  focusCellRichTextTextarea()
}

function setCellRichTextDraftColor(field: SheetRichTextColorField, value: string) {
  const color = normalizeCssColor(value)
  cellRichTextDraftColors.value = {
    ...cellRichTextDraftColors.value,
    [field]: color || (field === 'text_color' ? DEFAULT_CELL_TEXT_COLOR : DEFAULT_CELL_BACKGROUND_COLOR),
  }
  if (!color) {
    return
  }
  if (!getRichTextSelectionRange()) {
    return
  }
  applyRichTextPatchToDraftSelection(field === 'text_color'
    ? { text_color: color }
    : { background_color: color })
}

function handleCellRichTextColorPopoverVisibleChange(field: SheetRichTextColorField, visible: boolean) {
  activeCellRichTextColorField.value = visible ? field : null
}

function getCellRichTextDraftSwatchStyle(field: SheetRichTextColorField) {
  return { backgroundColor: cellRichTextDraftColors.value[field] }
}

function handleCellRichTextDraftInput(event: Event) {
  const textarea = event.target as HTMLTextAreaElement | null
  cellRichTextDraftText.value = normalizeCellValue(textarea?.value ?? '')
  cellRichTextDraftSpans.value = normalizeRichTextSpans(cellRichTextDraftSpans.value, cellRichTextDraftText.value.length)
  updateCellRichTextSelectionFromTextarea()
}

function getCellRawTextForRichText(cell: SelectedSheetCell) {
  return getGridCellRawValue(cell.row, cell.column)
}

function canUseRichTextFormatForCell(cell: SelectedSheetCell) {
  return !isFormulaExpression(getCellRawTextForRichText(cell))
    && !getCellActionAt(cell.documentRow, cell.column)
}

function canEditCellRichTextTarget(cell: SelectedSheetCell | null) {
  if (!cell || !canEditConfig.value) {
    return false
  }
  if (!isRichTextCellAt(cell.documentRow, cell.column) || !canUseRichTextFormatForCell(cell)) {
    return false
  }
  return cell.row < sheetHeaderRowCount.value ? canEditConfig.value : canEditDataColumn(cell.column)
}

function getFormulaBarSheetCell(): SelectedSheetCell | null {
  const cell = formulaBarCell.value
  if (!cell) {
    return null
  }
  return {
    row: cell.gridRow,
    column: cell.column,
    documentRow: cell.documentGridRow,
  }
}

function getSelectedCellRichTextDialogTarget() {
  const singleCell = getSingleSelectedSheetCell()
  if (canEditCellRichTextTarget(singleCell)) {
    return singleCell
  }

  const editableTargets = getSelectedSheetCells().filter((cell) => canEditCellRichTextTarget(cell))
  if (editableTargets.length === 1) {
    return editableTargets[0]
  }

  const nonEmptyTargets = editableTargets.filter((cell) => (
    getCellRawTextForRichText(cell).trim()
    || hasCellRichTextAt(cell.documentRow, cell.column)
  ))
  if (nonEmptyTargets.length === 1) {
    return nonEmptyTargets[0]
  }

  const formulaBarTarget = getFormulaBarSheetCell()
  if (canEditCellRichTextTarget(formulaBarTarget)) {
    return formulaBarTarget
  }
  return null
}

function canOpenSelectedCellRichTextDialog() {
  return !!getSelectedCellRichTextDialogTarget()
}

function openSelectedCellRichTextDialog() {
  const cell = getSelectedCellRichTextDialogTarget()
  if (!cell || !canEditCellRichTextTarget(cell)) {
    const selectedCell = getSingleSelectedSheetCell() ?? getFormulaBarSheetCell()
    if (selectedCell && !isRichTextCellAt(selectedCell.documentRow, selectedCell.column)) {
      ElMessage.warning('请先把单元格类型改为富文本')
    } else if (selectedCell && isFormulaExpression(getCellRawTextForRichText(selectedCell))) {
      ElMessage.warning('公式单元格不支持富文本')
    } else {
      ElMessage.warning('请选择一个富文本单元格')
    }
    return
  }

  const rawText = getCellRawTextForRichText(cell)
  cellRichTextDialogCell.value = cell
  cellRichTextDraftText.value = rawText
  cellRichTextDraftSpans.value = getCellRichTextAt(cell.documentRow, cell.column, rawText)?.spans ?? []
  cellRichTextSelection.value = { start: 0, end: 0 }
  activeCellRichTextColorField.value = null
  cellRichTextDialogVisible.value = true
  focusCellRichTextTextarea()
}

function closeCellRichTextDialog() {
  cellRichTextDialogVisible.value = false
  cellRichTextDialogCell.value = null
  cellRichTextDraftText.value = ''
  cellRichTextDraftSpans.value = []
  cellRichTextSelection.value = { start: 0, end: 0 }
  activeCellRichTextColorField.value = null
}

function clearCellRichTextDialogStyles() {
  cellRichTextDraftSpans.value = []
  focusCellRichTextTextarea()
}

function applyCellRichTextDialog() {
  const cell = cellRichTextDialogCell.value
  if (!cell || !canEditCellRichTextTarget(cell)) {
    closeCellRichTextDialog()
    return
  }

  const nextText = normalizeCellValue(cellRichTextDraftText.value)
  if (isFormulaExpression(nextText)) {
    ElMessage.warning('公式单元格不支持富文本')
    return
  }

  const undoEntry = createLocalUndoEntry('rich-text')
  let finalText = nextText
  const previousText = getGridCellRawValue(cell.row, cell.column)
  if (cell.row < sheetHeaderRowCount.value) {
    applySheetHeaderGridChange(cell.row, cell.column, finalText)
  } else {
    finalText = normalizeCellInputValueForColumn(nextText, cell.column)
    const hot = getHotInstance()
    if (hot) {
      hot.setDataAtCell(cell.row, toHotColumnIndex(cell.column), finalText, 'rich-text-dialog')
    } else {
      const dataRow = getDataRowIndex(cell.row)
      if (dataRow >= 0) {
        const nextRows = rows.value.map((row) => normalizeRow(row, columnHeaders.value))
        if (!nextRows[dataRow]) {
          nextRows[dataRow] = createEmptyRow(columnHeaders.value.length)
        }
        nextRows[dataRow][cell.column] = finalText
        rows.value = nextRows
      }
    }
  }

  const metaResult = setCellRichText(cell.documentRow, cell.column, { spans: cellRichTextDraftSpans.value }, finalText)
  refreshFormulaDisplayState()
  syncFormulaBarDraftFromSelectedCell(true)
  refreshGridStructure()
  pushLocalUndoEntry(undoEntry)
  queueImmediateDataCellValueAndMetaPatchSave(
    cell.documentRow,
    cell.column,
    finalText,
    metaResult,
    previousText !== finalText,
    '富文本保存失败，已保留本地草稿',
  )
  closeCellRichTextDialog()
}

function getCellStyleDraftModelValue(field: SheetCellColorField) {
  return cellStyleDraft.value[field] || (
    field === 'text_color' ? DEFAULT_CELL_TEXT_COLOR : DEFAULT_CELL_BACKGROUND_COLOR
  )
}

function getCellStyleDraftSwatchStyle(field: SheetCellColorField) {
  const color = normalizeCssColor(cellStyleDraft.value[field])
  return color
    ? { backgroundColor: color }
    : { backgroundImage: 'linear-gradient(135deg, transparent 0 46%, #dcdfe6 46% 54%, transparent 54% 100%)' }
}

function setCellStyleDraftColor(field: SheetCellColorField, value: string) {
  cellStyleDraftTouched.value[field] = true
  cellStyleDraft.value = {
    ...cellStyleDraft.value,
    [field]: normalizeCssColor(value),
  }
}

function clearCellStyleDraftColor(field: SheetCellColorField) {
  setCellStyleDraftColor(field, '')
}

function handleCellStyleColorPopoverVisibleChange(field: SheetCellColorField, visible: boolean) {
  activeCellStyleColorField.value = visible ? field : null
}

function setCellStyleDraftFormatType(value: unknown) {
  cellStyleDraftTouched.value.cell_type = true
  cellStyleDraft.value = {
    ...cellStyleDraft.value,
    cell_type: normalizeCellFormatType(value),
  }
}

function setCellStyleDraftFontFamily(value: unknown) {
  cellStyleDraftTouched.value.font_family = true
  cellStyleDraft.value = {
    ...cellStyleDraft.value,
    font_family: normalizeCellFontFamily(value),
  }
}

function setCellStyleDraftFontSize(value: unknown) {
  cellStyleDraftTouched.value.font_size = true
  cellStyleDraft.value = {
    ...cellStyleDraft.value,
    font_size: normalizeCellFontSize(value),
  }
}

function clearCellStyleDraftFontSize() {
  cellStyleDraftTouched.value.font_size = true
  cellStyleDraft.value = {
    ...cellStyleDraft.value,
    font_size: null,
  }
}

function setCellStyleDraftTextAlign(value: unknown) {
  cellStyleDraftTouched.value.text_align = true
  cellStyleDraft.value = {
    ...cellStyleDraft.value,
    text_align: normalizeCellTextAlign(value),
  }
}

function setCellStyleDraftVerticalAlign(value: unknown) {
  cellStyleDraftTouched.value.vertical_align = true
  cellStyleDraft.value = {
    ...cellStyleDraft.value,
    vertical_align: normalizeCellVerticalAlign(value),
  }
}

function getCellStyleDraftCells() {
  return cellStyleDialogCells.value.length ? cellStyleDialogCells.value : getSelectedSheetCells()
}

function getCellInheritedFontSize(cell: SelectedSheetCell) {
  if (cell.row >= sheetHeaderRowCount.value) {
    const header = columnHeaders.value[cell.column]
    return header ? getColumnFontSizeFromConfig(columnConfigs.value[header]) : DEFAULT_COLUMN_FONT_SIZE
  }
  return DEFAULT_COLUMN_FONT_SIZE
}

function getCellEffectiveFontSize(cell: SelectedSheetCell) {
  return normalizeCellFontSize(getCellStyleAt(cell.documentRow, cell.column)?.font_size)
    ?? getCellInheritedFontSize(cell)
}

function getCommonCellFontSize(
  cells: SelectedSheetCell[],
  resolver: (cell: SelectedSheetCell) => number | null,
) {
  const anchorCells = normalizeSheetCellsToMergeAnchors(cells)
  if (!anchorCells.length) {
    return null
  }

  const firstValue = resolver(anchorCells[0])
  const hasMixedValue = anchorCells.some((cell) => resolver(cell) !== firstValue)
  return hasMixedValue ? null : firstValue
}

function getCellStyleDraftFontSizeModelValue() {
  if (cellStyleDraftTouched.value.font_size) {
    return cellStyleDraft.value.font_size
      ?? getCommonCellFontSize(getCellStyleDraftCells(), getCellInheritedFontSize)
  }
  return getCommonCellFontSize(getCellStyleDraftCells(), getCellEffectiveFontSize)
}

function getCellStyleFontSizeStateLabel() {
  const cells = normalizeSheetCellsToMergeAnchors(getCellStyleDraftCells())
  if (!cells.length) {
    return ''
  }

  if (getCellStyleDraftFontSizeModelValue() == null) {
    return '多个值'
  }
  if (cellStyleDraftTouched.value.font_size) {
    return cellStyleDraft.value.font_size == null ? '保存后继承' : '将覆盖'
  }

  const overrideStates = cells.map((cell) => (
    normalizeCellFontSize(getCellStyleAt(cell.documentRow, cell.column)?.font_size) != null
  ))
  const overrideCount = overrideStates.filter(Boolean).length
  if (overrideCount === 0) {
    return '继承'
  }
  if (overrideCount === overrideStates.length) {
    return '手动'
  }
  return '混合来源'
}

function applyCellStyleToSelectedCells(cells: SelectedSheetCell[]) {
  const touched = cellStyleDraftTouched.value
  if (
    !touched.cell_type
    && !touched.background_color
    && !touched.text_color
    && !touched.font_family
    && !touched.font_size
    && !touched.text_align
    && !touched.vertical_align
  ) {
    return
  }

  const nextFormatType = normalizeCellFormatType(cellStyleDraft.value.cell_type)
  const richTextTypeRejectedKeys = new Set<string>()
  if (touched.cell_type && nextFormatType === 'rich_text') {
    normalizeSheetCellsToMergeAnchors(cells).forEach((cell) => {
      if (!canUseRichTextFormatForCell(cell)) {
        richTextTypeRejectedKeys.add(createCellMetaKey(cell.documentRow, cell.column))
      }
    })
  }

  const undoEntry = createLocalUndoEntry('cell-style')
  const metaPatchResults = updateCellMetaEntries(cells, (entry, cell) => {
    const nextEntry = { ...entry }
    const nextStyle: SheetCellStyle = { ...(nextEntry.style ?? {}) }
    if (touched.cell_type) {
      const key = createCellMetaKey(cell.documentRow, cell.column)
      if (nextFormatType === 'rich_text' && !richTextTypeRejectedKeys.has(key)) {
        nextEntry.cell_type = 'rich_text'
      } else {
        delete nextEntry.cell_type
        delete nextEntry.rich_text
      }
    }
    if (touched.background_color) {
      const backgroundColor = normalizeCssColor(cellStyleDraft.value.background_color)
      if (backgroundColor) {
        nextStyle.background_color = backgroundColor
      } else {
        delete nextStyle.background_color
      }
    }
    if (touched.text_color) {
      const textColor = normalizeCssColor(cellStyleDraft.value.text_color)
      if (textColor) {
        nextStyle.text_color = textColor
      } else {
        delete nextStyle.text_color
      }
    }
    if (touched.font_family) {
      const fontFamily = normalizeCellFontFamily(cellStyleDraft.value.font_family)
      if (fontFamily) {
        nextStyle.font_family = fontFamily
      } else {
        delete nextStyle.font_family
      }
    }
    if (touched.font_size) {
      const fontSize = normalizeCellFontSize(cellStyleDraft.value.font_size)
      if (fontSize) {
        nextStyle.font_size = fontSize
      } else {
        delete nextStyle.font_size
      }
    }
    if (touched.text_align) {
      const textAlign = normalizeCellTextAlign(cellStyleDraft.value.text_align)
      if (textAlign) {
        nextStyle.text_align = textAlign
      } else {
        delete nextStyle.text_align
      }
    }
    if (touched.vertical_align) {
      const verticalAlign = normalizeCellVerticalAlign(cellStyleDraft.value.vertical_align)
      if (verticalAlign) {
        nextStyle.vertical_align = verticalAlign
      } else {
        delete nextStyle.vertical_align
      }
    }

    if (hasCellStyleValue(nextStyle)) {
      nextEntry.style = nextStyle
    } else {
      delete nextEntry.style
    }
    return nextEntry
  })
  pushLocalUndoEntry(undoEntry)
  queueImmediateCellMetaPatchSave(metaPatchResults)
  if (richTextTypeRejectedKeys.size) {
    ElMessage.warning('公式或动作单元格不支持富文本类型，已跳过')
  }
}

function openSelectedCellStyleDialog() {
  if (!ensureCanEditConfig()) {
    return
  }
  const cells = getSelectedSheetCells()
  if (!cells.length) {
    return
  }

  cellStyleDialogCells.value = cells
  activeCellStyleColorField.value = null
  cellStyleDraft.value = {
    cell_type: getCommonSelectedCellFormatType(cells),
    background_color: getCommonSelectedCellStyle(cells, 'background_color'),
    text_color: getCommonSelectedCellStyle(cells, 'text_color'),
    font_family: normalizeCellFontFamily(getCommonSelectedCellStyle(cells, 'font_family')),
    font_size: normalizeCellFontSize(getCommonSelectedCellStyle(cells, 'font_size')),
    text_align: normalizeCellTextAlign(getCommonSelectedCellStyle(cells, 'text_align')),
    vertical_align: normalizeCellVerticalAlign(getCommonSelectedCellStyle(cells, 'vertical_align')),
  }
  cellStyleDraftTouched.value = {
    cell_type: false,
    background_color: false,
    text_color: false,
    font_family: false,
    font_size: false,
    text_align: false,
    vertical_align: false,
  }
  cellStyleDialogVisible.value = true
}

function closeCellStyleDialog() {
  cellStyleDialogVisible.value = false
  cellStyleDialogCells.value = []
  activeCellStyleColorField.value = null
  cellStyleDraft.value = {
    cell_type: '',
    background_color: '',
    text_color: '',
    font_family: '',
    font_size: null,
    text_align: '',
    vertical_align: '',
  }
  cellStyleDraftTouched.value = {
    cell_type: false,
    background_color: false,
    text_color: false,
    font_family: false,
    font_size: false,
    text_align: false,
    vertical_align: false,
  }
}

function applyCellStyleDialog() {
  if (!ensureCanEditConfig()) {
    closeCellStyleDialog()
    return
  }
  const cells = [...cellStyleDialogCells.value]
  if (!cells.length) {
    closeCellStyleDialog()
    return
  }

  applyCellStyleToSelectedCells(cells)
  closeCellStyleDialog()
}

function clearCellStyleDialog() {
  if (!ensureCanEditConfig()) {
    closeCellStyleDialog()
    return
  }
  const cells = [...cellStyleDialogCells.value]
  if (cells.length) {
    const undoEntry = createLocalUndoEntry('cell-style')
    const metaPatchResults = updateCellMetaEntries(cells, (entry) => {
      const nextEntry = { ...entry }
      delete nextEntry.style
      delete nextEntry.cell_type
      delete nextEntry.rich_text
      return nextEntry
    })
    pushLocalUndoEntry(undoEntry)
    queueImmediateCellMetaPatchSave(metaPatchResults)
  }
  closeCellStyleDialog()
}

function openCellLink(link: SheetCellLink | null) {
  openUrlInNewWindow(buildDefaultCellLinkUrl(link))
}

function getSelectedColumnHeaderCellIndex() {
  const headerCell = selectedSheetHeaderCell.value
  if (!headerCell || headerCell.headerLevel !== columnHeaderLevel.value) {
    return null
  }
  if (headerCell.column < 0 || headerCell.column >= columnHeaders.value.length) {
    return null
  }
  return headerCell.column
}

function hasSingleLinkTargetSelection() {
  return !!getSelectedLinkTarget()
}

function getSelectedLinkTarget(): LinkDialogTarget | null {
  const cell = getSingleSelectedSheetCell()
  if (!cell) {
    return null
  }

  if (cell.row === columnHeaderLevel.value) {
    return { kind: 'column_header', column: cell.column }
  }
  return { kind: 'cell', row: cell.documentRow, column: cell.column }
}

function getLinkTargetLink(target: LinkDialogTarget | null) {
  if (!target) {
    return null
  }
  if (target.kind === 'cell') {
    return getCellLinkAt(target.row, target.column)
  }

  const headerDocumentRow = getDocumentGridRowIndex(columnHeaderLevel.value)
  return getCellLinkAt(headerDocumentRow, target.column) ?? getColumnHeaderLink(target.column)
}

function getSelectedLinkTargetLink() {
  return getLinkTargetLink(getSelectedLinkTarget())
}

function hasSelectedCellLink() {
  return !!getSelectedLinkTargetLink()
}

function shouldShowStyleContextMenuGroup() {
  return (
    hasSingleSheetCellSelection()
    || (hasSheetCellSelection() && canEditConfig.value)
    || (hasSheetCellSelection() && canEditConfig.value && hasCopiedCellFormat())
    || (hasSheetCellSelection() && canEditConfig.value && canMergeSelectedCells())
    || (hasSelectedMergedCell() && canEditConfig.value)
  )
}

function shouldShowLinkContextMenuGroup() {
  return (
    hasSelectedCellLink()
    || (hasSingleLinkTargetSelection() && canEditConfig.value)
  )
}

function parseSelectedCellLinkUrl() {
  const link = getSelectedLinkTargetLink()
  if (!link?.url || typeof window === 'undefined') {
    return null
  }

  try {
    return new URL(link.url, window.location.href)
  } catch {
    return null
  }
}

function buildCodeyunLinkVariantUrl(variant: CodeyunLinkVariant) {
  const sourceUrl = parseSelectedCellLinkUrl()
  return buildCodeyunUrlVariant(sourceUrl, variant)
}

function canOpenSelectedCellLinkVariant(variant: CodeyunLinkVariant) {
  return !!buildCodeyunLinkVariantUrl(variant)
}

function openSelectedCellLinkVariant(variant: CodeyunLinkVariant) {
  openUrlInNewWindow(buildCodeyunLinkVariantUrl(variant))
}

function buildDefaultCellLinkUrl(link: SheetCellLink | null) {
  if (!link?.url) {
    return ''
  }
  return buildCodeyunUrlVariant(link.url, 'current') || link.url
}

function openSelectedCellLink() {
  openCellLink(getSelectedLinkTargetLink())
}

function openSelectedCellLinkDefault() {
  if (hasSelectedCellLink()) {
    openSelectedCellLink()
    return
  }

  openSelectedCellLinkDialog()
}

async function copySelectedCellLink() {
  const link = getSelectedLinkTargetLink()
  if (!link?.url) {
    return
  }

  try {
    await copyTextToClipboard(link.url)
    ElMessage.success('已复制超链接')
  } catch (error) {
    console.warn('Failed to copy cell link:', error)
    ElMessage.error('复制超链接失败')
  }
}

function openSelectedCellLinkDialog() {
  if (!ensureCanEditConfig()) {
    return
  }
  const target = getSelectedLinkTarget()
  if (!target) {
    return
  }

  cellLinkDialogTarget.value = target
  cellLinkDraftUrl.value = getLinkTargetLink(target)?.url ?? ''
  cellLinkDialogVisible.value = true
}

function closeCellLinkDialog() {
  cellLinkDialogVisible.value = false
  cellLinkDialogTarget.value = null
  cellLinkDraftUrl.value = ''
}

function applyCellLinkDialog() {
  if (!ensureCanEditConfig()) {
    closeCellLinkDialog()
    return
  }
  const target = cellLinkDialogTarget.value
  if (!target) {
    closeCellLinkDialog()
    return
  }

  const rawUrl = normalizeCellValue(cellLinkDraftUrl.value).trim()
  const normalizedUrl = normalizeHyperlinkUrl(rawUrl)
  if (!normalizedUrl) {
    if (rawUrl) {
      ElMessage.warning('请输入有效的链接地址')
      return
    }

    const undoEntry = createLocalUndoEntry('cell-link')
    let metaResult: SheetCellMetaPatchResult | null = null
    let configOperation: NoteSheetPatchOperation | null = null
    if (target.kind === 'cell') {
      metaResult = setCellLink(target.row, target.column, '')
    } else {
      metaResult = setCellLink(getDocumentGridRowIndex(columnHeaderLevel.value), target.column, '')
      setColumnHeaderLink(target.column, '')
      configOperation = buildColumnConfigPatchOperation(target.column)
    }
    pushLocalUndoEntry(undoEntry)
    const operations = [
      ...buildCellMetaPatchOperations([metaResult]),
      ...(configOperation ? [configOperation] : []),
    ]
    if (operations.length) {
      queueImmediateSheetPatchSave(operations, '链接保存失败，已保留本地草稿')
    }
    closeCellLinkDialog()
    return
  }

  const undoEntry = createLocalUndoEntry('cell-link')
  let metaResult: SheetCellMetaPatchResult | null = null
  let configOperation: NoteSheetPatchOperation | null = null
  if (target.kind === 'cell') {
    metaResult = setCellLink(target.row, target.column, normalizedUrl)
  } else {
    metaResult = setCellLink(getDocumentGridRowIndex(columnHeaderLevel.value), target.column, normalizedUrl)
    setColumnHeaderLink(target.column, normalizedUrl)
    configOperation = buildColumnConfigPatchOperation(target.column)
  }
  pushLocalUndoEntry(undoEntry)
  const operations = [
    ...buildCellMetaPatchOperations([metaResult]),
    ...(configOperation ? [configOperation] : []),
  ]
  if (operations.length) {
    queueImmediateSheetPatchSave(operations, '链接保存失败，已保留本地草稿')
  }
  closeCellLinkDialog()
}

function getColumnDisplayMode(columnIndex: number): ColumnDisplayMode {
  const header = columnHeaders.value[columnIndex]
  if (!header) {
    return DEFAULT_COLUMN_DISPLAY_MODE
  }
  return normalizeColumnDisplayMode(columnConfigs.value[header]?.display_mode)
}

function resolveColumnTextAlign(config: SheetColumnConfig | ColumnSettingsDraft | undefined) {
  const align = normalizeColumnTextAlign(config?.align)
  if (align !== 'auto') {
    return align
  }

  const valueType = normalizeColumnValueType(config?.value_type)
  if (valueType === 'number' || valueType === 'percent' || valueType === 'date') {
    return 'right'
  }
  return 'left'
}

function isColumnValueValidByConfig(value: unknown, config: ColumnSettingsDraft) {
  const text = normalizeCellValue(value)
  if (!text) {
    return config.allow_empty
  }

  switch (config.value_type) {
    case 'number':
      return (typeof value === 'number' && Number.isFinite(value))
        || /^[-+]?(?:\d+(?:\.\d+)?|\.\d+)$/.test(text)
    case 'percent':
      return parsePercentDisplayNumber(value) != null
    case 'date':
      return !!parseDateDisplayValue(value)
    default:
      if (config.text_rule === 'phone') {
        return /^\d{11}$/.test(text)
      }
      if (config.text_rule === 'id_card') {
        return /^\d{17}[\dXx]$/.test(text)
      }
      return true
  }
}

function normalizeColumnValuesForValueType(columnIndex: number, valueType: ColumnValueType) {
  if (valueType !== 'multi_text') {
    return false
  }

  let changed = false
  const nextRows = rows.value.map((row) => {
    const nextRow = normalizeRow(row, columnHeaders.value)
    const currentValue = normalizeCellValue(nextRow[columnIndex])
    const nextValue = normalizeMultiTextValue(currentValue)
    if (nextValue !== currentValue) {
      nextRow[columnIndex] = nextValue
      changed = true
    }
    return nextRow
  })

  if (!changed) {
    return false
  }

  rows.value = nextRows
  loadCurrentHotGridRows(getHotInstance())
  return true
}

function getColumnSettingsDraftForColumn(columnIndex: number) {
  const header = columnHeaders.value[columnIndex]
  const draft = normalizeColumnConfig(header ? columnConfigs.value[header] : null)
  draft.width_value = normalizeColumnWidthValue(getEffectiveColumnWidth(columnIndex))
  return draft
}

function getColumnSettingsIndexesFromBounds(bounds: { start: number; end: number } | null) {
  if (!bounds) {
    return []
  }

  const start = Math.max(0, Math.min(bounds.start, columnHeaders.value.length - 1))
  const end = Math.max(0, Math.min(bounds.end, columnHeaders.value.length - 1))
  const indexes: number[] = []
  for (let index = Math.min(start, end); index <= Math.max(start, end); index += 1) {
    indexes.push(index)
  }
  return indexes
}

function createColumnSettingsDraftForSelection(indexes: number[]) {
  if (!indexes.length) {
    return {
      draft: createDefaultColumnSettingsDraft(),
      mixed: createColumnSettingsMixedState(),
    }
  }

  const drafts = indexes.map((index) => getColumnSettingsDraftForColumn(index))
  const draft = { ...drafts[0] }
  const mixed = createColumnSettingsMixedState()
  for (const key of COLUMN_SETTINGS_KEYS) {
    mixed[key] = drafts.some((item) => item[key] !== draft[key])
  }
  return { draft, mixed }
}

function getCurrentColumnSettingsSelectionDrafts() {
  const indexes = getColumnSettingsIndexesFromBounds(columnSettingsSelectionBounds.value)
  return indexes.map((index) => getColumnSettingsDraftForColumn(index))
}

function markColumnSettingTouched(key: ColumnSettingsDraftKey) {
  if (columnSettingsTouched.value[key]) {
    return
  }
  columnSettingsTouched.value = {
    ...columnSettingsTouched.value,
    [key]: true,
  }
}

function isColumnSettingMixed(key: ColumnSettingsDraftKey) {
  return isColumnSettingsMultiSelection.value
    && columnSettingsMixed.value[key]
    && !columnSettingsTouched.value[key]
}

function getColumnSettingSelectModel(key: ColumnSettingsDraftKey) {
  return isColumnSettingMixed(key) ? '' : String(columnSettingsDraft.value[key] ?? '')
}

function getColumnSettingsDraftBaseType() {
  return getColumnBaseType(columnSettingsDraft.value)
}

function getColumnSettingsDraftSubType() {
  return getColumnSubType(columnSettingsDraft.value)
}

function isColumnSettingsBaseTypeMixed() {
  if (!isColumnSettingsMultiSelection.value || columnSettingsTouched.value.value_type) {
    return false
  }
  const drafts = getCurrentColumnSettingsSelectionDrafts()
  if (drafts.length <= 1) {
    return false
  }
  const firstBaseType = getColumnBaseType(drafts[0])
  return drafts.some((draft) => getColumnBaseType(draft) !== firstBaseType)
}

function isColumnSettingsSubTypeMixed() {
  if (
    !isColumnSettingsMultiSelection.value
    || columnSettingsTouched.value.value_type
    || columnSettingsTouched.value.text_rule
  ) {
    return false
  }
  const drafts = getCurrentColumnSettingsSelectionDrafts()
  if (drafts.length <= 1) {
    return false
  }
  const firstSubType = getColumnSubType(drafts[0])
  return drafts.some((draft) => getColumnSubType(draft) !== firstSubType)
}

function getColumnSettingsBaseTypeSelectModel() {
  return isColumnSettingsBaseTypeMixed() ? '' : getColumnSettingsDraftBaseType()
}

function getColumnSettingsSubTypeSelectModel() {
  return isColumnSettingsSubTypeMixed() ? '' : getColumnSettingsDraftSubType()
}

function getColumnSettingsSubTypeOptions() {
  return COLUMN_SUB_TYPE_OPTIONS[getColumnSettingsDraftBaseType()]
}

function getColumnSettingTextModel(key: 'display_format') {
  return isColumnSettingMixed(key) ? '' : columnSettingsDraft.value[key]
}

function getColumnSettingNumberModel(key: 'font_size' | 'width_value') {
  return isColumnSettingMixed(key) ? undefined : columnSettingsDraft.value[key]
}

function getColumnSettingCheckboxModel(
  key: 'allow_empty' | 'trim_whitespace' | 'duplicate_value_highlight',
) {
  return !isColumnSettingMixed(key) && columnSettingsDraft.value[key]
}

function getColumnSettingFilterEnabledModel() {
  return isColumnSettingMixed('filter_enabled')
    ? ''
    : (columnSettingsDraft.value.filter_enabled ? 'enabled' : 'disabled')
}

function setColumnSettingsValueType(value: unknown) {
  columnSettingsDraft.value.value_type = normalizeColumnValueType(value)
  handleColumnSettingsValueTypeChange(columnSettingsDraft.value.value_type)
}

function setColumnSettingsBaseType(value: unknown) {
  const baseType = normalizeColumnBaseType(value)
  applyColumnSettingsSubType(getDefaultColumnSubType(baseType), baseType)
}

function setColumnSettingsSubType(value: unknown) {
  const currentBaseType = getColumnSettingsDraftBaseType()
  const nextSubType = normalizeColumnSubType(value, currentBaseType)
  applyColumnSettingsSubType(nextSubType, currentBaseType)
}

function applyColumnSettingsSubType(nextSubType: ColumnSubType, baseType: ColumnBaseType) {
  if (getColumnSubTypeBaseType(nextSubType) !== baseType) {
    return
  }

  if (nextSubType === 'multi_text') {
    columnSettingsDraft.value.value_type = 'multi_text'
    columnSettingsDraft.value.text_rule = 'none'
  } else if (nextSubType === 'phone' || nextSubType === 'id_card') {
    columnSettingsDraft.value.value_type = 'text'
    columnSettingsDraft.value.text_rule = nextSubType === 'phone' ? 'phone' : 'id_card'
  } else if (nextSubType === 'number' || nextSubType === 'percent' || nextSubType === 'date') {
    columnSettingsDraft.value.value_type = nextSubType
    columnSettingsDraft.value.text_rule = 'none'
  } else {
    columnSettingsDraft.value.value_type = 'text'
    columnSettingsDraft.value.text_rule = 'none'
  }

  handleColumnSettingsValueTypeChange(columnSettingsDraft.value.value_type)
  markColumnSettingTouched('text_rule')
}

function setColumnSettingsTextRule(value: unknown) {
  columnSettingsDraft.value.text_rule = normalizeColumnTextRule(value, columnSettingsDraft.value.value_type)
  markColumnSettingTouched('text_rule')
}

function setColumnSettingsValueMode(value: unknown) {
  columnSettingsDraft.value.value_mode = normalizeColumnValueMode(value)
  markColumnSettingTouched('value_mode')
}

function setColumnSettingsFilterEnabled(value: unknown) {
  columnSettingsDraft.value.filter_enabled = value === 'enabled' || value === true
  markColumnSettingTouched('filter_enabled')
}

function setColumnSettingsDisplayFormat(value: unknown) {
  columnSettingsDraft.value.display_format = String(value ?? '')
  markColumnSettingTouched('display_format')
}

function setColumnSettingsDisplayMode(value: unknown) {
  columnSettingsDraft.value.display_mode = normalizeColumnDisplayMode(value)
  markColumnSettingTouched('display_mode')
}

function setColumnSettingsAlign(value: unknown) {
  columnSettingsDraft.value.align = normalizeColumnTextAlign(value)
  markColumnSettingTouched('align')
}

function setColumnSettingsHashColorMode(value: unknown) {
  columnSettingsDraft.value.hash_color_mode = normalizeColumnHashColorMode(value)
  markColumnSettingTouched('hash_color_mode')
}

function setColumnSettingsHashColorTone(value: unknown) {
  columnSettingsDraft.value.hash_color_tone = normalizeColumnHashColorTone(value)
  markColumnSettingTouched('hash_color_tone')
}

function setColumnSettingsWidthMode(value: unknown) {
  columnSettingsDraft.value.width_mode = normalizeColumnWidthMode(value)
  markColumnSettingTouched('width_mode')
}

function setColumnSettingsFontFamily(value: unknown) {
  columnSettingsDraft.value.font_family = normalizeColumnFontFamily(value)
  markColumnSettingTouched('font_family')
}

function setColumnSettingsNumberValue(key: 'font_size' | 'width_value', value: unknown) {
  if (key === 'font_size') {
    columnSettingsDraft.value.font_size = normalizeColumnFontSize(value)
  } else {
    columnSettingsDraft.value.width_value = normalizeColumnWidthValue(value)
  }
  markColumnSettingTouched(key)
}

function setColumnSettingsBooleanValue(
  key: 'allow_empty' | 'trim_whitespace' | 'duplicate_value_highlight',
  value: unknown,
) {
  columnSettingsDraft.value[key] = value === true
  markColumnSettingTouched(key)
}

function mergeColumnSettingsDraft(
  currentConfig: ColumnSettingsDraft,
  draft: ColumnSettingsDraft,
  touched: ColumnSettingsTouchedState,
  applyAll: boolean,
) {
  if (applyAll) {
    return { ...draft }
  }

  const nextConfig = { ...currentConfig }
  for (const key of COLUMN_SETTINGS_KEYS) {
    if (touched[key]) {
      ;(nextConfig[key] as ColumnSettingsDraft[typeof key]) = draft[key]
    }
  }
  return nextConfig
}

function pickPreservedColumnConfig(currentRawConfig: SheetColumnConfig | undefined) {
  const preservedConfig: SheetColumnConfig = {}
  if (!currentRawConfig) {
    return preservedConfig
  }
  if (currentRawConfig.hidden) {
    preservedConfig.hidden = true
  }
  if (currentRawConfig.restore_index != null) {
    preservedConfig.restore_index = currentRawConfig.restore_index
  }
  if (currentRawConfig.header_background_color) {
    preservedConfig.header_background_color = currentRawConfig.header_background_color
  }
  if (currentRawConfig.header_text_color) {
    preservedConfig.header_text_color = currentRawConfig.header_text_color
  }
  if (currentRawConfig.header_link) {
    preservedConfig.header_link = currentRawConfig.header_link
  }
  if (currentRawConfig.note) {
    preservedConfig.note = normalizeColumnNote(currentRawConfig.note)
  }
  return preservedConfig
}

function createStoredColumnConfig(
  nextConfig: ColumnSettingsDraft,
  preservedConfig: SheetColumnConfig,
) {
  if (
    nextConfig.value_type === 'text'
    && nextConfig.text_rule === 'none'
    && nextConfig.value_mode === 'free'
    && !nextConfig.filter_enabled
    && isDefaultColumnDisplayFormat(nextConfig.value_type, nextConfig.display_format)
    && nextConfig.allow_empty
    && nextConfig.display_mode === DEFAULT_COLUMN_DISPLAY_MODE
    && nextConfig.align === DEFAULT_COLUMN_TEXT_ALIGN
    && nextConfig.trim_whitespace
    && !nextConfig.duplicate_value_highlight
    && nextConfig.hash_color_mode === 'none'
    && nextConfig.width_mode === 'adaptive'
    && nextConfig.font_family === 'default'
    && nextConfig.font_size === DEFAULT_COLUMN_FONT_SIZE
    && Object.keys(preservedConfig).length === 0
  ) {
    return null
  }

  const storedConfig: SheetColumnConfig = { ...preservedConfig }
  if (nextConfig.value_type !== 'text') {
    storedConfig.value_type = nextConfig.value_type
  }
  if (nextConfig.value_type === 'text' && nextConfig.text_rule !== 'none') {
    storedConfig.text_rule = nextConfig.text_rule
  }
  if (nextConfig.value_mode !== 'free') {
    storedConfig.value_mode = nextConfig.value_mode
  }
  if (nextConfig.filter_enabled) {
    storedConfig.filter_enabled = true
  }
  if (!isDefaultColumnDisplayFormat(nextConfig.value_type, nextConfig.display_format)) {
    storedConfig.display_format = nextConfig.display_format
  }
  if (!nextConfig.allow_empty) {
    storedConfig.allow_empty = false
  }
  if (nextConfig.display_mode !== DEFAULT_COLUMN_DISPLAY_MODE) {
    storedConfig.display_mode = nextConfig.display_mode
  }
  if (nextConfig.align !== DEFAULT_COLUMN_TEXT_ALIGN) {
    storedConfig.align = nextConfig.align
  }
  if (!nextConfig.trim_whitespace) {
    storedConfig.trim_whitespace = false
  }
  if (nextConfig.duplicate_value_highlight) {
    storedConfig.duplicate_value_highlight = true
  }
  if (nextConfig.hash_color_mode !== 'none') {
    storedConfig.hash_color_mode = nextConfig.hash_color_mode
    if (nextConfig.hash_color_tone !== 'light') {
      storedConfig.hash_color_tone = nextConfig.hash_color_tone
    }
  }
  if (nextConfig.width_mode !== 'adaptive') {
    storedConfig.width_mode = nextConfig.width_mode
  }
  if (nextConfig.font_family !== 'default') {
    storedConfig.font_family = nextConfig.font_family
  }
  if (nextConfig.font_size !== DEFAULT_COLUMN_FONT_SIZE) {
    storedConfig.font_size = nextConfig.font_size
  }
  return storedConfig
}

function getColumnNote(columnIndex: number) {
  const header = columnHeaders.value[columnIndex]
  if (!header) {
    return ''
  }
  return normalizeColumnNote(columnConfigs.value[header]?.note)
}

function getColumnHeaderLink(columnIndex: number) {
  const header = columnHeaders.value[columnIndex]
  if (!header) {
    return null
  }
  return normalizeCellLink(columnConfigs.value[header]?.header_link)
}

function getColumnSettingsTitle() {
  const selectedCount = columnSettingsSelectedCount.value
  if (selectedCount > 1) {
    return `设置字段：已选 ${selectedCount} 个字段`
  }

  const columnIndex = columnSettingsColumnIndex.value
  if (columnIndex == null) {
    return '设置字段'
  }

  const header = columnHeaders.value[columnIndex]
  return header ? `设置字段：${header}` : '设置字段'
}

function openColumnSettingsForBounds(bounds: { start: number; end: number }) {
  if (!ensureCanEditConfig()) {
    return
  }

  const indexes = getColumnSettingsIndexesFromBounds(bounds)
  if (!indexes.length) {
    return
  }

  const start = Math.min(...indexes)
  const end = Math.max(...indexes)
  const nextState = createColumnSettingsDraftForSelection(indexes)
  columnSettingsColumnIndex.value = indexes.length === 1 ? indexes[0] : null
  columnSettingsSelectionBounds.value = { start, end }
  columnSettingsDraft.value = nextState.draft
  columnSettingsMixed.value = nextState.mixed
  columnSettingsTouched.value = createColumnSettingsTouchedState()
  columnSettingsDialogVisible.value = true
}

function openColumnSettings(columnIndex: number) {
  if (!ensureCanEditConfig()) {
    return
  }

  if (columnIndex < 0 || columnIndex >= columnHeaders.value.length) {
    return
  }
  openColumnSettingsForBounds({ start: columnIndex, end: columnIndex })
}

function openSelectedColumnSettings() {
  if (!ensureCanEditConfig()) {
    return
  }

  const bounds = getColumnSettingsContextBounds()
  if (!bounds) {
    return
  }
  openColumnSettingsForBounds(bounds)
}

function closeColumnSettings() {
  columnSettingsDialogVisible.value = false
}

function handleColumnSettingsValueTypeChange(value: ColumnValueType) {
  markColumnSettingTouched('value_type')
  markColumnSettingTouched('display_format')
  if (value !== 'text') {
    columnSettingsDraft.value.text_rule = 'none'
    markColumnSettingTouched('text_rule')
  }
  if (value === 'date' || value === 'percent') {
    columnSettingsDraft.value.display_format = normalizeColumnDisplayFormat(
      columnSettingsDraft.value.display_format,
      value,
    )
    return
  }
  if (value !== 'number') {
    columnSettingsDraft.value.display_format = ''
  }
}

function applyColumnSettings() {
  if (!ensureCanEditConfig()) {
    closeColumnSettings()
    return
  }

  const indexes = getColumnSettingsIndexesFromBounds(columnSettingsSelectionBounds.value)
  if (!indexes.length) {
    closeColumnSettings()
    return
  }

  const applyAll = indexes.length === 1
  const touched = columnSettingsTouched.value
  if (!applyAll && !COLUMN_SETTINGS_KEYS.some((key) => touched[key])) {
    closeColumnSettings()
    return
  }

  const draft = normalizeColumnConfig(columnSettingsDraft.value)
  draft.width_value = normalizeColumnWidthValue(columnSettingsDraft.value.width_value)
  closeColumnSettings()
  closeColumnNotePopover()

  const currentNormalizedConfigs = normalizeColumnConfigs(columnConfigs.value, columnHeaders.value)
  const nextNormalizedConfigs = { ...currentNormalizedConfigs }
  const nextWidths = [...columnWidths.value]
  const previousHeaderRowCount = sheetHeaderRowCount.value
  let configChanged = false
  let widthChanged = false
  let normalizedValuesChanged = false
  const undoEntry = createLocalUndoEntry('column-settings')

  for (const columnIndex of indexes) {
    const header = columnHeaders.value[columnIndex]
    if (!header) {
      continue
    }

    const currentConfig = getColumnSettingsDraftForColumn(columnIndex)
    const nextConfig = mergeColumnSettingsDraft(currentConfig, draft, touched, applyAll)
    nextConfig.display_format = normalizeColumnDisplayFormat(nextConfig.display_format, nextConfig.value_type)
    nextConfig.width_value = normalizeColumnWidthValue(nextConfig.width_value)
    const currentWidthValue = normalizeColumnWidthValue(columnWidths.value[columnIndex] ?? getEffectiveColumnWidth(columnIndex))
    const nextWidthValue = normalizeColumnWidthValue(nextConfig.width_value)
    const columnValuesChanged = normalizeColumnValuesForValueType(columnIndex, nextConfig.value_type)
    normalizedValuesChanged ||= columnValuesChanged

    const preservedConfig = pickPreservedColumnConfig(currentNormalizedConfigs[header])
    const storedConfig = createStoredColumnConfig(nextConfig, preservedConfig)
    const currentStoredConfig = currentNormalizedConfigs[header] ?? null
    if (JSON.stringify(storedConfig ?? null) !== JSON.stringify(currentStoredConfig)) {
      configChanged = true
    }
    if (storedConfig) {
      nextNormalizedConfigs[header] = storedConfig
    } else {
      delete nextNormalizedConfigs[header]
    }

    const shouldRefreshAdaptiveWidth = (
      nextConfig.width_mode === 'adaptive'
      && (
        applyAll
        || touched.width_mode
        || touched.font_family
        || touched.font_size
        || touched.display_format
        || touched.value_type
        || touched.align
      )
      && (
        nextConfig.width_mode !== currentConfig.width_mode
        || nextConfig.font_family !== currentConfig.font_family
        || nextConfig.font_size !== currentConfig.font_size
        || nextConfig.display_format !== currentConfig.display_format
        || nextConfig.value_type !== currentConfig.value_type
        || nextConfig.align !== currentConfig.align
      )
    )
    if (shouldRefreshAdaptiveWidth) {
      const nextAutoWidth = getAutoColumnWidth(columnIndex, columnHeaders.value, rows.value, nextNormalizedConfigs)
      if (nextAutoWidth !== currentWidthValue) {
        nextWidths[columnIndex] = nextAutoWidth
        widthChanged = true
      }
    } else if ((applyAll || touched.width_value) && nextWidthValue !== currentWidthValue) {
      nextWidths[columnIndex] = nextWidthValue
      widthChanged = true
    }
  }

  if (!configChanged && !widthChanged && !normalizedValuesChanged) {
    return
  }

  const nextRows = configChanged
    ? remapRowsFormulaReferencesForHeaderRowCountChange(
      rows.value,
      previousHeaderRowCount,
      getSheetHeaderRowCountForColumnNoteEntity(hasColumnNoteEntityRow.value),
    )
    : rows.value
  const canPatchColumnSettings = !normalizedValuesChanged && nextRows === rows.value
  if (canPatchColumnSettings) {
    suppressNextRemoteSaveWatcher = true
  }

  if (configChanged) {
    columnConfigs.value = nextNormalizedConfigs
  }
  if (nextRows !== rows.value) {
    rows.value = nextRows
  }
  if (widthChanged) {
    columnWidths.value = nextWidths
  }
  refreshGridStructure()
  void refreshComputedRowHeights()
  pushLocalUndoEntry(undoEntry)
  if (canPatchColumnSettings) {
    const operations: NoteSheetPatchOperation[] = []
    const normalizedConfigs = normalizeColumnConfigs(columnConfigs.value, columnHeaders.value)
    for (const columnIndex of indexes) {
      const header = columnHeaders.value[columnIndex]
      if (!header) {
        continue
      }
      if (configChanged) {
        operations.push({
          op: 'set-column-config',
          column_index: columnIndex,
          config: normalizedConfigs[header] ?? {},
        })
      }
      if (widthChanged) {
        operations.push({
          op: 'set-column-width',
          column_index: columnIndex,
          width: normalizeColumnWidthValue(columnWidths.value[columnIndex] ?? getEffectiveColumnWidth(columnIndex)),
        })
      }
    }
    queueImmediateColumnConfigPatchSave(operations)
  } else {
    void nextTick(() => {
      scheduleRemoteSave(0)
    })
  }
}

function shouldShowRemoveColumnAction() {
  return shouldShowColumnActions() && !!getSelectionColumnBounds() && columnHeaders.value.length > 1
}

function shouldShowRemoveRowAction() {
  const hot = getHotInstance()
  return shouldShowRowActions() && !!getSelectionRowBounds() && !!hot?.countSourceRows()
}

function isRowRangeWithinData(
  bounds: { start: number; end: number } | null | undefined,
): bounds is { start: number; end: number } {
  return !!bounds && bounds.start >= 0 && bounds.end >= bounds.start && bounds.end < rows.value.length
}

function shouldShowCutRowAction() {
  return isWholeRowSelection() && !isSelectedByCorner() && isRowRangeWithinData(getSelectionRowBounds())
}

function getValidCutRowBounds() {
  if (!isRowRangeWithinData(cutRowBounds)) {
    cutRowBounds = null
    return null
  }
  return cutRowBounds
}

function shouldShowPasteCutRowAction() {
  return !!getValidCutRowBounds() && isWholeRowSelection() && !isSelectedByCorner() && isRowRangeWithinData(getSelectionRowBounds())
}

function getDataRowRangeLabel(bounds: { start: number; end: number }) {
  const startLabel = getSheetRowHeaderLabel(getGridRowIndex(bounds.start))
  const endLabel = getSheetRowHeaderLabel(getGridRowIndex(bounds.end))
  return bounds.start === bounds.end ? `第 ${startLabel} 行` : `第 ${startLabel}-${endLabel} 行`
}

function cutSelectedRows() {
  if (!ensureCanEditData()) {
    return
  }

  const bounds = getSelectionRowBounds()
  if (!isRowRangeWithinData(bounds)) {
    return
  }
  cutRowBounds = { start: bounds.start, end: bounds.end }
  renderCurrentHotWithReason('row-cut-mark')
  ElMessage.success(`已剪切${getDataRowRangeLabel(cutRowBounds)}`)
}

function pasteCutRowsFromSelection(side: 'above' | 'below') {
  if (!ensureCanEditData()) {
    return
  }

  const sourceBounds = getValidCutRowBounds()
  const targetBounds = getSelectionRowBounds()
  if (!sourceBounds || !isRowRangeWithinData(targetBounds)) {
    return
  }

  const targetDataIndex = side === 'above' ? targetBounds.start : targetBounds.end
  if (targetDataIndex >= sourceBounds.start && targetDataIndex <= sourceBounds.end) {
    ElMessage.info('目标行在已剪切行内，无需移动')
    return
  }

  const movedRows = Array.from(
    { length: sourceBounds.end - sourceBounds.start + 1 },
    (_, offset) => sourceBounds.start + offset,
  )
  const movedRowSet = new Set(movedRows)
  let remainingBeforeTarget = 0
  for (let rowIndex = 0; rowIndex < targetDataIndex; rowIndex += 1) {
    if (!movedRowSet.has(rowIndex)) {
      remainingBeforeTarget += 1
    }
  }
  const finalIndex = remainingBeforeTarget + (side === 'below' ? 1 : 0)

  const moved = moveDataRowsToFinalIndex(movedRows, finalIndex, 'row-cut-paste')
  if (!moved) {
    ElMessage.warning('当前行无法移动，可能是合并单元格选区不完整')
    return
  }

  cutRowBounds = null
  renderCurrentHotWithReason('row-cut-paste-clear')
  ElMessage.success(`已移动到${getDataRowRangeLabel(targetBounds)}${side === 'above' ? '上方' : '下方'}`)
}

function getSingleSelectedRowDetailIndex() {
  if ((!isSelectedByRowHeader() && !isSelectedByRowMarkerSelection()) || isSelectedByCorner()) {
    return null
  }
  const bounds = getSelectionRowBounds()
  if (!bounds || bounds.start !== bounds.end) {
    return null
  }
  return bounds.start >= 0 && bounds.start < rows.value.length ? bounds.start : null
}

function canOpenSelectedRowDetailDialog() {
  return getSingleSelectedRowDetailIndex() != null
}

function normalizeStudentLookupPersistedSelection(value: unknown): StudentLookupPersistedSelection | null {
  if (!value || typeof value !== 'object') {
    return null
  }

  const record = value as Record<string, unknown>
  const mode = normalizeCellValue(record.mode).trim() === 'questionnaire' ? 'questionnaire' : 'student'
  return {
    version: 1,
    mode,
    sequence: normalizeCellValue(record.sequence).trim(),
    group: normalizeCellValue(record.group).trim(),
    studentKey: normalizeCellValue(record.studentKey).trim(),
    studentGroup: normalizeCellValue(record.studentGroup).trim(),
    studentNumber: normalizeCellValue(record.studentNumber).trim(),
    studentName: normalizeCellValue(record.studentName).trim(),
    nickname: normalizeCellValue(record.nickname).trim(),
    updatedAt: Number(record.updatedAt) || 0,
  }
}

function readStudentLookupPersistedSelection() {
  if (typeof window === 'undefined') {
    return null
  }

  try {
    const raw = window.localStorage.getItem(studentLookupStorageKey.value)
    if (!raw) {
      return null
    }
    return normalizeStudentLookupPersistedSelection(JSON.parse(raw))
  } catch {
    window.localStorage.removeItem(studentLookupStorageKey.value)
    return null
  }
}

function isSameStudentLookupPersistedIdentity(
  option: StudentLookupOption,
  selection: StudentLookupPersistedSelection,
  requireGroup: boolean,
) {
  if (selection.mode === 'questionnaire' || option.mode === 'questionnaire') {
    return !!selection.sequence && option.sequence === selection.sequence
  }
  if (requireGroup && selection.studentGroup && option.group !== selection.studentGroup) {
    return false
  }
  if (selection.studentNumber && option.studentNumber !== selection.studentNumber) {
    return false
  }
  if (selection.studentName && option.studentName !== selection.studentName) {
    return false
  }
  if (selection.nickname && option.nickname !== selection.nickname) {
    return false
  }
  return !!selection.studentNumber || !!selection.studentName || !!selection.nickname
}

function findStudentLookupOptionFromPersistedSelection(
  selection: StudentLookupPersistedSelection | null,
  candidates: StudentLookupOption[] = studentLookupOptions.value,
) {
  if (!selection) {
    return null
  }

  if (selection.studentKey) {
    const keyMatch = candidates.find((option) => option.key === selection.studentKey)
    if (keyMatch) {
      return keyMatch
    }
  }

  return candidates.find((option) => isSameStudentLookupPersistedIdentity(option, selection, true))
    ?? candidates.find((option) => isSameStudentLookupPersistedIdentity(option, selection, false))
    ?? null
}

function persistStudentLookupSelectionToLocalStorage() {
  if (typeof window === 'undefined' || restoringStudentLookupSelection || !shouldShowStudentLookup.value) {
    return
  }

  const option = selectedStudentLookupOption.value
  const payload: StudentLookupPersistedSelection = {
    version: 1,
    mode: studentLookupMode.value,
    sequence: option?.sequence ?? (isStudentLookupQuestionnaireMode.value ? studentLookupStudentKey.value.trim() : ''),
    group: studentLookupGroup.value.trim(),
    studentKey: option?.key ?? '',
    studentGroup: option?.group ?? '',
    studentNumber: option?.studentNumber ?? '',
    studentName: option?.studentName ?? '',
    nickname: option?.nickname ?? '',
    updatedAt: Date.now(),
  }
  window.localStorage.setItem(studentLookupStorageKey.value, JSON.stringify(payload))
}

function restoreStudentLookupSelectionFromLocalStorage() {
  const selection = readStudentLookupPersistedSelection()
  const matchedOption = findStudentLookupOptionFromPersistedSelection(selection)
  const savedGroup = selection?.group ?? ''
  const nextGroup = !isStudentLookupQuestionnaireMode.value && savedGroup && studentLookupGroupOptions.value.includes(savedGroup)
    ? savedGroup
    : ''
  const nextStudentKey = matchedOption && (!nextGroup || matchedOption.group === nextGroup)
    ? matchedOption.key
    : ''

  restoringStudentLookupSelection = true
  studentLookupGroup.value = nextGroup
  studentLookupStudentKey.value = nextStudentKey
  void nextTick(() => {
    restoringStudentLookupSelection = false
  })
}

function getResolvedCellValueStyle(rowIndex: number, columnIndex: number, renderedText: string) {
  const gridRow = getGridRowIndex(rowIndex)
  const anchor = getMergeAnchorForGridCell(gridRow, columnIndex)
  const renderColumn = anchor.column
  if (renderColumn < 0) {
    return null
  }

  const dataRow = anchor.row >= 0 ? getDataRowIndex(anchor.row) : rowIndex
  const documentRow = anchor.documentRow >= 0 ? anchor.documentRow : getDocumentGridRowIndex(gridRow)
  const header = columnHeaders.value[renderColumn] ?? ''
  const columnConfig = header ? columnConfigs.value[header] : undefined
  const cellStyle = documentRow >= 0 ? getCellStyleAt(documentRow, renderColumn) : null
  const columnFontSize = getColumnFontSizeFromConfig(columnConfig)
  const detailFontSize = Math.max(columnFontSize, DETAIL_VALUE_MIN_FONT_SIZE)
  let backgroundColor = getPluginRowBackgroundColor(dataRow)
  let textColor = ''
  let fontFamilyStyle = getColumnFontFamilyStyle(columnConfig)
  let fontSizeStyle = ''
  let lineHeightStyle = ''
  let textAlignStyle = resolveColumnTextAlign(columnConfig)

  if (detailFontSize !== DEFAULT_COLUMN_FONT_SIZE) {
    fontSizeStyle = `${detailFontSize}px`
    lineHeightStyle = `${getColumnLineHeightFromFontSize(detailFontSize)}px`
  }

  const hashColorStyle = getCellHashColorStyle(renderColumn, columnConfig, renderedText)
  if (hashColorStyle?.backgroundColor) {
    backgroundColor = hashColorStyle.backgroundColor
  }
  if (hashColorStyle?.color) {
    textColor = hashColorStyle.color
  }

  const accentStyle = getCellAccentStyle(dataRow, renderColumn)
  if (accentStyle) {
    backgroundColor = accentStyle.backgroundColor
  }

  if (cellStyle?.background_color) {
    backgroundColor = cellStyle.background_color
  }
  if (cellStyle?.text_color) {
    textColor = cellStyle.text_color
  }
  if (cellStyle?.font_family) {
    fontFamilyStyle = getCellFontFamilyStyle(cellStyle.font_family)
  }
  if (cellStyle?.font_size) {
    fontSizeStyle = `${cellStyle.font_size}px`
    lineHeightStyle = `${getColumnLineHeightFromFontSize(cellStyle.font_size)}px`
  }
  if (cellStyle?.text_align) {
    textAlignStyle = cellStyle.text_align
  }

  if (isSyntheticEmptyDisplayRow(dataRow)) {
    backgroundColor = ''
  }

  const style: SheetResolvedCellValueStyle = {}
  if (backgroundColor) {
    style.backgroundColor = backgroundColor
  }
  if (textColor) {
    style.color = textColor
  }
  if (fontFamilyStyle) {
    style.fontFamily = fontFamilyStyle
  }
  if (fontSizeStyle) {
    style.fontSize = fontSizeStyle
  }
  if (lineHeightStyle) {
    style.lineHeight = lineHeightStyle
  }
  if (textAlignStyle) {
    style.textAlign = textAlignStyle
  }
  return style
}

function buildRowDetail(rowIndex: number): SheetRowDetail | null {
  if (rowIndex < 0 || rowIndex >= rows.value.length) {
    return null
  }

  const row = normalizeRow(rows.value[rowIndex], columnHeaders.value)
  const gridRow = getGridRowIndex(rowIndex)
  const documentGridRow = getDocumentGridRowIndex(gridRow)
  const rowLabel = getSheetRowHeaderLabel(gridRow)
  const items = columnHeaders.value
    .map((header, columnIndex): SheetRowDetailItem | null => {
      if (columnConfigs.value[header]?.hidden === true) {
        return null
      }

      const rawValue = row[columnIndex] ?? ''
      const normalizedRawValue = normalizeCellValue(rawValue)
      const link = getCellLinkAt(documentGridRow, columnIndex)
      const action = getCellActionAt(documentGridRow, columnIndex)
      const displayValue = action
        ? getCellActionDisplayLabel(action, normalizedRawValue)
        : getCellDisplayText(rowIndex, columnIndex, rawValue)
      const linkDisplayValue = link ? (displayValue || link.title || link.url) : displayValue
      const value = normalizeCellValue(linkDisplayValue)
      const editValue = action ? normalizedRawValue : getCellEditText(columnIndex, rawValue)
      return {
        columnIndex,
        marker: getColumnMarkerLabel(columnIndex),
        label: header || createFallbackHeader(columnIndex),
        rawValue: editValue,
        value,
        empty: !value.trim(),
        editable: canEditDataColumn(columnIndex) && !action,
        valueStyle: getResolvedCellValueStyle(rowIndex, columnIndex, value),
        link,
      }
    })
    .filter((item): item is SheetRowDetailItem => !!item)

  return { rowIndex, rowLabel, items }
}

function updateRowDetailItemValue(item: SheetRowDetailItem, value: unknown) {
  const detail = rowDetail.value
  if (!detail || !item.editable || !canEditDataColumn(item.columnIndex)) {
    return
  }

  const rowIndex = detail.rowIndex
  if (rowIndex < 0 || rowIndex >= rows.value.length) {
    return
  }

  const nextValue = normalizeCellInputValueForColumn(normalizeCellValue(value), item.columnIndex)
  item.rawValue = nextValue
  item.value = nextValue
  item.empty = !nextValue.trim()

  if (detail.mode === 'new_registration_student') {
    return
  }

  const hot = getHotInstance()
  const gridRow = getGridRowIndex(rowIndex)
  if (hot && gridRow >= sheetHeaderRowCount.value) {
    hot.setDataAtCell(gridRow, toHotColumnIndex(item.columnIndex), nextValue, 'row-detail')
    return
  }

  const nextRows = rows.value.map((row) => normalizeRow(row, columnHeaders.value))
  nextRows[rowIndex][item.columnIndex] = nextValue
  suppressNextRemoteSaveWatcher = true
  rows.value = nextRows
  queueImmediateCellPatchSave([{
    op: 'set-cell-value',
    row_index: getDocumentRowIndex(rowIndex),
    column_index: item.columnIndex,
    value: nextValue,
  }])
}

function getStudentLookupSectionTitle(columnIndex: number) {
  const topGroupRow = normalizedHeaderGroups.value[0]
  if (!topGroupRow?.length) {
    return ''
  }

  let startColumn = 0
  for (const cell of topGroupRow) {
    const colspan = Math.max(1, cell.colspan ?? 1)
    const endColumn = startColumn + colspan - 1
    if (columnIndex >= startColumn && columnIndex <= endColumn) {
      return normalizeCellValue(cell.label).trim()
    }
    startColumn += colspan
  }
  return ''
}

function openRowDetailDialog(rowIndex: number) {
  const detail = buildRowDetail(rowIndex)
  if (!detail) {
    return
  }
  rowDetail.value = detail
  rowDetailDialogVisible.value = true
}

function buildNewRegistrationStudentRowDetail(targetDataIndex: number): SheetRowDetail {
  const row = createEmptyRow(columnHeaders.value.length)
  const groupColumn = getHeaderColumnIndex(STUDENT_LOOKUP_GROUP_HEADER)
  const sequenceColumn = getHeaderColumnIndex(STUDENT_LOOKUP_SEQUENCE_HEADER)
  const submittedAtColumn = getHeaderColumnIndex(STUDENT_LOOKUP_SUBMITTED_AT_HEADER)
  const now = new Date()
  const groupValue = getRegistrationStudentGroupDefaultValue(targetDataIndex)
  if (groupColumn >= 0 && groupValue) {
    row[groupColumn] = groupValue
  }
  if (submittedAtColumn >= 0) {
    row[submittedAtColumn] = createDefaultRegistrationSubmittedAtValue(now)
    applyRegistrationTrackingValuesToRow(row, row[submittedAtColumn], now)
  }
  if (sequenceColumn >= 0) {
    row[sequenceColumn] = normalizeCellInputValueForColumn(
      getNextRegistrationSequenceValue(-1, groupValue),
      sequenceColumn,
    )
  }

  const items = columnHeaders.value
    .map((header, columnIndex): SheetRowDetailItem | null => {
      if (columnConfigs.value[header]?.hidden === true) {
        return null
      }

      const rawValue = row[columnIndex] ?? ''
      const value = normalizeCellValue(rawValue)
      return {
        columnIndex,
        marker: getColumnMarkerLabel(columnIndex),
        label: header || createFallbackHeader(columnIndex),
        rawValue,
        value,
        empty: !value.trim(),
        editable: canEditDataColumn(columnIndex),
        valueStyle: null,
        link: null,
      }
    })
    .filter((item): item is SheetRowDetailItem => !!item)

  return {
    rowIndex: -1,
    rowLabel: '',
    items,
    mode: 'new_registration_student',
    insertIndex: targetDataIndex,
  }
}

function openNewRegistrationStudentDialog(targetDataIndex: number) {
  rowDetail.value = buildNewRegistrationStudentRowDetail(targetDataIndex)
  rowDetailDialogVisible.value = true
}

function confirmNewRegistrationStudentRow() {
  const detail = rowDetail.value
  if (detail?.mode !== 'new_registration_student') {
    return
  }
  if (!ensureCanEditData()) {
    return
  }

  const hot = getHotInstance()
  const targetDataIndex = Math.max(0, Math.min(detail.insertIndex ?? rows.value.length, rows.value.length))
  const nextRow = createEmptyRow(columnHeaders.value.length)
  for (const item of detail.items) {
    if (item.columnIndex < 0 || item.columnIndex >= nextRow.length) {
      continue
    }
    nextRow[item.columnIndex] = normalizeCellInputValueForColumn(normalizeCellValue(item.rawValue), item.columnIndex)
  }

  const templateDataIndex = targetDataIndex > 0
    ? targetDataIndex - 1
    : (rows.value.length > 0 ? 0 : -1)
  pushLocalUndoSnapshot('registration-add-student')

  if (hot) {
    pendingRowInsertionTemplate = createRowInsertionTemplate(templateDataIndex, targetDataIndex)
    try {
      hot.alter('insert_row_above', getGridRowIndex(targetDataIndex), 1)
    } finally {
      pendingRowInsertionTemplate = null
    }

    const gridRow = getGridRowIndex(targetDataIndex)
    nextRow.forEach((value, columnIndex) => {
      hot.setDataAtCell(gridRow, toHotColumnIndex(columnIndex), value, 'registration-add-student')
    })
  } else {
    const nextRows = rows.value.map((row) => normalizeRow(row, columnHeaders.value))
    nextRows.splice(targetDataIndex, 0, nextRow)
    rows.value = nextRows
    scheduleRemoteSave()
  }

  rowDetailDialogVisible.value = false
  rowDetail.value = null
  void nextTick(() => {
    selectRowFromMarker(getGridRowIndex(targetDataIndex))
  })
}

function openSelectedRowDetailDialog() {
  const rowIndex = getSingleSelectedRowDetailIndex()
  if (rowIndex == null) {
    return
  }
  openRowDetailDialog(rowIndex)
}

function openStudentLookupFeedbackDialog() {
  const option = selectedStudentLookupOption.value
  if (!option) {
    return
  }

  studentLookupFeedbackCorrectionRequest.value = ''
  studentLookupFeedbackLastSubmittedKey.value = ''
  studentLookupFeedbackSubmittedAt.value = ''
  studentLookupFeedbackDialogVisible.value = true
}

function resetStudentLookupFeedbackHistory() {
  studentLookupFeedbackHistoryRequestId += 1
  studentLookupFeedbackHistoryItems.value = []
  studentLookupFeedbackHistoryTotal.value = 0
  studentLookupFeedbackHistoryLoading.value = false
}

async function loadStudentLookupFeedbackHistory() {
  const courseName = studentLookupFeedbackCourseName.value.trim()
  const studentName = studentLookupFeedbackStudentName.value.trim()
  if (!courseName || !studentName) {
    resetStudentLookupFeedbackHistory()
    return
  }

  const requestId = studentLookupFeedbackHistoryRequestId + 1
  studentLookupFeedbackHistoryRequestId = requestId
  studentLookupFeedbackHistoryLoading.value = true
  try {
    const result = await fetchAttendanceFeedbackHistory({
      course_name: courseName,
      student_name: studentName,
      limit: 8,
    })
    if (requestId !== studentLookupFeedbackHistoryRequestId) {
      return
    }
    studentLookupFeedbackHistoryItems.value = result.items || []
    studentLookupFeedbackHistoryTotal.value = result.total || 0
  } catch {
    if (requestId !== studentLookupFeedbackHistoryRequestId) {
      return
    }
    studentLookupFeedbackHistoryItems.value = []
    studentLookupFeedbackHistoryTotal.value = 0
  } finally {
    if (requestId === studentLookupFeedbackHistoryRequestId) {
      studentLookupFeedbackHistoryLoading.value = false
    }
  }
}

async function submitStudentLookupFeedback() {
  const option = selectedStudentLookupOption.value
  const courseName = studentLookupFeedbackCourseName.value.trim()
  const studentId = studentLookupFeedbackStudentId.value
  const studentName = studentLookupFeedbackStudentName.value.trim()
  const correctionRequest = studentLookupFeedbackCorrectionRequest.value.trim()

  if (!option) {
    ElMessage.warning('请先选择学员')
    return
  }
  if (!courseName) {
    ElMessage.warning('未识别所属课程')
    return
  }
  if (!studentId) {
    ElMessage.warning('当前学员缺少学号')
    return
  }
  if (!studentName) {
    ElMessage.warning('当前学员缺少姓名')
    return
  }
  if (!correctionRequest) {
    ElMessage.warning('请填写修正需求')
    return
  }

  studentLookupFeedbackSubmitting.value = true
  try {
    const saved = await submitAttendanceFeedback({
      course_name: courseName,
      student_id_text: studentId,
      student_name: studentName,
      correction_request: correctionRequest,
      extra_note: '',
      workbook_id: props.workbookId ?? null,
      sheet_id: props.sheetId ?? null,
    })
    studentLookupFeedbackCorrectionRequest.value = correctionRequest
    studentLookupFeedbackLastSubmittedKey.value = studentLookupFeedbackCurrentDraftKey.value
    studentLookupFeedbackSubmittedAt.value = saved.submitted_at_text || new Date().toLocaleString('zh-CN', { hour12: false })
    ElMessage.success('已提交反馈')
    void loadStudentLookupFeedbackHistory()
  } catch (error) {
    ElMessage.error(getSheetActionErrorMessage(error, '提交反馈失败'))
  } finally {
    studentLookupFeedbackSubmitting.value = false
  }
}

function getNextCustomColumnNumber(headers: string[]) {
  const usedNumbers = headers
    .map((header) => header.match(new RegExp(`^${CUSTOM_COLUMN_PREFIX}(\\d+)$`)))
    .filter((match): match is RegExpMatchArray => !!match)
    .map((match) => Number(match[1]))
    .filter((value) => Number.isFinite(value))

  return usedNumbers.length ? Math.max(...usedNumbers) + 1 : 1
}

function createCustomColumnNames(amount: number, existingHeaders = columnHeaders.value) {
  const nextHeaders = [...existingHeaders]
  const names: string[] = []
  let nextNumber = getNextCustomColumnNumber(nextHeaders)

  while (names.length < amount) {
    const candidate = `${CUSTOM_COLUMN_PREFIX}${nextNumber}`
    nextNumber += 1
    if (nextHeaders.includes(candidate) || names.includes(candidate)) {
      continue
    }
    names.push(candidate)
  }

  return names
}

function cloneColumnConfigForInsertedColumn(source: SheetColumnConfig | undefined) {
  if (!source) {
    return null
  }

  const config = { ...source }
  delete config.hidden
  delete config.restore_index
  delete config.note
  delete config.header_link
  return Object.keys(config).length ? { ...config } : null
}

function createColumnInsertionTemplate(templateColumnIndex: number, targetIndex: number): ColumnInsertionTemplate | null {
  const header = columnHeaders.value[templateColumnIndex]
  if (!header) {
    return null
  }

  const normalizedConfigs = normalizeColumnConfigs(columnConfigs.value, columnHeaders.value)
  const config = cloneColumnConfigForInsertedColumn(normalizedConfigs[header])
  const width = normalizeColumnWidthValue(columnWidths.value[templateColumnIndex] ?? getEffectiveColumnWidth(templateColumnIndex))
  const cellStyles = Object.entries(cellMeta.value)
    .map(([key, meta]) => {
      const position = parseCellMetaKey(key)
      if (!position || position.column !== templateColumnIndex) {
        return null
      }

      const style = normalizeCellStyle(meta.style)
      return style ? { row: position.row, style } : null
    })
    .filter((item): item is ColumnInsertionTemplate['cellStyles'][number] => !!item)

  return { targetIndex, width, config, cellStyles }
}

function applyColumnInsertionTemplate(
  headers: string[],
  index: number,
  amount: number,
  template: ColumnInsertionTemplate | null,
) {
  const normalizedConfigs = normalizeColumnConfigs(columnConfigs.value, headers)
  if (!template || template.targetIndex !== index) {
    return normalizedConfigs
  }

  for (let offset = 0; offset < amount; offset += 1) {
    const header = headers[index + offset]
    if (header && template.config) {
      normalizedConfigs[header] = { ...template.config }
    }
  }
  return normalizeColumnConfigs(normalizedConfigs, headers)
}

function applyColumnInsertionTemplateCellStyles(index: number, amount: number, template: ColumnInsertionTemplate | null) {
  if (!template || template.targetIndex !== index || !template.cellStyles.length) {
    return
  }

  const nextMeta = { ...cellMeta.value }
  for (const cell of template.cellStyles) {
    for (let offset = 0; offset < amount; offset += 1) {
      const key = createCellMetaKey(cell.row, index + offset)
      const entry = normalizeCellMetaEntry({ ...(nextMeta[key] ?? {}), style: { ...cell.style } })
      if (entry) {
        nextMeta[key] = entry
      } else {
        delete nextMeta[key]
      }
    }
  }
  cellMeta.value = normalizeCellMetaMap(nextMeta, columnHeaders.value.length)
}

function getDocumentGridRowIndexForDataRow(dataRowIndex: number) {
  return sheetHeaderRowCount.value + getDocumentRowIndex(dataRowIndex)
}

function createRowInsertionTemplate(templateDataIndex: number, targetDataIndex: number): RowInsertionTemplate | null {
  if (templateDataIndex < 0 || templateDataIndex >= rows.value.length) {
    return null
  }

  const sourceDocumentRow = getDocumentGridRowIndexForDataRow(templateDataIndex)
  const targetDocumentRow = getDocumentGridRowIndexForDataRow(targetDataIndex)
  const cellStyles = Object.entries(cellMeta.value)
    .map(([key, meta]) => {
      const position = parseCellMetaKey(key)
      if (!position || position.row !== sourceDocumentRow || position.column >= columnHeaders.value.length) {
        return null
      }

      const style = normalizeCellStyle(meta.style)
      return style ? { column: position.column, style } : null
    })
    .filter((item): item is RowInsertionTemplate['cellStyles'][number] => !!item)

  return { targetDocumentRow, cellStyles }
}

function applyRowInsertionTemplateCellStyles(startDocumentRow: number, amount: number, template: RowInsertionTemplate | null) {
  if (!template || template.targetDocumentRow !== startDocumentRow || !template.cellStyles.length) {
    return
  }

  const nextMeta = { ...cellMeta.value }
  for (let offset = 0; offset < amount; offset += 1) {
    for (const cell of template.cellStyles) {
      const key = createCellMetaKey(startDocumentRow + offset, cell.column)
      const entry = normalizeCellMetaEntry({ ...(nextMeta[key] ?? {}), style: { ...cell.style } })
      if (entry) {
        nextMeta[key] = entry
      } else {
        delete nextMeta[key]
      }
    }
  }
  cellMeta.value = normalizeCellMetaMap(nextMeta, columnHeaders.value.length)
}

function insertColumnFromSelection(side: 'left' | 'right', amount = 1) {
  if (!ensureCanEditConfig()) {
    return
  }

  const hot = getHotInstance()
  if (!hot) {
    return
  }

  const bounds = getSelectionColumnBounds()
  const columnAmount = normalizeColumnInsertAmount(amount)
  const targetIndex = bounds
    ? (side === 'left' ? bounds.start : bounds.end + 1)
    : columnHeaders.value.length
  const templateColumnIndex = bounds
    ? (side === 'left' ? bounds.start : bounds.end)
    : columnHeaders.value.length - 1

  pushLocalUndoSnapshot('column-insert')
  pendingColumnInsertionTemplate = createColumnInsertionTemplate(templateColumnIndex, targetIndex)
  try {
    hot.alter('insert_col_start', toHotColumnIndex(targetIndex), columnAmount)
  } finally {
    pendingColumnInsertionTemplate = null
  }
}

function insertRowFromSelection(side: 'above' | 'below', amount = 1) {
  if (!ensureCanEditData()) {
    return
  }

  const hot = getHotInstance()
  if (!hot) {
    return
  }

  const bounds = getSelectionRowBounds()
  const rowAmount = normalizeRowInsertAmount(amount)
  const targetDataIndex = bounds
    ? (side === 'above' ? bounds.start : bounds.end + 1)
    : rows.value.length
  const templateDataIndex = bounds
    ? (side === 'above' ? bounds.start : bounds.end)
    : rows.value.length - 1

  pushLocalUndoSnapshot('row-insert')
  pendingRowInsertionTemplate = createRowInsertionTemplate(templateDataIndex, targetDataIndex)
  try {
    hot.alter('insert_row_above', getGridRowIndex(targetDataIndex), rowAmount)
  } finally {
    pendingRowInsertionTemplate = null
  }
}

function isArchivedRegistrationRowForInsert(row: SheetRow, now = new Date()) {
  const submittedAtColumn = getHeaderColumnIndex(STUDENT_LOOKUP_SUBMITTED_AT_HEADER)
  const normalizedRow = normalizeRow(row, columnHeaders.value)

  if (submittedAtColumn < 0) {
    return false
  }
  const submittedAt = getRegistrationSubmittedAtDate(normalizedRow[submittedAtColumn])
  if (!submittedAt) {
    return false
  }

  const submittedDate = new Date(submittedAt.getFullYear(), submittedAt.getMonth(), submittedAt.getDate())
  return submittedDate < getRegistrationCutoffDate(now)
}

function getRegistrationStudentInsertDataIndex() {
  if (!isNianzhuChuangguanWorkbook.value) {
    return rows.value.length
  }

  const now = new Date()
  const archivedIndex = rows.value.findIndex((row) => isArchivedRegistrationRowForInsert(row, now))
  return archivedIndex >= 0 ? archivedIndex : rows.value.length
}

function getRegistrationStudentGroupDefaultValue(targetDataIndex: number) {
  const groupColumn = getHeaderColumnIndex(STUDENT_LOOKUP_GROUP_HEADER)
  if (groupColumn < 0 || targetDataIndex < 0) {
    return ''
  }

  const currentGroup = normalizeCellValue(rows.value[targetDataIndex]?.[groupColumn]).trim()
  if (currentGroup) {
    return currentGroup
  }

  let groupValue = ''
  for (let rowIndex = targetDataIndex - 1; rowIndex >= 0; rowIndex -= 1) {
    groupValue = normalizeCellValue(rows.value[rowIndex]?.[groupColumn]).trim()
    if (groupValue) {
      break
    }
  }
  if (!groupValue) {
    return ''
  }

  return normalizeCellInputValueForColumn(groupValue, groupColumn)
}

function applyRegistrationStudentGroupDefault(targetDataIndex: number) {
  const groupColumn = getHeaderColumnIndex(STUDENT_LOOKUP_GROUP_HEADER)
  if (groupColumn < 0 || targetDataIndex < 0 || targetDataIndex >= rows.value.length) {
    return ''
  }

  const nextValue = getRegistrationStudentGroupDefaultValue(targetDataIndex)
  if (!nextValue) {
    return ''
  }

  const hot = getHotInstance()
  const gridRow = getGridRowIndex(targetDataIndex)
  if (hot && gridRow >= sheetHeaderRowCount.value) {
    hot.setDataAtCell(gridRow, toHotColumnIndex(groupColumn), nextValue, 'registration-add-student')
    return nextValue
  }

  const nextRows = rows.value.map((row) => normalizeRow(row, columnHeaders.value))
  nextRows[targetDataIndex][groupColumn] = nextValue
  rows.value = nextRows
  scheduleRemoteSave()
  return nextValue
}

const REGISTRATION_GROUP_SEQUENCE_PATTERN = /^\s*(\d{1,3})\s*(?:[_\-－–—]|组)\s*(\d{1,4})\s*(?:号)?\s*$/
const REGISTRATION_CHINESE_DIGITS: Record<string, number> = {
  零: 0,
  〇: 0,
  一: 1,
  二: 2,
  两: 2,
  三: 3,
  四: 4,
  五: 5,
  六: 6,
  七: 7,
  八: 8,
  九: 9,
}

function parseRegistrationChineseInteger(value: string) {
  const text = value.trim()
  if (!text) {
    return null
  }
  if (/^\d+$/.test(text)) {
    return Number(text)
  }
  if ([...text].some((char) => !(char in REGISTRATION_CHINESE_DIGITS) && char !== '十')) {
    return null
  }
  if (text.includes('十')) {
    const [left, right = ''] = text.split('十')
    const tens = left ? REGISTRATION_CHINESE_DIGITS[left] : 1
    const ones = right ? REGISTRATION_CHINESE_DIGITS[right] : 0
    return tens == null || ones == null ? null : tens * 10 + ones
  }
  if (text.length === 1) {
    return REGISTRATION_CHINESE_DIGITS[text] ?? null
  }
  const digits = [...text].map((char) => REGISTRATION_CHINESE_DIGITS[char])
  return digits.some((digit) => digit == null) ? null : Number(digits.join(''))
}

function parseRegistrationGroupNumber(value: unknown) {
  const text = normalizeCellValue(value).trim()
  if (!text) {
    return null
  }
  const digitMatch = text.match(/(?:第\s*)?(\d{1,3})\s*(?:小组|组)/)
  if (digitMatch) {
    return String(Number(digitMatch[1]))
  }
  const chineseMatch = text.match(/(?:第\s*)?([零〇一二两三四五六七八九十]{1,4})\s*(?:小组|组)/)
  if (chineseMatch) {
    const number = parseRegistrationChineseInteger(chineseMatch[1])
    return number && number > 0 ? String(number) : null
  }
  return null
}

function parseRegistrationGroupedSequenceValue(value: unknown) {
  const text = normalizeCellValue(value).trim()
  const match = text.match(REGISTRATION_GROUP_SEQUENCE_PATTERN)
  if (!match) {
    return null
  }
  return {
    group: String(Number(match[1])),
    member: Number(match[2]),
    width: Math.max(match[2].length, 2),
  }
}

function parseRegistrationSequenceValue(value: unknown) {
  const text = normalizeCellValue(value).trim()
  if (!text) {
    return null
  }

  if (!/^\d+(?:\.0+)?$/.test(text)) {
    return null
  }

  const integerValue = Math.floor(Number(text))
  return integerValue >= 0 ? integerValue : null
}

function shouldUseRegistrationGroupedSequenceForInsert() {
  const sequenceColumn = getHeaderColumnIndex(STUDENT_LOOKUP_SEQUENCE_HEADER)
  const groupColumn = getHeaderColumnIndex(STUDENT_LOOKUP_GROUP_HEADER)
  if (sequenceColumn < 0) {
    return false
  }

  const plainSequenceGroups = new Map<number, Set<string>>()
  for (const row of rows.value) {
    if (parseRegistrationGroupedSequenceValue(row?.[sequenceColumn])) {
      return true
    }
    if (groupColumn < 0) {
      continue
    }
    const groupNumber = parseRegistrationGroupNumber(row?.[groupColumn])
    const sequence = parseRegistrationSequenceValue(row?.[sequenceColumn])
    if (!groupNumber || sequence == null) {
      continue
    }
    const groups = plainSequenceGroups.get(sequence) ?? new Set<string>()
    groups.add(groupNumber)
    plainSequenceGroups.set(sequence, groups)
    if (groups.size > 1) {
      return true
    }
  }
  return false
}

function getNextRegistrationSequenceValue(targetDataIndex: number, preferredGroup = '') {
  const sequenceColumn = getHeaderColumnIndex(STUDENT_LOOKUP_SEQUENCE_HEADER)
  if (sequenceColumn < 0) {
    return ''
  }

  const groupColumn = getHeaderColumnIndex(STUDENT_LOOKUP_GROUP_HEADER)
  const groupNumber = parseRegistrationGroupNumber(preferredGroup)
    ?? (groupColumn >= 0 ? parseRegistrationGroupNumber(rows.value[targetDataIndex]?.[groupColumn]) : null)
  if (groupNumber && shouldUseRegistrationGroupedSequenceForInsert()) {
    let maxMember = 0
    let width = 2
    rows.value.forEach((row, rowIndex) => {
      if (rowIndex === targetDataIndex) {
        return
      }
      const grouped = parseRegistrationGroupedSequenceValue(row?.[sequenceColumn])
      if (grouped?.group === groupNumber) {
        maxMember = Math.max(maxMember, grouped.member)
        width = Math.max(width, grouped.width)
        return
      }
      if (groupColumn >= 0 && parseRegistrationGroupNumber(row?.[groupColumn]) === groupNumber) {
        const sequence = parseRegistrationSequenceValue(row?.[sequenceColumn])
        if (sequence != null) {
          maxMember = Math.max(maxMember, sequence)
        }
      }
    })
    return `${groupNumber}_${String(maxMember + 1).padStart(width, '0')}`
  }

  const maxSequence = rows.value.reduce((maxValue, row, rowIndex) => {
    if (rowIndex === targetDataIndex) {
      return maxValue
    }

    const sequence = parseRegistrationSequenceValue(row[sequenceColumn])
    return sequence == null ? maxValue : Math.max(maxValue, sequence)
  }, 0)
  return String(maxSequence + 1)
}

function applyRegistrationStudentSequenceDefault(targetDataIndex: number, preferredGroup = '') {
  const sequenceColumn = getHeaderColumnIndex(STUDENT_LOOKUP_SEQUENCE_HEADER)
  if (sequenceColumn < 0 || targetDataIndex < 0 || targetDataIndex >= rows.value.length) {
    return
  }

  if (normalizeCellValue(rows.value[targetDataIndex]?.[sequenceColumn]).trim()) {
    return
  }

  const nextValue = normalizeCellInputValueForColumn(getNextRegistrationSequenceValue(targetDataIndex, preferredGroup), sequenceColumn)
  const hot = getHotInstance()
  const gridRow = getGridRowIndex(targetDataIndex)
  if (hot && gridRow >= sheetHeaderRowCount.value) {
    hot.setDataAtCell(gridRow, toHotColumnIndex(sequenceColumn), nextValue, 'registration-add-student')
    return
  }

  const nextRows = rows.value.map((row) => normalizeRow(row, columnHeaders.value))
  nextRows[targetDataIndex][sequenceColumn] = nextValue
  rows.value = nextRows
  scheduleRemoteSave()
}

function addRegistrationStudentRow() {
  if (!ensureCanEditData()) {
