function getHashColorTokenOptions(
  mode: ColumnHashColorMode,
  tone: ColumnHashColorTone,
): StableVisualColorOptions {
  if (mode === 'background') {
    return {
      colorSpace: tone === 'dark' ? 'solid' : 'soft',
    }
  }
  return {}
}

function createHashColorStyleFromToken(
  mode: ColumnHashColorMode,
  toneName: ColumnHashColorTone,
  token: StableVisualToken,
): HashColorStyle | null {
  const { hue, tone } = token
  if (mode === 'background') {
    const textSaturation = Math.max(42, tone.saturation - 18)
    return {
      backgroundColor: `hsl(${hue} ${tone.saturation}% ${tone.backgroundLightness}%)`,
      color: `hsl(${hue} ${textSaturation}% ${tone.textLightness}%)`,
    }
  }

  if (mode === 'text') {
    const textLightness = toneName === 'dark' ? 26 : 44
    const textSaturation = Math.max(54, tone.saturation - 4)
    return {
      color: `hsl(${hue} ${textSaturation}% ${textLightness}%)`,
    }
  }

  return null
}

function createColumnHashColorStyleKey(
  columnIndex: number,
  mode: ColumnHashColorMode,
  tone: ColumnHashColorTone,
  seed: string,
) {
  return `${columnIndex}:${mode}:${tone}:${seed}`
}

function compareHashColorSeeds(a: string, b: string) {
  const naturalOrder = HASH_COLOR_SEED_COLLATOR.compare(a, b)
  if (naturalOrder !== 0) {
    return naturalOrder
  }
  return stableHash32(a) - stableHash32(b)
}

function getCellHashColorStyle(columnIndex: number, config: SheetColumnConfig | undefined, value: string) {
  const mode = normalizeColumnHashColorMode(config?.hash_color_mode)
  if (mode === 'none') {
    return null
  }

  const seed = normalizeCellValue(value).trim()
  if (!seed) {
    return null
  }

  const tone = normalizeColumnHashColorTone(config?.hash_color_tone)
  const columnCacheKey = createColumnHashColorStyleKey(columnIndex, mode, tone, seed)
  const columnStyle = columnHashColorStyleMap.value.get(columnCacheKey)
  if (columnStyle) {
    return columnStyle
  }

  const cacheKey = `${mode}:${tone}:${seed}`
  if (cellHashColorStyleCache.has(cacheKey)) {
    return cellHashColorStyleCache.get(cacheKey) ?? null
  }

  const token = getStableVisualToken(seed, getHashColorTokenOptions(mode, tone))
  if (!token) {
    cellHashColorStyleCache.set(cacheKey, null)
    return null
  }

  const style = createHashColorStyleFromToken(mode, tone, token)
  cellHashColorStyleCache.set(cacheKey, style)
  return style
}

function handleBeforeRender(isForced: boolean) {
  if (!sheetPerfLoggingEnabled.value) {
    return
  }
  patchSheetPerfHotInstance()
  const selection = sheetPerfLastSelectionEntry
  sheetPerfCurrentRender = {
    id: ++sheetPerfRenderSeq,
    start: getSheetPerfNow(),
    isForced,
    cellCount: 0,
    cellMetaCount: 0,
    cellMetaMs: 0,
    rowHeightCount: 0,
    rowHeightMs: 0,
    rendererCount: 0,
    rendererMs: 0,
    selectionId: selection?.id,
    selectionAddress: selection?.address,
    selectionRow: selection?.row,
    selectionHotColumn: selection?.hotColumn,
  }
}

function handleAfterRender(isForced: boolean) {
  scheduleInlineEditorCellStyleSync()
  updateRichTextContentEditorPosition()
  if (!sheetPerfLoggingEnabled.value) {
    return
  }
  const end = getSheetPerfNow()
  const renderState = sheetPerfCurrentRender
  sheetPerfCurrentRender = null
  if (!renderState) {
    recordSheetPerfEvent('handsontable.render', {
      isForced,
      duration: 0,
      detail: {
        missingBeforeRender: true,
        ...getSheetPerfSelectedCellContext(),
        viewport: getSheetPerfHotViewport(),
      },
    })
    return
  }

  const duration = Math.max(0, end - renderState.start)
  recordSheetPerfEvent('handsontable.render', {
    renderId: renderState.id,
    isForced,
    duration: roundSheetPerfMs(duration),
    perfStart: roundSheetPerfMs(renderState.start),
    perfEnd: roundSheetPerfMs(end),
    detail: {
      beforeRenderIsForced: renderState.isForced,
      cellCount: renderState.cellCount,
      cellMetaCount: renderState.cellMetaCount,
      cellMetaMs: roundSheetPerfMs(renderState.cellMetaMs),
      rowHeightCount: renderState.rowHeightCount,
      rowHeightMs: roundSheetPerfMs(renderState.rowHeightMs),
      rendererCount: renderState.rendererCount,
      rendererMs: roundSheetPerfMs(renderState.rendererMs),
      callbackMs: roundSheetPerfMs(renderState.cellMetaMs + renderState.rowHeightMs + renderState.rendererMs),
      callbackShare: duration > 0
        ? roundSheetPerfMs((renderState.cellMetaMs + renderState.rowHeightMs + renderState.rendererMs) / duration)
        : 0,
      selectionId: renderState.selectionId,
      selectionAddress: renderState.selectionAddress,
      selectionRow: renderState.selectionRow,
      selectionHotColumn: renderState.selectionHotColumn,
      ...getSheetPerfSelectedCellContext(),
      viewport: getSheetPerfHotViewport(),
    },
  })
}

function handleAfterScrollHorizontally() {
  recordSheetPerfEvent('handsontable.scrollHorizontal', {
    detail: {
      ...getSheetPerfSelectedCellContext(),
      viewport: getSheetPerfHotViewport(),
    },
  })
  scheduleRichTextInlineToolbarSync()
  scheduleInlineEditorCellStyleSync()
  scheduleSheetOverlayAlignment()
  updateRichTextContentEditorPosition()
}

function handleAfterScrollVertically() {
  recordSheetPerfEvent('handsontable.scrollVertical', {
    detail: {
      ...getSheetPerfSelectedCellContext(),
      viewport: getSheetPerfHotViewport(),
    },
  })
  scheduleRichTextInlineToolbarSync()
  scheduleInlineEditorCellStyleSync()
  scheduleSheetOverlayAlignment()
  updateRichTextContentEditorPosition()
}

function handleCoreAfterRenderer(
  TD: HTMLTableCellElement,
  row: number,
  hotColumn: number,
  _prop: string | number,
  value: string,
) {
  const perfStart = getSheetPerfRenderCallbackStart()
  try {
    if (row >= 0 && isRowMarkerHotColumn(hotColumn)) {
      renderRowMarkerCell(TD, row)
      return
    }

    const column = toSheetColumnIndex(hotColumn)
    if (column < 0) {
      resetRenderedCellState(TD)
      return
    }

    if (row >= 0 && isSheetHeaderGridRow(row)) {
      renderCoreSheetHeaderGridCell(TD, row, column, value)
      return
    }

    resetRenderedCellState(TD)
    applyFreezePaneBoundaryClasses(TD, row, column)
  } finally {
    recordSheetPerfRenderCallback('renderer', perfStart)
  }
}

function handleAfterRenderer(
  TD: HTMLTableCellElement,
  row: number,
  hotColumn: number,
  _prop: string | number,
  value: string,
) {
  const perfStart = getSheetPerfRenderCallbackStart()
  try {
    if (row >= 0 && isRowMarkerHotColumn(hotColumn)) {
      renderRowMarkerCell(TD, row)
      return
    }

    const column = toSheetColumnIndex(hotColumn)
    if (column < 0) {
      resetRenderedCellState(TD)
      return
    }

    if (row >= 0 && column >= 0 && isSheetHeaderGridRow(row)) {
      const anchor = getMergeAnchorForGridCell(row, column)
      renderSheetHeaderGridCell(TD, anchor.row, anchor.column, getGridCellRenderSourceValue(anchor.row, anchor.column))
      return
    }

  const anchor = row >= 0 && column >= 0
    ? getMergeAnchorForGridCell(row, column)
    : { row, column, documentRow: -1 }
  const renderColumn = anchor.column
  const dataRow = anchor.row >= 0 ? getDataRowIndex(anchor.row) : -1
  resetRenderedCellState(TD)
  applyFreezePaneBoundaryClasses(TD, anchor.row, renderColumn)
  const documentRow = dataRow >= 0 ? anchor.documentRow : -1
  const rawText = dataRow >= 0 && renderColumn >= 0
    ? getGridCellRawValue(anchor.row, renderColumn)
    : normalizeCellValue(value)
  const header = renderColumn >= 0 ? columnHeaders.value[renderColumn] ?? '' : ''
  const columnConfig = header ? columnConfigs.value[header] : undefined
  const cellMetaEntry = documentRow >= 0 && renderColumn >= 0
    ? getCellMetaAt(documentRow, renderColumn)
    : null
  const link = cellMetaEntry?.link ?? null
  const sourceAction = cellMetaEntry?.action ?? null
  const action = sourceAction
    && sourceAction.type !== SHEET_CELL_ACTION_ATTENDANCE_COURSE_UPDATE_DATA
    && isSheetCellActionAllowedAt(sourceAction, documentRow, renderColumn)
    ? sourceAction
    : null
  const linkDisplayText = rawText.trim() ? '' : (link?.title || link?.url || '')
  const formulaCell = dataRow >= 0 && renderColumn >= 0 && isFormulaExpression(rawText)
    ? getFormulaCellModel(dataRow, renderColumn)
    : null
  const formulaText = formulaCell?.text ?? null
  let renderedText = rawText
  if (action) {
    renderedText = getCellActionDisplayLabel(action, rawText)
  } else if (formulaCell) {
    renderedText = formulaCell.text
  } else if (linkDisplayText) {
    renderedText = linkDisplayText
  } else if (dataRow >= 0 && renderColumn >= 0) {
    renderedText = formatCellDisplayValueCached(rawText, columnConfig)
  }

  const richText = (
    !action
    && formulaText == null
    && renderedText === rawText
    && documentRow >= 0
    && renderColumn >= 0
  )
    ? normalizeRichTextForText(cellMetaEntry?.rich_text, rawText)
    : null

  if (action) {
    renderCellActionButton(TD, renderedText, action, {
      documentRow,
      column: renderColumn,
    }, rawText)
  } else if (richText) {
    renderRichTextCell(TD, renderedText, richText)
  } else if (formulaText != null || renderedText !== rawText) {
    setRenderedCellText(TD, renderedText)
  }

  const hasFormula = formulaText != null
  const hasFormulaError = hasFormula && (isFormulaErrorValue(formulaCell?.value) || formulaCell.text.startsWith('#'))
  const isFormulaReferencePreview = dataRow >= 0 && renderColumn >= 0 && isCellInFormulaReferencePreview(dataRow, renderColumn)
  const displayMode = normalizeColumnDisplayMode(columnConfig?.display_mode)

  const cellStyle = cellMetaEntry?.style ?? null
  let backgroundColor = ''
  let textColor = ''
  let fontFamilyStyle = ''
  let fontSizeStyle = ''
  let lineHeightStyle = ''
  let textAlignStyle = ''
  let verticalAlignStyle = ''

  if (renderColumn >= 0) {
    backgroundColor = getPluginRowBackgroundColor(dataRow)
    fontFamilyStyle = getColumnFontFamilyStyle(columnConfig)
    textAlignStyle = resolveColumnTextAlign(columnConfig)
    const fontSize = getColumnFontSizeFromConfig(columnConfig)
    if (fontSize !== DEFAULT_COLUMN_FONT_SIZE) {
      fontSizeStyle = `${fontSize}px`
      lineHeightStyle = `${getColumnLineHeightFromFontSize(fontSize)}px`
    }

    const hashColorStyle = getCellHashColorStyle(renderColumn, columnConfig, renderedText)
    if (hashColorStyle?.backgroundColor) {
      backgroundColor = hashColorStyle.backgroundColor
    }
    if (hashColorStyle?.color) {
      textColor = hashColorStyle.color
    }

    const accentStyle = getCellAccentStyle(dataRow, renderColumn)
    if (accentStyle) {
      backgroundColor = accentStyle.backgroundColor
    }

    if (cellStyle?.background_color) {
      backgroundColor = cellStyle.background_color
    }
    if (cellStyle?.text_color) {
      textColor = cellStyle.text_color
    }
    if (cellStyle?.font_family) {
      fontFamilyStyle = getCellFontFamilyStyle(cellStyle.font_family)
    }
    if (cellStyle?.font_size) {
      fontSizeStyle = `${cellStyle.font_size}px`
      lineHeightStyle = `${getColumnLineHeightFromFontSize(cellStyle.font_size)}px`
    }
    if (cellStyle?.text_align) {
      textAlignStyle = cellStyle.text_align
    }
    if (cellStyle?.vertical_align) {
      verticalAlignStyle = cellStyle.vertical_align
    }

    if (isSyntheticEmptyDisplayRow(dataRow)) {
      backgroundColor = ''
    }
  }

  let title = ''

  const hasLink = !!link
  TD.classList.toggle('sheet-cell-has-link', hasLink)
  TD.classList.toggle('sheet-cell-has-action', !!action)
  TD.classList.toggle('sheet-cell-formula', hasFormula)
  TD.classList.toggle('sheet-cell-formula-error', hasFormulaError)
  TD.classList.toggle('sheet-cell-formula-reference-preview', isFormulaReferencePreview)
  TD.classList.toggle('sheet-cell-single-line', displayMode === 'single_line')
  TD.classList.toggle('sheet-cell-wrap', displayMode === 'wrap')
  TD.style.backgroundColor = backgroundColor
  TD.style.color = textColor
  TD.style.fontFamily = fontFamilyStyle
  TD.style.fontSize = fontSizeStyle
  TD.style.lineHeight = lineHeightStyle
  TD.style.textAlign = textAlignStyle
  TD.style.verticalAlign = verticalAlignStyle

  if (link) {
    TD.dataset.hyperlinkUrl = link.url
  } else if (TD.dataset.hyperlinkUrl) {
    delete TD.dataset.hyperlinkUrl
  }

  if (formulaText == null && renderedText !== rawText && rawText) {
    title = `${rawText}\n= ${renderedText}`
  }

  if (link) {
    title = title ? `${title}\n${link.url}` : link.url
  }
  if (action) {
    const actionTitle = getCellActionTitle(action)
    if (actionTitle) {
      title = title ? `${title}\n${actionTitle}` : actionTitle
    }
  }
  if (title) {
    if (TD.title !== title) {
      TD.title = title
    }
  } else if (TD.title) {
    TD.removeAttribute('title')
  }
  } finally {
    recordSheetPerfRenderCallback('renderer', perfStart)
  }
}

function getExcelColumnLabel(index: number) {
  let current = index
  let label = ''

  do {
    label = String.fromCharCode(65 + (current % 26)) + label
    current = Math.floor(current / 26) - 1
  } while (current >= 0)

  return label
}

function handleAfterColumnResize(newSize: number, hotColumn: number, isDoubleClick = false) {
  if (!canEditConfig.value) {
    return
  }
  const column = toSheetColumnIndex(hotColumn)
  if (column < 0 || column >= columnHeaders.value.length || !Number.isFinite(newSize) || newSize <= 0) {
    return
  }

  setColumnWidth(column, newSize, {
    commitAdaptiveWidth: isDoubleClick,
    commitFixedWidth: !isDoubleClick,
    refreshRowHeights: true,
    save: true,
  })
  scheduleInlineEditorCellStyleSync()
  updateRichTextContentEditorPosition()
}

function handleAfterRowResize() {
  void updateSheetViewportHeight()
  scheduleInlineEditorCellStyleSync()
  updateRichTextContentEditorPosition()
}

watch(
  hasFormulaExpressions,
  (hasFormula) => {
    if (hasFormula) {
      void ensureFormulaEngineLoaded()
    }
  },
  { immediate: true },
)

watch(
  [rows, columnHeaders, headerGroups, columnConfigs, sheetViewSettings],
  () => {
    const columnNotesRestored = syncColumnNotesFromHeaderPrefixRows()
    if (suppressNextFormulaDisplayStructureWatcher) {
      suppressNextFormulaDisplayStructureWatcher = false
    } else {
      refreshFormulaDisplayState()
    }
    if (columnNotesRestored) {
      refreshGridStructure()
    }
  },
  { deep: true, flush: 'post' },
)

watch(
  () => {
    const cell = formulaBarCell.value
    return cell ? getFormulaBarCellRawValue(cell) : ''
  },
  () => {
    syncFormulaBarDraftFromSelectedCell()
  },
)

watch(
  [rows, columnHeaders, headerGroups, cellMeta, columnConfigs, columnWidths],
  () => {
    if (suppressNextRemoteSaveWatcher) {
      suppressNextRemoteSaveWatcher = false
      return
    }
    scheduleRemoteSave()
  },
  { deep: true },
)

watch(
  () => sheetTitle.value,
  () => {
    scheduleRemoteSave()
  },
)

watch(
  effectiveAccessCapabilities,
  () => {
    if (!canPersistSheet.value) {
      clearSaveTimer()
      clearDraftStorage()
    }
    const hot = getHotInstance()
    if (hot) {
      hot.updateSettings({
        cells: sheetHotRenderCellMetaResolver.value,
        readOnly: sheetHotRenderReadOnly.value,
      })
      renderHotWithReason(hot, 'access-capabilities')
    }
  },
  { deep: true },
)

watch(
  () => props.accessCapabilities,
  () => {
    invalidateSheetDocumentCache(props.sheetId, props.workbookId ?? null)
  },
  { deep: true },
)

watch(
  () => props.sheetId,
  (nextSheetId, previousSheetId) => {
    sheetWorkspaceView.value = getDefaultSheetWorkspaceView()
    clearUserMatchRunPollTimer()
    clearClockinLinkDetectionRunPollTimer()
    userMatchRunStatus.value = null
    clockinLinkDetectionRunStatus.value = null
    userMatchStartPending.value = false
    clearSaveTimer()
    resetSheetFilterReloadState()
    closeSheetResourceSocket()
    if (!nextSheetId) {
      restoreInitialDocumentSeq += 1
      sheetLoadSettled.value = true
      if (hasInlineDocument.value) {
        applyInlineSheetDocument()
      } else {
        suppressPersistence = true
        resetWorkspaceState()
        currentPage.value = 1
        pageCount.value = 1
        totalRowCount.value = 0
        unfilteredTotalRowCount.value = 0
        pageRowOffset.value = 0
        pageLoadedRowCount.value = 0
        pageRowIndexes.value = null
        pendingDeletedPageRowIndexes.value = []
        suppressPersistence = false
      }
      void updateSheetViewportHeight()
      return
    }
    if (nextSheetId === previousSheetId) {
      return
    }
    columnFilters.value = {}
    closeColumnFilterPopover()
    sheetLoadSettled.value = false
    currentPage.value = 1
    pageCount.value = 1
    totalRowCount.value = 0
    unfilteredTotalRowCount.value = 0
    sheetVersion.value = 0
    sheetContentReady.value = false
    loadedSheetContentIdentity = ''
    resetHotInitialGridRowsLoaded()
    clearHotMergeCellsPlugin(getHotInstance())
    pageRowOffset.value = 0
    pageLoadedRowCount.value = 0
    pageRowIndexes.value = null
    pendingDeletedPageRowIndexes.value = []
    void restoreInitialDocument({
      preserveContent: false,
      clearOnError: true,
      initialDetail: getUsableInitialSheetDetail(props.initialDetail),
      applyInitialWorkspaceView: true,
    }).finally(() => {
      connectSheetResourceSocket()
      void updateSheetViewportHeight()
    })
  },
)

watch(
  [() => props.inlineDocument, () => props.inlineTitle],
  () => {
    if (props.sheetId != null) {
      return
    }
    applyInlineSheetDocument()
    void updateSheetViewportHeight()
  },
  { deep: true },
)

watch(
  () => props.workbookId,
  (nextWorkbookId, previousWorkbookId) => {
    if (nextWorkbookId === previousWorkbookId || props.sheetId == null) {
      return
    }
    sheetWorkspaceView.value = getDefaultSheetWorkspaceView()
    clearUserMatchRunPollTimer()
    clearClockinLinkDetectionRunPollTimer()
    userMatchRunStatus.value = null
    clockinLinkDetectionRunStatus.value = null
    userMatchStartPending.value = false
    clearSaveTimer()
    resetSheetFilterReloadState()
    sheetLoadSettled.value = false
    void restoreInitialDocument({
      preserveContent: sheetContentReady.value,
      clearOnError: true,
      initialDetail: getUsableInitialSheetDetail(props.initialDetail),
      applyInitialWorkspaceView: true,
    }).finally(() => {
      void updateSheetViewportHeight()
    })
  },
)

watch(
  () => props.initialWorkspaceView,
  (nextView, previousView) => {
    if (nextView === previousView || !sheetContentReady.value) {
      return
    }
    restoreSheetWorkspaceViewFromLocalStorage({
      applyInitialWorkspaceView: true,
    })
  },
)

watch(
  [() => rows.value.length, () => columnHeaders.value.length, () => props.sheetId],
  () => {
    void updateSheetViewportHeight()
  },
)

watch(
  [studentLookupGroup, filteredStudentLookupOptions],
  () => {
    if (
      studentLookupGroup.value
      && !studentLookupGroupOptions.value.includes(studentLookupGroup.value)
    ) {
      studentLookupGroup.value = ''
      return
    }

    if (
      studentLookupStudentKey.value
      && !filteredStudentLookupOptions.value.some((option) => option.key === studentLookupStudentKey.value)
    ) {
      if (isStudentLookupQuestionnaireMode.value) {
        const matchedSequenceOption = filteredStudentLookupOptions.value.find(
          (option) => option.sequence === studentLookupStudentKey.value.trim(),
        )
        if (matchedSequenceOption) {
          studentLookupStudentKey.value = matchedSequenceOption.key
        }
        return
      }

      const persistedOption = findStudentLookupOptionFromPersistedSelection(
        readStudentLookupPersistedSelection(),
        filteredStudentLookupOptions.value,
      )
      if (persistedOption) {
        studentLookupStudentKey.value = persistedOption.key
        return
      }
      studentLookupStudentKey.value = ''
    }
  },
)

watch(
  [studentLookupGroup, studentLookupStudentKey],
  () => {
    persistStudentLookupSelectionToLocalStorage()
  },
)

watch(
  [studentLookupStudentKey, shouldShowStudentLookup],
  () => {
    void updateSheetViewportHeight()
  },
)

watch(
  [
    studentLookupFeedbackDialogVisible,
    studentLookupFeedbackCourseName,
    studentLookupFeedbackStudentId,
    studentLookupFeedbackStudentName,
  ],
  () => {
    if (!studentLookupFeedbackDialogVisible.value) {
      resetStudentLookupFeedbackHistory()
      return
    }
    void loadStudentLookupFeedbackHistory()
  },
)

watch(
  isOriginalSheetViewActive,
  (active) => {
    if (active) {
      void updateSheetViewportHeight()
    }
  },
)

watch(
  [
    () => hotTableRef.value?.hotInstance ?? null,
    () => sheetContentReady.value,
    () => sheetHotGridRows.value,
  ],
  () => {
    requestHotInitialGridRowsLoaded('hot-instance-ready')
  },
  { flush: 'post' },
)

watch(
  [columnHeaders, columnConfigs],
  () => {
    pruneColumnFilters()
  },
  { deep: true },
)

watch(
  [
    columnFilters,
    () => props.baseRowFilterProgram,
    () => props.baseRowFilterPrograms,
    () => props.rowFilterProgram,
  ],
  () => {
    scheduleFilteredPaginationReload()
  },
  { deep: true },
)

watch(
  [
    () => sheetContentReady.value,
    () => effectivePaginationEnabled.value,
    () => pageRowIndexes.value,
    () => activeColumnFilterEntries.value.length,
    () => externalRowFilterProgramActive.value,
  ],
  () => {
    if (
      sheetContentReady.value
      && effectivePaginationEnabled.value
      && pageRowIndexes.value === null
      && (activeColumnFilterEntries.value.length > 0 || externalRowFilterProgramActive.value)
    ) {
      scheduleFilteredPaginationReload()
    }
  },
)

watch(
  sheetFilterHiddenRows,
  (hiddenRows) => {
    const hot = getHotInstance()
    if (!hot) {
      return
    }
    hot.updateSettings({
      hiddenRows: {
        rows: [...hiddenRows],
        indicators: false,
      },
    })
    renderHotWithReason(hot, 'hidden-rows-filter')
    void refreshComputedRowHeights()
    void updateSheetViewportHeight()
  },
  { deep: true },
)

onMounted(() => {
  markBootPerf('note-sheet-workspace.mounted', {
    sheetId: props.sheetId ?? null,
    workbookId: props.workbookId ?? null,
    hasInitialDetail: !!props.initialDetail,
    hasInlineDocument: hasInlineDocument.value,
  })
  installSheetPerfLogger()
  touchContextMenuFallbackEnabled.value = shouldEnableTouchContextMenuFallback()
  bindSheetLayoutObserver()
  window.addEventListener('resize', handleWindowResize)
  window.addEventListener('scroll', handleWindowScroll, true)
  window.addEventListener('mousedown', handleGlobalMouseDown)
  document.addEventListener('visibilitychange', handleSheetVisibilityChange)
  document.addEventListener('selectionchange', handleRichTextInlineSelectionEvent)
  document.addEventListener('mouseup', handleRichTextInlineSelectionEvent, true)
  document.addEventListener('keyup', handleRichTextInlineSelectionEvent, true)
  document.addEventListener('input', handleInlineEditorInput, true)
  if (props.sheetId != null) {
    void restoreInitialDocument({
      initialDetail: getUsableInitialSheetDetail(props.initialDetail),
      applyInitialWorkspaceView: true,
    }).finally(() => {
      markBootPerf('note-sheet-workspace.mounted.restore.finally')
      connectSheetResourceSocket()
      void updateSheetViewportHeight()
    })
  } else if (hasInlineDocument.value) {
    applyInlineSheetDocument()
    void updateSheetViewportHeight()
  } else {
    void updateSheetViewportHeight()
  }
})

onBeforeUnmount(() => {
  closeSheetResourceSocket()
  closeRichTextContentEditor({ save: true })
  clearSheetRenderEnhancementFrame()
  clearSheetOverlayAlignmentFrame()
  clearSaveTimer()
  if (readOnlyActionWarningSuppressTimer != null) {
    window.clearTimeout(readOnlyActionWarningSuppressTimer)
    readOnlyActionWarningSuppressTimer = null
  }
  clearDeferredCellSelectionState()
  clearCellLinkOpenPointerGuard()
  resetSheetFilterReloadState()
  clearInitialSheetActionStatusRefreshTimer()
  clearUserMatchRunPollTimer()
  clearClockinLinkDetectionRunPollTimer()
  finishFormulaReferenceRange()
  clearScheduledFormulaBarDraftSync()
  clearScheduledInlineEditorFormulaBarSync()
  clearScheduledRowMarkerSelection()
  clearRowMarkerSelectionAnchor()
  unbindRowDetailDialogSizeObserver()
  clearFormulaReferencePointerDownReset()
  studentLookupFeedbackHistoryRequestId += 1
  window.removeEventListener('resize', handleWindowResize)
  window.removeEventListener('scroll', handleWindowScroll, true)
  window.removeEventListener('mousedown', handleGlobalMouseDown)
  document.removeEventListener('visibilitychange', handleSheetVisibilityChange)
  document.removeEventListener('selectionchange', handleRichTextInlineSelectionEvent)
  document.removeEventListener('mouseup', handleRichTextInlineSelectionEvent, true)
  document.removeEventListener('keyup', handleRichTextInlineSelectionEvent, true)
  document.removeEventListener('input', handleInlineEditorInput, true)
  void flushSheetPerfLogEntries({ beacon: true })
  uninstallSheetPerfLogger()
  sheetLayoutObserver?.disconnect()
  sheetLayoutObserver = null
})

defineExpose({
  openSheetSettings,
  openDefinedNamesDialog,
  hideEmptyColumns,
  detectAndSetOptionFilters,
})
</script>

<template>
  <div
    class="note-sheet-workspace"
    :class="{
      'is-content-height': isContentHeightMode,
      'is-lookup-view': isStudentLookupViewActive,
    }"
    :style="sheetWorkspaceStyle"
  >
    <div v-if="shouldRenderSheetContent && (showTitleInput || showBackButton)" class="sheet-topbar">
      <el-input
        v-if="showTitleInput"
        v-model="sheetTitle"
        placeholder="表格名称"
        class="sheet-title-input"
        :disabled="!canEditConfig"
      />
      <el-button v-if="showBackButton" @click="router.push(backTo)">{{ backLabel }}</el-button>
      <div v-if="showUserIdentity" class="sheet-user-slot">
        <span v-if="userIdentityLabel" class="sheet-user-identity">
          <el-icon><User /></el-icon>
          <span>{{ userIdentityLabel }}</span>
        </span>
        <button v-else type="button" class="sheet-login-button" @click="openLoginPage">
          登录
        </button>
      </div>
    </div>

    <div v-if="shouldRenderSheetContent" class="sheet-formula-bar">
      <el-select
        v-if="shouldShowSheetWorkspaceViewSelect"
        :model-value="sheetWorkspaceView"
        class="sheet-workspace-view-select"
        size="small"
        aria-label="切换视图"
        title="右键复制视图链接"
        @change="handleSheetWorkspaceViewChange"
        @contextmenu="openSheetWorkspaceViewLinkMenu"
      >
        <el-option
          v-for="option in sheetWorkspaceViewOptions"
          :key="option.value"
          :label="option.label"
          :value="option.value"
        />
      </el-select>
      <div v-if="shouldShowSheetWorkspaceViewSelect && isOriginalSheetViewActive" class="sheet-formula-separator" />
      <template v-if="isOriginalSheetViewActive">
        <div class="sheet-formula-address">{{ formulaBarAddress || '--' }}</div>
        <button
          v-if="showContextMenuFallbackButton"
          ref="contextMenuFallbackButtonRef"
          type="button"
          class="sheet-context-menu-fallback"
          aria-label="打开右键菜单"
          title="打开右键菜单"
          @click="openTouchContextMenuFallback"
          @mousedown.stop
          @touchstart.stop
        >
          右键菜单
        </button>
        <div class="sheet-formula-separator" />
        <div class="sheet-formula-prefix">fx</div>
        <el-input
          ref="formulaBarInputRef"
          :model-value="formulaBarDraft"
          class="sheet-formula-input"
          :disabled="!formulaBarCell"
          :readonly="!canEditFormulaBarCell() || !shouldUseEnhancedSheetRenderSettings"
          clearable
          @update:model-value="value => updateFormulaBarDraft(String(value))"
          @focus="handleFormulaBarFocus"
          @blur="handleFormulaBarBlur"
          @keydown="handleFormulaBarKeyDown"
          @keydown.enter.exact.prevent="commitFormulaBarDraftAndExit"
          @keydown.esc.prevent="resetFormulaBarDraftAndExit"
        />
      </template>
    </div>

    <section
      v-if="isStudentLookupViewActive"
      class="sheet-student-lookup"
      :style="getStudentLookupLayoutStyle(selectedStudentLookupDetailRecords)"
    >
      <div class="sheet-student-lookup-controls">
        <label v-if="shouldShowStudentLookupGroupSelect" class="sheet-student-lookup-field">
          <span class="sheet-student-lookup-label">分组</span>
          <el-select
            v-model="studentLookupGroup"
            class="sheet-student-lookup-group-select"
            size="small"
          >
            <el-option label="全部分组" value="" />
            <el-option
              v-for="group in studentLookupGroupOptions"
              :key="group"
              :label="group"
              :value="group"
            />
          </el-select>
        </label>

        <label class="sheet-student-lookup-field sheet-student-lookup-field-main">
          <span class="sheet-student-lookup-label">{{ studentLookupPrimaryLabel }}</span>
          <el-select
            v-model="studentLookupStudentKey"
            class="sheet-student-lookup-student-select"
            size="small"
            clearable
            :filterable="isStudentLookupQuestionnaireMode"
            :allow-create="isStudentLookupQuestionnaireMode"
            :default-first-option="isStudentLookupQuestionnaireMode"
            :placeholder="studentLookupStudentPlaceholder"
            :disabled="filteredStudentLookupOptions.length === 0"
          >
            <el-option
              v-for="option in filteredStudentLookupOptions"
              :key="option.key"
              :label="option.label"
              :value="option.key"
            >
              <div
                class="sheet-student-lookup-option"
                :class="{ 'is-archived': isStudentLookupArchivedOption(option) }"
              >
                <span>{{ option.label }}</span>
                <span v-if="option.secondaryLabel" class="sheet-student-lookup-option-group">{{ option.secondaryLabel }}</span>
              </div>
            </el-option>
          </el-select>
        </label>

        <el-button
          v-if="studentLookupMode === 'student'"
          class="sheet-student-lookup-feedback-button"
          size="small"
          :disabled="!selectedStudentLookupOption"
          @click="openStudentLookupFeedbackDialog"
        >我要反馈问题</el-button>
      </div>

      <div
        v-if="selectedStudentLookupDetailRecords.length"
        class="sheet-student-lookup-detail"
        :class="{ 'is-questionnaire': isStudentLookupQuestionnaireMode }"
      >
        <article
          v-for="record in selectedStudentLookupDetailRecords"
          :key="record.key"
          class="sheet-student-lookup-record"
          :class="{ 'is-current': record.current }"
        >
          <div v-if="record.title" class="sheet-student-lookup-record-title">
            <span>{{ record.title }}</span>
            <span v-if="record.current" class="sheet-student-lookup-record-current">当前</span>
          </div>
          <section
            v-for="(section, sectionIndex) in record.sections"
            :key="`${record.key}-${section.title || 'default'}-${sectionIndex}`"
            class="sheet-student-lookup-section"
          >
            <div v-if="section.title" class="sheet-student-lookup-section-title">{{ section.title }}</div>
            <div class="sheet-student-lookup-items">
              <div
                v-for="item in section.items"
                :key="`${record.key}-${item.columnIndex}`"
                class="sheet-student-lookup-item"
                :class="{ 'is-empty': item.empty }"
              >
                <div class="sheet-student-lookup-key">
                  <span class="sheet-student-lookup-marker">{{ item.marker }}</span>
                  <span class="sheet-student-lookup-item-label">{{ item.label }}</span>
                </div>
                <div class="sheet-student-lookup-value" :style="item.valueStyle">
                  <a
                    v-if="item.link"
                    :href="item.link.url"
                    target="_blank"
                    rel="noreferrer"
                  >{{ item.value || item.link.url }}</a>
                  <span v-else>{{ item.value || '--' }}</span>
                </div>
              </div>
            </div>
          </section>
        </article>
      </div>
      <div v-else-if="studentLookupEmptyText" class="sheet-student-lookup-empty">{{ studentLookupEmptyText }}</div>
    </section>

    <el-dialog
      v-model="studentLookupFeedbackDialogVisible"
      title="反馈问题"
      width="min(640px, calc(100vw - 24px))"
      class="sheet-student-feedback-dialog"
      destroy-on-close
      append-to-body
      :close-on-click-modal="!studentLookupFeedbackSubmitting"
      :close-on-press-escape="!studentLookupFeedbackSubmitting"
    >
      <div class="sheet-student-feedback-form">
        <div class="sheet-student-feedback-context">
          <div class="sheet-student-feedback-context-item">
            <span>课程</span>
            <strong>{{ studentLookupFeedbackCourseName || '--' }}</strong>
          </div>
          <div class="sheet-student-feedback-context-item">
            <span>学员</span>
            <strong class="sheet-student-feedback-student">
              <span class="sheet-student-feedback-student-field">
                <span class="sheet-student-feedback-student-label">学号</span>
                <span>{{ studentLookupFeedbackStudentId || '--' }}</span>
              </span>
              <span class="sheet-student-feedback-student-field">
                <span class="sheet-student-feedback-student-label">姓名</span>
                <span>{{ studentLookupFeedbackStudentName || '--' }}</span>
              </span>
              <span class="sheet-student-feedback-student-field">
                <span class="sheet-student-feedback-student-label">昵称</span>
                <span>{{ studentLookupFeedbackNickname || '--' }}</span>
              </span>
            </strong>
          </div>
        </div>

        <label class="sheet-student-feedback-field">
          <span class="sheet-student-feedback-label">
            <span>修正需求</span>
            <span class="sheet-student-feedback-help">例如“共学打卡已满 21 次”或“第 18 课有完成当堂学习”</span>
          </span>
          <el-input
            v-model="studentLookupFeedbackCorrectionRequest"
            type="textarea"
            :rows="4"
            resize="vertical"
            placeholder="请直接写需要修正或核对的内容"
            maxlength="400"
            show-word-limit
          />
        </label>

        <div class="sheet-student-feedback-actions">
          <el-button :disabled="studentLookupFeedbackSubmitting" @click="studentLookupFeedbackDialogVisible = false">
            取消
          </el-button>
          <el-button
            type="primary"
            :loading="studentLookupFeedbackSubmitting"
            :disabled="hasSubmittedStudentLookupFeedbackDraft"
            @click="submitStudentLookupFeedback"
          >
            提交反馈
          </el-button>
        </div>

        <div v-if="studentLookupFeedbackSubmittedAt" class="sheet-student-feedback-submit-status">
          {{ studentLookupFeedbackSubmittedAt }} 已提交{{ hasSubmittedStudentLookupFeedbackDraft ? '，修改内容后可再次提交' : '，当前内容已变更，可重新提交' }}
        </div>

        <AttendanceFeedbackHistoryList
          v-if="studentLookupFeedbackHistoryItems.length"
          class="sheet-student-feedback-history"
          title="历史问卷"
          loading-text="正在查询历史问卷..."
          empty-text="暂未查到这个学员的历史问卷。"
          :ready="canLoadStudentLookupFeedbackHistory"
          :loading="studentLookupFeedbackHistoryLoading"
          :items="studentLookupFeedbackHistoryItems"
          :total="studentLookupFeedbackHistoryTotal"
          :student-id="studentLookupFeedbackStudentId"
          :student-name="studentLookupFeedbackStudentName"
        />
      </div>
    </el-dialog>

    <div
      v-if="shouldShowOriginalSheetArea"
      ref="sheetFrameRef"
      v-loading="workspaceLoading && shouldRenderSheetContent"
      class="sheet-frame"
      :class="{
        'is-empty': !shouldRenderSheetContent,
        'has-frozen-columns': fixedColumnsStart > 0,
        'has-frozen-rows': sheetHeaderRowCount > 0,
      }"
      @contextmenu.capture="openSheetContextMenuAt"
    >
      <HotTable
        v-if="isOriginalSheetViewActive && shouldRenderSheetContent"
        :key="hotTableInstanceKey"
        ref="hotTableRef"
        class="ht-theme-main"
        :data="sheetHotGridRows"
        :language="'zh-CN'"
        :col-headers="sheetColumnHeaders"
        :col-widths="sheetHotColumnWidths"
        :row-headers="false"
        :fixed-rows-top="sheetHeaderRowCount"
        :fixed-columns-start="fixedHotColumnsStart"
        :merge-cells="sheetHotRenderMergeCells"
        :hidden-columns="sheetHotHiddenColumnsSettings"
        :hidden-rows="sheetHotHiddenRowsSettings"
        :manual-column-resize="sheetHotRenderManualColumnResize"
        :manual-column-move="sheetHotRenderManualColumnMove"
        :manual-row-resize="sheetHotRenderManualRowResize"
        :manual-row-move="sheetHotRenderManualRowMove"
        :read-only="sheetHotRenderReadOnly"
        :copy-paste="true"
        :undo="true"
        :context-menu="sheetHotRenderContextMenu"
        :cells="sheetHotRenderCellMetaResolver"
        :row-heights="sheetHotRenderRowHeightResolver"
        :auto-column-size="false"
        :auto-row-size="false"
        :auto-wrap-row="false"
        :auto-wrap-col="false"
        :render-all-columns="false"
        :viewport-column-rendering-offset="sheetHotViewportColumnRenderingOffset"
        :min-spare-rows="0"
        :render-all-rows="false"
        :viewport-row-rendering-offset="SHEET_HOT_ROW_RENDERING_OFFSET"
        :height="sheetGridHeight"
        :stretch-h="'none'"
        :selection-mode="'range'"
        :outside-click-deselects="false"
        :license-key="'non-commercial-and-evaluation'"
        :before-change="handleBeforeChange"
        :before-autofill="handleBeforeAutofill"
        :before-copy="handleBeforeCopy"
        :before-cut="handleBeforeCut"
        :before-paste="handleBeforePaste"
        :after-change="handleAfterChange"
        :before-create-row="handleBeforeCreateRow"
        :after-create-row="handleAfterCreateRow"
        :after-remove-row="handleAfterRemoveRow"
        :after-create-col="handleAfterCreateCol"
        :before-remove-col="handleBeforeRemoveCol"
        :after-remove-col="handleAfterRemoveCol"
        :after-column-resize="handleAfterColumnResize"
        :after-row-resize="handleAfterRowResize"
        :before-column-move="handleBeforeColumnMove"
        :before-row-move="handleBeforeRowMove"
        :before-on-cell-mouse-down="handleBeforeCellMouseDown"
        :before-on-cell-mouse-over="handleBeforeCellMouseOver"
        :before-on-cell-mouse-up="handleBeforeCellMouseUp"
        :after-context-menu-show="handleAfterContextMenuShow"
        :after-on-cell-mouse-down="handleHeaderMouseDown"
        :after-begin-editing="handleAfterBeginEditing"
        :before-key-down="handleBeforeKeyDown"
        :after-document-key-down="handleAfterDocumentKeyDown"
        :after-selection="handleAfterSelection"
        :after-deselect="handleAfterDeselect"
        :after-get-col-header="handleAfterGetColHeader"
        :after-get-row-header="handleAfterGetRowHeader"
        :before-render="handleBeforeRender"
        :after-render="handleAfterRender"
        :after-scroll-horizontally="handleAfterScrollHorizontally"
        :after-scroll-vertically="handleAfterScrollVertically"
        :after-renderer="sheetHotRenderAfterRenderer"
      />

      <div v-else class="sheet-empty-state">{{ sheetEmptyStateText }}</div>

      <Teleport to="body">
        <div
          v-if="richTextContentEditor.visible"
          ref="richTextContentEditorRef"
          class="sheet-rich-text-cell-editor"
          :style="[
            richTextContentEditor.style,
            {
              left: `${richTextContentEditor.left}px`,
              top: `${richTextContentEditor.top}px`,
              width: `${richTextContentEditor.width}px`,
              height: `${richTextContentEditor.height}px`,
            },
          ]"
          contenteditable="true"
          spellcheck="false"
          @mousedown.stop
          @click.stop
          @contextmenu.stop
          @input="handleRichTextContentEditorInput"
          @keydown="handleRichTextContentEditorKeyDown"
          @keyup="handleRichTextInlineSelectionEvent"
          @mouseup="handleRichTextInlineSelectionEvent"
          @paste="handleRichTextContentEditorPaste"
        >
          <template v-if="richTextContentEditorSegments.length">
            <span
              v-for="(segment, index) in richTextContentEditorSegments"
              :key="index"
              class="sheet-rich-text-segment"
              :style="getRichTextSegmentStyle(segment.style)"
            >{{ segment.text }}</span>
          </template>
          <br v-else>
        </div>
      </Teleport>

      <div
        v-if="richTextInlineToolbar.visible"
        class="sheet-rich-text-inline-toolbar"
        :style="{
          left: `${richTextInlineToolbar.x}px`,
          top: `${richTextInlineToolbar.y}px`,
        }"
        @mousedown="handleRichTextInlineToolbarPointerDown"
        @contextmenu.prevent.stop
      >
        <button
          type="button"
          class="sheet-rich-text-inline-button is-strong"
          title="加粗"
          aria-label="加粗"
          @click="applyRichTextInlineToolbarPatch({ bold: true })"
        >
          B
        </button>
        <button
          type="button"
          class="sheet-rich-text-inline-button is-italic"
          title="斜体"
          aria-label="斜体"
          @click="applyRichTextInlineToolbarPatch({ italic: true })"
        >
          I
        </button>
        <button
          type="button"
          class="sheet-rich-text-inline-button is-underline"
          title="下划线"
          aria-label="下划线"
          @click="applyRichTextInlineToolbarPatch({ underline: true })"
        >
          U
        </button>
        <StandardColorPickerPopover
          :model-value="richTextInlineToolbarColors.text_color"
          :visible="activeRichTextInlineToolbarColorField === 'text_color'"
          :reset-value="richTextInlineToolbarColors.text_color"
          placement="bottom"
          @update:model-value="value => setRichTextInlineToolbarColor('text_color', value)"
          @update:visible="visible => handleRichTextInlineToolbarColorPopoverVisibleChange('text_color', visible)"
        >
          <template #reference>
            <span
              class="sheet-rich-text-inline-split"
              :class="{ 'is-open': activeRichTextInlineToolbarColorField === 'text_color' }"
            >
              <button
                type="button"
                class="sheet-rich-text-inline-button sheet-rich-text-inline-color-main is-color"
                title="应用文字颜色"
                aria-label="应用文字颜色"
                @click.stop="applyRichTextInlineToolbarCurrentColor('text_color')"
              >
                <span>A</span>
                <span class="sheet-rich-text-inline-color-bar" :style="getRichTextInlineToolbarSwatchStyle('text_color')" />
              </button>
              <button
                type="button"
                class="sheet-rich-text-inline-button sheet-rich-text-inline-color-menu"
                title="选择文字颜色"
                aria-label="选择文字颜色"
                @click.stop="toggleRichTextInlineToolbarColorPopover('text_color')"
              >
                ▾
              </button>
            </span>
          </template>
        </StandardColorPickerPopover>
        <StandardColorPickerPopover
          :model-value="richTextInlineToolbarColors.background_color"
          :visible="activeRichTextInlineToolbarColorField === 'background_color'"
          :reset-value="richTextInlineToolbarColors.background_color"
          placement="bottom"
          @update:model-value="value => setRichTextInlineToolbarColor('background_color', value)"
          @update:visible="visible => handleRichTextInlineToolbarColorPopoverVisibleChange('background_color', visible)"
        >
          <template #reference>
            <span
              class="sheet-rich-text-inline-split"
              :class="{ 'is-open': activeRichTextInlineToolbarColorField === 'background_color' }"
            >
              <button
                type="button"
                class="sheet-rich-text-inline-button sheet-rich-text-inline-color-main is-color"
                title="应用背景高亮"
                aria-label="应用背景高亮"
                @click.stop="applyRichTextInlineToolbarCurrentColor('background_color')"
              >
                <span>▰</span>
                <span class="sheet-rich-text-inline-color-bar" :style="getRichTextInlineToolbarSwatchStyle('background_color')" />
              </button>
              <button
                type="button"
                class="sheet-rich-text-inline-button sheet-rich-text-inline-color-menu"
                title="选择背景高亮"
                aria-label="选择背景高亮"
                @click.stop="toggleRichTextInlineToolbarColorPopover('background_color')"
              >
                ▾
              </button>
            </span>
          </template>
        </StandardColorPickerPopover>
        <button
          type="button"
          class="sheet-rich-text-inline-clear"
          title="清除选区格式"
          aria-label="清除选区格式"
          @click="clearRichTextInlineToolbarSelectionStyle"
        >
          清除
        </button>
      </div>
    </div>

    <div v-if="isOriginalSheetViewActive && shouldRenderSheetContent && pageStatusText" class="sheet-pagination-bar">
      <div class="sheet-pagination-status">{{ pageStatusText }}</div>
      <StandardPagination
        v-if="effectivePaginationEnabled"
        :page="currentPage"
        :page-size="pageSize"
        :page-count="pageCount"
        :show-page-size="false"
        :disabled="workspaceLoading || saveInFlight"
        @page-change="handlePageChange"
      />
    </div>

    <el-dialog
      v-model="rowDetailDialogVisible"
      :title="rowDetailDialogTitle"
      :width="rowDetailDialogWidth"
      :style="rowDetailDialogStyle"
      class="sheet-row-detail-dialog"
      draggable
      destroy-on-close
      append-to-body
      @opened="bindRowDetailDialogSizeObserver"
      @closed="unbindRowDetailDialogSizeObserver"
    >
      <div v-if="rowDetail" class="sheet-row-detail-list">
        <div
          v-for="item in rowDetail.items"
          :key="item.columnIndex"
          class="sheet-row-detail-item"
          :class="{ 'is-empty': item.empty }"
        >
          <div class="sheet-row-detail-key">
            <span class="sheet-row-detail-marker">{{ item.marker }}</span>
            <span class="sheet-row-detail-label">{{ item.label }}</span>
          </div>
          <div class="sheet-row-detail-value" :style="item.valueStyle">
            <el-input
              v-if="item.editable"
              v-model="item.rawValue"
              class="sheet-row-detail-editor"
              type="textarea"
              :autosize="{ minRows: 1, maxRows: 6 }"
              @input="(value) => updateRowDetailItemValue(item, value)"
            />
            <a
              v-else-if="item.link"
              :href="item.link.url"
              target="_blank"
              rel="noreferrer"
            >{{ item.value || item.link.url }}</a>
            <span v-else>{{ item.value || '--' }}</span>
          </div>
        </div>
      </div>
      <template v-if="rowDetail?.mode === 'new_registration_student'" #footer>
        <el-button @click="rowDetailDialogVisible = false">取消</el-button>
        <el-button type="primary" @click="confirmNewRegistrationStudentRow">确认新增</el-button>
      </template>
    </el-dialog>

    <el-dialog
      v-model="excelImportDialogVisible"
      title="导入 Excel"
      width="min(620px, calc(100vw - 24px))"
      class="sheet-excel-import-dialog"
      destroy-on-close
      align-center
      append-to-body
      :close-on-click-modal="!excelImportRunning"
      :close-on-press-escape="!excelImportRunning"
      :show-close="!excelImportRunning"
    >
      <div class="sheet-settings-form">
        <div class="sheet-settings-field">
          <input
            ref="excelImportFileInputRef"
            class="sheet-excel-file-input"
            type="file"
            accept=".xlsx,.xlsm,.xltx,.xltm"
            :disabled="excelImportRunning"
            @change="handleExcelImportFileChange"
          >
        </div>
        <div class="sheet-settings-field">
          <div class="sheet-settings-label">补充说明</div>
          <el-input
            v-model="excelImportInstruction"
            type="textarea"
            :rows="4"
            :disabled="excelImportRunning"
            placeholder="例如：只导入报名学员；日志批阅师资不要导入"
          />
        </div>
      </div>
      <template #footer>
        <div class="sheet-settings-footer sheet-excel-import-footer">
          <el-button :disabled="excelImportRunning" @click="() => closeExcelImportDialog()">取消</el-button>
          <div class="sheet-excel-import-actions">
            <el-button
              v-if="shouldShowExcelImportResetButton"
              type="danger"
              plain
              :loading="excelImportRunningMode === 'reset'"
              :disabled="excelImportRunning || !excelImportFile"
              @click="applyExcelImport('reset')"
            >
              {{ EXCEL_IMPORT_RESET_BUTTON_LABEL }}
            </el-button>
            <el-button
              type="primary"
              :loading="excelImportRunningMode === 'append'"
              :disabled="excelImportRunning || !excelImportFile"
              @click="applyExcelImport('append')"
            >
              {{ EXCEL_IMPORT_APPEND_BUTTON_LABEL }}
            </el-button>
          </div>
        </div>
      </template>
    </el-dialog>

    <el-dialog
      v-model="userMatchDialogVisible"
      title="更新用户匹配"
      width="420px"
      destroy-on-close
      append-to-body
    >
      <div class="sheet-settings-form">
        <div class="sheet-settings-field">
          <el-checkbox
            v-model="userMatchUseBrowserFallback"
            :disabled="userMatchStartPending || activeUserMatchRun"
          >
            未命中时回查小鹅通
          </el-checkbox>
          <div class="sheet-excel-import-hint">
            先查本地用户库；保持勾选时，未命中会调用 codepc_mi15 打开小鹅通用户列表逐行兜底。
          </div>
        </div>
        <div v-if="userMatchRunSummary" class="sheet-action-run-status">
          {{ userMatchRunSummary }}
        </div>
      </div>
      <template #footer>
        <div class="sheet-settings-footer">
          <el-button :disabled="userMatchStartPending" @click="() => closeUserMatchDialog()">
            {{ activeUserMatchRun ? '关闭' : '取消' }}
          </el-button>
          <el-button
            v-if="activeUserMatchRun"
            type="danger"
            plain
            :loading="userMatchStartPending"
            @click="() => startUserMatchRun(true)"
          >
            强制重启
          </el-button>
          <el-button
            v-else
            type="primary"
            :loading="userMatchStartPending"
            @click="() => startUserMatchRun(false)"
          >
            开始匹配
          </el-button>
        </div>
      </template>
    </el-dialog>

    <el-dialog
      v-model="definedNamesDialogVisible"
      title="名称管理器"
      width="min(820px, calc(100vw - 24px))"
      class="sheet-defined-names-dialog"
      destroy-on-close
      append-to-body
      :close-on-click-modal="!definedNamesSaving"
      :close-on-press-escape="!definedNamesSaving"
    >
      <div class="sheet-defined-names-toolbar">
        <el-button
          size="small"
          title="新增名称"
          aria-label="新增名称"
          @click="addDefinedNameDraftRow('workbook')"
        >+</el-button>
      </div>
      <div v-if="definedNamesError" class="sheet-defined-names-error">{{ definedNamesError }}</div>
      <div v-loading="definedNamesLoading" class="sheet-defined-names-list">
        <div class="sheet-defined-names-header">
          <span>作用域</span>
          <span>名称</span>
          <span>公式</span>
          <span>备注</span>
          <span />
        </div>
        <div
